app/kb/bases.mjs.source:
// The knowledge bases (docs/KNOWLEDGE-BASE.md): one entry per base, each the procedures of one profile with the
// address root its entries live under and the address of its library. The software how-tos live under /software
// (DECIDE 4), the library and its entries both. Declared once here; the procedure validator's roots and the route table read it,
// so a base's address is never typed twice. A list in code, not a table (Dustin, 2026-10-09): a base is nothing
// without its profile's components, and those are code.

/**
 * @typedef {{
 *   id: string,
 *   name: string,
 *   singular: string,
 *   profile: "protocol" | "recipe" | "computational",
 *   entryRoot: string,
 *   library: string,
 * }} KnowledgeBase
 */

/** @type {readonly KnowledgeBase[]} */
export const BASES = Object.freeze([
  {
    id: "protocols",
    name: "Protocols",
    singular: "Protocol",
    profile: "protocol",
    entryRoot: "/research/protocols/",
    library: "/research/protocols",
  },
  {
    id: "how-tos",
    name: "Software how-tos",
    singular: "Software how-to",
    profile: "computational",
    entryRoot: "/software/how-tos/",
    library: "/software/how-tos",
  },
  {
    id: "recipes",
    name: "Recipes",
    singular: "Recipe",
    profile: "recipe",
    entryRoot: "/recipes/",
    library: "/recipes",
  },
]);

app/kb/procedures/lineage.mjs.source:
// A variant's lineage (docs/KNOWLEDGE-BASE.md, P3): the procedure it was copied from with the editor's Duplicate, as the
// page, the twin and the JSON-LD name it. The file holds only `forked_from: { slug, version }`; the parent's title and
// address are its own facts, read from its row when the page is served, so a renamed parent reads right everywhere.

import { BASES } from "../bases.mjs";
import { versionPath } from "./cite.mjs";

/**
 * @typedef {{ title: string, href: string | null, version: string | null }} Lineage
 */

/**
 * Where a variant points: the frozen copy of the version it was copied at when there is one, else the parent's live page,
 * else (a parent not published) its name with no link.
 *
 * @param {{ slug: string, version: string | null } | null} forkedFrom
 * @param {string} profile
 * @param {{ live: { title: string, path: string } | null, frozen: { title: string } | null }} parent
 * @returns {Lineage | null}
 */
export function resolveLineage(forkedFrom, profile, parent) {
  if (!forkedFrom) return null;
  const root = BASES.find((b) => b.profile === profile)?.entryRoot ?? "/research/protocols/";
  const path = `${root}${forkedFrom.slug}`;
  if (forkedFrom.version && parent.frozen)
    return {
      title: parent.frozen.title,
      href: versionPath(path, forkedFrom.version),
      version: forkedFrom.version,
    };
  if (parent.live)
    return { title: parent.live.title, href: parent.live.path, version: forkedFrom.version };
  return { title: forkedFrom.slug, href: null, version: forkedFrom.version };
}

/** "Phage DNA extraction, version 2": the words the lineage is shown in. @param {Lineage} lineage */
export const lineageText = (lineage) =>
  `${lineage.title}${lineage.version ? `, version ${lineage.version}` : ""}`;

/** The twin's fact line for a lineage, as the page's fact reads. @param {Lineage} lineage @param {string} origin */
const lineageMarkdown = (lineage, origin) =>
  `- Based on: ${lineage.href ? `[${lineageText(lineage)}](${origin}${lineage.href})` : lineageText(lineage)}`;

/**
 * The fact the stored twin carries for a variant: the parent's file name and version, all the compile knows. The twin's
 * routes swap it for the parent's title and address when they serve it (`withLineage`).
 *
 * @param {{ slug: string, version: string | null }} forkedFrom
 */
export const storedLineage = (forkedFrom) =>
  `${forkedFrom.slug}${forkedFrom.version ? `, version ${forkedFrom.version}` : ""}`;

/**
 * A twin with its stored lineage fact read out in full: the parent's title, linked to the copy it was taken from.
 *
 * @param {string} markdown
 * @param {{ forkedFrom: { slug: string, version: string | null } | null }} record
 * @param {Lineage | null} lineage
 * @param {string} origin
 */
export function withLineage(markdown, record, lineage, origin) {
  if (!record.forkedFrom || !lineage) return markdown;
  return markdown.replace(
    `- Based on: ${storedLineage(record.forkedFrom)}\n`,
    `${lineageMarkdown(lineage, origin)}\n`,
  );
}

/**
 * What is wrong with a variant's `forked_from` against the procedures in the repository (P3): the parent is a file
 * here, of the same profile, and the version named is one the parent states (its current version or one in its history),
 * which is a version that is or will be frozen. The shape is validate.mjs's; this is the corpus check:protocols runs.
 *
 * @param {{ forkedFrom: { slug: string, version: string | null } | null, profile: string }} record
 * @param {Map<string, { profile: string, version: string | null, history: Array<{ version: string }> }>} procedures by slug
 * @returns {string[]}
 */
export function lineageErrors(record, procedures) {
  const from = record.forkedFrom;
  if (!from) return [];
  const parent = procedures.get(from.slug);
  if (!parent) return [`forked_from names ${from.slug}, which is not a procedure here`];
  if (parent.profile !== record.profile)
    return [
      `forked_from names ${from.slug}, a ${parent.profile}; a variant keeps its parent's profile (${record.profile})`,
    ];
  if (!from.version) return [];
  const stated = new Set([parent.version, ...parent.history.map((h) => h.version)].filter(Boolean));
  return stated.has(from.version)
    ? []
    : [
        `forked_from names version ${from.version} of ${from.slug}, which states ${[...stated].join(", ") || "no version"}`,
      ];
}

app/kb/procedures/recipe-views.mjs.source:
// A recipe's views (docs/KNOWLEDGE-BASE.md, step 9): its ingredients both ways (R2), metric and imperial (R3) and its
// mise-en-place (R5), every one computed from the compiled record and the reader's address, never stored. Unit conversion is
// arithmetic on the record's own amounts; volume becomes weight only for an ingredient whose recipe states `grams_per_cup`
// (DECIDE 7), never from a table of densities. Pure, so the page, the sheet and a test read the same numbers.

import { formatNumber, formatQuantity } from "./marks.mjs";

/** The unit systems a reader can ask for; absent is the recipe's own units. */
export const UNIT_SYSTEMS = Object.freeze({ metric: "Metric", imperial: "Imperial (US)" });

/** @typedef {keyof typeof UNIT_SYSTEMS} UnitSystem */
/** @typedef {{ amount: string, unit: string, fixed: boolean, min: number | null, max: number | null }} Quantity */

/** The system an address asks for (`?units=metric`), or null for the recipe's own. @param {string | null} value @returns {UnitSystem | null} */
export function readUnits(value) {
  return value === "metric" || value === "imperial" ? value : null;
}

/** Grams in one of each mass unit. */
const GRAMS = /** @type {Record<string, number>} */ ({
  g: 1,
  kg: 1000,
  oz: 28.349523125,
  lb: 453.59237,
});
/** Millilitres in one of each volume unit (US customary). */
const MILLILITRES = /** @type {Record<string, number>} */ ({
  ml: 1,
  l: 1000,
  tsp: 4.92892159375,
  tbsp: 14.78676478125,
  "fl oz": 29.5735295625,
  cup: 236.5882365,
});
/** The spoons a cook uses in either system, kept as written. */
const SPOONS = new Set(["tsp", "tbsp"]);

/** A unit's one spelling: "teaspoons" is tsp, "Cups" is cup. @param {string} unit */
function canonical(unit) {
  const u = unit.trim().toLowerCase().replace(/\.$/, "");
  const aliases = /** @type {Record<string, string>} */ ({
    gram: "g",
    grams: "g",
    kilogram: "kg",
    kilograms: "kg",
    ounce: "oz",
    ounces: "oz",
    pound: "lb",
    pounds: "lb",
    lbs: "lb",
    millilitre: "ml",
    millilitres: "ml",
    milliliter: "ml",
    milliliters: "ml",
    litre: "l", // codespell:ignore (British input accepted)
    litres: "l", // codespell:ignore (British input accepted)
    liter: "l",
    liters: "l",
    teaspoon: "tsp",
    teaspoons: "tsp",
    tablespoon: "tbsp",
    tablespoons: "tbsp",
    cups: "cup",
    "fluid ounce": "fl oz",
    "fluid ounces": "fl oz",
  });
  return aliases[u] ?? u;
}

/** A number rounded as a cook reads it in a unit: whole grams, quarter cups, half ounces. @param {number} n @param {string} unit */
function round(n, unit) {
  const step =
    unit === "cup"
      ? 0.25
      : unit === "lb"
        ? 0.1
        : unit === "oz"
          ? 0.25
          : unit === "tsp" || unit === "tbsp"
            ? 0.25
            : n < 10
              ? 0.1
              : 1;
  return Math.round(n / step) * step;
}

/**
 * One amount in a unit of `system`: grams become ounces and the reverse, millilitres become cups and the reverse, spoons stay. In
 * metric, a volume of an ingredient with `gramsPerCup` becomes its weight. A unit neither system knows (a pinch, 2 eggs) is
 * left as written, and so is an amount with no number.
 *
 * @param {number} value
 * @param {string} unit
 * @param {UnitSystem} system
 * @param {number | null} gramsPerCup
 * @returns {{ value: number, unit: string } | null}
 */
function convert(value, unit, system, gramsPerCup) {
  const u = canonical(unit);
  if (u in GRAMS) {
    const g = value * /** @type {number} */ (GRAMS[u]);
    if (system === "metric")
      return g >= 1000 ? { value: g / 1000, unit: "kg" } : { value: g, unit: "g" };
    const oz = g / /** @type {number} */ (GRAMS.oz);
    return oz >= 16 ? { value: oz / 16, unit: "lb" } : { value: oz, unit: "oz" };
  }
  if (u in MILLILITRES) {
    if (SPOONS.has(u)) return null;
    const ml = value * /** @type {number} */ (MILLILITRES[u]);
    if (system === "metric") {
      if (gramsPerCup)
        return { value: (ml / /** @type {number} */ (MILLILITRES.cup)) * gramsPerCup, unit: "g" };
      return ml >= 1000 ? { value: ml / 1000, unit: "l" } : { value: ml, unit: "ml" };
    }
    if (ml < 15) return { value: ml / /** @type {number} */ (MILLILITRES.tsp), unit: "tsp" };
    if (ml < 60) return { value: ml / /** @type {number} */ (MILLILITRES.tbsp), unit: "tbsp" };
    return { value: ml / /** @type {number} */ (MILLILITRES.cup), unit: "cup" };
  }
  return null;
}

/**
 * An amount as the reader asked for it: scaled by `factor` (a fixed amount is not), then in `system` when one is asked for.
 *
 * @param {Quantity} q
 * @param {number} factor
 * @param {UnitSystem | null} system
 * @param {number | null} [gramsPerCup]
 */
export function showQuantity(q, factor, system, gramsPerCup = null) {
  if (!system || q.min === null) return formatQuantity({ ...q, raw: "" }, factor);
  const scale = q.fixed ? 1 : factor;
  const low = convert(q.min * scale, q.unit, system, gramsPerCup);
  if (!low) return formatQuantity({ ...q, raw: "" }, factor);
  const high =
    q.max !== null && q.max !== q.min ? convert(q.max * scale, q.unit, system, gramsPerCup) : null;
  // A range is shown in the unit of its low end, so "1 to 2 cups" never reads "1 cup to 0.5 quart".
  const highValue = high
    ? high.unit === low.unit
      ? high.value
      : (q.max ?? 0) * scale * (low.value / (q.min * scale))
    : null;
  const amount =
    highValue !== null
      ? `${formatNumber(round(low.value, low.unit))} to ${formatNumber(round(highValue, low.unit))}`
      : formatNumber(round(low.value, low.unit));
  return `${amount} ${low.unit}`;
}

/** A temperature in the other scale, to the nearest 5 degrees as an oven dial reads. @param {number} t @param {"C" | "F"} to */
const toScale = (t, to) => Math.round((to === "F" ? (t * 9) / 5 + 32 : ((t - 32) * 5) / 9) / 5) * 5;

/**
 * A step's words with its temperatures in the asked-for system's scale: "180 °C" reads "355 °F" in imperial, and the reverse in
 * metric. HTML in, HTML out: only the text of a temperature changes.
 *
 * @param {string} html
 * @param {UnitSystem | null} system
 */
export function showTemperatures(html, system) {
  if (!system) return html;
  const from = system === "imperial" ? "C" : "F";
  const to = system === "imperial" ? "F" : "C";
  return html.replace(
    new RegExp(`(-?\\d+(?:\\.\\d+)?)(?:\\s*(?:to|-)\\s*(-?\\d+(?:\\.\\d+)?))?\\s*°${from}`, "g"),
    (_all, low, high) =>
      high !== undefined
        ? `${toScale(Number(low), to)} to ${toScale(Number(high), to)} °${to}`
        : `${toScale(Number(low), to)} °${to}`,
  );
}

/** The anchor of a step on the page: its list's scope and its number. @param {string} scope @param {number} number */
export const stepId = (scope, number) => `${scope}step-${number}`;

/**
 * Every step each ingredient is used in, in the page's order: the other half of R2, read from the marks the compile already
 * put on each step. Keyed by the ingredient's name, lower-cased, as the record's materials are.
 *
 * @param {import("./render.mjs").ProcedureRecord} record
 */
export function ingredientSteps(record) {
  /** @type {Map<string, Array<{ number: number, id: string }>>} */
  const uses = new Map();
  for (const section of record.sections) {
    section.blocks.forEach((block, i) => {
      if (block.type !== "steps") return;
      for (const step of block.steps) {
        for (const m of step.materials) {
          const key = m.name.toLowerCase();
          const list = uses.get(key) ?? [];
          if (
            !list.some(
              (u) =>
                u.number === step.number && u.id === stepId(`${section.id}-${i}-`, step.number),
            )
          ) {
            list.push({ number: step.number, id: stepId(`${section.id}-${i}-`, step.number) });
          }
          uses.set(key, list);
        }
      }
    });
  }
  return uses;
}

/**
 * The grams in a cup of each ingredient whose recipe states it, by lower-cased name.
 *
 * @param {import("./render.mjs").ProcedureRecord} record
 */
export function gramsPerCup(record) {
  return new Map(
    record.materials.flatMap((m) =>
      typeof m.gramsPerCup === "number" ? [[m.name.toLowerCase(), m.gramsPerCup]] : [],
    ),
  );
}

/**
 * A step's ingredients, each with its amount as the reader asked for it: the first half of R2.
 *
 * @param {import("./render.mjs").ProcedureRecord["sections"][number]["blocks"][number] extends infer B ? B extends { type: "steps", steps: Array<infer S> } ? S : never : never} step
 * @param {number} factor
 * @param {UnitSystem | null} system
 * @param {Map<string, number>} densities
 * @param {Map<string, string>} [names] the ingredient list's words for each ingredient, which the step's own marks may shorten
 */
export function stepIngredients(step, factor, system, densities, names = new Map()) {
  return step.materials.map((m) => {
    const q = step.quantities.find((x) => x.name?.toLowerCase() === m.name.toLowerCase());
    return {
      name: names.get(m.name.toLowerCase()) ?? m.display,
      amount: q
        ? showQuantity(q, factor, system, densities.get(m.name.toLowerCase()) ?? null)
        : null,
    };
  });
}

/** Each ingredient's words in the ingredient list, by lower-cased name. @param {import("./render.mjs").ProcedureRecord} record */
export function ingredientNames(record) {
  return new Map(record.materials.map((m) => [m.name.toLowerCase(), m.display]));
}

/**
 * The mise-en-place: every ingredient once, with its total amount at the reader's servings and units, in the order of the
 * ingredient list; and the same as plain lines, a shopping list to copy (R5).
 *
 * @param {import("./render.mjs").ProcedureRecord} record
 * @param {number} factor
 * @param {UnitSystem | null} system
 */
export function miseEnPlace(record, factor, system) {
  const items = record.materials.map((m) => {
    const amount = m.amount
      ? m.amount
      : m.quantity
        ? showQuantity(m.quantity, factor, system, m.gramsPerCup ?? null)
        : null;
    return { name: m.display, amount };
  });
  return {
    items,
    text: items.map((i) => `- ${i.amount ? `${i.amount} ` : ""}${i.name}`).join("\n"),
  };
}

app/kb/procedures/run.mjs.source:
// The pure half of run mode (docs/PROCEDURES.md "Run mode"): what a bench run is, how its timers count, and what
// the saved record says. A run is a person working through one procedure once: which steps are done, a note on
// each, the timers they started, the scale they chose. It lives in the browser (localStorage), is downloadable and
// printable, and never reaches the server: nothing here touches the DOM, a clock or storage, so the same functions
// run in a test. The browser module (app/enhance/run.ts) passes `now` in.
//
// A timer's remaining time is computed from the moment it ends, not counted down, so a phone that sleeps or a page
// that reloads mid-incubation still knows how long is left.

import { thing } from "@drdustinedwards/site-helpers/schema";

import { SITE_ORIGIN } from "../../lib/site-origin.mjs";

export const RUN_VERSION = 1;

/** Seconds in each unit a timer mark can use (validate.mjs TIME_UNITS). */
const UNIT_SECONDS = Object.freeze(
  /** @type {Record<string, number>} */ ({
    second: 1,
    seconds: 1,
    sec: 1,
    s: 1,
    minute: 60,
    minutes: 60,
    min: 60,
    hour: 3600,
    hours: 3600,
    h: 3600,
    day: 86400,
    days: 86400,
  }),
);

/**
 * @typedef {{ label: string, text: string, min: number | null, max: number | null, unit: string }} StepTimer
 * @typedef {{ state: "running" | "paused" | "done", endsAt: number | null, remainingMs: number, totalMs: number }} TimerState
 * @typedef {{ done: boolean, doneAt: number | null, note: string }} StepState
 * @typedef {{
 *   v: number, path: string, version: string, title: string, scale: number | null,
 *   startedAt: number, finishedAt: number | null, note: string,
 *   steps: Record<string, StepState>, timers: Record<string, TimerState>,
 * }} Run
 */

/**
 * A timer's length in milliseconds: the longer end of a range ("5 to 10 minutes" runs 10), because a timer that
 * rings early is the mistake that costs a prep. Null when the mark carries no usable number.
 *
 * @param {StepTimer} timer
 */
export function timerMs(timer) {
  const seconds = UNIT_SECONDS[String(timer.unit).toLowerCase()];
  const amount = timer.max ?? timer.min;
  if (seconds === undefined || amount === null || !Number.isFinite(amount) || amount <= 0)
    return null;
  return Math.round(amount * seconds * 1000);
}

/** The key a step's nth timer is stored under. */
export const timerKey = (/** @type {number | string} */ step, /** @type {number} */ index) =>
  `${step}.${index}`;

/**
 * @param {{ path: string, version: string, title: string, scale: number | null }} procedure
 * @param {number} now
 * @returns {Run}
 */
export function newRun(procedure, now) {
  return {
    v: RUN_VERSION,
    path: procedure.path,
    version: procedure.version,
    title: procedure.title,
    scale: procedure.scale,
    startedAt: now,
    finishedAt: null,
    note: "",
    steps: {},
    timers: {},
  };
}

const stepOf = (/** @type {Run} */ run, /** @type {number | string} */ step) =>
  run.steps[String(step)] ?? { done: false, doneAt: null, note: "" };

/** @param {Run} run @param {number | string} step @param {number} now */
export function toggleDone(run, step, now) {
  const current = stepOf(run, step);
  return {
    ...run,
    steps: {
      ...run.steps,
      [String(step)]: { ...current, done: !current.done, doneAt: current.done ? null : now },
    },
  };
}

/** @param {Run} run @param {number | string} step @param {string} note */
export function setNote(run, step, note) {
  return {
    ...run,
    steps: { ...run.steps, [String(step)]: { ...stepOf(run, step), note: note.slice(0, 2000) } },
  };
}

/** @param {Run} run @param {string} note */
export function setRunNote(run, note) {
  return { ...run, note: note.slice(0, 4000) };
}

/** @param {Run} run @param {number | null} scale */
export function setScale(run, scale) {
  return { ...run, scale };
}

/** @param {Run} run @param {number} now */
export function finishRun(run, now) {
  return { ...run, finishedAt: run.finishedAt ?? now };
}

/** Starts a timer, or resumes a paused one from where it stopped. @param {Run} run @param {string} key @param {number} ms @param {number} now */
export function startTimer(run, key, ms, now) {
  const current = run.timers[key];
  const remainingMs = current && current.state === "paused" ? current.remainingMs : ms;
  return {
    ...run,
    timers: {
      ...run.timers,
      [key]: {
        state: /** @type {const} */ ("running"),
        endsAt: now + remainingMs,
        remainingMs,
        totalMs: ms,
      },
    },
  };
}

/** @param {Run} run @param {string} key @param {number} now */
export function pauseTimer(run, key, now) {
  const current = run.timers[key];
  if (!current || current.state !== "running" || current.endsAt === null) return run;
  return {
    ...run,
    timers: {
      ...run.timers,
      [key]: {
        ...current,
        state: /** @type {const} */ ("paused"),
        endsAt: null,
        remainingMs: Math.max(0, current.endsAt - now),
      },
    },
  };
}

/** @param {Run} run @param {string} key */
export function resetTimer(run, key) {
  const { [key]: _gone, ...rest } = run.timers;
  return { ...run, timers: rest };
}

/** Milliseconds left on a timer, or null when it has not been started. @param {Run} run @param {string} key @param {number} now */
export function timerRemaining(run, key, now) {
  const t = run.timers[key];
  if (!t) return null;
  if (t.state === "paused" || t.state === "done") return t.state === "done" ? 0 : t.remainingMs;
  return Math.max(0, (t.endsAt ?? now) - now);
}

/**
 * Marks every running timer whose time has come as done, and returns which rang so the page can alert once.
 *
 * @param {Run} run @param {number} now
 * @returns {{ run: Run, rang: string[] }}
 */
export function tickTimers(run, now) {
  /** @type {string[]} */
  const rang = [];
  /** @type {Record<string, TimerState>} */
  const timers = { ...run.timers };
  for (const [key, t] of Object.entries(run.timers)) {
    if (t.state === "running" && t.endsAt !== null && t.endsAt <= now) {
      timers[key] = { ...t, state: /** @type {const} */ ("done"), endsAt: null, remainingMs: 0 };
      rang.push(key);
    }
  }
  return rang.length === 0 ? { run, rang } : { run: { ...run, timers }, rang };
}

/** "2:05", "1:30:00": a countdown in the form a person reads at the bench. @param {number} ms */
export function clock(ms) {
  const total = Math.ceil(Math.max(0, ms) / 1000);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  return h > 0
    ? `${h}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`
    : `${m}:${String(s).padStart(2, "0")}`;
}

/** How far along a run is, over the steps the procedure has. @param {Run} run @param {Array<number | string>} steps */
export function runProgress(run, steps) {
  const done = steps.filter((n) => run.steps[String(n)]?.done).length;
  return { done, total: steps.length };
}

/**
 * The step one-at-a-time view shows (docs/KNOWLEDGE-BASE.md, R4, the cook view): the one the person chose, while it is still a
 * step of the procedure; else the first not yet done; else the last, so a finished run still shows a step.
 *
 * @param {Run} run
 * @param {string[]} keys every step's key, in the page's order
 * @param {string | null} chosen
 */
export function shownStep(run, keys, chosen) {
  if (chosen && keys.includes(chosen)) return chosen;
  return keys.find((key) => !run.steps[key]?.done) ?? keys[keys.length - 1] ?? null;
}

/**
 * The step before or after `key`, or null at either end.
 *
 * @param {string[]} keys
 * @param {string} key
 * @param {-1 | 1} by
 */
export function stepBeside(keys, key, by) {
  const at = keys.indexOf(key);
  return at === -1 ? null : (keys[at + by] ?? null);
}

const when = (/** @type {number | null} */ ms) => (ms === null ? "" : new Date(ms).toISOString());

/** The Bioschemas profile a run's download follows (docs/KNOWLEDGE-BASE.md, P4). */
const LAB_PROCESS_PROFILE = "https://bioschemas.org/profiles/LabProcess/0.1-DRAFT";

/**
 * The saved record as a plain object: what a download is, and what survives the browser. Only what the person
 * entered or did, with the procedure's own identity so the record says which version it followed.
 *
 * It is also a Bioschemas LabProcess (P4): runs are private, so this download is the only place one is written. The
 * protocol it executes is named by the `@id` the procedure's page gives its LabProtocol, and its version.
 *
 * A step's `key` is unique in the procedure (its section and its number: numbering restarts in a section that starts
 * its own list), `number` is the one the page prints.
 *
 * @param {Run} run
 * @param {Array<{ key?: string, number: number | string, section?: string, text: string }>} steps
 * @param {string} [origin] the site the run was made on
 */
export function runRecord(run, steps, origin = SITE_ORIGIN) {
  // A run made on a frozen version's page carries its /v/ address; the protocol's identity is its plain page.
  const page = run.path.replace(/\/v\/[^/]+$/, "");
  // The LabProcess node is Prelum's `thing`; the record's own fields follow it as they are, since a null scale or an empty
  // note is part of the saved record's format (RUN_VERSION), not a missing fact.
  return {
    ...thing("LabProcess", {
      "http://purl.org/dc/terms/conformsTo": { "@id": LAB_PROCESS_PROFILE },
      name: `Run of ${run.title}`,
      executesLabProtocol: {
        "@type": "LabProtocol",
        "@id": `${origin}${page}#procedure`,
        name: run.title,
        url: `${origin}${run.path}`,
        ...(run.version ? { version: run.version } : {}),
      },
      startTime: when(run.startedAt),
      ...(run.finishedAt !== null ? { endTime: when(run.finishedAt) } : {}),
      ...(run.note.trim() ? { description: run.note.trim() } : {}),
      ...(run.scale !== null
        ? { parameterValue: [{ "@type": "PropertyValue", name: "Scale", value: run.scale }] }
        : {}),
    }),
    record: "dustinedwards.info run",
    format: RUN_VERSION,
    procedure: { path: run.path, title: run.title, version: run.version },
    scale: run.scale,
    startedAt: when(run.startedAt),
    finishedAt: when(run.finishedAt),
    note: run.note,
    steps: steps.map((s) => {
      const st = stepOf(run, s.key ?? s.number);
      return {
        step: s.number,
        section: s.section ?? "",
        text: s.text,
        done: st.done,
        doneAt: when(st.doneAt),
        note: st.note,
      };
    }),
  };
}

/**
 * The same record as plain Markdown, for a notebook or an email: a heading, the run's facts, and each step as a
 * checked or unchecked line with its note under it.
 *
 * @param {Run} run
 * @param {Array<{ key?: string, number: number | string, section?: string, text: string }>} steps
 */
export function runMarkdown(run, steps) {
  const lines = [`# Run: ${run.title}`, ""];
  lines.push(`Protocol: ${run.path}${run.version ? `, version ${run.version}` : ""}`);
  if (run.scale !== null) lines.push(`Scale: ${run.scale}`);
  lines.push(`Started: ${when(run.startedAt)}`);
  if (run.finishedAt !== null) lines.push(`Finished: ${when(run.finishedAt)}`);
  if (run.note.trim()) lines.push("", run.note.trim());
  lines.push("", "## Steps", "");
  let section = "";
  for (const s of steps) {
    if ((s.section ?? "") !== section) {
      section = s.section ?? "";
      if (section) lines.push("", `### ${section}`, "");
    }
    const st = stepOf(run, s.key ?? s.number);
    lines.push(
      `- [${st.done ? "x" : " "}] ${s.number}. ${s.text.replace(/\s+/g, " ").trim()}${st.done && st.doneAt ? ` (${when(st.doneAt)})` : ""}`,
    );
    if (st.note.trim()) lines.push(`  - Note: ${st.note.trim().replace(/\n+/g, " ")}`);
  }
  return `${lines.join("\n")}\n`;
}

/**
 * Parses a stored run, or returns null: a stored value from another format or one that is not a run is ignored, never
 * trusted. Only the shapes this module writes are accepted.
 *
 * @param {unknown} raw
 * @returns {Run | null}
 */
export function parseRun(raw) {
  if (typeof raw !== "string") return null;
  let value;
  try {
    value = JSON.parse(raw);
  } catch {
    return null;
  }
  if (!value || typeof value !== "object" || value.v !== RUN_VERSION) return null;
  // typeof null is "object", so a null `steps` must be refused by name.
  const plainObject = (/** @type {unknown} */ x) =>
    x !== null && typeof x === "object" && !Array.isArray(x);
  if (
    typeof value.path !== "string" ||
    typeof value.startedAt !== "number" ||
    !plainObject(value.steps) ||
    !plainObject(value.timers)
  )
    return null;
  return /** @type {Run} */ ({
    v: RUN_VERSION,
    path: value.path,
    version: typeof value.version === "string" ? value.version : "",
    title: typeof value.title === "string" ? value.title : "",
    scale: typeof value.scale === "number" ? value.scale : null,
    startedAt: value.startedAt,
    finishedAt: typeof value.finishedAt === "number" ? value.finishedAt : null,
    note: typeof value.note === "string" ? value.note : "",
    steps: value.steps,
    timers: value.timers,
  });
}

