/*
 * The plaintext redirect itself is site-runtime's `canonicalRedirect` (workers/app.ts). A gateway redirect must never
 * be cached: the scheme is not in the edge key, so HTTPS readers would be redirected to the URL they asked for.
 */

/**
 * 308 for non-GET: a 301 lets a browser turn a POST into a GET and drop the
 * no-script sign-in form's body. Every redirect the gateway answers uses this rule; the post and
 * PDF helpers re-export it under their own names.
 *
 * @param {string} method
 * @returns {number}
 */
export function httpsRedirectStatus(method) {
  const m = String(method ?? "").toUpperCase();
  return m === "GET" || m === "HEAD" ? 301 : 308;
}

app/lib/identity.mjs.source:
// The owner's identity, derived from the CV (docs/CV.md): the one-line role, the Person record's job title, the
// headship, the department and the university. content/cv/profile.md holds the person (name, degree, discipline,
// department, organization) and content/cv/appointments.md holds what he is appointed to, so a change to either
// changes every place the site states them: the site settings (app/lib/seo.ts), page titles, the About text, the
// CV's own header and the structured data. scripts/build-identity.mjs runs this over the files at build and
// writes app/lib/identity.generated.mjs, which those places import.
//
// Pure and dependency-free, so the build, the CV compile and the tests share one definition.

/** The CV's section of ranks and positions, and its section of headships and other leadership. */
const POSITIONS_SECTION = "Positions";
const ADMIN_SECTION = "Administrative and leadership";

/**
 * "a", "a and b", "a, b, and c".
 *
 * @param {string[]} items
 */
export function joinList(items) {
  if (items.length <= 1) return items.join("");
  if (items.length === 2) return `${items[0]} and ${items[1]}`;
  return `${items.slice(0, -1).join(", ")}, and ${items[items.length - 1]}`;
}

/**
 * @typedef {{ name: string, degree: string, discipline: string, department: string, org: string }} IdentityPerson
 * @typedef {{ type?: string, section?: string, title?: string, endYear?: number | "present" | null, headline?: boolean }} IdentityEntry
 *
 * @typedef {{
 *   name: string,
 *   degree: string,
 *   discipline: string,
 *   disciplineLower: string,
 *   rank: string,
 *   role: string,
 *   adminTitles: string[],
 *   adminTitle: string,
 *   jobTitle: string,
 *   cvTitle: string,
 *   department: string,
 *   departmentSubject: string,
 *   org: string,
 *   affiliation: string,
 * }} Identity
 */

/**
 * What the CV states he is now: the one current position (its rank is the first half of the role), every current
 * administrative title (the headship), and the person's discipline (the second half). Returns every problem, so
 * a CV edit that would leave the site with no role is refused where it is made.
 *
 * `role` is "<rank> and <discipline>" ("Professor and Virologist"). `jobTitle` is the Person record's, which also
 * carries the headship ("Virologist, Professor, and Department Head"). `cvTitle` is the CV header's line.
 *
 * @param {IdentityPerson} person
 * @param {IdentityEntry[]} entries every CV entry; only the appointments are read
 * @returns {{ ok: false, errors: string[] } | { ok: true, identity: Identity }}
 */
export function deriveIdentity(person, entries) {
  /** @type {string[]} */
  const errors = [];
  const current = (/** @type {string} */ section, /** @type {boolean} */ headlineOnly) =>
    entries
      .filter(
        (e) =>
          e.type === "appointment" &&
          e.section === section &&
          e.endYear === "present" &&
          typeof e.title === "string" &&
          (!headlineOnly || e.headline === true),
      )
      .map((e) => /** @type {string} */ (e.title));
  const positions = current(POSITIONS_SECTION, false);
  // Only the leadership entries marked `headline: true` are stated beside the role; the rest stay on the CV alone.
  const adminTitles = current(ADMIN_SECTION, true);
  if (positions.length !== 1) {
    errors.push(
      `the CV states ${positions.length} current positions (section "${POSITIONS_SECTION}", endYear present); the site's one-line role is built from exactly one`,
    );
  }
  for (const key of /** @type {const} */ (["name", "degree", "discipline", "department", "org"])) {
    if (typeof person?.[key] !== "string" || person[key].trim() === "")
      errors.push(`the profile's person.${key} is missing`);
  }
  if (errors.length > 0) return { ok: false, errors };

  const rank = /** @type {string} */ (positions[0]);
  const role = `${rank} and ${person.discipline}`;
  return {
    ok: true,
    identity: {
      name: person.name,
      degree: person.degree,
      discipline: person.discipline,
      disciplineLower: person.discipline.toLowerCase(),
      rank,
      role,
      adminTitles,
      adminTitle: joinList(adminTitles),
      jobTitle: joinList([person.discipline, rank, ...adminTitles]),
      cvTitle: [role, ...adminTitles].join(", "),
      department: person.department,
      departmentSubject: person.department.replace(/^Department of /, ""),
      org: person.org,
      // The university alone: the profile's organization carries its system after a comma.
      affiliation: (person.org.split(",")[0] ?? person.org).trim(),
    },
  };
}

app/lib/phages/catalog.mjs.source:
// The phage table's one declaration (docs/PHAGES.md): the fields a phage is searched, filtered, sorted and listed by,
// declared once for Capsomer's catalog. The table on /research/phages, its search and facets, and its counts all read
// this, so a field is described here and nowhere else. Pure: the route passes in the rows it read from D1. The page's
// markdown table (the twin, the search records, the invariants) is still written from the same rows by compile.mjs.

import { defineCatalog, parseCatalogParams, queryCatalog } from "capsomer/behavior/catalog";

import { foldText } from "../cv/view.mjs";
import { HOSTS, PHAGES_PAGE_PATH, phageSlug } from "./compile.mjs";

/** @typedef {import("./compile.mjs").Phage} Phage */

/** A host as a facet option and a cell read it, without the markdown emphasis the page's text carries. @param {string} key */
export function hostLabel(key) {
  const host = /** @type {Record<string, { long: string }>} */ (HOSTS)[key];
  return host ? host.long.replaceAll("*", "") : key;
}

/** The page's own order: year, then name, folded so case and accents do not matter (the same as `sortPhages`). @param {Phage} a @param {Phage} b */
const byYearThenName = (a, b) =>
  a.year - b.year || foldText(a.name).localeCompare(foldText(b.name), "en", { numeric: true });

export const PHAGES = defineCatalog(
  /** @type {import("capsomer/behavior/catalog").CatalogDefinition<Phage>} */ ({
    id: "phages",
    noun: ["phage", "phages"],
    basePath: PHAGES_PAGE_PATH,
    itemKey: (p) => phageSlug(p.name),
    // Year, then name: what the page has always listed. The year's own comparison carries the name tie-break.
    defaultSort: "year",
    fields: [
      {
        key: "name",
        label: "Name",
        value: (p) => p.name,
        search: 3,
        sort: true,
        column: { header: "Phage" },
      },
      { key: "formerly", label: "Formerly", value: (p) => p.formerly, search: 1 },
      {
        key: "year",
        label: "Year",
        value: (p) => p.year,
        type: "number",
        sort: { compare: byYearThenName, labels: { asc: "oldest first", desc: "newest first" } },
        facet: { kind: "many", order: "alpha", limit: 6 },
        column: { header: "Year", align: "end" },
      },
      {
        key: "host",
        label: "Host",
        value: (p) => p.host,
        facet: { kind: "many", general: true, label: hostLabel },
        column: { header: "Host", drop: 1 },
      },
      {
        key: "county",
        label: "County",
        value: (p) => p.county,
        search: 1,
        facet: { kind: "many", order: "alpha" },
        column: { header: "County", drop: 2 },
      },
      {
        key: "phagesdb",
        label: "PhagesDB",
        value: (p) => p.phagesdb,
        column: { header: "PhagesDB", drop: 2 },
      },
      {
        key: "paper",
        label: "Genome paper",
        value: (p) => (p.paper ? "published" : null),
        facet: { kind: "one", label: () => "Published" },
        column: { header: "Paper", drop: 2 },
      },
    ],
  }),
);

/**
 * The page's state for an address.
 *
 * @param {URLSearchParams | string} params
 * @param {Phage[]} phages every phage
 */
export function phageListing(params, phages) {
  return queryCatalog(PHAGES, phages, parseCatalogParams(PHAGES, params));
}

app/lib/publications/parse.mjs.source:
// Reads a publication file (docs/PUBLICATIONS.md) into the front matter as written and the one body
// section it may carry, the extracted full text. Nothing here judges: validate.mjs does, so the check and
// the save tool read one parse.

import matter from "gray-matter";

import { yamlPlain } from "../yaml-plain.mjs";

export const PUBLICATIONS_DIR = "content/publications";

/** The repository path of a publication's file. */
export function publicationPath(/** @type {string} */ slug) {
  return `${PUBLICATIONS_DIR}/${slug}.md`;
}

/** The only heading the body may carry. Everything after it is the PDF's extracted text. */
export const FULL_TEXT_HEADING = "## Full text";

const FULL_TEXT_LINE = /^## Full text[ \t]*$/m;

/**
 * @typedef {{ data: Record<string, unknown>, fullText: string | null, problems: string[] }} ParsedPublication
 */

/**
 * @param {{ file: string, raw: string }} input
 * @returns {ParsedPublication} `fullText` is null when the file has no Full text section, and a string (possibly empty) when it has.
 */
export function parsePublication({ file, raw }) {
  /** @type {string[]} */
  const problems = [];
  /** @type {Record<string, unknown>} */
  let data = {};
  let content = "";
  try {
    // An options object, even an empty one: gray-matter caches by input when it is omitted, and a
    // cached parse is one object shared by every caller.
    const parsed = matter(raw, {});
    data = /** @type {Record<string, unknown>} */ (yamlPlain(parsed.data));
    content = parsed.content;
  } catch (error) {
    problems.push(
      `${file}: the front matter does not parse: ${error instanceof Error ? error.message.split("\n")[0] : String(error)}`,
    );
    return { data, fullText: null, problems };
  }
  if (!raw.startsWith("---")) {
    problems.push(`${file}: the file must start with a --- front matter block`);
  }

  const heading = FULL_TEXT_LINE.exec(content);
  if (!heading) {
    if (content.trim() !== "") {
      problems.push(
        `${file}: the body carries text outside a "${FULL_TEXT_HEADING}" section. The abstract belongs in front matter, and the body holds only the PDF's extracted text under that heading.`,
      );
    }
    return { data, fullText: null, problems };
  }
  const before = content.slice(0, heading.index).trim();
  if (before !== "") {
    problems.push(
      `${file}: the body carries text before the "${FULL_TEXT_HEADING}" heading. The abstract belongs in front matter, and the body holds only the PDF's extracted text.`,
    );
  }
  const fullText = content.slice(heading.index + heading[0].length).trim();
  return { data, fullText, problems };
}

app/lib/publications/serialize.mjs.source:
// Writes a publication file: the front matter in one fixed key order, every string double quoted (YAML's
// double-quoted style is a superset of JSON strings, so JSON.stringify is the escaper and no value can be
// read back as a date, a boolean or a number it was not). Used by the one-time migration, by the PDF text
// extractor, which rewrites a file's Full text section in place, and by the tests.

import { FULL_TEXT_HEADING } from "./parse.mjs";

/** Canonical order. A key not listed here is a key the validator refuses. */
const FRONT_MATTER_KEYS = [
  "doi",
  "slug",
  "id",
  "status",
  "draft",
  "type",
  "title",
  "authors",
  "journal",
  "publishedDate",
  "year",
  "volume",
  "issue",
  "pages",
  "topics",
  "access",
  "pdfPath",
  "pdfSha256",
  "externalUrl",
  "pmid",
  "pmcid",
  "pmcUrl",
  "preprintDoi",
  "isOpenAccess",
  "license",
  "licenseSource",
  "summary",
  "selected",
  "accessions",
  "updateNotice",
  "abstract",
  "csl",
];

const PLAIN_KEY = /^[A-Za-z0-9_][A-Za-z0-9_-]*$/;

/** @param {unknown} value */
const isScalar = (value) =>
  value === null || ["string", "number", "boolean"].includes(typeof value);

/** @param {unknown} value */
function scalar(value) {
  if (value === null) return "null";
  return typeof value === "string" ? JSON.stringify(value) : String(value);
}

/** @param {string} key */
const keyText = (key) => (PLAIN_KEY.test(key) ? key : JSON.stringify(key));

/**
 * @param {string} key
 * @param {unknown} value
 * @param {number} indent
 * @returns {string[]}
 */
function entry(key, value, indent) {
  const pad = " ".repeat(indent);
  const k = keyText(key);
  if (isScalar(value)) return [`${pad}${k}: ${scalar(value)}`];
  if (Array.isArray(value)) {
    if (value.length === 0) return [`${pad}${k}: []`];
    if (value.every(isScalar))
      return [`${pad}${k}:`, ...value.map((v) => `${pad}  - ${scalar(v)}`)];
    if (value.every((v) => v && typeof v === "object" && !Array.isArray(v))) {
      return [
        `${pad}${k}:`,
        ...value.flatMap((item) => {
          const lines = block(/** @type {Record<string, unknown>} */ (item), indent + 4);
          if (lines.length === 0) return [`${pad}  - {}`];
          // The first line of the mapping rides on the dash: "- " is the two columns the indent gained.
          return [`${pad}  - ${(lines[0] ?? "").slice(indent + 4)}`, ...lines.slice(1)];
        }),
      ];
    }
    // Arrays of arrays (a date-parts triple): one line of flow style, which is JSON.
    return [`${pad}${k}: ${JSON.stringify(value)}`];
  }
  const lines = block(/** @type {Record<string, unknown>} */ (value), indent + 2);
  return lines.length === 0 ? [`${pad}${k}: {}`] : [`${pad}${k}:`, ...lines];
}

/**
 * @param {Record<string, unknown>} object
 * @param {number} indent
 * @returns {string[]}
 */
function block(object, indent) {
  return Object.entries(object).flatMap(([key, value]) =>
    value === undefined ? [] : entry(key, value, indent),
  );
}

/**
 * @param {Record<string, unknown>} data front matter fields; null and undefined values are left out
 * @param {string | null} fullText the extracted text, or null for a file with no Full text section
 * @returns {string}
 */
export function renderPublicationFile(data, fullText) {
  const known = new Set(FRONT_MATTER_KEYS);
  const unknown = Object.keys(data).filter((key) => !known.has(key));
  if (unknown.length > 0)
    throw new Error(`renderPublicationFile: not front matter fields: ${unknown.join(", ")}`);
  const lines = FRONT_MATTER_KEYS.flatMap((key) => {
    const value = data[key];
    return value === null || value === undefined ? [] : entry(key, value, 0);
  });
  const head = ["---", ...lines, "---", ""].join("\n");
  return fullText === null ? head : `${head}\n${FULL_TEXT_HEADING}\n\n${fullText}\n`;
}

app/lib/publications/update-notice.mjs.source:
// No record carries a notice today; the path is built cold so a correction needs only a data change,
// and a test drives it with a real retracted DOI. The paper carries updated-by (the notice carries
// update-to), so the DOI here is the notice's.

export const UPDATE_TYPES = /** @type {const} */ ([
  "retraction",
  "correction",
  "expression-of-concern",
]);

const LABEL = {
  retraction: "Retracted",
  correction: "Corrected",
  "expression-of-concern": "Expression of concern",
};

/**
 * @typedef {object} UpdateNotice
 * @property {string} type one of UPDATE_TYPES
 * @property {string} doi the NOTICE's DOI, not the paper's
 * @property {string | null} [date] YYYY-MM-DD, as deposited
 */

/**
 * A reason, not a boolean, so the gate can say which part of a notice is malformed.
 *
 * @param {unknown} value
 * @returns {string | null} null when the notice is usable
 */
export function updateNoticeProblem(value) {
  if (value === null || value === undefined) return null;
  if (typeof value !== "object") return "not an object";
  const notice = /** @type {Record<string, unknown>} */ (value);
  if (!UPDATE_TYPES.includes(/** @type {any} */ (notice.type))) {
    return `type ${JSON.stringify(notice.type)} is not one of ${UPDATE_TYPES.join(", ")}`;
  }
  // Shape only: checking existence would put a network call in a gate.
  if (typeof notice.doi !== "string" || !/^10\.\d{4,9}\/\S+$/.test(notice.doi)) {
    return `doi ${JSON.stringify(notice.doi)} is not a DOI name`;
  }
  if (
    notice.date !== null &&
    notice.date !== undefined &&
    !(typeof notice.date === "string" && /^\d{4}-\d{2}-\d{2}$/.test(notice.date))
  ) {
    return `date ${JSON.stringify(notice.date)} is not YYYY-MM-DD`;
  }
  return null;
}

/**
 * Links to the notice's own DOI, the only honest citation for it. The deposited date is in the sentence
 * so an undated retraction is not read as recent.
 *
 * @param {UpdateNotice} notice
 * @returns {{ label: string, sentence: string, url: string }}
 */
export function updateNoticeText(notice) {
  const problem = updateNoticeProblem(notice);
  if (problem) {
    // Every caller passed the gate, so data changed under a green build; a 500 beats a half-rendered notice.
    throw new Error(`unusable update notice: ${problem}`);
  }
  const label = LABEL[/** @type {keyof typeof LABEL} */ (notice.type)];
  const when = notice.date ? ` on ${notice.date}` : "";
  return {
    label,
    sentence:
      notice.type === "expression-of-concern"
        ? `The publisher has issued an expression of concern about this paper${when}.`
        : `This paper was ${label.toLowerCase()}${when} by the publisher.`,
    url: `https://doi.org/${notice.doi}`,
  };
}

