app/lib/webmention/urls.mjs.source:
import { SLUG_PATTERN } from "../content/slug.mjs";

// Pure so node:test can reach it (the route imports `~/lib/context`). Allowed origins are passed in, never
// a constant: the site answers on two hosts across the cutover. The slug uses the imported `SLUG_PATTERN`;
// a local regex would fail silently in the permissive direction.

const BLOG_PREFIX = "/writing/";

/**
 * Null for every rejection: distinct refusals would let a caller map this site's URL space.
 *
 * @param {string} target the `target` field, verbatim
 * @param {readonly string[]} allowedOrigins origins this site answers on
 * @returns {string | null} the post slug, or null
 */
export function targetSlug(target, allowedOrigins) {
  let url;
  try {
    url = new URL(target);
  } catch {
    return null;
  }
  if (url.protocol !== "https:" && url.protocol !== "http:") return null;
  if (!allowedOrigins.includes(url.origin)) return null;

  // `new URL` has already resolved dot segments and decoded the path, so only prefix and shape remain.
  if (!url.pathname.startsWith(BLOG_PREFIX)) return null;
  const rest = url.pathname.slice(BLOG_PREFIX.length);
  // A trailing slash is the same post; anything with a further segment is not.
  const slug = rest.endsWith("/") ? rest.slice(0, -1) : rest;
  if (!SLUG_PATTERN.test(slug)) return null;
  return slug;
}

/**
 * IPv6 reaches `hostname` bracketed. `http://2130706433/` stays all digits, so the digits arm catches it.
 *
 * @param {string} hostname
 */
function isIpLiteral(hostname) {
  if (hostname.startsWith("[")) return true;
  if (/^[0-9]+$/.test(hostname)) return true;
  return /^[0-9]{1,3}(?:\.[0-9]{1,3}){3}$/.test(hostname);
}

/**
 * RFC 6761 reserves the whole `.localhost` tree, and some resolvers honor it.
 *
 * @param {string} hostname
 */
function isLoopbackName(hostname) {
  const host = hostname.toLowerCase();
  return host === "localhost" || host.endsWith(".localhost");
}

const SOURCE_REFUSALS = {
  unparseable: "source is not an absolute URL",
  protocol: "source must be http or https",
  selfOrigin: "source must be another site",
  ipLiteral: "source must name a host, not an IP address",
  loopback: "source must not be a loopback address",
  sameAsTarget: "source and target must differ",
};

/**
 * The verifier fetches the source, so these refusals bound SSRF. NOT a complete defense: public DNS can
 * resolve to a private address. The runtime bounds the rest: a Worker's `fetch` has no private network
 * or metadata endpoint, and the verifier reads at most 1 MB and stores no markup.
 *
 * @param {string} source the `source` field, verbatim
 * @param {string} target the `target` field, verbatim
 * @param {readonly string[]} allowedOrigins origins this site answers on
 * @returns {{ ok: true } | { ok: false, reason: string }}
 */
export function sourceVerdict(source, target, allowedOrigins) {
  let url;
  try {
    url = new URL(source);
  } catch {
    return { ok: false, reason: SOURCE_REFUSALS.unparseable };
  }
  if (url.protocol !== "https:" && url.protocol !== "http:") {
    return { ok: false, reason: SOURCE_REFUSALS.protocol };
  }
  if (allowedOrigins.includes(url.origin)) {
    return { ok: false, reason: SOURCE_REFUSALS.selfOrigin };
  }
  if (isLoopbackName(url.hostname)) {
    return { ok: false, reason: SOURCE_REFUSALS.loopback };
  }
  if (isIpLiteral(url.hostname)) {
    return { ok: false, reason: SOURCE_REFUSALS.ipLiteral };
  }
  if (source === target) {
    return { ok: false, reason: SOURCE_REFUSALS.sameAsTarget };
  }
  return { ok: true };
}

/**
 * A trailing slash and the fragment are ignored; the QUERY is not, because a query can name a different
 * document (the `/writing` index filters with one).
 *
 * @param {string} href an absolute URL, already resolved against the source
 * @param {string} target the target URL
 */
export function sameDocument(href, target) {
  let a;
  let b;
  try {
    a = new URL(href);
    b = new URL(target);
  } catch {
    return false;
  }
  const strip = (/** @type {URL} */ u) =>
    `${u.origin}${u.pathname.endsWith("/") ? u.pathname.slice(0, -1) : u.pathname}${u.search}`;
  return strip(a) === strip(b);
}

// One owner; the schema comment points here.
const EXCERPT_MAX_CHARS = 280;

/**
 * Plain text by construction: the caller passes `textContent`. This is not a sanitizer.
 *
 * @param {string} text
 */
export function collapseExcerpt(text) {
  const flat = text.replace(/\s+/g, " ").trim();
  return flat.length > EXCERPT_MAX_CHARS ? flat.slice(0, EXCERPT_MAX_CHARS) : flat;
}

/**
 * Checked again at RENDER: a row can outlive the code that wrote it or be hand-written, and a wrong `href`
 * is executable. Null means render the name without a link. Returns the parser's output, not the input.
 *
 * @param {string | null | undefined} value
 * @returns {string | null}
 */
export function safeHttpHref(value) {
  if (!value) return null;
  let url;
  try {
    url = new URL(value);
  } catch {
    return null;
  }
  if (url.protocol !== "https:" && url.protocol !== "http:") return null;
  return url.href;
}

app/kb/procedures/compile.mjs.source:
// One door from a procedure file to everything derived from it: parse, validate, render, the markdown
// twin and the search input. check:protocols, sync:content and the operator API's save_procedure all
// call compileProcedure, so a file CI passes is the file the save tool accepts and the page draws.

import { gitBlobSha } from "../../lib/content/hashes.mjs";
import { itemPath } from "../registry/catalog.mjs";
import { NON_STRAIN_ORGANISMS } from "./taxonomy.mjs";
import { parseProcedure, procedurePath } from "./parse.mjs";
import { procedureSearchInput, renderProcedure } from "./render.mjs";
import { validateProcedure } from "./validate.mjs";

/** The file name a slug is written in; the same rule as a post's. */
const PROCEDURE_SLUG = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

/**
 * @param {{
 *   slug: string,
 *   raw: string,
 *   pipeline: { renderBody: import("./render.mjs").RenderBody, findWideDashes: (text: string) => Array<{ line: number, column: number, char: string, excerpt: string }> },
 *   resolveImage?: (src: string) => Promise<{ width: number, height: number }>,
 *   registry?: {
 *     primers: (ids: string[]) => Promise<Map<string, import("./render.mjs").StoredPrimer>>,
 *     strains: (ids: string[]) => Promise<Map<string, import("./render.mjs").StoredStrain>>,
 *     reagents: (ids: string[]) => Promise<Map<string, import("./render.mjs").StoredReagent>>,
 *     equipment: (ids: string[]) => Promise<Map<string, import("./render.mjs").StoredEquipment>>,
 *   },
 * }} input
 * @returns {Promise<
 *   | { ok: false, errors: string[], gaps: Array<{ field: string, reason: string }> }
 *   | { ok: true, errors: [], gaps: Array<{ field: string, reason: string }>, record: import("./render.mjs").ProcedureRecord,
 *       markdown: string, searchInput: ReturnType<typeof procedureSearchInput>, sourcePath: string, sourceBlobSha: string }
 * >}
 */
export async function compileProcedure({ slug, raw, pipeline, resolveImage, registry }) {
  if (!PROCEDURE_SLUG.test(slug)) {
    return { ok: false, errors: [`"${slug}" is not a lowercase kebab-case slug`], gaps: [] };
  }
  const file = procedurePath(slug);
  const dashes = pipeline
    .findWideDashes(raw)
    .map(
      (hit) =>
        `line ${hit.line}, column ${hit.column}: wide dash ${hit.char}; house style uses commas, periods, parentheses or colons ("${hit.excerpt}")`,
    );
  const parsed = parseProcedure({ file, raw });
  // A protocol names its primers by their id in the lab registry and stores no sequence (docs/REGISTRY.md); the registry's
  // rows are read here, so the record carries them and a frozen version freezes them. A caller with no registry cannot
  // compile a protocol that names primers: writing a record with no primer table would be silent.
  const named = Array.isArray(parsed.data.primers)
    ? parsed.data.primers.flatMap((p) => (typeof p?.primer === "string" ? [p.primer] : []))
    : [];
  const namedStrains = Array.isArray(parsed.data.host_strain)
    ? parsed.data.host_strain.flatMap((s) => (typeof s?.strain === "string" ? [s.strain] : []))
    : [];
  // An organism that is not a non-strain organism is a strain of the registry, so it is read from there too.
  const organismIds = Array.isArray(parsed.data.organism)
    ? parsed.data.organism.filter(
        (id) => typeof id === "string" && !Object.hasOwn(NON_STRAIN_ORGANISMS, id),
      )
    : [];
  // A material that is a reagent of the registry names it by id; its facts are the registry's, not typed in the protocol.
  const namedReagents = Array.isArray(parsed.data.materials)
    ? parsed.data.materials.flatMap((m) => (typeof m?.reagent === "string" ? [m.reagent] : []))
    : [];
  // An equipment entry that is an item of the registry names it by id.
  const namedEquipment = Array.isArray(parsed.data.equipment)
    ? parsed.data.equipment.flatMap((e) => (typeof e?.equipment === "string" ? [e.equipment] : []))
    : [];
  if (
    (named.length > 0 ||
      namedStrains.length > 0 ||
      organismIds.length > 0 ||
      namedReagents.length > 0 ||
      namedEquipment.length > 0) &&
    !registry
  ) {
    return {
      ok: false,
      errors: [
        "this compile was given no lab registry, so the primers, host strains, organisms, reagents and equipment the file names cannot be read",
      ],
      gaps: [],
    };
  }
  const primerRows = named.length > 0 && registry ? await registry.primers(named) : new Map();
  const strainIds = [...new Set([...namedStrains, ...organismIds])];
  const strainRows =
    strainIds.length > 0 && registry ? await registry.strains(strainIds) : new Map();
  const equipmentIds = [...new Set(namedEquipment)];
  const equipmentRows =
    equipmentIds.length > 0 && registry ? await registry.equipment(equipmentIds) : new Map();
  const reagentIds = [...new Set(namedReagents)];
  const reagentRows =
    reagentIds.length > 0 && registry ? await registry.reagents(reagentIds) : new Map();
  const { errors, gaps } = validateProcedure(parsed, {
    slug,
    primers: new Set(primerRows.keys()),
    strains: new Set(strainRows.keys()),
    reagents: new Set(reagentRows.keys()),
    equipment: new Set(equipmentRows.keys()),
  });
  // A draft primer is the admin's alone, so a published protocol may not print it.
  if (parsed.data.draft !== true) {
    for (const [id, row] of primerRows)
      if (row.status === "draft")
        errors.push(
          `primers[${id}] is a draft in the lab registry, so a published protocol cannot print it`,
        );
    for (const [id, row] of strainRows)
      if (row.status === "draft")
        errors.push(
          `strain ${id} is a draft in the lab registry, so a published protocol cannot name it`,
        );
    for (const [id, row] of reagentRows)
      if (row.status === "draft")
        errors.push(
          `reagent ${id} is a draft in the lab registry, so a published protocol cannot name it`,
        );
    for (const [id, row] of equipmentRows)
      if (row.status === "draft")
        errors.push(
          `equipment ${id} is a draft in the lab registry, so a published protocol cannot name it`,
        );
  }
  errors.unshift(...dashes);
  if (errors.length > 0) return { ok: false, errors, gaps };

  let record;
  try {
    record = await renderProcedure({
      slug,
      parsed,
      gaps,
      renderBody: pipeline.renderBody,
      resolveImage,
      primerRows: named.flatMap((id) => (primerRows.has(id) ? [primerRows.get(id)] : [])),
      // The strain's page is where the protocol links it, computed from its id here and not typed anywhere.
      strainRows: namedStrains.flatMap((id) =>
        strainRows.has(id) ? [{ ...strainRows.get(id), path: itemPath("strain", id) }] : [],
      ),
      // The reagents the materials name, as the registry states them, so the table shows where each comes from and types none.
      reagentRows: reagentIds.flatMap((id) => (reagentRows.has(id) ? [reagentRows.get(id)] : [])),
      // The equipment the list names, as the registry states it, so the table shows who makes each and types none.
      equipmentRows: equipmentIds.flatMap((id) =>
        equipmentRows.has(id) ? [equipmentRows.get(id)] : [],
      ),
      // The words for each organism id the protocol names, from the registry (or the non-strain list), so the library needs no list of its own.
      organismNames: Object.fromEntries(
        (Array.isArray(parsed.data.organism) ? parsed.data.organism : []).flatMap((id) => {
          const words = Object.hasOwn(NON_STRAIN_ORGANISMS, id)
            ? /** @type {Record<string, string>} */ (NON_STRAIN_ORGANISMS)[id]
            : strainRows.get(id)?.organism;
          return words ? [[id, words]] : [];
        }),
      ),
    });
  } catch (error) {
    return { ok: false, errors: [error instanceof Error ? error.message : String(error)], gaps };
  }
  const searchInput = procedureSearchInput(record, parsed);
  return {
    ok: true,
    errors: [],
    gaps,
    record,
    markdown: searchInput.markdown,
    searchInput,
    sourcePath: file,
    sourceBlobSha: await gitBlobSha(raw),
  };
}

app/kb/procedures/json-ld.mjs.source:
// The structured data a procedure page carries, from its D1 record: Bioschemas LabProtocol for a protocol
// (https://bioschemas.org/profiles/LabProtocol/0.9-DRAFT; every LabProtocol version is a draft), schema.org Recipe for a
// recipe, following Google's recipe structured-data guidance, and schema.org HowTo for a computational procedure, the closest type
// for a sequence of commands with tools and supplies. Only facts the record states: a gap stays out.

import { thing } from "@drdustinedwards/site-helpers/schema";
import { isoDuration } from "@drdustinedwards/site-helpers/text";

import { citeFacts } from "./cite.mjs";
import { readConditions } from "./marks.mjs";

const LAB_PROTOCOL_PROFILE = "https://bioschemas.org/profiles/LabProtocol/0.9-DRAFT";

/** A number as a step writes it: "13,000" is 13000. @param {string} n */
const numeral = (n) => Number(n.replaceAll(",", ""));

/**
 * The protocol's conditions as 0.9-DRAFT's `parameter` (docs/KNOWLEDGE-BASE.md, P4): every temperature and spin its steps
 * state, once each, in the order first stated. The profile puts them on the protocol as a whole, not on a step, and these
 * are the conditions the compile already reads (marks.mjs readConditions): from a step's words, and the g-force its
 * SPIN flag states. Nothing is typed twice.
 *
 * @param {import("./render.mjs").ProcedureRecord} record
 */
export function protocolParameters(record) {
  // Keyed by the condition, so one stated in several steps is one parameter, at the place it was first stated.
  /** @type {Map<string, Record<string, unknown>>} */
  const seen = new Map();
  for (const section of record.sections) {
    for (const block of section.blocks) {
      if (block.type !== "steps") continue;
      for (const step of block.steps) {
        // A row compiled before the conditions were stored has none until the next sync rewrites it.
        for (const t of step.temperatures ?? []) {
          seen.set(`t:${t.min}:${t.max}`, {
            "@type": "PropertyValue",
            name: "Temperature",
            ...(t.min === t.max ? { value: t.min } : { minValue: t.min, maxValue: t.max }),
            unitCode: "CEL",
            unitText: "°C",
          });
        }
        const flagged = (step.spin ?? []).flatMap((s) => readConditions(s).spins);
        for (const spin of [...(step.spins ?? []), ...flagged]) {
          const [low = "", high] = spin.speed.split(/\s*to\s*/);
          const range =
            high === undefined
              ? { value: numeral(low) }
              : { minValue: numeral(low), maxValue: numeral(high) };
          seen.set(`s:${spin.speed}:${spin.unit}`, {
            "@type": "PropertyValue",
            name: spin.unit === "rpm" ? "Rotor speed" : "Relative centrifugal force",
            ...range,
            unitText: spin.unit === "rpm" ? "rpm" : "x g",
          });
        }
      }
    }
  }
  return [...seen.values()];
}

/**
 * The procedure a variant was copied from, as `isBasedOn` names it (P3): its address, at the version copied when there is
 * a frozen copy of it, and its title. Resolved at request time from the parent's row (lineage.server.ts).
 *
 * @param {import("./lineage.mjs").Lineage | null} lineage
 * @param {string} origin
 */
function lineageWork(lineage, origin) {
  if (!lineage?.href) return [];
  return [
    {
      "@type": "CreativeWork",
      name: lineage.title,
      url: `${origin}${lineage.href}`,
      ...(lineage.version ? { version: lineage.version } : {}),
    },
  ];
}

/** @param {string | null | undefined} html */
function text(html) {
  return String(html ?? "")
    .replace(/<[^>]+>/g, "")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#x27;|&#39;/g, "'")
    .replace(/\s+/g, " ")
    .trim();
}

/**
 * "20 minutes", "1.5 hours" as ISO 8601; null for anything else.
 *
 * @param {string | null} value
 */
function minutesToIso(value) {
  const m = /^(\d+(?:\.\d+)?) (minutes?|hours?)$/.exec(String(value ?? ""));
  if (!m) return null;
  const minutes = Math.round(Number(m[1]) * (m[2]?.startsWith("hour") ? 60 : 1));
  return isoDuration(minutes * 60) ?? "PT0M";
}

/**
 * @param {import("./render.mjs").ProcedureRecord} record
 * @param {string} origin
 * @param {{ "@type": string, "@id": string, name: string, url: string }} person
 * @param {import("./lineage.mjs").Lineage | null} [lineage] the procedure this one is a variant of
 */
export function procedureJsonLd(record, origin, person, lineage = null) {
  const url = `${origin}${record.path}`;
  const steps = record.sections.flatMap((section) => {
    const items = section.blocks.flatMap((b) => (b.type === "steps" ? b.steps : []));
    if (items.length === 0) return [];
    return [
      {
        "@type": "HowToSection",
        name: section.title,
        itemListElement: items.map((step) => ({
          "@type": "HowToStep",
          position: step.number,
          text: step.text,
          url: `${url}#${section.id}`,
          ...(step.photos[0] ? { image: `${origin}${step.photos[0].src}` } : {}),
        })),
      },
    ];
  });
  const basedOn = [
    ...lineageWork(lineage, origin),
    ...record.basedOn.map((s) => ({
      "@type": "CreativeWork",
      name: s.citation,
      ...(s.doi
        ? { identifier: `https://doi.org/${s.doi}`, url: `https://doi.org/${s.doi}` }
        : s.url
          ? { url: s.url }
          : {}),
    })),
  ];
  const cite = citeFacts(record);
  // Prelum's `thing` writes the context and the type, then these, and drops an empty field.
  const common = {
    "@id": `${url}#procedure`,
    name: record.title,
    description: record.description,
    url,
    author: person,
    ...(record.updated ? { dateModified: record.updated } : {}),
    ...(record.version ? { version: record.version } : {}),
    ...(cite?.doi ? { identifier: `https://doi.org/${cite.doi}` } : {}),
    ...(basedOn.length ? { isBasedOn: basedOn } : {}),
    ...(record.references.length ? { citation: record.references.map(text) } : {}),
  };

  if (record.profile === "protocol") {
    return thing("LabProtocol", {
      ...common,
      "http://purl.org/dc/terms/conformsTo": { "@id": LAB_PROTOCOL_PROFILE },
      reagent: record.materials.map((m) => m.display),
      labEquipment: record.equipment.map((e) => e.name),
      ...(record.biosafetyLevel
        ? {
            additionalProperty: {
              "@type": "PropertyValue",
              name: "Biosafety level",
              value: record.biosafetyLevel,
            },
          }
        : {}),
      ...(record.biosafety
        ? {
            bioSample: [record.biosafety.organism, record.biosafety.strain]
              .filter(Boolean)
              .join(" "),
          }
        : {}),
      ...(record.expectedResultsHtml ? { protocolOutcome: text(record.expectedResultsHtml) } : {}),
      ...(record.limitationsHtml ? { protocolLimitation: text(record.limitationsHtml) } : {}),
      ...(minutesToIso(record.time.total) ? { totalTime: minutesToIso(record.time.total) } : {}),
      ...(protocolParameters(record).length ? { parameter: protocolParameters(record) } : {}),
      step: steps,
    });
  }

  if (record.profile === "recipe") {
    const prep = minutesToIso(record.prepTime);
    const cook = minutesToIso(record.cookTime);
    const minutes = (/** @type {string | null} */ d) => {
      const m = /^PT(?:(\d+)H)?(?:(\d+)M)?$/.exec(d ?? "");
      return m ? Number(m[1] ?? 0) * 60 + Number(m[2] ?? 0) : null;
    };
    const total =
      prep && cook ? minutesToIso(`${(minutes(prep) ?? 0) + (minutes(cook) ?? 0)} minutes`) : null;
    return thing("Recipe", {
      ...common,
      ...(record.image ? { image: [`${origin}${record.image.src}`] } : {}),
      ...(record.servings ? { recipeYield: String(record.servings) } : {}),
      ...(record.cuisine ? { recipeCuisine: record.cuisine } : {}),
      ...(record.category ? { recipeCategory: record.category } : {}),
      ...(prep ? { prepTime: prep } : {}),
      ...(cook ? { cookTime: cook } : {}),
      ...(total ? { totalTime: total } : {}),
      recipeIngredient: record.materials.map((m) =>
        m.amount ? `${m.amount} ${m.display}` : m.display,
      ),
      recipeInstructions: steps,
    });
  }

  return thing("HowTo", {
    ...common,
    tool: record.materials
      .filter((m) => m.kind === "software")
      .map((m) => ({
        "@type": "HowToTool",
        name: m.version ? `${m.display} ${m.version}` : m.display,
      })),
    supply: record.materials
      .filter((m) => m.kind !== "software")
      .map((m) => ({ "@type": "HowToSupply", name: m.display })),
    step: steps,
  });
}

app/kb/procedures/qr.mjs.source:
// The QR code on a procedure's printed sheet: an inline SVG drawn on the server, so the sheet needs no
// script and the code is in the HTML a machine reads. It encodes one absolute address.

import { renderSVG } from "uqr";

/**
 * The QR code for `url` as an SVG string. Medium error correction survives a smudged or folded sheet.
 * Black on white with a quiet zone, whatever the reader's theme, because a scanner reads contrast.
 *
 * @param {string} url an absolute http(s) address
 */
export function sheetQr(url) {
  if (!/^https?:\/\/\S+$/.test(url))
    throw new Error(`A sheet's QR code encodes an absolute address; got ${JSON.stringify(url)}.`);
  return renderSVG(url, { ecc: "M", border: 2, whiteColor: "#ffffff", blackColor: "#000000" });
}

app/kb/registry/kinds.mjs.source:
// The kinds the lab registry holds (docs/REGISTRY.md). A kind is data here, not a branch in the compile: its label,
// its address and the fields it knows beyond the ones every item has (name and status). The compile
// (compile.mjs), the save, the sync, the drift check and Carrel's handlers all read this one object, so a kind
// added here is a kind every one of them serves.
//
// The registry shipped as a framework with no kind (job_915d43f44cee), and each kind arrives with its own records and
// pages in its own change: primer, then strain, then reagent and equipment.

import { EQUIPMENT } from "./equipment.mjs";
import { PRIMER } from "./primer.mjs";
import { REAGENT } from "./reagent.mjs";
import { STRAIN } from "./strain.mjs";

/**
 * What a kind says about one field. `check` returns a message when the value is wrong and null when it is right; it
 * may be async (a field that names a publication asks the host). A value written "MISSING: <why>" is a recorded gap
 * and skips `check`, as in a procedure.
 *
 * @typedef {{
 *   required?: boolean,
 *   check: (value: unknown, context: RegistryContext) => string | null | Promise<string | null>,
 * }} FieldSpec
 *
 * @typedef {{
 *   singular: string,
 *   plural: string,
 *   itemPages?: boolean,
 *   fields: Record<string, FieldSpec>,
 *   setErrors?: (items: RegistryItem[]) => string[],
 * }} KindSpec
 *
 * What the host can answer for a file the repository holds, so the Worker (reading GitHub) and Node (reading the
 * clone) judge a file the same way. `paper` is whether the site holds a publication with that file key, and `recipe` whether the site holds a procedure with the
 * recipe profile under that file key.
 *
 * @typedef {{ paper: (slug: string) => Promise<boolean>, recipe: (slug: string) => Promise<boolean> }} RegistryHost
 * @typedef {{ host: RegistryHost, data: Record<string, unknown> }} RegistryContext
 *
 * One item as the table holds it: the shared columns and the kind's own fields, `null` where a kind's field is
 * absent. `fields` never repeats a shared column.
 *
 * @typedef {{ kind: string, id: string, name: string, status: "published" | "draft", fields: Record<string, unknown> }} RegistryItem
 */

/** @type {Readonly<Record<string, KindSpec>>} */
export const KINDS = Object.freeze({
  primer: PRIMER,
  strain: STRAIN,
  reagent: REAGENT,
  equipment: EQUIPMENT,
});

/** The kinds in the order the site lists them, which is the order they are defined in. @param {Record<string, KindSpec>} [kinds] */
export function kindKeys(kinds = KINDS) {
  return Object.keys(kinds);
}

app/kb/registry/reference.mjs.source:
// The reference sequences a primer is placed on (docs/REGISTRY.md): GenBank records, fetched once into data/references/ as
// FASTA files that keep NCBI's own header, and read here. A primer's position, strand and mismatches, and a pair's product,
// are COMPUTED from a reference by align.mjs (the tested code in primers.mjs), never copied from a paper or a database, and
// the page states which accession it used.
//
// A reference is a whole record (`DQ387450.1`) or a region of one (`NC_052532.1:76902320-76906237`, how NCBI names a slice of
// a chromosome). A position is reported in the ACCESSION's own coordinates, so a region's offset is added back and a reader
// can check it against the record at NCBI.

import { parseFasta } from "../../lib/primers.mjs";

/** The id a header names: an accession.version, and for a slice of a record its from-to span. */
const HEADER = /^>?\s*([A-Z]{1,2}_?[0-9]+\.[0-9]+)(?::([0-9]+)-([0-9]+))?\s+(.*)$/;

/**
 * @typedef {{
 *   id: string,
 *   accession: string,
 *   from: number,
 *   to: number,
 *   description: string,
 *   sequence: string,
 * }} Reference
 */

/**
 * One FASTA text, parsed. The header must be NCBI's own (`>accession.version[:from-to] description`) and the sequence must
 * be the length that header says, so a truncated or edited file cannot be read as the record it names.
 *
 * @param {string} text
 * @returns {Reference}
 */
export function parseReference(text) {
  const { header, sequence } = parseFasta(text);
  const match = HEADER.exec(header);
  if (!match)
    throw new Error(
      `"${header}" is not an NCBI FASTA header: >accession.version[:from-to] description`,
    );
  const [, accession = "", fromText, toText, description = ""] = match;
  const from = fromText === undefined ? 1 : Number(fromText);
  const to = toText === undefined ? sequence.length : Number(toText);
  if (to - from + 1 !== sequence.length) {
    throw new Error(
      `${accession}: the header spans ${from}-${to} (${to - from + 1} bases) but the sequence is ${sequence.length}`,
    );
  }
  if (!/^[ACGT]+$/.test(sequence))
    throw new Error(
      `${accession}: the sequence has a base other than A, C, G and T, so it cannot be a placement reference`,
    );
  const id = fromText === undefined ? accession : `${accession}:${from}-${to}`;
  return { id, accession, from, to, description, sequence };
}

/**
 * A 1-based position on the reference's own sequence, as the accession numbers it.
 *
 * @param {Reference} reference
 * @param {number} position 1-based on `reference.sequence`
 */
export function accessionPosition(reference, position) {
  return reference.from + position - 1;
}

app/lib/admin/check-copy.mjs.source:
/**
 * @typedef {object} CheckCopy
 * @property {string} name
 * @property {(counts: { expected: number, present: number } | undefined) => string | null} failing
 * @property {string} passing
 * @property {{ action: string, intent: string, label: string } | null} repair
 */

/** @type {Record<string, CheckCopy>} */
const CHECK_COPY = {
  "content-drift": {
    name: "Posts on the site",
    failing: (counts) =>
      counts
        ? `${counts.expected - counts.present} of the ${counts.expected} posts are older on the site than in its source. Syncing re-renders them.`
        : "Some posts are older on the site than in its source. Syncing re-renders them.",
    passing: "Every post on the site matches its source.",
    repair: { action: "/admin/tools", intent: "regenerate", label: "Re-render every post" },
  },
  "procedures-drift": {
    name: "Procedures on the site",
    failing: (counts) =>
      counts
        ? `${counts.expected - counts.present} of the ${counts.expected} procedures are older on the site than in its source. The site's watcher re-compiles them on its next check.`
        : "Some procedures are older on the site than in its source. The site's watcher re-compiles them on its next check.",
    passing: "Every procedure on the site matches its source.",
    repair: null,
  },
  "dictionary-drift": {
    name: "Dictionary entries on the site",
    failing: (counts) =>
      counts
        ? `${counts.expected - counts.present} of the ${counts.expected} dictionary entries are older on the site than in its source. The site's watcher re-compiles them on its next check.`
        : "Some dictionary entries are older on the site than in its source. The site's watcher re-compiles them on its next check.",
    passing: "Every dictionary entry on the site matches its source.",
    repair: null,
  },
  "registry-drift": {
    name: "Lab registry on the site",
    failing: (counts) =>
      counts
        ? `${counts.expected - counts.present} of the ${counts.expected} lab registry items are older on the site than in its source. The site's watcher re-compiles them on its next check.`
        : "Some lab registry items are older on the site than in its source. The site's watcher re-compiles them on its next check.",
    passing: "Every lab registry item on the site matches its source.",
    repair: null,
  },
  "pages-drift": {
    name: "Pages on the site",
    failing: (counts) =>
      counts
        ? `${counts.expected - counts.present} of the ${counts.expected} pages are older on the site than in its source. The site's watcher re-compiles them on its next check.`
        : "Some pages are older on the site than in its source. The site's watcher re-compiles them on its next check.",
    passing: "Every page on the site matches its source.",
    repair: null,
  },
  "publications-drift": {
    name: "Publications on the site",
    failing: (counts) =>
      counts
        ? `${counts.expected - counts.present} of the ${counts.expected} publications are older on the site than in its source. The site's watcher re-compiles them on its next check.`
        : "Some publications are older on the site than in its source. The site's watcher re-compiles them on its next check.",
    passing: "Every publication on the site matches its source.",
    repair: null,
  },
  "roster-drift": {
    name: "Roster on the site",
    failing: (counts) =>
      counts
        ? `${counts.expected - counts.present} of the ${counts.expected} cohorts are older on the site than in its source. The site's watcher re-compiles them on its next check.`
        : "Some cohorts are older on the site than in its source. The site's watcher re-compiles them on its next check.",
    passing: "Every cohort on the site matches its source.",
    repair: null,
  },
  "phage-drift": {
    name: "Phage table on the site",
    failing: (counts) =>
      counts
        ? `${counts.expected - counts.present} of the ${counts.expected} phages are older on the site than in its source. The site's watcher re-compiles them on its next check.`
        : "Some phages are older on the site than in its source. The site's watcher re-compiles them on its next check.",
    passing: "Every phage on the site matches its source.",
    repair: null,
  },
  "llms-drift": {
    name: "The llms.txt file on the site",
    failing: () =>
      "The llms.txt the site serves is older than its source. The site's watcher rewrites it on its next check.",
    passing: "The llms.txt the site serves matches its source.",
    repair: null,
  },
  "cv-drift": {
    name: "The CV on the site",
    failing: (counts) =>
      counts
        ? `${counts.expected - counts.present} of the ${counts.expected} CV files are older on the site than in its source. The site's watcher re-compiles them on its next check.`
        : "Some CV files are older on the site than in its source. The site's watcher re-compiles them on its next check.",
    passing: "The CV on the site matches its source.",
    repair: null,
  },
  "cv-pdf-drift": {
    name: "The CV PDF",
    failing: () =>
      "The CV PDF is older than the CV on the site, or missing. The site's watcher re-renders it on its next check.",
    passing: "The CV PDF was drawn from the CV the site shows.",
    repair: null,
  },
  "ask-index-drift": {
    name: "Search answers",
    failing: (counts) =>
      counts
        ? `The answer index has ${counts.present} of ${counts.expected} posts, so an answer may quote text that has changed.`
        : "The answer index is out of step with the posts, so an answer may quote text that has changed.",
    passing: "The answer index has every post, and none it should not.",
    repair: { action: "/admin/tools", intent: "sync-ask", label: "Rebuild the answer index" },
  },
  "media-index-drift": {
    name: "Media library",
    failing: (counts) =>
      counts
        ? `The library lists ${counts.present} files and ${counts.expected} are stored, so something is missing from one side.`
        : "The library and the stored files disagree about what exists.",
    passing: "Every stored file is listed, and nothing is listed that is not there.",
    repair: { action: "/admin/media", intent: "rebuild", label: "Rebuild the library listing" },
  },
  "fts-equality": {
    name: "Site search",
    // Same: five subqueries compared pairwise, not a total against a total.
    failing: () => null,
    passing: "Search knows about every post and every page it should.",
    repair: null,
  },
};

/**
 * @param {{ name: string, ok: boolean, detail: string, counts?: { expected: number, present: number } }} check
 * @returns {{ name: string, finding: string, repair: { action: string, intent: string, label: string } | null }}
 */
export function humanCheck(check) {
  const copy = CHECK_COPY[check.name];
  if (!copy) {
    // A check with no words yet still reads as words: "registry-drift" becomes "Registry drift".
    const words = check.name.replace(/-/g, " ");
    return {
      name: words.charAt(0).toUpperCase() + words.slice(1),
      finding: check.detail,
      repair: null,
    };
  }
  if (check.ok) {
    return { name: copy.name, finding: copy.passing, repair: null };
  }
  const finding = copy.failing(check.counts) ?? check.detail;
  return { name: copy.name, finding, repair: copy.repair };
}

/**
 * @param {Array<{ name: string, ok: boolean, detail: string, counts?: { expected: number, present: number } }>} checks
 * @returns {string}
 */
export function statusSentence(checks) {
  const failing = checks.filter((check) => !check.ok);
  // Guard the value, not the length, so the compiler knows `worst` is defined.
  const worst = failing[0];
  if (!worst) {
    return "Everything agrees: the site, the source, the library and search are all in step.";
  }
  const first = humanCheck(worst);
  if (failing.length === 1) {
    return `One thing needs attention. ${first.finding}`;
  }
  return `${failing.length} things need attention. ${first.finding}`;
}

