// Its own module because ogImageKey must hash the same clamped strings the card draws, and because a
// route names a page's card through it without importing the markdown renderer. Characters stand in
// for width, so every number here was measured off rendered cards.

import { fnv1a32 } from "../fingerprint.mjs";
import { longDateUTC } from "../long-date.mjs";
import { ASSET_PREFIX } from "../media/classify.mjs";

export const TITLE_MAX = 150;

/**
 * Measured off rendered 1200x630 cards against the layout in build-og.mjs.
 *
 * @type {ReadonlyArray<{ maxChars: number, fontSize: number }>}
 */
export const TITLE_SIZES = [
  { maxChars: 72, fontSize: 72 },
  { maxChars: 110, fontSize: 54 },
  { maxChars: TITLE_MAX, fontSize: 42 },
];

// Two lines of description, enforced here because satori's WebkitLineClamp does nothing.
export const DESCRIPTION_MAX = 132;

// Dashes as escapes in a string: a hook bans those characters from the repo's bytes.
const DANGLING_PUNCTUATION = new RegExp("[,;:.\\u2014\\u2013-]+$");

/**
 * A single word longer than max is still cut: running off the card is worse.
 *
 * @param {string | null | undefined} value
 * @param {number} max
 * @returns {string}
 */
export function clampWords(value, max) {
  const text = (value ?? "").trim();
  if (text.length <= max) return text;
  const cut = text.slice(0, max);
  const lastSpace = cut.lastIndexOf(" ");
  const kept = lastSpace > 0 ? cut.slice(0, lastSpace) : cut;
  return `${kept.replace(DANGLING_PUNCTUATION, "")}…`;
}

/**
 * @param {string | null | undefined} title
 * @returns {string}
 */
export function cardTitle(title) {
  return clampWords(title, TITLE_MAX);
}

/**
 * @param {string | null | undefined} description
 * @returns {string}
 */
export function cardDescription(description) {
  return clampWords(description, DESCRIPTION_MAX);
}

/**
 * Throws, never falls back: a title past the last rung means TITLE_MAX and the ladder disagree.
 *
 * @param {string} title the title AS DRAWN, i.e. already through `cardTitle`
 * @returns {number}
 */
export function titleFontSize(title) {
  const length = (title ?? "").length;
  for (const rung of TITLE_SIZES) {
    if (length <= rung.maxChars) return rung.fontSize;
  }
  throw new Error(
    `og-card-text: a ${length}-character title is past the last rung of the ` +
      `ladder (${TITLE_MAX}). Titles must go through cardTitle() first.`,
  );
}

// Bump on any card template change: the key hashes only the card's inputs, and an immutable cache
// ignores a restyled PNG under an unchanged key forever.
const OG_TEMPLATE_VERSION = 7;

/**
 * Hashes exactly what the card draws, AS DRAWN (through cardTitle, cardDescription, longDateUTC), so
 * the key changes when the picture would and never otherwise. FNV-1a: identical in Node and a Worker,
 * and this is a cache-busting key, not a security boundary.
 *
 * @param {{
 *   slug: string,
 *   title: string,
 *   description?: string | null,
 *   publishAt?: string | null,
 * }} post
 */
export function ogImageKey(post) {
  const drawnDate = longDateUTC(post.publishAt);
  const input =
    `${OG_TEMPLATE_VERSION}\n${post.slug}\n${cardTitle(post.title)}\n` +
    `${cardDescription(post.description)}\n${drawnDate === null ? "" : drawnDate}`;
  return `og/${ASSET_PREFIX}${post.slug}-${fnv1a32(input)}.png`;
}

app/lib/content/pipeline.mjs.source:
// The only markdown renderer, shared by the build and the Worker: if they could disagree, check:content
// would fail on content nobody edited. Runs in a Worker, so no node:fs. The pipeline is Prelum's
// (@drdustinedwards/site-helpers/render); this module holds what stays with the site: the frontmatter,
// the media rules and the post record.

import { ContentError, render } from "@drdustinedwards/site-helpers/render";
import { createHighlight } from "@drdustinedwards/site-helpers/render/highlight";
import { editorialPack } from "@drdustinedwards/site-helpers/render/packs";
import { isAllowedUrl } from "@drdustinedwards/site-helpers/render/url";
import matter from "gray-matter";
import { z } from "zod";

// Each diagram drawing's size, which build:diagrams writes beside the drawings (Prelum's DIAGRAM_SIZES_FILE), so a
// diagram's <img> carries width and height and nothing shifts as it loads.
import diagramSizes from "../../../public/diagrams/sizes.json" with { type: "json" };
import { ASSET_PREFIX, classify, dimensionsFromKey } from "../media/classify.mjs";
import { makeChartData } from "./chart-data.mjs";
import { gitBlobSha, renderHash } from "./hashes.mjs";
import { contentImage, images, mediaContentVersion } from "../media/images.mjs";
import { SLUG_MAX_LENGTH, SLUG_PATTERN, postPath } from "./slug.mjs";

import { readingTimeMinutes } from "./reading-time.mjs";
import { withBacklinks, withRelated } from "./corpus.mjs";
import { internalLinkSlug, isFurtherReadingUrl } from "./url-policy.mjs";

export { LANGUAGES, SHIKI_THEMES } from "@drdustinedwards/site-helpers/render/highlight";

// Re-exported: build scripts, gates and tests import these from here, the renderer's one door.
export { ContentError, internalLinkSlug, isAllowedUrl, withBacklinks, withRelated };

// YAML turns an unquoted 2026-07-27 into a Date, so both spellings arrive here.
/** @param {unknown} value */
const asDateString = (value) =>
  value instanceof Date ? value.toISOString().slice(0, 10) : value;

/** @param {unknown} value */
const asDateTimeString = (value) =>
  value instanceof Date ? value.toISOString() : value;

const isoDate = z.preprocess(
  asDateString,
  z.string().regex(/^\d{4}-\d{2}-\d{2}$/, "must be a YYYY-MM-DD date"),
);

const isoDateTime = z.preprocess(
  asDateTimeString,
  z
    .string()
    .refine((v) => !Number.isNaN(Date.parse(v)), "must be a parseable date-time"),
);

export { SLUG_ATTRIBUTE_PATTERN, SLUG_PATTERN, postPath } from "./slug.mjs";

export const frontmatterSchema = z.object({
  title: z.string().min(1, "must not be empty"),
  slug: z
    .string()
    .regex(SLUG_PATTERN, "must be lowercase kebab-case")
    .max(SLUG_MAX_LENGTH, `must be at most ${SLUG_MAX_LENGTH} characters`),
  date: isoDate,
  tags: z.array(z.string().min(1)).default([]),
  description: z.string().min(1, "must not be empty"),
  draft: z.boolean().default(false),
  publish_at: isoDateTime.optional(),
  cover: z
    .object({
      /**
       * The regex refuses protocol-relative paths; isAllowedUrl is the shared protocol check and
       * must be called, not reimplemented. Both are needed.
       */
      src: z
        .string()
        .regex(/^\/(?![/\\])/, "must be a site-absolute path, not //host or a full URL")
        .refine(isAllowedUrl, "protocol is not allowed (https, http, mailto or relative only)"),
      alt: z.string().min(1, "is required when cover is set"),
    })
    .optional(),
  featured: z.boolean().default(false),
  series: z.string().min(1).optional(),
  part: z.number().int().min(1, "must be 1 or greater").optional(),
  // Not `status`, which is the row's draft/published column. A closed set so readers learn it once.
  writing_status: z.enum(["notes", "draft", "in progress", "finished", "obsolete"]).optional(),
  assumed_audience: z.string().min(1).max(200).optional(),
  key_takeaways: z.array(z.string().min(1).max(300)).min(2).max(4).optional(),
  // isoDate because YAML parses a bare 2026-08-15 into a Date object.
  changelog: z
    .array(
      z.object({
        date: isoDate,
        note: z.string().min(1).max(300),
      }),
    )
    .min(1)
    .max(20)
    .optional(),
  further_reading: z
    .array(
      z.object({
        title: z.string().min(1, "must not be empty"),
        /**
         * isAllowedUrl is the SAME predicate the render layer uses (check:urls reads this phrase): z.url()
         * accepts javascript:, and rehypeUrlProtocols never sees frontmatter. Internal links are /writing/ paths, not absolute URLs, so they survive the origin change at cutover.
         */
        url: z
          .string()
          .refine(isFurtherReadingUrl, "must be an absolute http(s) URL or a /writing/ path")
          .refine(isAllowedUrl, "protocol is not allowed (https, http, mailto or relative only)"),
      }),
    )
    .default([]),
  og_title: z.string().min(1).optional(),
  og_description: z.string().min(1).optional(),
  // site-api's search fields (description is the one above): Carrel writes them under these shared names.
  searchTitle: z.string().min(1).optional(),
  image: z
    .string()
    .regex(/^\/(?![/\\])/, "must be a site-absolute path, not //host or a full URL")
    .refine(isAllowedUrl, "protocol is not allowed (https, http, mailto or relative only)")
    .optional(),
  imageAlt: z.string().min(1).optional(),
  canonical: z.string().url().refine((v) => /^https?:/.test(v), "must be an http(s) URL").optional(),
  noindex: z.boolean().default(false),
  /**
   * A date, not a timestamp: the build derives it from git and the editor cannot know the time of
   * the commit it is about to create, so only a date lets the two agree.
   */
  updated: isoDate.optional(),
  // Server-owned, stamped on first publish. renderPost deliberately keeps it out of the record.
  first_published: isoDate.optional(),
}).superRefine((value, ctx) => {
  if (value.series && value.part === undefined) {
    ctx.addIssue({ code: "custom", path: ["part"], message: "is required when series is set" });
  }
  if (value.part !== undefined && !value.series) {
    ctx.addIssue({ code: "custom", path: ["series"], message: "is required when part is set" });
  }
});

export { findWideDashes } from "./wide-dash.mjs";

export { readingTimeMinutes };

// Isolate-wide: one highlighter, the same for every request.
/** @type {ReturnType<typeof createHighlight> | null} */
let highlight = null;

/**
 * Injected: a Worker refuses WebAssembly.instantiate() on bytes, so it passes an instantiator over a
 * statically imported module. The engine is the same, so the HTML is byte-identical.
 *
 * @type {() => any}
 */
let wasmLoader = () => import("shiki/wasm");

/** @param {() => any} loader */
export function setWasmLoader(loader) {
  wasmLoader = loader;
  highlight = null;
}

function getHighlight() {
  highlight ??= createHighlight({ wasm: () => wasmLoader() });
  return highlight;
}

// The card key lives beside the card text it hashes, so a route can name a card without this renderer.
export { ogImageKey } from "./og-card-text.mjs";

/**
 * R2 objects are keyed after /media/, static assets by their public path. An unrecognized extension
 * returns null: a page link is not a media citation and would never join.
 *
 * @param {string} raw
 * @returns {string | null}
 */
function mediaKeyOf(raw) {
  if (typeof raw !== "string" || raw.length === 0) return null;

  let path = raw;
  const origin = path.match(/^(?:[a-z][a-z0-9+.-]*:)?\/\/[^/]+(\/.*)$/i);
  if (origin) path = origin[1] ?? path;
  // Query and fragment are not part of the key: ?w=320 is a transform request.
  path = path.split(/[?#]/)[0] ?? "";
  if (!path.startsWith("/")) return null;

  if (path.startsWith("/media/")) {
    const key = path.slice("/media/".length);
    return key.length > 0 ? key : null;
  }

  try {
    classify(path);
  } catch {
    return null;
  }
  return path;
}

/**
 * Only /media/ keys are responsive: static assets never pass through the transform route, so their
 * widths would 404. `sources` makes Prelum write a <picture>, AVIF then WebP; the <img> keeps the WebP
 * srcset. The link goes to the unsized original, which srcset never serves. A GIF's reduced-motion stills (site-runtime
 * 0.43, a source with `media`) are left out: this Prelum's <picture> writes no `media`, so a still would win for every
 * reader. The GIF stays animated, as before.
 *
 * @param {string} src
 */
function imageProps(src) {
  if (!src.startsWith("/media/")) return null;
  const key = src.slice("/media/".length);
  const { srcset, sizes, sources } = contentImage(src, dimensionsFromKey(key));
  // The original, versioned like its sizes (mediaContentVersion), so a link to it is never a stale copy either.
  const href = images.url(`/media/${key}`, { version: mediaContentVersion(key) });
  if (!srcset) return { href };
  return { srcSet: srcset, sizes, sources: sources.filter((s) => !s.media).map((s) => ({ type: s.type, srcSet: s.srcset })), href };
}

const SITE_OPTIONS = {
  media: { keyOf: mediaKeyOf, imageProps },
};

/**
 * The editorial pack for one render. `strictCharts` refuses a chart with no title or too many series (checklist E4),
 * so the publish names it before it goes live. `readChartData` reads a cited CSV from the
 * media library (chart-data.mjs); without it a `:::chart{src}` is refused, as Prelum does.
 *
 * @param {((key: string) => Promise<string | null>) | undefined} readChartData
 * @param {Set<string>} cited
 */
function packsFor(readChartData, cited) {
  return [
    editorialPack({
      assetPrefix: ASSET_PREFIX,
      strictCharts: true,
      diagramSizes,
      ...(readChartData ? { chartData: makeChartData(readChartData, cited) } : {}),
    }),
  ];
}

/**
 * @param {object} options
 * @param {string} options.file label used in error messages
 * @param {string} options.body markdown with frontmatter already stripped
 * @param {(src: string) => Promise<{ width: number, height: number }>} options.resolveImage
 * @param {(key: string) => Promise<string | null>} [options.readChartData] reads a chart's CSV from the media library
 */
export async function renderBody({ file, body, resolveImage, readChartData }) {
  /** @type {Set<string>} */
  const cited = new Set();
  const { html, toc, hasMath, diagrams, mediaRefs, blockedUrls } = await render({
    file,
    body,
    resolveImage,
    options: { ...SITE_OPTIONS, packs: packsFor(readChartData, cited), highlight: getHighlight() },
  });
  for (const key of cited) mediaRefs.push({ key, form: "other", detail: "chart data" });
  return { html, toc, hasMath, diagrams, mediaRefs, blockedUrls };
}

/** @param {string} html */
function demoteFirstImage(html) {
  return html.replace(/<img\b[^>]*\bfetchpriority="high"[^>]*>/, (tag) =>
    tag.replace(' fetchpriority="high"', "").replace('loading="eager"', 'loading="lazy"'),
  );
}

/**
 * @param {object} options
 * @param {string} options.file path or label, used in error messages
 * @param {string} options.raw the whole file including frontmatter
 * @param {string} options.expectedSlug slug the filename implies
 * @param {(src: string) => Promise<{ width: number, height: number }>} options.resolveImage
 * @param {(key: string) => Promise<string | null>} [options.readChartData]
 */
export async function renderPost({ file, raw, expectedSlug, resolveImage, readChartData }) {
  const parsed = matter(raw);
  const result = frontmatterSchema.safeParse(parsed.data);
  if (!result.success) {
    const detail = result.error.issues
      .map((issue) => `${issue.path.join(".") || "(root)"} ${issue.message}`)
      .join("; ");
    throw new ContentError(file, `invalid frontmatter: ${detail}`);
  }
  const fm = result.data;

  if (fm.slug !== expectedSlug) {
    throw new ContentError(
      file,
      `slug "${fm.slug}" does not match the filename "${expectedSlug}"`,
    );
  }

  const rendered = await renderBody({
    file,
    body: parsed.content,
    resolveImage,
    readChartData,
  });
  const { toc, diagrams, mediaRefs, hasMath } = rendered;
  // The cover is the LCP where there is one, so the body's first image gives up Prelum's eager, high-priority pair:
  // two images marked high is the same as none.
  const html = fm.cover ? demoteFirstImage(rendered.html) : rendered.html;

  let cover = null;
  if (fm.cover) {
    const { width, height } = await resolveImage(fm.cover.src);
    cover = { src: fm.cover.src, alt: fm.cover.alt, width, height };
    // The body renderer never sees a frontmatter cover; without this it would be listed as unused.
    const coverKey = mediaKeyOf(fm.cover.src);
    if (coverKey) {
      mediaRefs.push({ key: coverKey, form: "frontmatter-cover", detail: "cover image" });
    }
  }

  const searchFields = {
    ...(fm.searchTitle ? { searchTitle: fm.searchTitle } : {}),
    ...(fm.image ? { image: fm.image, ...(fm.imageAlt ? { imageAlt: fm.imageAlt } : {}) } : {}),
    ...(fm.canonical ? { canonical: fm.canonical } : {}),
    ...(fm.noindex ? { noindex: true } : {}),
  };
  const imageKey = fm.image ? mediaKeyOf(fm.image) : null;
  if (imageKey) mediaRefs.push({ key: imageKey, form: "other", detail: "share image" });

  return {
    slug: fm.slug,
    title: fm.title,
    description: fm.description,
    date: fm.date,
    publishAt: fm.publish_at ?? `${fm.date}T00:00:00.000Z`,
    draft: fm.draft,
    tags: fm.tags,
    cover,
    featured: fm.featured,
    series: fm.series ?? null,
    part: fm.part ?? null,
    writingStatus: fm.writing_status ?? null,
    assumedAudience: fm.assumed_audience ?? null,
    keyTakeaways: fm.key_takeaways ?? null,
    changelog: fm.changelog ?? null,
    furtherReading: fm.further_reading,
    ogTitle: fm.og_title ?? null,
    ogDescription: fm.og_description ?? null,
    /** The search fields beside description, or null when the post sets none (the posts.search_fields column). */
    searchFields: Object.keys(searchFields).length > 0 ? searchFields : null,
    updated: fm.updated ?? null,
    readingTimeMinutes: readingTimeMinutes(parsed.content),
    // Never stored: it rides only so check:content can compare it with htmlHasMath.
    hasMath,
    toc,
    diagrams,
    mediaRefs,
    markdown: parsed.content,
    html,
    sourcePath: postPath(fm.slug),
    // Over the whole raw file, frontmatter included, because that is the blob git stores.
    sourceBlobSha: await gitBlobSha(raw),
    renderHash: await renderHash(html),
  };
}

app/lib/media-ref-key.mjs.source:
/**
 * NUL cannot occur in any part, so the join is unambiguous; a printable `|`
 * would collide ("a|b","c" vs "a","b|c") and silently drop a ref. Keep it an
 * escape: a literal NUL makes the file binary to git and invisible in editors.
 *
 * @param {{ mediaKey: string, form: string, detail: string | null }} ref
 * @returns {string}
 */
export function mediaRefKey(ref) {
  return `${ref.mediaKey}\u0000${ref.form}\u0000${ref.detail ?? ""}`;
}

app/lib/media/template-refs.mjs.source:
// Runs at BUILD time and ships as a committed artifact: the Worker has no repository, and its ASSETS
// binding can only fetch. The match is LITERAL, so a constructed path like `/diagrams/${id}.svg` is
// invisible; that is why the library says "no reference found" rather than "unused".

// `content/posts` is absent: post citations belong to the other tracker, and an asset must not claim both.
export const SOURCE_ROOTS = ["app", "workers"];

export const SOURCE_FILES = ["content/features.json"];

// Each paper's file names its PDF by path (`pdfPath`) and each dictionary entry its pronunciation clip (`audio`), so
// these markdown files are sources: without them every hosted PDF and clip would read as unreferenced. Passed
// through unstripped, like JSON: the extracted text has apostrophes. Each cohort's file under content/roster names its
// photograph by path, so without it the nine photographs would read as unreferenced.
export const SOURCE_DIRECTORIES = ["content/publications", "content/dictionary", "content/roster"];

const SOURCE_EXTENSIONS = [".ts", ".tsx", ".mjs", ".js", ".css", ".json", ".webmanifest"];

// Checked first because `SOURCE_FILES` bypass the root rule. `assets.json` lists every asset path.
const SELF_REFERENTIAL = ["content/generated/assets.json"];

/**
 * @param {string} file repo-relative, forward slashes
 * @returns {boolean}
 */
export function isSourceFile(file) {
  if (SELF_REFERENTIAL.includes(file)) return false;
  if (SOURCE_FILES.includes(file)) return true;
  if (SOURCE_DIRECTORIES.some((dir) => file.startsWith(`${dir}/`) && file.endsWith(".md")))
    return true;
  const root = file.split("/")[0] ?? "";
  if (!SOURCE_ROOTS.includes(root)) return false;
  return SOURCE_EXTENSIONS.some((ext) => file.endsWith(ext));
}

/**
 * Prose about an asset is not a reference. A tokenizer, not a regex: stripping from `//` to end of line
 * would destroy every `https://` inside a string literal, which is where real references live.
 *
 * @param {string} text
 * @param {boolean} [cssOnly] true for `.css`, which has no line comments
 * @returns {string} the same length, with comment bytes blanked to spaces
 */
export function stripComments(text, cssOnly = false) {
  let out = "";
  let i = 0;
  /** @type {"code"|"line"|"block"|"'"|"\""|"`"} */
  let mode = "code";
  while (i < text.length) {
    const c = text[i];
    const next = text[i + 1];
    if (mode === "code") {
      if (c === "/" && next === "*") {
        mode = "block";
        out += "  ";
        i += 2;
        continue;
      }
      if (!cssOnly && c === "/" && next === "/") {
        mode = "line";
        out += "  ";
        i += 2;
        continue;
      }
      if (!cssOnly && (c === "'" || c === '"' || c === "`")) {
        mode = c;
        out += c;
        i += 1;
        continue;
      }
      if (cssOnly && (c === "'" || c === '"')) {
        mode = c;
        out += c;
        i += 1;
        continue;
      }
      out += c;
      i += 1;
      continue;
    }
    if (mode === "line") {
      if (c === "\n") {
        mode = "code";
        out += c;
        i += 1;
        continue;
      }
      // Blanked rather than deleted, so offsets stay comparable and lines cannot join.
      out += " ";
      i += 1;
      continue;
    }
    if (mode === "block") {
      if (c === "*" && next === "/") {
        mode = "code";
        out += "  ";
        i += 2;
        continue;
      }
      out += c === "\n" ? c : " ";
      i += 1;
      continue;
    }
    if (c === "\\") {
      out += text.slice(i, i + 2);
      i += 2;
      continue;
    }
    if (c === mode) {
      mode = "code";
      out += c;
      i += 1;
      continue;
    }
    out += c;
    i += 1;
  }
  return out;
}

/**
 * Both ends must be boundaries: `/dustin-edwards-logo.svg` is a prefix of `/dustin-edwards-logo-dark.svg`,
 * and `"public/site.webmanifest"` ends with `/site.webmanifest`.
 *
 * @param {string} text the file contents
 * @param {string[]} assetPaths every known asset path
 * @returns {string[]} the subset referenced, in the order given
 */
export function referencesIn(text, assetPaths) {
  return assetPaths.filter((asset) => {
    let from = 0;
    for (;;) {
      const at = text.indexOf(asset, from);
      if (at < 0) return false;
      const before = at === 0 ? undefined : text[at - 1];
      const after = text[at + asset.length];
      /** @param {string | undefined} ch */
      const bounded = (ch) => ch === undefined || !/[A-Za-z0-9._~/-]/.test(ch);
      if (bounded(before) && bounded(after)) return true;
      from = at + 1;
    }
  });
}

/**
 * Sorted, so the generated artifact does not churn with directory order and a gate can byte-compare it.
 *
 * @param {Array<{ file: string, assets: string[] }>} scanned
 * @returns {{ generated: number, refs: Record<string, string[]> }}
 */
export function foldRefs(scanned) {
  /** @type {Record<string, string[]>} */
  const refs = {};
  for (const { file, assets } of scanned) {
    for (const asset of assets) {
      if (!refs[asset]) refs[asset] = [];
      if (!refs[asset].includes(file)) refs[asset].push(file);
    }
  }
  /** @type {Record<string, string[]>} */
  const sorted = {};
  for (const asset of Object.keys(refs).sort()) sorted[asset] = (refs[asset] ?? []).slice().sort();
  return { generated: Object.keys(sorted).length, refs: sorted };
}

app/lib/not-found-query.mjs.source:
// Plain .mjs so `node --test` can import it; the types are JSDoc under checkJs.

/**
 * The words of a missing address, to start the 404 page's search box with: the last path segment
 * with any file extension off, split on everything that is not a letter or digit. Number-only words
 * are dropped, because a bare year is a search filter and an old dated address would otherwise
 * narrow the search to that year. Percent escapes are dropped rather than decoded, since a malformed
 * one would throw. Empty when nothing useful is left, and the box then shows its placeholder.
 *
 * @param {string} pathname
 * @returns {string}
 */
export function notFoundQuery(pathname) {
  const segments = pathname.split("/").filter((segment) => segment.length > 0);
  const last = segments.at(-1) ?? "";
  const words = last
    .replace(/%[0-9A-Fa-f]{2}/g, " ")
    .replace(/\.[A-Za-z0-9]{1,5}$/, "")
    .split(/[^\p{L}\p{N}]+/u)
    .filter((word) => word.length > 0 && !/^\p{N}+$/u.test(word));
  return words.join(" ").slice(0, 100).trim();
}

app/lib/podcast/clock.mjs.source:
// On its own, without the feed parser, because the player's enhancement bundle imports it.

/**
 * A duration as a clock: `m:ss`, or `h:mm:ss` from an hour. A missing or unreadable length (NaN,
 * which an audio element reports before its metadata loads) reads as 0:00.
 *
 * @param {number} seconds
 */
export function clockTime(seconds) {
  const s = Math.max(0, Math.floor(seconds || 0));
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const rest = String(s % 60).padStart(2, "0");
  return h > 0 ? `${h}:${String(m).padStart(2, "0")}:${rest}` : `${m}:${rest}`;
}

app/lib/publications/listing.mjs.source:
/**
 * The publication index (docs/PUBLICATIONS.md): its fields declared once for Capsomer's catalog, so the search box, the
 * topic and other facets, the sort menu, the year headings and the counts all come from this one declaration. Pure
 * over the query string and the papers it is handed. The route adds the citation counts (a D1 read) and the page copy.
 *
 * What did not change, because search engines and the machine-readable gates hold it: `?topic=` is the address of a
 * topic's papers, and exactly the four bare single-topic addresses canonicalise to themselves (`soleTopic`); every other
 * address is a view of the base page.
 */

import { defineCatalog, parseCatalogParams, queryCatalog } from "capsomer/behavior/catalog";

import { decodeEntities } from "./entities.mjs";
import { TOPICS, TOPIC_IDS } from "./topics.mjs";

/** @typedef {import("./types.ts").Publication} Publication */
/** @typedef {import("./types.ts").PublicationType} PublicationType */
/** @typedef {import("./types.ts").TopicId} TopicId */

/**
 * Conference abstracts stay in the data file, which the CV also reads, and are excluded here.
 *
 * @type {Set<PublicationType>}
 */
export const SHOWCASE_TYPES = new Set(["article", "review", "chapter", "teaching-resource"]);

const PUBLICATIONS_BASE = "/research/publications";

const TYPE_LABELS = /** @type {Record<string, string>} */ ({
  article: "Article",
  review: "Review",
  chapter: "Chapter",
  "teaching-resource": "Teaching resource",
});

/** The journal, volume and pages as the page prints them, entities decoded (the year has its own column). @param {Publication} p */
export function venue(p) {
  return decodeEntities([p.journal, p.volume, p.pages].filter(Boolean).join(", "));
}

/** The papers' catalog. Newest first by default, under a heading for each year; any search or other sort is flat. */
export const PUBLICATIONS = defineCatalog(
  /** @type {import("capsomer/behavior/catalog").CatalogDefinition<Publication>} */ ({
    id: "papers",
    noun: ["paper", "papers"],
    basePath: PUBLICATIONS_BASE,
    itemKey: (p) => p.id,
    defaultSort: "-year",
    group: { field: "year" },
    fields: [
      {
        key: "title",
        label: "Title",
        value: (p) => decodeEntities(p.title),
        search: 3,
        sort: true,
        column: { header: "Paper" },
      },
      { key: "authors", label: "Authors", value: (p) => p.authors.map(decodeEntities), search: 1 },
      {
        key: "journal",
        label: "Journal",
        value: (p) => venue(p),
        search: 2,
        column: { header: "Journal", drop: 1 },
      },
      {
        key: "year",
        label: "Year",
        value: (p) => p.year,
        type: "number",
        sort: { labels: { asc: "oldest first", desc: "newest first" } },
        column: { header: "Year", align: "end", hideWhenGrouped: true },
      },
      {
        key: "topic",
        label: "Topic",
        value: (p) => p.topics,
        facet: {
          kind: "many",
          general: true,
          order: TOPICS.map((t) => t.id),
          label: (v) => TOPICS.find((t) => t.id === v)?.label ?? v,
        },
      },
      {
        key: "type",
        label: "Type",
        value: (p) => p.type,
        facet: { kind: "many", label: (v) => TYPE_LABELS[v] ?? v },
      },
      // Chosen with `?selected=1`, as the page's "Selected" filter always was.
      {
        key: "selected",
        label: "Selected",
        value: (p) => (p.selected ? "1" : null),
        facet: { kind: "one", label: () => "Selected papers" },
      },
      {
        key: "access",
        label: "Access",
        value: (p) => (p.isOpenAccess ? "open" : null),
        facet: { kind: "one", label: () => "Open access" },
      },
    ],
  }),
);

/**
 * The address a request written in the old parameters should have, or null. The page used `?sort=year-desc|year-asc|title`
 * and `?selected=1|true`; the catalog says `sort=-year|year|title` and `selected=1`. A link in the wild keeps working: it
 * is sent, once, to the same view at its new address. A request with none of the old spellings is left alone.
 *
 * @param {URL} url
 */
export function legacyAddress(url) {
  const params = url.searchParams;
  const sort = params.get("sort");
  const oldSort = sort === "year-desc" || sort === "year-asc";
  const oldSelected = (params.get("selected") ?? "").toLowerCase() === "true";
  if (!oldSort && !oldSelected) return null;
  const next = new URLSearchParams(params);
  if (sort === "year-desc") next.delete("sort");
  if (sort === "year-asc") next.set("sort", "year");
  if (oldSelected) next.set("selected", "1");
  return queryCatalog(PUBLICATIONS, [], parseCatalogParams(PUBLICATIONS, next)).href();
}

/**
 * Only the four bare single-topic URLs self-canonical: the rest are subsets or orderings, and q is unbounded.
 *
 * @param {URLSearchParams} params
 * @returns {TopicId | null}
 */
export function soleTopic(params) {
  const topics = params.getAll("topic").filter((t) => TOPIC_IDS.has(t));
  const KNOWN_PARAMS = new Set(["topic", "q", "sort", "selected"]);
  const hasUnknownParam = [...params.keys()].some((k) => !KNOWN_PARAMS.has(k));
  return topics.length === 1 &&
    params.getAll("topic").length === 1 &&
    !params.has("q") &&
    !params.has("sort") &&
    !params.has("selected") &&
    !hasUnknownParam
    ? /** @type {TopicId} */ (topics[0])
    : null;
}

/**
 * The page's state for an address: the showcase papers run through the catalog, with the span the header states and the
 * canonical topic. Everything shown is in `result`.
 *
 * @param {URLSearchParams} params
 * @param {Publication[]} publications every published paper, newest first (app/db/publications.ts)
 */
export function publicationListing(params, publications) {
  const showcase = publications.filter((p) => SHOWCASE_TYPES.has(p.type));
  const result = queryCatalog(PUBLICATIONS, showcase, parseCatalogParams(PUBLICATIONS, params));
  const items = result.rows;
  const span = {
    papers: items.length,
    firstYear: items.length > 0 ? Math.min(...items.map((p) => p.year)) : null,
    lastYear: items.length > 0 ? Math.max(...items.map((p) => p.year)) : null,
    venues: new Set(items.map((p) => p.journal).filter(Boolean)).size,
  };
  return { items, result, span, soleTopic: soleTopic(params), total: showcase.length };
}

app/lib/search/ask-twins.mjs.source:
// A failed key still joins keys: the caller prunes every key it is not given, so leaving it out would
// turn a transient into a deletion. Failures are returned so the sync report can refuse to converge.

export const TWIN_ATTEMPTS = 3;

/**
 * Uploads in flight at once during sync_ask. The corpus is one document per search record (552 on 2026-11-08),
 * and one at a time took over five minutes, past the 300 s Node's fetch waits for response headers, so the
 * converge job's call died "fetch failed" with the Worker still uploading.
 */
export const ASK_UPLOAD_CONCURRENCY = 8;

const TWIN_BACKOFF_MS = 500;

/**
 * @template T
 * @param {() => Promise<T>} fn
 * @param {{ attempts?: number, backoffMs?: number, sleep?: (ms: number) => Promise<void> }} [opts]
 * @returns {Promise<T>}
 */
export async function withRetry(fn, opts = {}) {
  const attempts = opts.attempts ?? TWIN_ATTEMPTS;
  const backoffMs = opts.backoffMs ?? TWIN_BACKOFF_MS;
  const sleep = opts.sleep ?? ((ms) => new Promise((r) => setTimeout(r, ms)));
  /** @type {unknown} */
  let last;
  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    try {
      return await fn();
    } catch (error) {
      last = error;
      if (attempt < attempts) await sleep(backoffMs * 2 ** (attempt - 1));
    }
  }
  throw last;
}

/**
 * Runs `fn` over `items` with at most `limit` in flight and returns the results in item order. The first
 * rejection stops new work from starting and is thrown once the calls already in flight have settled.
 *
 * @template T, R
 * @param {readonly T[]} items
 * @param {number} limit
 * @param {(item: T, index: number) => Promise<R>} fn
 * @returns {Promise<R[]>}
 */
export async function mapPool(items, limit, fn) {
  /** @type {R[]} */
  const results = Array.from({ length: items.length });
  let next = 0;
  let failed = false;
  /** @type {unknown} */
  let failure;
  const worker = async () => {
    while (!failed && next < items.length) {
      const index = next;
      next += 1;
      try {
        results[index] = await fn(/** @type {T} */ (items[index]), index);
      } catch (error) {
        if (!failed) failure = error;
        failed = true;
      }
    }
  };
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker));
  if (failed) throw failure;
  return results;
}

/**
 * @param {Array<{ key: string, path: string }>} twins the item key and the asset path of each twin
 * @param {{
 *   fetchText: (path: string) => Promise<string>,
 *   upload: (key: string, body: string) => Promise<unknown>,
 *   log?: (...args: unknown[]) => void,
 *   attempts?: number,
 *   backoffMs?: number,
 *   sleep?: (ms: number) => Promise<void>,
 * }} io `fetchText` throws on a missing or unreadable twin
 * @returns {Promise<{ keys: string[], failed: Array<{ key: string, error: string }> }>}
 */
export async function uploadTwins(twins, io) {
  const retry = { attempts: io.attempts, backoffMs: io.backoffMs, sleep: io.sleep };
  const log = io.log ?? console.error;
  const keys = [];
  const failed = [];
  for (const { key, path } of twins) {
    keys.push(key);
    try {
      const body = await withRetry(() => io.fetchText(path), retry);
      await withRetry(() => io.upload(key, body), retry);
    } catch (error) {
      const message = error instanceof Error ? `${error.name}: ${error.message}` : String(error);
      log("ask twin upload failed after retries", key, message);
      failed.push({ key, error: message });
    }
  }
  return { keys, failed };
}

app/lib/search/follow-up.mjs.source:
// Not in ask-prompt.mjs: the client imports this, and importing from there shipped the system prompt
// in the client bundle (tree-shaking did not remove it), which would make answerLeaksPrompt moot.

/** A marker, not "the last line": splitting on position would eat a sentence when no follow-up came. */
export const FOLLOW_UP_MARKER = "NEXT:";

/**
 * The marker must start a line (mid-sentence it is prose), and is searched from the end, since the
 * follow-up is asked for last.
 *
 * @param {string} raw
 * @returns {{ answer: string, followUp: string | null }}
 */
export function splitFollowUp(raw) {
  const lines = raw.split("\n");
  for (let i = lines.length - 1; i >= 0; i -= 1) {
    /* The ?? "" only satisfies noUncheckedIndexedAccess. */
    const line = (lines[i] ?? "").trim();
    if (!line.startsWith(FOLLOW_UP_MARKER)) continue;
    const question = line.slice(FOLLOW_UP_MARKER.length).trim();
    const answer = lines.slice(0, i).join("\n").trimEnd();
    return { answer, followUp: question.length > 0 ? question : null };
  }
  return { answer: raw, followUp: null };
}

app/lib/search/records.mjs.source:
// Section-grained: a reader lands on the matching heading, and fusion needs more than one hit per
// index to do anything. Pure: no clock, filesystem or git, so a record never carries a revision date.

import { PUBLISHED_STATUS, statusForDraft } from "./visibility.mjs";

/**
 * Fenced code is kept: the identifiers readers search for live in code blocks as often as in prose.
 *
 * @param {string} markdown
 * @returns {string}
 */
export function plainText(markdown) {
  return (
    markdown
      // Fence markers, keeping the code between them.
      .replace(/^\s{0,3}(?:```|~~~).*$/gm, "")
      // Container directives (:::figure ... :::) and their attribute lines.
      .replace(/^\s{0,3}:::.*$/gm, "")
      // Images first, so the alt text of an image does not survive as prose.
      .replace(/!\[[^\]]*\]\([^)]*\)/g, "")
      // Links keep their text, drop their target.
      .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
      // Reference-style link labels and footnote markers.
      .replace(/\[\^([^\]]+)\]/g, "")
      .replace(/^\s{0,3}\[[^\]]+\]:.*$/gm, "")
      // Leading block markers: heading hashes, quotes, list bullets.
      .replace(/^\s{0,3}#{1,6}\s+/gm, "")
      .replace(/^\s{0,3}>\s?/gm, "")
      .replace(/^\s{0,3}(?:[-*+]|\d+\.)\s+/gm, "")
      // Table pipes and separator rows.
      .replace(/^\s{0,3}\|?[\s:|-]+\|[\s:|-]*$/gm, "")
      .replace(/\|/g, " ")
      // Inline code and emphasis markers; the words they wrap stay.
      .replace(/`+/g, "")
      .replace(/\*+/g, "")
      // Underscores only as emphasis: intra-word ones are identifiers (posts_fts), as in CommonMark.
      .replace(/(?<![A-Za-z0-9])_+|_+(?![A-Za-z0-9])/g, "")
      // Whitespace last, so every rule above can leave blank lines behind.
      .replace(/\s+/g, " ")
      .trim()
  );
}

/**
 * Headings inside fences are skipped. Zipped with toc BY INDEX, since toc carries the ids rehype-slug
 * generated and re-deriving them here would drift on punctuation.
 *
 * @param {string} markdown post body with frontmatter already stripped
 * @param {Array<{ depth: number, id: string, text: string }>} toc
 * @returns {{ intro: string, sections: Array<{ anchor: string, title: string, depth: number, body: string }> }}
 */
export function splitSections(markdown, toc) {
  const lines = markdown.split(/\r?\n/);
  /*
   * @type {Array<{ line: number, depth: number }>}
   */
  const headings = [];

  let fence = "";
  for (const [i, line] of lines.entries()) {
    const fenceMatch = line.match(/^\s{0,3}(```+|~~~+)/);
    if (fenceMatch) {
      const marker = fenceMatch[1]?.[0];
      if (marker) {
        if (!fence) fence = marker;
        else if (fence === marker) fence = "";
      }
      continue;
    }
    if (fence) continue;
    const heading = line.match(/^\s{0,3}(#{2,3})\s+\S/);
    if (heading?.[1]) headings.push({ line: i, depth: heading[1].length });
  }

  // Fail closed: if this slicer and the renderer disagree on heading count, every later anchor is wrong.
  if (headings.length !== toc.length) {
    throw new Error(
      `heading count disagrees with the rendered outline: markdown has ${headings.length}, ` +
        `the pipeline collected ${toc.length}. Records would carry wrong anchors.`,
    );
  }

  const introEnd = headings[0]?.line ?? lines.length;
  const intro = plainText(lines.slice(0, introEnd).join("\n"));

  /** @type {Array<{ anchor: string, title: string, depth: number, body: string }>} */
  const sections = [];
  for (const [s, heading] of headings.entries()) {
    const entry = toc[s];
    if (!entry) throw new Error(`no toc entry for heading ${s}`);
    const start = heading.line + 1;
    const end = headings[s + 1]?.line ?? lines.length;
    sections.push({
      anchor: entry.id,
      title: entry.text,
      depth: heading.depth,
      body: plainText(lines.slice(start, end).join("\n")),
    });
  }

  return { intro, sections };
}

/**
 * @typedef {{ uid: string, url: string, type: "post" | "page", title: string, body: string, tags: string,
 *             docTags: string, docUid: string, docTitle: string, docUrl: string, anchor: string | null,
 *             ordinal: number, status: string, publishAt: any }} SearchRecord
 */

/**
 * One index record. A document's own record has no anchor and ordinal 0; a section's record takes
 * the document's uid and url with its anchor appended. Key order is fixed: the output is compared
 * across runs.
 *
 * @param {{ uid: string, url: string, type: "post" | "page", title: string, docTags: string,
 *           status: string, publishAt: any }} doc
 * @param {{ title: string, body: string, tags?: string,
 *           section?: { anchor: string, ordinal: number } }} part
 * @returns {SearchRecord}
 */
function record(doc, { title, body, tags = "", section }) {
  return {
    uid: section ? `${doc.uid}#${section.anchor}` : doc.uid,
    url: section ? `${doc.url}#${section.anchor}` : doc.url,
    type: doc.type,
    title,
    body,
    tags,
    docTags: doc.docTags,
    docUid: doc.uid,
    docTitle: doc.title,
    docUrl: doc.url,
    anchor: section ? section.anchor : null,
    ordinal: section ? section.ordinal : 0,
    status: doc.status,
    publishAt: doc.publishAt,
  };
}

/**
 * @param {any} post a rendered post record from the shared pipeline
 * @returns {SearchRecord[]}
 */
export function recordsForPost(post) {
  const tags = post.tags.join(" ");
  // Pipe-delimited on both ends so a filter can test for an exact tag with
  // instr(doc_tags, '|d1|') and never match `d1` inside `d10`.
  const docTags = post.tags.length > 0 ? `|${post.tags.join("|")}|` : "";
  const { intro, sections } = splitSections(post.markdown, post.toc);
  const doc = {
    uid: `post:${post.slug}`,
    url: `/writing/${post.slug}`,
    type: /** @type {const} */ ("post"),
    title: post.title,
    docTags,
    status: statusForDraft(post.draft),
    publishAt: post.publishAt,
  };

  /** @type {SearchRecord[]} */
  const records = [
    record(doc, {
      title: post.title,
      body: [post.description, intro].filter(Boolean).join(" "),
      tags,
    }),
  ];

  sections.forEach((section, i) => {
    // A heading with no prose of its own would match nothing and only pad the facet counts.
    if (!section.body) return;
    // Tags stay on the document: repeated per section, section count would drive identity ranking.
    records.push(
      record(doc, {
        title: section.title,
        body: section.body,
        section: { anchor: section.anchor, ordinal: i + 1 },
      }),
    );
  });

  return records;
}

/**
 * @param {any[]} posts
 * @returns {SearchRecord[]}
 */
export function recordsForPosts(posts) {
  return [...posts]
    .sort((a, b) => a.slug.localeCompare(b.slug))
    .flatMap((post) => recordsForPost(post));
}

/**
 * publishAt null and status published by design: the visibility predicate admits a null date, and
 * inventing one would put an untrue fact in the index.
 *
 * @param {{ url: string, uid: string, title: string, description: string,
 *           intro: string,
 *           sections: Array<{ anchor: string, title: string, body: string }> }} page
 * @returns {SearchRecord[]}
 */
function recordsForPage(page) {
  // Fail closed: no sections loses every deep link, and a duplicate anchor collides on uid.
  if (page.sections.length === 0) {
    throw new Error(
      `page ${page.url} produced no section records. A page indexed without ` +
        `its sections loses every deep link, which is not an empty result, it ` +
        `is a wrong one.`,
    );
  }
  const anchors = new Set(page.sections.map((s) => s.anchor));
  if (anchors.size !== page.sections.length) {
    throw new Error(
      `page ${page.url} has duplicate section anchors, so two records would ` + `share a uid.`,
    );
  }

  // No tags: a page would appear under a tag nothing else on the site shares.
  const doc = {
    uid: page.uid,
    url: page.url,
    type: /** @type {const} */ ("page"),
    title: page.title,
    docTags: "",
    status: PUBLISHED_STATUS,
    publishAt: null,
  };

  /** @type {SearchRecord[]} */
  const records = [
    record(doc, {
      title: page.title,
      body: [page.description, page.intro].filter(Boolean).join(" "),
    }),
  ];

  page.sections.forEach((section, i) => {
    if (!section.body) return;
    records.push(
      record(doc, {
        title: section.title,
        body: section.body,
        section: { anchor: section.anchor, ordinal: i + 1 },
      }),
    );
  });

  return records;
}

/**
 * Sorted by uid: the output is compared across runs, so call order must not leak into it.
 *
 * @param {any[]} pages page inputs, as `recordsForPage` takes them
 * @returns {SearchRecord[]}
 */
export function recordsForPages(pages) {
  return [...pages]
    .sort((a, b) => String(a.uid).localeCompare(String(b.uid)))
    .flatMap((page) => recordsForPage(page));
}

/**
 * One record per paper, not recordsForPage: a paper has no deep links to lose, and some have no abstract.
 * type "page" because a CHECK constraint allows only post or page, and a facet label is not worth a migration.
 *
 * @param {Array<{ uid: string, url: string, title: string, body: string }>} papers
 * @returns {SearchRecord[]}
 */
export function recordsForPapers(papers) {
  for (const paper of papers) {
    // Fail closed: an empty body would match only its own title and still look healthy.
    if (!paper.body || paper.body.trim().length === 0) {
      throw new Error(
        `paper ${paper.url} produced an empty search body. A record with no ` +
          `text is not a small record, it is one that cannot be found by ` +
          `anything except its own title.`,
      );
    }
  }
  return [...papers]
    .sort((a, b) => String(a.uid).localeCompare(String(b.uid)))
    .map((paper) =>
      // No tags: the tag facet is the blog's, and its archive would not list a paper.
      record(
        {
          uid: paper.uid,
          url: paper.url,
          type: "page",
          title: paper.title,
          docTags: "",
          status: PUBLISHED_STATUS,
          publishAt: null,
        },
        { title: paper.title, body: paper.body },
      ),
    );
}

app/lib/wordpress-redirects.mjs.source:
/**
 * The old WordPress site's addresses, answered on the apex host (and www) so they are live the moment
 * DNS moves: a 301 to the page that replaces each one, or 410 Gone for what was removed. The map is
 * cutover.md's "Redirect map" (Capsid, dustinedwards), decided 2026-09-27; this file is that record in
 * code, pattern rules first, then explicit rows.
 *
 * Host-scoped, because the workers.dev host serves the new site's own paths and must never see these.
 * These are the only moves the gateway answers: the new site's own old addresses do not redirect (Dustin,
 * 2026-10-20: "the only redirects should be from the old site to the new site").
 *
 * Paths match with and without the trailing slash. The query is ignored: a 301 never carries it, since
 * WordPress's `?et_blog` and `?profiletab=` mean nothing on the new site.
 */

import { PUBLICATIONS_PREFIX } from "./publications/pdf-redirect.mjs";
import { SITE_ORIGIN } from "./site-origin.mjs";

const APEX_HOSTS = new Set(["dustinedwards.info", "www.dustinedwards.info"]);

/** @param {string} hostname */
export function isApexHost(hostname) {
  return APEX_HOSTS.has(hostname.toLowerCase());
}

/**
 * Where a request to `www` goes: the apex, in ONE hop. The apex is the canonical host, so `www` serving the same
 * pages would be a second copy of every URL. An old WordPress address goes straight to the page that replaces it
 * (the map's own Location, which carries no query), so a `www` reader of an old URL is not sent through two
 * redirects. Everything else keeps its path and query. A removed address (410) goes to the apex too, which
 * answers it. Null for any host but `www`.
 *
 * @param {string} hostname
 * @param {string} pathname
 * @param {string} search the request's query string, with its `?`, or ""
 * @returns {string | null} an absolute https URL on the apex
 */
export function wwwRedirectTarget(hostname, pathname, search) {
  if (hostname.toLowerCase() !== "www.dustinedwards.info") return null;
  const disposition = wordpressDisposition(pathname);
  // The apex drops a trailing slash (canonicalRedirect), except on a paper and an old WordPress address, so it goes in
  // this same hop: `http://www/about/` is one redirect, not two.
  const path =
    disposition === null && !pathname.startsWith(PUBLICATIONS_PREFIX)
      ? pathname.replace(/(.)\/+$/, "$1")
      : pathname;
  const target = disposition?.status === 301 ? disposition.location : `${path}${search}`;
  return new URL(target, SITE_ORIGIN).toString();
}

/**
 * Not kept, and not put in R2: its protocol is rewritten as a page, so the old PDF address, which
 * still earns clicks, points there (Dustin, 2026-09-27).
 */
export const BAYLOR_PDF = "/wp-content/uploads/2017/09/DNA-Extraction-Protocol-Baylor.pdf";
const CV_PDF = "/wp-content/uploads/2019/02/Dustin-Edwards-Curriculum-Vitae-2019.pdf";

/**
 * Targets whose pages do not exist yet. Every 301 into one of these answers 404 until its page job
 * lands, so the switch checklist reads this list: it must be empty, or each entry accepted, before
 * DNS moves.
 */
export const PENDING_TARGETS = [
  "/research",
  "/research/retroviruses",
  "/research/bacteriophages",
  "/research/science-education",
  "/research/phages",
  "/research/protocols",
  "/research/protocols/phage-isolation",
  "/research/protocols/phage-dna-extraction",
  "/research/protocols/coi-primers",
  "/research/protocols/rev-lpdv-primers",
  "/research/protocols/pan-avian-gapdh",
  "/teaching",
  "/teaching/phage-discovery",
  "/teaching/virus-isolation",
  "/teaching/phage-bioinformatics",
  "/teaching/central-dogma",
  "/teaching/study-skills",
  "/research/retroviruses/avian",
];

/**
 * @typedef {{ status: 301, location: string } | { status: 410 }} Disposition
 */

/** Where every student and author profile goes, except Dustin's own. */
export const PROFILE_TARGET = "/teaching/phage-discovery#roster";

/** @type {(location: string) => Disposition} */
const moved = (location) => ({ status: 301, location });
/** @type {Disposition} */
const GONE = { status: 410 };

/**
 * Pattern rules, in order; each reads the path without its trailing slash. `null` passes to the next.
 * @type {Array<(path: string) => Disposition | null>}
 */
const PATTERNS = [
  (p) => {
    const name = /^\/(?:discovery|annotation)-of-([a-z0-9-]+)$/i.exec(p)?.[1];
    return name ? moved(`/research/phages#${name.toLowerCase()}`) : null;
  },
  (p) =>
    [
      "/phylogenetics-lysm",
      "/arlo-gene-67",
      "/arlo-gene-67-cloning",
      "/raspberry-pi-plaque-counter",
    ].includes(p)
      ? moved("/research/phages")
      : null,
  // The lab's own directory answered "how do I join", so it goes to Join the lab, ahead of the rule below.
  (p) => (p === "/directory-research-group" ? moved("/teaching#join-the-lab") : null),
  (p) => (/^\/directory-[^/]+$/.test(p) ? moved("/teaching/phage-discovery") : null),
  // Dustin's own author page ranks for his name, so it goes to the About page, ahead of the rule below.
  (p) => (p === "/author/dustin" ? moved("/about") : null),
  // The bare /user/ was the membership directory, so it is gone with the membership pages.
  (p) =>
    ["/user", "/register", "/members", "/logout", "/account", "/password-reset"].includes(p)
      ? GONE
      : null,
  // Every other student and author profile (146 in Search Console, 147 with Dustin's own) goes to the
  // roster at the bottom of the Phage Discovery Program page, as on the old site (Dustin, 2026-09-27).
  (p) => (/^\/(?:user|author)(?:\/.*)?$/.test(p) ? moved(PROFILE_TARGET) : null),
  (p) =>
    /^\/(?:category\/phage-isolation-notes|microbiomes\/page|phages\/page)(?:\/.*)?$/.test(p)
      ? moved("/research/phages")
      : null,
  (p) => (/^\/knowledge-base\/category(?:\/.*)?$/.test(p) ? moved("/research/protocols") : null),
  (p) => (/^\/(?:category|tag)(?:\/.*)?$/.test(p) ? GONE : null),
  (p) => (p === BAYLOR_PDF ? moved("/research/protocols/phage-dna-extraction") : null),
  (p) => (p === CV_PDF ? moved("/dustin-edwards-cv.pdf") : null),
  // Both still earn clicks or impressions: a lab protocol goes to the page that carries it.
  (p) =>
    p === "/wp-content/uploads/2023/11/Electrophoresis.pdf" ? moved("/research/protocols") : null,
  (p) =>
    p === "/wp-content/uploads/2023/11/DNA-Extraction-Scan.pdf"
      ? moved("/research/protocols/phage-dna-extraction")
      : null,
  (p) => (p.startsWith("/wp-content/uploads/") ? GONE : null),
  // Nothing on the new site does these calculations (Dustin, 2026-09-27).
  (p) => (["/molarity-calculator", "/knowledge-base/metric-prefix"].includes(p) ? GONE : null),
];

/** Explicit rows, keyed by the old path without its trailing slash. */
const ROWS = /** @type {Record<string, string>} */ ({
  // Yoast's sitemap index, which Search Console still holds from the WordPress site.
  "/sitemap_index.xml": "/sitemap.xml",
  "/knowledge-base/pcr-coi-lco1490-hco2198": "/research/protocols/coi-primers",
  // The old pages were a course and a program, so each goes to the course or program, not a protocol.
  "/virus-isolation": "/teaching/virus-isolation",
  "/phage-discovery": "/teaching/phage-discovery",
  // No Wolbachia page: it is not Dustin's research any more, so its methods land on the protocols.
  "/wolbachia-project-genetic-techniques": "/research/protocols",
  "/knowledge-base/pcr-wolbachia-16s-rrna": "/research/protocols",
  "/gentech-2018a": "/research/protocols",
  "/research": "/research",
  "/knowledge-base/pcr-rev-3-ltr-8000-8297": "/research/protocols/rev-lpdv-primers",
  "/knowledge-base/pcr-rev-pol-2500-3750": "/research/protocols/rev-lpdv-primers",
  "/knowledge-base/pcr-rev-pol-4777-5575": "/research/protocols/rev-lpdv-primers",
  "/knowledge-base/pcr-pan-avian-gapdh": "/research/protocols/pan-avian-gapdh",
  "/publications": "/research/publications",
  "/manuscripts": "/research/publications",
  "/knowledge-base/rev-lpdv-2018-2020-database": "/research/publications",
  "/knowledge-base/rev-lpdv-2023-2025-database": "/research/publications",
  "/virology-course": "/teaching",
  "/genetics-course": "/teaching",
  "/vaccines-course": "/teaching",
  "/cell-biology-course": "/teaching",
  "/lecture-courses": "/teaching",
  "/courses": "/teaching",
  "/related-courses": "/teaching",
  "/research-lab-courses": "/teaching",
  "/study-skills-guide": "/teaching/study-skills",
  "/prospective-students": "/teaching#join-the-lab",
  "/biomedical-sciences-academic-advising": "/teaching",
  "/teaching-philosophy": "/teaching#teaching-philosophy",
  "/tarleton-biological-sciences-biomedical-sciences-and-biology": "/teaching",
  "/phages": "/research/phages",
  "/phage-archives": "/research/phages",
  "/microbiomes": "/research",
  "/laboratory": "/research",
  "/phage-bioinformatics": "/teaching/phage-bioinformatics",
  "/phage-genetic-studies": "/research/bacteriophages",
  "/phage-discovery-application": "/teaching/phage-discovery",
  "/central-dogma-tutorials": "/teaching/central-dogma",
  "/retroviruses": "/research/retroviruses",
  "/rev-lpdv-surveys": "/research/retroviruses/avian",
  "/rev-lpdv-genetic-studies": "/research/retroviruses/avian",
  "/knowledge-base": "/research/protocols",
  "/virus-isolation-reagent-request": "/teaching/virus-isolation",
});

/** Kept at their own address: the home page, and the two pages the new site answers itself. */
const KEPT = new Set(["", "/contact", "/login"]);

/** Every explicit row's old path, for the tests. */
export const EXPLICIT_ROWS = Object.freeze({ ...ROWS });

/**
 * What an apex request for `pathname` gets: a 301 with its path-only Location, a 410, or null when the
 * new site answers the path itself (a kept page, or anything the map does not name).
 *
 * @param {string} pathname the request's pathname, already decoded by URL
 * @returns {{ status: 301, location: string } | { status: 410 } | null}
 */
export function wordpressDisposition(pathname) {
  if (typeof pathname !== "string" || !pathname.startsWith("/")) return null;
  const path = pathname.length > 1 ? pathname.replace(/\/+$/, "") : "";
  if (KEPT.has(path)) return null;

  let disposition = null;
  for (const rule of PATTERNS) {
    disposition = rule(path);
    if (disposition) break;
  }
  const row = Object.hasOwn(ROWS, path) ? ROWS[path] : undefined;
  if (!disposition && row) disposition = moved(row);
  if (!disposition) return null;

  // A row that rebuilds a page at its own address (`/research/` to `/research`) redirects only the
  // slashed form; the bare form is the page, and redirecting it to itself would loop.
  if (disposition.status === 301 && disposition.location === pathname) return null;
  return disposition;
}

app/kb/form-fields.mjs.source:
// What the Knowledge Base form shows for each front-matter field (docs/KNOWLEDGE-BASE.md): its label, the input it is
// edited with and, for a choice, the closed list it is chosen from. The lists are the ones the validator holds a file to
// (taxonomy.mjs, validate.mjs), so the form cannot offer a value the save would refuse. A field not named here is still
// edited, as YAML, so nothing in a file is out of the form's reach.

import { BIOSAFETY_LEVELS, HOWTO_TYPES } from "./procedures/validate.mjs";
import {
  COURSES,
  METHODS,
  NON_STRAIN_ORGANISMS,
  PROTOCOL_STATUSES,
} from "./procedures/taxonomy.mjs";

/**
 * @typedef {"text" | "textarea" | "lines" | "date" | "number" | "checkbox" | "select" | "multi" | "choice" | "materials" | "equipment" | "primers" | "strains" | "readonly" | "yaml"} FieldKind
 * @typedef {{ key: string, label: string, kind: FieldKind, help?: string, options?: Array<{ value: string, label: string }> }} FieldSpec
 */

/** A key the form has no label for, in words: "published_doi" is "Published DOI". @param {string} key */
export const keyWords = (key) =>
  key
    .replaceAll("_", " ")
    .replace(/\b(doi|rrid|url|atcc|id|pmid)\b/gi, (m) => m.toUpperCase())
    .replace(/^./, (c) => c.toUpperCase());

/** @param {Record<string, string | { label: string }>} map */
const options = (map) =>
  Object.entries(map).map(([value, label]) => ({
    value,
    label: typeof label === "string" ? label : label.label,
  }));

/** Every profile's fields first, in the order a person fills them in. @type {FieldSpec[]} */
const COMMON = [
  { key: "title", label: "Title", kind: "text" },
  {
    key: "seo_title",
    label: "Search title",
    kind: "text",
    help: "The title search engines show; at most 60 characters.",
  },
  {
    key: "description",
    label: "Description",
    kind: "textarea",
    help: "One sentence, at most 155 characters.",
  },
  { key: "draft", label: "Draft (only you can see it)", kind: "checkbox" },
  {
    key: "version",
    label: "Version",
    kind: "text",
    help: "Letters, digits, dots and hyphens, such as 2 or 1.1. A version, once published, is frozen.",
  },
  { key: "updated", label: "Updated", kind: "date" },
];

/** @type {FieldSpec[]} */
const PROTOCOL = [
  { key: "status", label: "Status", kind: "select", options: options(PROTOCOL_STATUSES) },
  {
    key: "biosafety_level",
    label: "Biosafety level",
    kind: "choice",
    options: BIOSAFETY_LEVELS.map((v) => ({ value: v, label: v })),
  },
  { key: "method", label: "Method", kind: "multi", options: options(METHODS) },
  { key: "course", label: "Courses", kind: "multi", options: options(COURSES) },
  { key: "organism", label: "Organisms", kind: "multi" },
  {
    key: "target",
    label: "Targets",
    kind: "lines",
    help: "One per line: a gene, region or sample.",
  },
  { key: "first_used", label: "First used", kind: "text" },
  { key: "last_run", label: "Last run", kind: "date" },
  {
    key: "start_here",
    label: "Start-here position",
    kind: "number",
    help: "Its place in the library's Start here list; leave empty for none.",
  },
  { key: "host_strain", label: "Host strains", kind: "strains" },
  { key: "primers", label: "Primers", kind: "primers" },
  { key: "materials", label: "Reagents", kind: "materials" },
  { key: "equipment", label: "Equipment", kind: "equipment" },
  {
    key: "biosafety",
    label: "Biosafety agent",
    kind: "yaml",
    help: "The agent only: { organism, strain, atcc }, or not applicable.",
  },
  { key: "expected_results", label: "Expected results", kind: "textarea" },
  { key: "limitations", label: "Limitations", kind: "textarea" },
];

/** @type {FieldSpec[]} */
const RECIPE = [
  { key: "servings", label: "Servings", kind: "number" },
  { key: "prep_time", label: "Prep time", kind: "text" },
  { key: "cook_time", label: "Cook time", kind: "text" },
  { key: "cuisine", label: "Cuisine", kind: "text" },
  { key: "category", label: "Category", kind: "text" },
  { key: "diet", label: "Diet", kind: "lines" },
  { key: "materials", label: "Ingredients", kind: "materials" },
  { key: "equipment", label: "Equipment", kind: "equipment" },
];

/** @type {FieldSpec[]} */
const COMPUTATIONAL = [
  {
    key: "type",
    label: "Type",
    kind: "select",
    options: options(HOWTO_TYPES),
    help: "A tutorial teaches, step by step; a how-to gets one task done.",
  },
  {
    key: "questions",
    label: "Questions",
    kind: "lines",
    help: "One per line: what the reader will be able to answer.",
  },
  {
    key: "objectives",
    label: "Objectives",
    kind: "lines",
    help: "One per line: what the reader will be able to do. A tutorial needs them.",
  },
  {
    key: "key_points",
    label: "Key points",
    kind: "lines",
    help: "One per line, shown at the end.",
  },
  { key: "method", label: "Method", kind: "multi", options: options(METHODS) },
  { key: "course", label: "Courses", kind: "multi", options: options(COURSES) },
  { key: "environment", label: "Environment", kind: "textarea" },
  { key: "prerequisites", label: "Prerequisites", kind: "lines" },
  { key: "materials", label: "Software and data", kind: "materials" },
  { key: "expected_results", label: "Expected results", kind: "textarea" },
  { key: "limitations", label: "Limitations", kind: "textarea" },
];

/** Shown, never edited: a procedure's profile and address are its file's name and place (the validator ties them). */
const FIXED = [
  { key: "profile", label: "Profile", kind: /** @type {const} */ ("readonly") },
  { key: "path", label: "Address", kind: /** @type {const} */ ("readonly") },
  { key: "forked_from", label: "Copied from", kind: /** @type {const} */ ("readonly") },
];

/**
 * The fields of an entry of `profile`, then every other field the file has, as YAML. The organism list is the registry's
 * strains and the non-strain organisms, the list the validator holds `organism` to.
 *
 * @param {string} profile
 * @param {Record<string, unknown>} data
 * @param {Array<{ value: string, label: string }>} strains
 * @returns {FieldSpec[]}
 */
export function entryFields(profile, data, strains) {
  const own =
    profile === "recipe" ? RECIPE : profile === "computational" ? COMPUTATIONAL : PROTOCOL;
  /** @type {FieldSpec[]} */
  const specs = [...FIXED, ...COMMON, ...own].map((spec) =>
    spec.key === "organism"
      ? { ...spec, options: [...strains, ...options(NON_STRAIN_ORGANISMS)] }
      : spec,
  );
  const named = new Set(specs.map((s) => s.key));
  const rest = Object.keys(data)
    .filter((key) => !named.has(key))
    .map((key) => ({ key, label: keyWords(key), kind: /** @type {const} */ ("yaml") }));
  return [...specs, ...rest];
}

/**
 * A field's label as the form shows it, for any key a file of `profile` can have.
 *
 * @param {string} profile
 * @param {string} key
 */
export function fieldLabel(profile, key) {
  const own =
    profile === "recipe" ? RECIPE : profile === "computational" ? COMPUTATIONAL : PROTOCOL;
  return [...FIXED, ...COMMON, ...own].find((s) => s.key === key)?.label ?? keyWords(key);
}

/**
 * A registry item's fields: its name, whether it is a draft, then every field its kind declares. A field that holds true
 * or false is a checkbox; every other is text, since a kind's fields are words (docs/REGISTRY.md).
 *
 * @param {string[]} declared
 * @param {Record<string, unknown>} data
 * @returns {FieldSpec[]}
 */
export function itemFields(declared, data) {
  return [
    { key: "name", label: "Name", kind: "text" },
    { key: "draft", label: "Draft (only you can see it)", kind: "checkbox" },
    ...declared.map((key) => ({
      key,
      label: keyWords(key),
      kind: /** @type {FieldKind} */ (
        typeof data[key] === "boolean" || key.startsWith("prepared_") ? "checkbox" : "text"
      ),
    })),
  ];
}

/** A recorded gap's reason, or null for a value. @param {unknown} value */
export function gapReason(value) {
  const match = typeof value === "string" ? /^MISSING:\s*([\s\S]+)$/.exec(value) : null;
  return match ? /** @type {string} */ (match[1]) : null;
}

app/kb/procedures/key-resources.mjs.source:
// A protocol's Key Resources Table (docs/KNOWLEDGE-BASE.md, step 6), in the shape Cell Press's STAR Methods ask for:
// each resource with its source and identifier, grouped by type. Computed from the record, never stored or typed: the
// strains, reagents, primers and equipment a protocol names are the lab registry's, baked into the record when it is
// compiled, so the table, the page's own tables and the twin print the same facts. A fact the registry records as a gap
// reads "Not recorded", and an identifier a resource does not have reads "N/A", as STAR tables write it.

const NOT_RECORDED = "Not recorded";
const NONE = "N/A";

/**
 * @typedef {{ resource: string, sequence?: string, href: string | null, source: string, identifier: string }} KeyResource
 * @typedef {{ id: string, heading: string, rows: KeyResource[] }} KeyResourceGroup
 */

/**
 * The table's groups, in STAR's order, each holding at least one row; empty for a record that is not a protocol or names
 * nothing from the registry.
 *
 * @param {import("./render.mjs").ProcedureRecord} record
 * @returns {KeyResourceGroup[]}
 */
export function keyResources(record) {
  if (record.profile !== "protocol") return [];

  const strains = record.hostStrains.map((s) => ({
    resource: s.name,
    href: s.path,
    source: s.collection ?? NOT_RECORDED,
    // The registry stores the collection and its number apart ("ATCC", "700084"); a table names the deposit with both.
    identifier: s.collectionNumber
      ? [s.collection, s.collectionNumber].filter(Boolean).join(" ")
      : NONE,
  }));

  // A reagent once, however many materials name it, in the order the protocol first names it.
  const seen = new Set();
  const chemicals = [];
  for (const m of record.materials) {
    const r = m.reagent;
    if (!r || seen.has(r.id)) continue;
    seen.add(r.id);
    chemicals.push({
      resource: r.name,
      href: null,
      source: r.preparedInLab ? "Prepared in the lab" : (r.supplier ?? NOT_RECORDED),
      identifier: r.preparedInLab
        ? NONE
        : r.catalogNumber
          ? `Cat# ${r.catalogNumber}`
          : NOT_RECORDED,
    });
  }

  // A primer's sequence, 5′ to 3′, is a part of the row, as STAR tables give it, kept apart from its name so the page can set
  // it in monospace and let it break anywhere.
  const oligos = record.primers.map((p) => ({
    resource: p.name,
    ...(p.sequence ? { sequence: `5′-${p.sequence}-3′` } : {}),
    href: `/research/lab/primers/${p.id}`,
    source: p.publishedIn ?? NOT_RECORDED,
    identifier: NONE,
  }));

  const other = record.equipment.flatMap((e) =>
    e.item
      ? [
          {
            resource: e.item.name,
            href: null,
            source: e.item.manufacturer ?? NOT_RECORDED,
            identifier: NONE,
          },
        ]
      : [],
  );

  return [
    { id: "strains", heading: "Bacterial and virus strains", rows: strains },
    { id: "chemicals", heading: "Chemicals, peptides, and recombinant proteins", rows: chemicals },
    { id: "oligonucleotides", heading: "Oligonucleotides", rows: oligos },
    { id: "other", heading: "Other", rows: other },
  ].filter((group) => group.rows.length > 0);
}

/** A cell's text for a markdown table: pipes escaped, so a citation with one cannot split the row. @param {string} text */
const cell = (text) => text.replace(/\|/g, "\\|");

/**
 * The table as the twin prints it: one markdown table, each group a bold row above its resources.
 *
 * @param {KeyResourceGroup[]} groups
 * @returns {string[]} lines, ending with a blank one; none when there is nothing to list
 */
export function keyResourcesMarkdown(groups) {
  if (groups.length === 0) return [];
  const out = [
    "## Key resources",
    "",
    "| Reagent or resource | Source | Identifier |",
    "| --- | --- | --- |",
  ];
  for (const group of groups) {
    out.push(`| **${cell(group.heading)}** | | |`);
    for (const row of group.rows) {
      const name = row.href ? `[${cell(row.resource)}](${row.href})` : cell(row.resource);
      const sequence = row.sequence ? `: \`${row.sequence}\`` : "";
      out.push(`| ${name}${sequence} | ${cell(row.source)} | ${cell(row.identifier)} |`);
    }
  }
  out.push("");
  return out;
}

app/kb/procedures/library.mjs.source:
// The protocol library's one declaration (docs/PROCEDURES.md): the fields a protocol is searched, filtered, sorted
// and listed by, declared once for Capsomer's catalog. The page, its facets and counts, its sort menu, the CSV and
// JSON downloads and the markdown twin all read this, so a field is described in exactly one place and a protocol's
// facts are drawn from its record, never typed again. Pure: the route passes in the records it read from D1.

import {
  catalogRedirect,
  defineCatalog,
  parseCatalogParams,
  queryCatalog,
} from "capsomer/behavior/catalog";

import { TOOLS } from "../../lib/phage-tools.mjs";
import {
  CALCULATORS_PATH,
  COURSES,
  LIBRARY_PATH,
  LIBRARY_TABS,
  METHODS,
  PHAGE_PIPELINE,
  courseLabel,
  methodLabel,
  NON_STRAIN_ORGANISMS,
  organismLabel,
  rememberOrganisms,
} from "./taxonomy.mjs";

export { LIBRARY_PATH };

/** The kinds a library entry can be: a bench protocol, or a computational method. */
const KINDS = Object.freeze({ protocol: "Protocol", computational: "Computational method" });

/** @param {string} id */
const kindLabel = (id) => /** @type {Record<string, string>} */ (KINDS)[id] ?? id;

/**
 * The one fact worth showing beside a title, drawn from the record and never typed: what it works on (its targets),
 * else how long it takes. A fact the record does not hold is left out; nothing stands in for it.
 *
 * @param {{ targets: string[], time: { total: string | null } }} record
 */
export function keyFact(record) {
  if (record.targets.length > 0) return record.targets.join(", ");
  if (record.time.total) return record.time.total;
  return "";
}

/** How many steps a record has, over all its method sections. @param {import("./render.mjs").ProcedureRecord} record */
export function stepCount(record) {
  let n = 0;
  for (const section of record.sections) {
    for (const block of section.blocks) if (block.type === "steps") n += block.steps.length;
  }
  return n;
}

/**
 * The library's rows: the published protocols, each reduced to what the catalog reads. Software how-tos and recipes
 * have libraries of their own (app/kb/libraries.mjs).
 *
 * @param {Array<import("./render.mjs").ProcedureRecord>} records
 */
export function libraryItems(records) {
  for (const r of records) rememberOrganisms(r.organismNames ?? {});
  return records
    .filter((r) => r.profile === "protocol")
    .map((r) => ({
      slug: r.slug,
      path: r.path,
      title: r.title,
      description: r.description,
      kind: r.profile,
      methods: r.methods,
      organisms: r.organisms,
      targets: r.targets,
      courses: r.courses,
      updated: r.updated ? String(r.updated) : "",
      version: r.version ? String(r.version) : "",
      time: r.time.total ? String(r.time.total) : "",
      steps: stepCount(r),
      keyFact: keyFact(r),
      startHere: r.startHere ?? null,
    }));
}

/** @typedef {ReturnType<typeof libraryItems>[number]} LibraryItem */

/**
 * The catalog: fields in the order the facets, columns and sort menu list them. There is no Kind facet while every
 * entry is a protocol, because a facet of one value filters nothing; it returns with the first computational method.
 */
export const LIBRARY = defineCatalog(
  /** @type {import("capsomer/behavior/catalog").CatalogDefinition<LibraryItem>} */ ({
    id: "protocols",
    noun: ["protocol", "protocols"],
    basePath: LIBRARY_PATH,
    itemKey: (p) => p.slug,
    defaultSort: "title",
    pageSize: 25,
    fields: [
      {
        key: "title",
        label: "Protocol",
        value: (p) => p.title,
        search: 3,
        column: { header: "Protocol" },
        sort: true,
      },
      { key: "description", label: "Description", value: (p) => p.description, search: 1 },
      {
        key: "method",
        label: "Method",
        value: (p) => p.methods,
        facet: { kind: "many", general: true, label: methodLabel },
        column: { header: "Method", drop: 1 },
        search: 1,
      },
      {
        key: "organism",
        label: "Organism",
        value: (p) => p.organisms,
        facet: { kind: "many", label: organismLabel },
        search: 1,
      },
      {
        key: "target",
        label: "Target",
        value: (p) => p.targets,
        facet: { kind: "many", order: "alpha" },
        search: 2,
      },
      {
        key: "course",
        label: "Course",
        value: (p) => p.courses,
        facet: { kind: "many", label: courseLabel },
      },
      {
        key: "fact",
        label: "Key fact",
        value: (p) => p.keyFact,
        column: { header: "Key fact", drop: 2 },
      },
      {
        key: "steps",
        label: "Steps",
        value: (p) => p.steps,
        type: "number",
        sort: true,
        column: { header: "Steps", align: "end", drop: 2 },
      },
      {
        key: "links",
        label: "Quick links",
        value: () => "",
        column: { header: "Quick links", drop: 2 },
      },
      {
        key: "updated",
        label: "Updated",
        value: (p) => p.updated,
        type: "date",
        sort: { labels: { asc: "Updated, oldest first", desc: "Updated, newest first" } },
      },
    ],
  }),
);

/**
 * The library as rows for a download: every fact the page shows, for the filter state in the address, as ids with
 * their words, so a machine reads what a person sees. The CSV and the JSON are both this.
 *
 * @param {LibraryItem[]} items
 * @param {URLSearchParams | string} params
 * @param {string} origin
 */
export function libraryRecords(items, params, origin) {
  const state = parseCatalogParams(LIBRARY, params);
  return queryCatalog({ ...LIBRARY, pageSize: undefined }, items, { ...state, page: 1 }).rows.map(
    (p) => ({
      id: p.slug,
      title: p.title,
      url: `${origin}${p.path}`,
      kind: kindLabel(p.kind),
      methods: p.methods.map(methodLabel),
      organisms: p.organisms.map(organismLabel),
      targets: p.targets,
      courses: p.courses.map(courseLabel),
      steps: p.steps,
      time: p.time,
      version: p.version,
      updated: p.updated,
      description: p.description,
    }),
  );
}

/**
 * The same rows as CSV (RFC 4180): a list field is its values joined with "; ". A cell is quoted when it holds a
 * comma, a quote or a line break.
 *
 * @param {Array<Record<string, unknown>>} rows a library's download rows, its own or another base's (app/kb/libraries.mjs)
 */
export function libraryCsv(rows) {
  const columns = Object.keys(rows[0] ?? { id: 1, title: 1, url: 1 });
  const cellOf = (/** @type {unknown} */ value) => {
    const text = Array.isArray(value) ? value.join("; ") : String(value ?? "");
    return /[",\r\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
  };
  return `${[columns.join(","), ...rows.map((row) => columns.map((c) => cellOf(row[c])).join(","))].join("\r\n")}\r\n`;
}

/** One cell of a markdown table. @param {string} text */
const cell = (text) => text.replaceAll("|", "\\|").replace(/\s+/g, " ").trim();

/**
 * The twin's table: every protocol with the facts the page shows, drawn from the same items. Links are to the
 * protocols' own pages, so an agent can follow them.
 *
 * @param {LibraryItem[]} items
 * @param {string} origin
 */
export function libraryMarkdown(items, origin) {
  const head = ["Protocol", "Method", "Organism", "Target", "Course", "Steps", "Updated"];
  const rows = items.map((p) =>
    [
      `[${cell(p.title)}](${origin}${p.path})`,
      p.methods.map(methodLabel).join(", "),
      p.organisms.map(organismLabel).join(", "),
      p.targets.join(", "),
      p.courses.map(courseLabel).join(", "),
      String(p.steps),
      p.updated,
    ].map((c, i) => (i === 0 ? c : cell(c))),
  );
  return [
    `| ${head.join(" | ")} |`,
    `| ${head.map(() => "---").join(" | ")} |`,
    ...rows.map((r) => `| ${r.join(" | ")} |`),
  ].join("\n");
}

/** @param {number} n @param {[string, string]} noun */
export const countOf = (n, noun) => `${n} ${n === 1 ? noun[0] : noun[1]}`;

/**
 * The overview's counts as a sentence: the one the page's count line and the twin both carry.
 *
 * @param {ReturnType<typeof libraryOverview>} overview
 */
export function overviewSentence(overview) {
  const parts = [
    `${countOf(overview.total, ["protocol", "protocols"])} across ${countOf(overview.methods, ["method", "methods"])}`,
    overview.organisms > 0 ? `${countOf(overview.organisms, ["organism", "organisms"])}` : "",
    overview.updated ? `newest updated ${overview.updated}` : "",
  ].filter(Boolean);
  return `${parts.join(", ")}.`;
}

/**
 * The overview for the twin: the count sentence, the workflow as a list with a link for each stage that has
 * protocols, and the methods with their counts, so a machine reads what the page shows.
 *
 * @param {ReturnType<typeof libraryOverview>} overview
 * @param {string} origin
 */
export function overviewMarkdown(overview, origin) {
  const noun = /** @type {[string, string]} */ (["protocol", "protocols"]);
  const stage = (/** @type {(typeof overview.stages)[number]} */ s) =>
    (s.href ? `- [${s.label}](${origin}${s.href}): ${countOf(s.count, noun)}` : `- ${s.label}`) +
    s.tools.map((t) => `\n  - [${t.label}](${origin}${t.href})`).join("");
  return [
    "## In the library",
    "",
    overviewSentence(overview),
    ...(overview.start.length > 0
      ? [
          "",
          "### Start here",
          "",
          ...overview.start.map(
            (p, i) => `${i + 1}. [${p.title}](${origin}${p.href}): ${p.description}`,
          ),
        ]
      : []),
    "",
    "### The phage workflow",
    "",
    ...overview.stages.map(stage),
    ...overview.browse.flatMap((group) => [
      "",
      `### ${group.title}`,
      "",
      ...group.tiles.map((t) => {
        const about =
          "about" in t && typeof t.about === "string"
            ? ` ([about the course](${origin}${t.about}))`
            : "";
        return `- [${t.label}](${origin}${t.href}): ${countOf(t.count, noun)}${about}`;
      }),
    ]),
    "",
    "### Calculators",
    "",
    `- [Phage Lab Calculators](${origin}${CALCULATORS_PATH}): ${countOf(calculatorCount(), ["calculator", "calculators"])}`,
  ].join("\n");
}

/**
 * The address of the library narrowed to some values of a facet: the one a person reaches by choosing them there.
 *
 * @param {string} key the facet's parameter (method, organism, course)
 * @param {readonly string[]} values
 */
function facetHref(key, values) {
  return `${LIBRARY_PATH}?${values.map((v) => `${key}=${encodeURIComponent(v)}`).join("&")}`;
}

/** The library narrowed to some methods. @param {readonly string[]} methods */
export function methodHref(methods) {
  return facetHref("method", methods);
}

/**
 * A calculator as a link: its page and the name its form carries, both from the one registry. An id the registry does
 * not know is an error here, not a missing link.
 *
 * @param {string} id
 */
export function toolLink(id) {
  const tool = TOOLS[id];
  if (!tool)
    throw new Error(
      `the phage workflow names a calculator "${id}" that phage-tools.mjs does not define`,
    );
  return { id, label: tool.title, href: tool.path };
}

/**
 * What the library says about itself, counted from its rows: how many protocols, over how many methods and
 * organisms, when the newest changed, a tile for each method that has a protocol, and the phage workflow with the
 * number of protocols under each stage. Nothing here is typed: a protocol saved changes every figure.
 *
 * @param {LibraryItem[]} items
 */
export function libraryOverview(items) {
  /** A tile for each id of a closed list that has a protocol: its words, its count and the library narrowed to it. */
  const tilesOf = (
    /** @type {string} */ key,
    /** @type {Record<string, unknown>} */ list,
    /** @type {(item: LibraryItem) => readonly string[]} */ valuesOf,
    /** @type {(id: string) => string} */ label,
  ) =>
    Object.keys(list)
      .map((id) => ({
        id,
        label: label(id),
        count: items.filter((p) => valuesOf(p).includes(id)).length,
        href: facetHref(key, [id]),
      }))
      .filter((tile) => tile.count > 0);
  const tiles = tilesOf("method", METHODS, (p) => p.methods, methodLabel);
  const browse = [
    { id: "method", title: "Browse by method", tiles },
    {
      id: "course",
      title: "Browse by course",
      // A course's tile also names the page that describes it, so the course is one click from its protocols.
      tiles: tilesOf("course", COURSES, (p) => p.courses, courseLabel).map((tile) => ({
        ...tile,
        about: COURSES[/** @type {keyof typeof COURSES} */ (tile.id)].path,
      })),
    },
    {
      id: "organism",
      title: "Browse by organism",
      tiles: tilesOf(
        "organism",
        Object.fromEntries(
          [...new Set(items.flatMap((p) => p.organisms))]
            .sort(
              (a, b) =>
                Number(Object.hasOwn(NON_STRAIN_ORGANISMS, a)) -
                  Number(Object.hasOwn(NON_STRAIN_ORGANISMS, b)) ||
                organismLabel(a).localeCompare(organismLabel(b), "en"),
            )
            .map((id) => [id, true]),
        ),
        (p) => p.organisms,
        organismLabel,
      ),
    },
  ].filter((group) => group.tiles.length > 0);
  const stages = PHAGE_PIPELINE.map((stage) => {
    const count = items.filter((p) => p.methods.some((m) => stage.methods.includes(m))).length;
    const tools = stage.tools.map((id) => toolLink(id));
    return {
      id: stage.id,
      label: stage.label,
      count,
      href: count > 0 ? methodHref(stage.methods) : null,
      tools,
    };
  });
  // The protocols that say where to begin, in the position each states (never inferred from anything else).
  const start = items
    .filter((p) => p.startHere !== null)
    .sort((a, b) => /** @type {number} */ (a.startHere) - /** @type {number} */ (b.startHere))
    .map((p) => ({ slug: p.slug, title: p.title, href: p.path, description: p.description }));
  const dates = items
    .map((p) => p.updated)
    .filter(Boolean)
    .sort();
  return {
    total: items.length,
    methods: tiles.length,
    organisms: new Set(items.flatMap((p) => p.organisms)).size,
    updated: dates.at(-1) ?? "",
    tiles,
    browse,
    stages,
    start,
  };
}

/**
 * The tabs over the catalog: All, then each kind of work with the number of protocols in it. A tab is a link, so a
 * tab, Back and a bookmark all work with no script. The current one is the tab whose methods are exactly the method
 * filter in the address; All is current while no method is chosen. The registry's kinds (primers, as they land) follow the
 * calculators as links to their own pages, counted from the registry and never the current tab here.
 *
 * @param {LibraryItem[]} items
 * @param {readonly string[]} chosen the method ids in the address
 * @param {Array<{ id: string, label: string, count: number, href: string }>} [registry] one entry for each registry kind that has items
 */
export function libraryTabs(items, chosen, registry = []) {
  const same = (/** @type {readonly string[]} */ methods) =>
    chosen.length === methods.length && methods.every((m) => chosen.includes(m));
  return [
    {
      id: "all",
      label: "All",
      count: items.length,
      href: LIBRARY_PATH,
      current: chosen.length === 0,
    },
    ...LIBRARY_TABS.map((tab) => ({
      id: tab.id,
      label: tab.label,
      count: items.filter((p) => p.methods.some((m) => tab.methods.includes(m))).length,
      href: methodHref(tab.methods),
      current: same(tab.methods),
    })),
    // The calculators are not protocols, so they are not rows of this catalog: their tab is a link to their own page,
    // counted from the registry that holds them, and never the current one here.
    {
      id: "calculators",
      label: "Calculators",
      count: calculatorCount(),
      href: CALCULATORS_PATH,
      current: false,
    },
    ...registry.map((tab) => ({ ...tab, current: false })),
  ];
}

/** How many calculator pages there are: the distinct pages the registry's tools sit on. */
function calculatorCount() {
  return new Set(Object.values(TOOLS).map((tool) => tool.path)).size;
}

/**
 * The address a request should have, or null. The catalog's own redirect sends an address with defaults spelled out,
 * or in another order, to its one clean address; and it drops every parameter it does not know. The library keeps
 * the first and leaves the second alone: a tracking parameter or a cache-buster on a library address is served, not
 * redirected, so a link carrying one still lands on the page it names.
 *
 * @param {URL} url
 */
export function libraryRedirect(url) {
  const known = new Set([
    "q",
    "sort",
    "page",
    ...LIBRARY.fields.filter((f) => f.facet).map((f) => f.key),
  ]);
  const kept = new URLSearchParams();
  for (const [key, value] of url.searchParams) if (known.has(key)) kept.append(key, value);
  const only = new URL(url);
  only.search = kept.toString();
  return catalogRedirect(LIBRARY, only);
}

/**
 * How to cite the library, from the site's own identity and the library's address: nothing typed here but the shape
 * of a citation. The date of access is the reader's to add.
 *
 * @param {{ name: string, affiliation: string, origin: string }} who
 */
export function libraryCitation({ name, affiliation, origin }) {
  const lab = `${name} Lab`;
  return {
    library: `${name}. Protocol library. ${lab}, ${affiliation}. ${origin}${LIBRARY_PATH}`,
    access: "Add the date you accessed it.",
    protocol:
      "To cite one protocol, cite its own page: its title, the lab, the institution, its address and the date you accessed it. " +
      "A protocol's page names the papers it follows, so cite those for the method itself.",
  };
}

/**
 * The downloads of a view: the CSV and the JSON carry the filter state the address does, so what is downloaded is what is
 * shown; the markdown twin is always the whole library.
 *
 * @param {{ href: () => string }} result the catalog's result, whose `href()` is the clean address of this view
 */
export function libraryDownloads(result) {
  const href = result.href();
  const query = href.includes("?") ? href.slice(href.indexOf("?")) : "";
  return {
    csv: `${LIBRARY_PATH}.csv${query}`,
    json: `${LIBRARY_PATH}.json${query}`,
    markdown: `${LIBRARY_PATH}.md`,
  };
}

/**
 * The twin's "Download and cite": the same addresses and the same citation the page shows, as absolute links.
 *
 * @param {ReturnType<typeof libraryCitation>} citation
 * @param {string} origin
 */
export function citeMarkdown(citation, origin) {
  return [
    "## Download and cite",
    "",
    `- [CSV](${origin}${LIBRARY_PATH}.csv): every protocol with every fact the table shows; a filtered address gives the filtered rows`,
    `- [JSON](${origin}${LIBRARY_PATH}.json): the same rows`,
    `- [Markdown](${origin}${LIBRARY_PATH}.md): this page`,
    "",
    "### Cite the library",
    "",
    citation.library,
    "",
    citation.access,
    "",
    citation.protocol,
  ].join("\n");
}

/**
 * Where a protocol sits in the phage workflow, drawn from the same stages the library's strip uses: its stage (the first
 * whose methods it carries out), the protocols of the nearest earlier and later stage that has any, and the calculators
 * of its stage. Nothing is typed per protocol: a protocol saved changes its neighbors' links. A protocol outside the
 * workflow (a PCR primer set) has none, and so does a stage with nothing before or after it.
 *
 * @param {LibraryItem[]} items every published library entry
 * @param {string} path the protocol's own path
 */
export function workflowContext(items, path) {
  const self = items.find((p) => p.path === path);
  if (!self) return null;
  const stageOf = (/** @type {LibraryItem} */ p) =>
    PHAGE_PIPELINE.findIndex((stage) => p.methods.some((m) => stage.methods.includes(m)));
  const at = stageOf(self);
  if (at === -1) return null;
  const link = (/** @type {LibraryItem} */ p) => ({ title: p.title, href: p.path });
  const others = items.filter((p) => p.path !== path);
  const nearest = (/** @type {number} */ step) => {
    for (let i = at + step; i >= 0 && i < PHAGE_PIPELINE.length; i += step) {
      const found = others.filter((p) => stageOf(p) === i);
      if (found.length > 0) return found.map(link);
    }
    return [];
  };
  const stage = /** @type {(typeof PHAGE_PIPELINE)[number]} */ (PHAGE_PIPELINE[at]);
  return {
    stage: stage.label,
    before: nearest(-1),
    after: nearest(1),
    tools: stage.tools.map(toolLink),
  };
}

/**
 * The same context as lines for the markdown twin, so an agent reads the neighbors a person sees.
 *
 * @param {ReturnType<typeof workflowContext>} context
 * @param {string} origin
 */
export function workflowMarkdown(context, origin) {
  if (!context) return "";
  const links = (/** @type {Array<{ title: string, href: string }>} */ list) =>
    list.map((p) => `[${p.title}](${origin}${p.href})`).join(", ");
  return [
    "## In the phage workflow",
    "",
    `Stage: ${context.stage}.`,
    ...(context.before.length > 0 ? ["", `Before this: ${links(context.before)}.`] : []),
    ...(context.after.length > 0 ? ["", `After this: ${links(context.after)}.`] : []),
    ...(context.tools.length > 0
      ? ["", `Calculators: ${links(context.tools.map((t) => ({ title: t.label, href: t.href })))}.`]
      : []),
  ].join("\n");
}

