// The inline marks a procedure step carries, in Cooklang's syntax (https://cooklang.org/docs/spec/):
// `@material{20%µl}`, `#equipment{}`, `~{10%minutes}`, plus the cooklang-rs alias form
// `@material|shown words{20%µl}` and its fixed-amount form `{=20%µl}`. The official parser
// (@cooklang/cooklang) is a pre-1.0 WASM build whose model is recipes only, so the site reads the marks
// itself and keeps Cooklang's spelling, so a file stays readable by Cooklang tools.
//
// Temperatures and spin speeds are read from the words, not marked, so a step stays the sentence a
// person wrote: "Incubate at 55 to 60 °C" is both.

/** A mark starts at the start of the text or after whitespace, so `(#refs)` and `a@b.c` are text. */
const MARK_START = /[@#~]/g;

/** A multi-word name runs to its `{`; it cannot cross another mark, a brace or a line. */
const BRACED = /^([@#])([^@#~{}\n]{1,160}?)\{([^{}\n]*)\}/u;
const SINGLE = /^([@#])([\p{L}\p{N}_-]+)/u;
const TIMER = /^~([^@#~{}\n]{0,60}?)\{([^{}\n]*)\}/u;

/**
 * Stretches of the text where a mark is never read: inline code, a link's target, an autolink.
 *
 * @param {string} text
 * @returns {Array<[number, number]>}
 */
function protectedRanges(text) {
  /** @type {Array<[number, number]>} */
  const ranges = [];
  for (const pattern of [/`[^`\n]*`/g, /\]\([^)\n]*\)/g, /<[a-z]+:[^>\n]*>/gi]) {
    for (const match of text.matchAll(pattern))
      ranges.push([match.index, match.index + match[0].length]);
  }
  return ranges;
}

/**
 * A number as written: "20", "1.25", "10,000", "1/2", "1 1/2".
 *
 * @param {string} raw
 * @returns {number | null}
 */
export function parseNumber(raw) {
  const s = raw.trim().replaceAll(",", "");
  let m = /^(\d+) (\d+)\/(\d+)$/.exec(s);
  if (m) return Number(m[1]) + Number(m[2]) / Number(m[3]);
  m = /^(\d+)\/(\d+)$/.exec(s);
  if (m) return Number(m[1]) / Number(m[2]);
  return /^-?\d+(?:\.\d+)?$/.test(s) ? Number(s) : null;
}

/**
 * The inside of a mark's braces: `20%µl`, `=20%µl`, `1.25 to 5%µl`, `2`, or empty.
 *
 * @param {string} inner
 * @returns {{ raw: string, amount: string, unit: string, fixed: boolean, min: number | null, max: number | null } | null}
 */
export function parseQuantity(inner) {
  let body = inner.trim();
  if (!body) return null;
  const fixed = body.startsWith("=");
  if (fixed) body = body.slice(1).trim();
  const at = body.indexOf("%");
  const amount = (at < 0 ? body : body.slice(0, at)).trim();
  const unit = at < 0 ? "" : body.slice(at + 1).trim();
  const range = /^(.+?)\s*(?:-|to)\s*(.+)$/.exec(amount);
  const min = parseNumber(range ? (range[1] ?? "") : amount);
  const max = range ? parseNumber(range[2] ?? "") : min;
  return { raw: inner, amount, unit, fixed, min, max: min === null ? null : max };
}

/**
 * @typedef {{ type: "text", value: string }} TextSegment
 * @typedef {ReturnType<typeof parseQuantity>} Quantity
 * @typedef {{ type: "material", name: string, display: string, quantity: Quantity }} MaterialSegment
 * @typedef {{ type: "equipment", name: string, display: string }} EquipmentSegment
 * @typedef {{ type: "timer", label: string, quantity: Quantity }} TimerSegment
 * @typedef {TextSegment | MaterialSegment | EquipmentSegment | TimerSegment} Segment
 */

/**
 * Where each mark sits in the text, with the parts it was written with: the one reading of the marks, which tokenize turns
 * into words and the admin editor turns into chips (app/kb/step-marks.mjs), so the two can never split a step differently.
 *
 * @param {string} text
 * @returns {Array<{ start: number, end: number, sign: "@" | "#" | "~", name: string, shown: string, braces: string | null }>}
 */
export function markSpans(text) {
  const ranges = protectedRanges(text);
  const inRange = (/** @type {number} */ i) => ranges.some(([a, b]) => i >= a && i < b);
  /** @type {Array<{ start: number, end: number, sign: "@" | "#" | "~", name: string, shown: string, braces: string | null }>} */
  const out = [];
  let last = 0;
  for (const hit of text.matchAll(MARK_START)) {
    const i = hit.index;
    if (i < last || inRange(i)) continue;
    const before = i === 0 ? "" : (text[i - 1] ?? "");
    if (before && !/\s/.test(before)) continue;
    const rest = text.slice(i);
    if (rest[0] === "~") {
      const m = TIMER.exec(rest);
      if (!m) continue;
      out.push({
        start: i,
        end: i + m[0].length,
        sign: "~",
        name: (m[1] ?? "").trim(),
        shown: "",
        braces: m[2] ?? "",
      });
      last = i + m[0].length;
      continue;
    }
    const m = BRACED.exec(rest) ?? SINGLE.exec(rest);
    if (!m) continue;
    const [name, shown] = (m[2] ?? "").split("|").map((part) => part.trim());
    out.push({
      start: i,
      end: i + m[0].length,
      sign: /** @type {"@" | "#"} */ (m[1]),
      name: name ?? "",
      shown: shown ?? "",
      braces: m[3] === undefined ? null : m[3],
    });
    last = i + m[0].length;
  }
  return out;
}

/**
 * The text split into words and marks.
 *
 * @param {string} text
 * @returns {Segment[]}
 */
export function tokenize(text) {
  /** @type {Segment[]} */
  const out = [];
  let last = 0;
  for (const span of markSpans(text)) {
    if (span.start > last) out.push({ type: "text", value: text.slice(last, span.start) });
    if (span.sign === "~")
      out.push({ type: "timer", label: span.name, quantity: parseQuantity(span.braces ?? "") });
    else if (span.sign === "@") {
      out.push({
        type: "material",
        name: span.name,
        display: span.shown || span.name,
        quantity: span.braces === null ? null : parseQuantity(span.braces),
      });
    } else out.push({ type: "equipment", name: span.name, display: span.shown || span.name });
    last = span.end;
  }
  if (text.length > last) out.push({ type: "text", value: text.slice(last) });
  return out;
}

/**
 * A number printed the way the file would write it: no trailing zeros, thousands with commas.
 *
 * @param {number} n
 */
export function formatNumber(n) {
  const rounded = Math.round(n * 1000) / 1000;
  return rounded.toLocaleString("en-US", { maximumFractionDigits: 3 });
}

/**
 * A quantity as words, scaled by `factor` unless it is fixed or not a number.
 *
 * @param {NonNullable<Quantity>} q
 * @param {number} [factor]
 */
export function formatQuantity(q, factor = 1) {
  let amount = q.amount;
  if (factor !== 1 && !q.fixed && q.min !== null) {
    amount =
      q.max !== null && q.max !== q.min
        ? `${formatNumber(q.min * factor)} to ${formatNumber(q.max * factor)}`
        : formatNumber(q.min * factor);
  }
  return q.unit ? `${amount} ${q.unit}` : amount;
}

/**
 * The words a segment stands for on the page.
 *
 * @param {Segment} segment
 * @param {number} [factor]
 */
export function segmentText(segment, factor = 1) {
  switch (segment.type) {
    case "text":
      return segment.value;
    case "material":
      return segment.quantity
        ? `${formatQuantity(segment.quantity, factor)} of ${segment.display}`
        : segment.display;
    case "equipment":
      return segment.display;
    case "timer":
      return segment.quantity ? formatQuantity(segment.quantity) : segment.label;
  }
}

/** "37 °C", "55 to 60 °C", "-80 °C", "55-60 °C". Exported for the editor, which shows each as a chip. */
export const TEMPERATURE = /(-?\d+(?:\.\d+)?)(?:\s*(?:to|-)\s*(-?\d+(?:\.\d+)?))?\s*°C/g;
/** "10,000 rpm", "12,000 x g", "10,000 to 15,000 x g". */
const SPIN = /(?<![\d.,])(\d[\d,]*(?:\s*to\s*\d[\d,]*)?)\s*(rpm|x g)\b/g;

/**
 * The temperatures and spins a step's words state.
 *
 * @param {string} text the step with its marks already turned into words
 */
export function readConditions(text) {
  const temperatures = [...text.matchAll(TEMPERATURE)].map((m) => ({
    min: Number(m[1]),
    max: m[2] === undefined ? Number(m[1]) : Number(m[2]),
    text: m[0],
  }));
  const spins = [...text.matchAll(SPIN)].map((m) => ({
    speed: (m[1] ?? "").trim(),
    unit: m[2] === "rpm" ? "rpm" : "x g",
    text: m[0],
  }));
  return { temperatures, spins };
}

app/kb/procedures/render.mjs.source:
// Turns a parsed, validated procedure into the record D1 stores and the page draws: every markdown
// fragment rendered to HTML through the site's own pipeline (so links pass the same URL allowlist as a
// post), every gap left out, and the quantities a reader can scale left as numbered slots in the HTML.
// The markdown twin and the search inputs are derived here too, from the same parse, so a machine and a
// person read the same facts.
//
// `renderBody` is passed in, not imported: the pipeline is 4 MB, so the Worker loads it lazily
// (load-pipeline.server.ts) and a Node script imports it directly.

import GithubSlugger from "github-slugger";

import { TOOLS } from "../../lib/phage-tools.mjs";
import { productsForRows } from "../registry/align.mjs";
import { itemPath } from "../registry/catalog.mjs";
import { plainText } from "../../lib/search/records.mjs";
import { keyResources, keyResourcesMarkdown } from "./key-resources.mjs";
import { proofFromFile } from "./proof.mjs";
import { formatQuantity, readConditions, segmentText } from "./marks.mjs";
import { statusLabel } from "./taxonomy.mjs";
import { allSteps, PLATFORMS, procedurePath, readCalcs } from "./parse.mjs";
import { HOWTO_TYPES } from "./validate.mjs";
import { storedLineage } from "./lineage.mjs";

/** The slot a scalable quantity leaves in a step's HTML, filled at request time (fillQuantities). */
const SLOT = (/** @type {number} */ i) => `QZQ${i}QZQ`;
const SLOT_PATTERN = /QZQ(\d+)QZQ/g;

const GAP = /^MISSING:/;

/** A heading as the pipeline writes it: rehype-slug's id, then the autolink inside. */
const HEADING = /<h([1-6]) id="([^"]+)">([\s\S]*?)<\/h\1>/g;

/**
 * The ids of the sections the components draw from the front matter (ProcedureView), so a prose
 * heading with the same words takes the -1 suffix rather than the fixed section's id.
 *
 * @param {unknown} profile
 */
export function fixedSectionIds(profile) {
  const materials =
    profile === "recipe"
      ? "ingredients"
      : profile === "computational"
        ? "software-and-data"
        : "reagents";
  const fixed = [
    materials,
    "equipment",
    "primers",
    "troubleshooting",
    "expected-results",
    "limitations",
    "references",
    "proof-of-use",
    "version-history",
    "cite-this-procedure",
    "key-resources",
  ];
  // A how-to's own sections (S2, S1), after the shared ones so no protocol's prose heading changes its id.
  return profile === "computational"
    ? [...fixed, "overview", "questions", "objectives", "key-points", "explanation"]
    : fixed;
}

/**
 * The value, or null when it is a recorded gap or absent.
 *
 * @template T
 * @param {T} value
 * @returns {T | null}
 */
function known(value) {
  if (value === undefined || value === null || value === "") return null;
  if (typeof value === "string" && GAP.test(value)) return null;
  return value;
}

/** @param {unknown} v */
const list = (v) => (Array.isArray(v) ? v : v === undefined || v === null ? [] : [v]);

/**
 * @typedef {(input: { file: string, body: string, resolveImage: (src: string) => Promise<any> }) =>
 *   Promise<{ html: string, toc: Array<{ depth: number, id: string, text: string }>, blockedUrls: Array<{ url: string }> }>} RenderBody
 */

/**
 * A primer as a protocol carries it: the lab registry's own facts about it, read when the protocol is compiled and stored
 * in the record, so the page, the sheet, the twin and a frozen version all print the same sequence, and the protocol's
 * file holds none (docs/REGISTRY.md). Its Tm and length are computed from the sequence where they are shown.
 *
 * @typedef {{ id: string, name: string, status: "published" | "draft", set: string | null, direction: string | null, sequence: string | null, reference: string | null, publishedIn?: string | null }} StoredPrimer
 */

/**
 * A host strain as a protocol carries it: the lab registry's stated facts about it, read when the protocol is compiled and
 * stored in the record, so the page, the twin and a frozen version name one strain and the protocol's file types none.
 *
 * A reagent as a protocol carries it: the lab registry's name for it, read when the protocol is compiled, so a material that
 * names a reagent shows the registry's name and links its page and a frozen version keeps the name it was published with.
 *
 * An equipment item as a protocol carries it: the registry's stated facts (who makes it, and a centrifuge's rotor, or that the rotor
 * is a recorded gap), read when the protocol is compiled, so the protocol's Equipment table and twin say as it was published.
 *
 * @typedef {{ id: string, name: string, status: "published" | "draft", manufacturer: string | null, rotor: string | null, rotorGap: boolean }} StoredEquipment
 *
 * @typedef {{ id: string, name: string, status: "published" | "draft", preparedInLab: boolean, supplier: string | null, catalogNumber: string | null, productUrl: string | null, recipe: string | null }} StoredReagent
 *
 * @typedef {{ id: string, name: string, status: "published" | "draft", organism: string | null, strain: string | null, collection: string | null, collectionNumber: string | null }} StoredStrain
 */

/**
 * Where a reagent comes from, in the words a protocol's table and twin use: a bought reagent's supplier and catalog number, linked to
 * its product page where there is one; a reagent prepared in the lab, linked to its recipe where one exists.
 *
 * @param {StoredReagent} reagent
 * @returns {{ text: string, href: string | null }}
 */
export function reagentSource(reagent) {
  if (reagent.preparedInLab) {
    return {
      text: reagent.recipe ? "Prepared in the lab (recipe)" : "Prepared in the lab",
      href: reagent.recipe ? `/recipes/${reagent.recipe}` : null,
    };
  }
  const text = [reagent.supplier, reagent.catalogNumber].filter(Boolean).join(", ");
  return { text: text || "Not recorded", href: reagent.productUrl };
}

/**
 * @param {{
 *   slug: string,
 *   parsed: import("./parse.mjs").ParsedProcedure,
 *   gaps: Array<{ field: string, reason: string }>,
 *   renderBody: RenderBody,
 *   resolveImage?: (src: string) => Promise<{ width: number, height: number }>,
 *   primerRows?: StoredPrimer[],
 *   strainRows?: Array<StoredStrain & { path: string }>,
 *   organismNames?: Record<string, string>,
 *   reagentRows?: StoredReagent[],
 *   equipmentRows?: StoredEquipment[],
 * }} input
 */
export async function renderProcedure({
  slug,
  parsed,
  gaps,
  renderBody,
  resolveImage,
  primerRows,
  strainRows,
  organismNames,
  reagentRows,
  equipmentRows,
}) {
  const file = procedurePath(slug);
  const d = parsed.data;
  const refuseImage = async (/** @type {string} */ src) => {
    throw new Error(
      `${file}: an image in prose ("${src}") is not supported; recipes carry photos on a step's own line`,
    );
  };

  /**
   * @param {unknown} markdown
   * @param {{ inline?: boolean }} [opts]
   */
  const md = async (markdown, opts = {}) => {
    if (typeof markdown !== "string" || !markdown.trim() || GAP.test(markdown)) return null;
    const out = await renderBody({ file, body: markdown, resolveImage: refuseImage });
    if (out.blockedUrls.length > 0) {
      throw new Error(
        `${file}: the URL allowlist refused ${out.blockedUrls.map((b) => b.url).join(", ")}`,
      );
    }
    const html = out.html.trim();
    if (!opts.inline) return html;
    const single = /^<p>([\s\S]*)<\/p>$/.exec(html);
    return single && !single[1]?.includes("<p>") ? (single[1] ?? "") : html;
  };

  /** @param {{ src: string, alt: string }} photo */
  const photo = async (photo) => {
    if (!resolveImage) return { src: photo.src, alt: photo.alt, width: null, height: null };
    const size = await resolveImage(photo.src);
    return { src: photo.src, alt: photo.alt, width: size.width, height: size.height };
  };

  /** @param {unknown} value */
  const inlineList = async (value) =>
    /** @type {string[]} */ (
      (
        await Promise.all(
          list(known(value)).map((/** @type {string} */ x) => md(x, { inline: true })),
        )
      ).filter(Boolean)
    );

  const materialsByName = new Map(
    list(d.materials).map((/** @type {any} */ m) => [String(m.name).toLowerCase(), m]),
  );

  /** @param {import("./parse.mjs").Step} step */
  const renderStep = async (step) => {
    /** @type {Array<{ name: string, amount: string, unit: string, fixed: boolean, min: number | null, max: number | null }>} */
    const quantities = [];
    /** @type {Array<{ name: string, display: string, amount: string | null }>} */
    const materials = [];
    /** @type {string[]} */
    const equipment = [];
    /** @type {Array<{ label: string, text: string, min: number | null, max: number | null, unit: string }>} */
    const timers = [];
    let words = "";
    for (const seg of step.segments) {
      if (seg.type === "material") {
        materials.push({
          name: seg.name,
          display: seg.display,
          amount: seg.quantity ? formatQuantity(seg.quantity) : null,
        });
        if (seg.quantity) {
          quantities.push({
            // Which ingredient the amount is of, so a recipe can show it in other units (recipe-views.mjs).
            name: seg.name,
            amount: seg.quantity.amount,
            unit: seg.quantity.unit,
            fixed: seg.quantity.fixed,
            min: seg.quantity.min,
            max: seg.quantity.max,
          });
          words += `${SLOT(quantities.length - 1)} of ${seg.display}`;
          continue;
        }
      } else if (seg.type === "equipment") {
        equipment.push(seg.name);
      } else if (seg.type === "timer" && seg.quantity) {
        timers.push({
          label: seg.label,
          text: formatQuantity(seg.quantity),
          min: seg.quantity.min,
          max: seg.quantity.max,
          unit: seg.quantity.unit,
        });
      }
      words += segmentText(seg);
    }
    const text = step.segments.map((s) => segmentText(s)).join("");
    const { temperatures, spins } = readConditions(text);
    const flagHtml = async (/** @type {string[]} */ items) =>
      /** @type {string[]} */ ((await Promise.all(items.map((t) => md(t)))).filter(Boolean));
    return {
      number: step.number,
      html: await md(words, { inline: true }),
      text: plainText(text),
      quantities,
      materials,
      equipment,
      timers,
      temperatures,
      spins,
      spin: step.flags.spin.filter((s) => !GAP.test(s)),
      critical: await flagHtml(step.flags.critical),
      pause: await flagHtml(step.flags.pause),
      why: await flagHtml(step.flags.why),
      expect: await flagHtml(step.flags.expect),
      troubleshooting: step.flags.troubleshooting,
      calculators: readCalcs(step.flags.calc),
      // A tutorial's challenges, each with the solution the parse paired with it (S5).
      challenges: await Promise.all(
        step.flags.challenge.map(async (c, i) => ({
          html: await md(c),
          solutionHtml: await md(step.flags.solution[i] ?? ""),
        })),
      ),
      commands: step.commands,
      photos: await Promise.all(step.photos.map(photo)),
    };
  };

  // One slugger for the whole page, as rehype-slug has for a whole post: each prose block is rendered
  // on its own, so a heading repeated across blocks would otherwise keep one id twice. The sections the
  // components draw themselves take their ids first.
  const slugger = new GithubSlugger();
  for (const id of fixedSectionIds(d.profile)) slugger.slug(id);
  /** @type {Array<{ depth: number, id: string, text: string }>} */
  const toc = [];
  /** @type {Array<{ id: string, title: string, blocks: Array<{ type: "prose", html: string } | { type: "steps", steps: Array<Awaited<ReturnType<typeof renderStep>>> }> }>} */
  const sections = [];
  for (const section of parsed.sections) {
    const sectionId = section.custom ? section.id : slugger.slug(section.title);
    toc.push({ depth: 2, id: sectionId, text: section.title });
    /** @type {(typeof sections)[number]["blocks"]} */
    const blocks = [];
    for (const block of section.blocks) {
      if (block.type === "prose") {
        const out = await renderBody({ file, body: block.markdown, resolveImage: refuseImage });
        if (out.blockedUrls.length > 0) {
          throw new Error(
            `${file}: the URL allowlist refused ${out.blockedUrls.map((b) => b.url).join(", ")}`,
          );
        }
        const html = out.html.replace(HEADING, (_all, level, id, inner) => {
          const text = String(inner)
            .replace(/<[^>]+>/g, "")
            .replace(/#$/, "")
            .trim();
          const unique = slugger.slug(text);
          if (Number(level) === 3) toc.push({ depth: 3, id: unique, text });
          return `<h${level} id="${unique}">${String(inner).replace(`href="#${id}"`, `href="#${unique}"`)}</h${level}>`;
        });
        blocks.push({ type: "prose", html });
      } else {
        blocks.push({ type: "steps", steps: await Promise.all(block.steps.map(renderStep)) });
      }
    }
    sections.push({ id: sectionId, title: section.title, blocks });
  }

  const reagentsById = new Map((reagentRows ?? []).map((r) => [r.id, r]));
  const materials = await Promise.all(
    list(d.materials).map(async (/** @type {any} */ m) => ({
      name: m.name,
      // A reagent of the registry is shown by the registry's name, linked, so the protocol types no product name for it.
      display: m.display ?? reagentsById.get(m.reagent)?.name ?? m.name,
      // What the registry says of it, as it was when the protocol was compiled: the table shows where it comes from.
      reagent: reagentsById.get(m.reagent) ?? null,
      group: m.group ?? null,
      kind: m.kind ?? null,
      version: known(m.version),
      stock: list(m.stock)
        .filter((s) => known(s) !== null)
        .map(String),
      final: known(m.final),
      amount: known(m.amount),
      per: known(m.per),
      solution: m.solution ?? null,
      noteHtml: await md(m.note, { inline: true }),
      // A recipe's grams in one cup of it, where the recipe states it: the only way its volume is shown as weight (DECIDE 7).
      gramsPerCup:
        typeof m.grams_per_cup === "number" && m.grams_per_cup > 0 ? m.grams_per_cup : null,
      /** @type {{ amount: string, unit: string, fixed: boolean, min: number | null, max: number | null } | null} */
      quantity: null,
    })),
  );

  // A material with no amount of its own takes the sum of what its marks use, when they share a unit and
  // none is fixed, so a recipe's shopping list scales with its servings.
  /** @param {string} name */
  const markedTotal = (name) => {
    const qs = allSteps(parsed).flatMap((s) =>
      s.segments.flatMap((seg) =>
        seg.type === "material" && seg.name.toLowerCase() === name.toLowerCase() && seg.quantity
          ? [seg.quantity]
          : [],
      ),
    );
    const unit = qs[0]?.unit;
    if (qs.length === 0 || qs.some((q) => q.min === null || q.max !== q.min || q.unit !== unit))
      return null;
    const sum = qs.reduce((n, q) => n + (q.min ?? 0), 0);
    return {
      amount: String(sum),
      unit: unit ?? "",
      fixed: qs.every((q) => q.fixed),
      min: sum,
      max: sum,
    };
  };
  for (const m of materials) {
    if (m.amount === null) m.quantity = markedTotal(m.name);
  }

  // A recipe may leave its ingredients undeclared: the marks are the list, in order of first use.
  if (d.profile === "recipe") {
    for (const step of allSteps(parsed)) {
      for (const seg of step.segments) {
        if (seg.type !== "material" || materialsByName.has(seg.name.toLowerCase())) continue;
        materialsByName.set(seg.name.toLowerCase(), { name: seg.name });
        materials.push({
          name: seg.name,
          display: seg.name,
          reagent: null,
          group: null,
          kind: null,
          version: null,
          stock: [],
          final: null,
          amount: null,
          per: null,
          solution: null,
          noteHtml: null,
          gramsPerCup: null,
          quantity: markedTotal(seg.name),
        });
      }
    }
  }

  const troubleshooting = await Promise.all(
    list(d.troubleshooting).map(async (/** @type {any} */ row) => ({
      id: row.id,
      step: String(row.step),
      problem: await md(row.problem, { inline: true }),
      reason: await md(row.reason, { inline: true }),
      solution: await md(row.solution, { inline: true }),
    })),
  );

  const image = known(d.image);
  const record = {
    slug,
    profile: /** @type {"protocol" | "recipe" | "computational"} */ (d.profile),
    path: String(d.path),
    title: String(d.title),
    seoTitle: String(d.seo_title),
    description: String(d.description),
    draft: d.draft === true,
    version: known(d.version) === null ? null : String(d.version),
    // Newest first; the first entry is the version the page is at (validate.mjs). Empty until one is written.
    history: await Promise.all(
      list(known(d.history)).map(async (/** @type {any} */ h) => ({
        version: String(h.version),
        date: String(h.date),
        summaryHtml: await md(h.summary, { inline: true }),
        doi: h.doi ? String(h.doi) : null,
      })),
    ),
    updated: known(d.updated),
    // What the protocol library filters and lists by (taxonomy.mjs); ids, so the page draws the words.
    methods: /** @type {string[]} */ (list(known(d.method))),
    organisms: /** @type {string[]} */ (list(known(d.organism))),
    // The words for each organism id, read from the lab registry when the protocol was compiled (docs/REGISTRY.md).
    organismNames: organismNames ?? {},
    targets: /** @type {string[]} */ (list(known(d.target))),
    courses: /** @type {string[]} */ (list(known(d.course))),
    // The library's "Start here" position, or null: stored, never inferred.
    startHere: known(d.start_here) === null ? null : Number(d.start_here),
    // Proof of use: slugs of the papers that used the method and the phages it produced, or null. Stored, never inferred.
    proofOfUse: proofFromFile(known(d.proof_of_use)),
    firstUsed: known(d.first_used),
    lastRun: known(d.last_run),
    status: known(d.status) === null ? null : statusLabel(String(d.status)),
    // The procedure this one was copied from with the editor's Duplicate (validate.mjs checks the shape), or null.
    forkedFrom:
      d.forked_from && typeof d.forked_from === "object"
        ? {
            slug: String(d.forked_from.slug),
            version: d.forked_from.version ? String(d.forked_from.version) : null,
          }
        : null,
    time: {
      total: known(d.time?.total),
      handsOn: known(d.time?.hands_on),
    },
    introHtml: await md(parsed.intro),
    basedOn: list(known(d.based_on)).map((/** @type {any} */ s) => ({
      citation: String(s.citation),
      for: String(s.for),
      doi: s.doi ? String(s.doi) : null,
      url: s.url ? String(s.url) : null,
    })),
    references: /** @type {string[]} */ (
      (
        await Promise.all(
          list(known(d.references)).map((/** @type {string} */ r) => md(r, { inline: true })),
        )
      ).filter(Boolean)
    ),
    materials,
    equipment: await Promise.all(
      list(d.equipment).map(async (/** @type {any} */ e) => {
        const item =
          typeof e === "object" && e !== null
            ? ((equipmentRows ?? []).find((r) => r.id === e.equipment) ?? null)
            : null;
        return typeof e === "string"
          ? { name: e, noteHtml: null, item }
          : { name: String(e.name), noteHtml: await md(e.note, { inline: true }), item };
      }),
    ),
    troubleshooting,
    expectedResultsHtml: await md(d.expected_results),
    limitationsHtml: await md(d.limitations),
    sections,
    toc,
    // Protocol.
    scale: known(d.scale) ? { count: Number(d.scale.count), unit: String(d.scale.unit) } : null,
    biosafety: known(d.biosafety) && d.biosafety !== "not applicable" ? d.biosafety : null,
    // Dustin's to set per protocol. A gap reads as null, so no page, twin or structured data ever carries "MISSING".
    biosafetyLevel: /** @type {string | null} */ (known(d.biosafety_level)),
    // The strains are the registry's: the names are computed from them, never typed in the protocol.
    hostStrains: (strainRows ?? []).map((s) => ({
      id: s.id,
      name: s.name,
      path: s.path,
      organism: s.organism,
      strain: s.strain,
      collection: s.collection,
      collectionNumber: s.collectionNumber,
    })),
    hostStrain:
      (strainRows ?? []).length > 0 ? (strainRows ?? []).map((s) => s.name).join("; ") : null,
    solutions: list(d.solutions).map((/** @type {any} */ s) => ({
      id: s.id,
      name: s.name,
      components: list(s.components).map((/** @type {any} */ c) => ({
        name: String(c.name),
        final: known(c.final),
        amount: known(c.amount),
      })),
      storage: known(s.storage),
      shelfLife: known(s.shelf_life),
    })),
    // The registry's rows for the primers the file names, in the file's order (compile.mjs resolves them).
    primers: (primerRows ?? []).map((p) => ({
      id: p.id,
      name: p.name,
      set: p.set,
      direction: p.direction,
      sequence: p.sequence,
      reference: p.reference,
      publishedIn: p.publishedIn ?? null,
    })),
    cycling: Array.isArray(d.cycling) ? d.cycling : [],
    // Recipe.
    servings: known(d.servings) === null ? null : Number(d.servings),
    cuisine: known(d.cuisine),
    category: known(d.category),
    diet: list(known(d.diet)).map(String),
    prepTime: known(d.prep_time),
    cookTime: known(d.cook_time),
    image: image ? await photo(image) : null,
    substitutions: await Promise.all(
      list(d.substitutions).map(async (/** @type {any} */ s) => ({
        for: String(s.for),
        use: String(s.use),
        noteHtml: await md(s.note, { inline: true }),
      })),
    ),
    // Computational.
    // Tutorial or how-to (S1), and a tutorial's questions, objectives and key points (S2), as the file states them.
    howtoType: /** @type {keyof typeof HOWTO_TYPES | null} */ (
      d.profile === "computational" && Object.hasOwn(HOWTO_TYPES, d.type) ? d.type : null
    ),
    questions: await inlineList(d.questions),
    objectives: await inlineList(d.objectives),
    keyPoints: await inlineList(d.key_points),
    explanation: list(known(d.explanation)).map((/** @type {any} */ e) => ({
      title: String(e.title),
      url: String(e.url),
    })),
    environmentHtml: await md(d.environment),
    prerequisites: /** @type {string[]} */ (
      (
        await Promise.all(
          list(known(d.prerequisites)).map((/** @type {string} */ p) => md(p, { inline: true })),
        )
      ).filter(Boolean)
    ),
    gaps,
  };
  return record;
}

/** @typedef {Awaited<ReturnType<typeof renderProcedure>>} ProcedureRecord */

/**
 * The scale factor a request asks for, or 1. A protocol scales its material totals by the count of its
 * unit; a recipe scales its step amounts by servings.
 *
 * @param {ProcedureRecord} record
 * @param {number | null} asked the count (protocol) or servings (recipe) in the URL
 */
export function scaleFactor(record, asked) {
  if (!asked || !(asked > 0) || asked > 1000) return 1;
  if (record.profile === "recipe" && record.servings) return asked / record.servings;
  if (record.profile === "protocol" && record.scale) return asked / record.scale.count;
  return 1;
}

/**
 * The step's HTML with its quantity slots filled. A protocol's step amounts are per unit and never
 * scale; a recipe's scale unless the file fixed them.
 *
 * @param {{ html: string | null, quantities: Array<{ name?: string, amount: string, unit: string, fixed: boolean, min: number | null, max: number | null }> }} step
 * @param {number} factor
 * @param {(q: { name?: string, amount: string, unit: string, fixed: boolean, min: number | null, max: number | null }) => string} [show] how a recipe shows an amount in the reader's units (recipe-views.mjs)
 */
export function fillQuantities(step, factor, show) {
  return (step.html ?? "").replace(SLOT_PATTERN, (_all, i) => {
    const q = step.quantities[Number(i)];
    if (!q) return "";
    return show ? show(q) : formatQuantity({ ...q, raw: "" }, factor);
  });
}

/**
 * The markdown twin: the same facts as the page, generated from the same file.
 *
 * @param {ProcedureRecord} record
 * @param {import("./parse.mjs").ParsedProcedure} parsed
 */
export function procedureMarkdown(record, parsed) {
  const d = parsed.data;
  const out = [`# ${record.title}`, "", record.description, ""];
  const facts = [
    ["Type", record.howtoType ? HOWTO_TYPES[record.howtoType] : null],
    ["Version", record.version],
    ["Updated", record.updated],
    ["First used", record.firstUsed],
    ["Last run", record.lastRun],
    ["Status", record.status],
    [
      "Scale",
      record.scale
        ? `${record.scale.count} ${record.scale.unit}${record.scale.count === 1 ? "" : "s"}`
        : null,
    ],
    ["Servings", record.servings],
    ["Prep time", record.prepTime],
    ["Cook time", record.cookTime],
    ["Total time", record.time.total],
    ["Hands-on time", record.time.handsOn],
    // The parent's file name and version; the twin's route reads it out as the parent's title and address (lineage.mjs).
    ["Based on", record.forkedFrom ? storedLineage(record.forkedFrom) : null],
    [
      "Host strain",
      record.hostStrains.length > 0
        ? record.hostStrains.map((s) => `[${s.name}](${s.path})`).join("; ")
        : null,
    ],
    ["Biosafety level", record.biosafetyLevel],
    [
      "Biosafety",
      record.biosafety
        ? [
            record.biosafety.organism,
            record.biosafety.strain,
            record.biosafety.atcc ? `ATCC ${record.biosafety.atcc}` : null,
          ]
            .filter(Boolean)
            .join(", ")
        : null,
    ],
  ].filter(([, v]) => v !== null && v !== undefined && v !== "");
  for (const [k, v] of facts) out.push(`- ${k}: ${v}`);
  if (facts.length) out.push("");
  // A tutorial opens with what it answers and teaches (S2), as the page does.
  const bullets = (/** @type {string} */ title, /** @type {unknown} */ value) => {
    const items = list(known(value));
    if (items.length) out.push(`## ${title}`, "", ...items.map((x) => `- ${x}`), "");
  };
  bullets("Questions", d.questions);
  bullets("Objectives", d.objectives);
  if (parsed.intro) out.push(parsed.intro, "");

  if (record.basedOn.length) {
    out.push("## Based on", "");
    for (const s of record.basedOn) {
      const link = s.doi ? ` (doi:${s.doi})` : s.url ? ` (${s.url})` : "";
      out.push(`- ${s.citation}${link}: ${s.for}`);
    }
    out.push("");
  }

  const heading =
    record.profile === "recipe"
      ? "Ingredients"
      : record.profile === "computational"
        ? "Software and data"
        : "Reagents";
  out.push(`## ${heading}`, "");
  // The registry reagents the materials name, as the record baked them (the file holds only their ids).
  const reagentOf = new Map(record.materials.map((m) => [m.name, m.reagent]));
  for (const m of list(d.materials).length ? list(d.materials) : record.materials) {
    const parts = [
      known(m.amount) ? `${m.amount}${known(m.per) ? ` per ${m.per}` : ""}` : null,
      list(m.stock).filter((s) => known(s) !== null).length
        ? `stock ${list(m.stock)
            .filter((s) => known(s) !== null)
            .join(" or ")}`
        : null,
      known(m.final) ? `final ${m.final}` : null,
      known(m.version) ? `version ${m.version}` : null,
    ].filter(Boolean);
    const note = known(m.note) ? ` ${m.note}` : "";
    const reagent = reagentOf.get(m.name) ?? null;
    const shown = m.display ?? reagent?.name ?? m.name;
    if (reagent) {
      const source = reagentSource(reagent);
      parts.push(source.href ? `source [${source.text}](${source.href})` : `source ${source.text}`);
    }
    // A published reagent links its page, as the page's table does.
    const named =
      reagent?.status === "published" ? `[${shown}](${itemPath("reagent", reagent.id)})` : shown;
    out.push(
      `- ${named}${m.group ? ` (${m.group})` : ""}${parts.length ? `: ${parts.join("; ")}.` : ""}${note}`,
    );
  }
  out.push("");
  for (const s of record.solutions) {
    out.push(`### ${s.name}`, "");
    for (const c of s.components)
      out.push(
        `- ${c.name}${c.final ? `, ${c.final} final` : ""}${c.amount ? `, ${c.amount}` : ""}`,
      );
    if (s.storage) out.push(`- Storage: ${s.storage}`);
    if (s.shelfLife) out.push(`- Shelf life: ${s.shelfLife}`);
    out.push("");
  }
  if (record.equipment.length) {
    out.push("## Equipment", "");
    // The registry facts of each item, as the record baked them (the file holds only the ids).
    const itemOf = new Map(record.equipment.map((e) => [e.name, e.item]));
    for (const e of list(d.equipment)) {
      const name = typeof e === "string" ? e : String(e.name);
      const item = itemOf.get(name) ?? null;
      const facts = item
        ? ` (${[`manufacturer ${item.manufacturer ?? "not recorded"}`, item.rotor ? `rotor ${item.rotor}` : item.rotorGap ? "rotor not recorded" : null].filter(Boolean).join("; ")})`
        : "";
      const named =
        item?.status === "published" ? `[${name}](${itemPath("equipment", item.id)})` : name;
      out.push(`- ${named}${facts}${typeof e === "string" || !e.note ? "" : `: ${e.note}`}`);
    }
    out.push("");
  }
  if (record.primers.length) {
    const products = productsForRows(record.primers);
    out.push(
      "## Primers",
      "",
      "| Primer | Direction | Sequence (5′ to 3′) | Product (computed) |",
      "| --- | --- | --- | --- |",
    );
    for (const p of record.primers) {
      const pair = products.get(p.id);
      const sizes = pair
        ? [...new Set(pair.products.map((x) => x.length))].map((n) => `${n} bp`).join(" or ")
        : "";
      out.push(
        "| [" +
          p.name +
          "](/research/lab/primers/" +
          p.id +
          ") | " +
          (p.direction ?? "") +
          " | " +
          (p.sequence ? "`" + p.sequence + "`" : "") +
          " | " +
          sizes +
          " |",
      );
    }
    out.push("");
    const references = [...new Set([...products.values()].map((pair) => pair.reference.id))];
    if (references.length > 0)
      out.push(
        `Product sizes are computed from where the primers bind ${references.join(", ")}, in that accession's coordinates.`,
        "",
      );
  }
  out.push(...keyResourcesMarkdown(keyResources(record)));
  if (known(d.environment)) out.push("## Environment", "", String(d.environment), "");
  if (record.prerequisites.length)
    out.push("## Prerequisites", "", ...list(d.prerequisites).map((p) => `- ${p}`), "");

  for (const section of parsed.sections) {
    out.push(`## ${section.title}`, "");
    for (const block of section.blocks) {
      if (block.type === "prose") {
        out.push(block.markdown, "");
        continue;
      }
      for (const step of block.steps) {
        out.push(`${step.number}. ${step.segments.map((s) => segmentText(s)).join("")}`);
        const flag = (/** @type {string} */ name, /** @type {string[]} */ items) => {
          for (const item of items)
            if (!GAP.test(item)) out.push(`   > ${name}: ${item.replace(/\n/g, "\n   > ")}`);
        };
        flag("Critical", step.flags.critical);
        flag("Pause point", step.flags.pause);
        flag("Spin", step.flags.spin);
        flag("Why", step.flags.why);
        flag("Expected", step.flags.expect);
        for (const id of step.flags.troubleshooting)
          out.push(`   > Troubleshooting: see "${id}" below.`);
        for (const c of readCalcs(step.flags.calc))
          out.push(
            `   > Calculator: [${TOOLS[c.id]?.title}](${TOOLS[c.id]?.path})${
              Object.keys(c.values).length
                ? ` with ${Object.entries(c.values)
                    .map(([k, v]) => `${k} ${v}`)
                    .join(", ")}`
                : ""
            }`,
          );
        // Every platform's block, each under its name (S4): the page's tabs are a view of these.
        for (const cmd of step.commands) {
          if (cmd.platform)
            out.push(
              "",
              `   ${PLATFORMS[/** @type {keyof typeof PLATFORMS} */ (cmd.platform)] ?? cmd.platform}:`,
            );
          out.push(
            "",
            `   \`\`\`${cmd.lang}`,
            ...cmd.code.split("\n").map((l) => `   ${l}`),
            "   ```",
          );
          if (cmd.output !== null) {
            out.push(
              "",
              "   Expected output:",
              "",
              "   ```",
              ...cmd.output.split("\n").map((l) => `   ${l}`),
              "   ```",
            );
          }
        }
        for (const p of step.photos) out.push(`   ![${p.alt}](${p.src})`);
        // A challenge and its solution, both: the page folds the solution away, and a machine reads it anyway.
        step.flags.challenge.forEach((c, i) => {
          out.push("", `   > Challenge: ${c.replace(/\n/g, "\n   > ")}`);
          const solution = step.flags.solution[i];
          if (solution) out.push("", `   > Solution: ${solution.replace(/\n/g, "\n   > ")}`);
        });
      }
      out.push("");
    }
  }

  bullets("Key points", d.key_points);
  if (record.explanation.length)
    out.push(
      "## Explanation",
      "",
      ...record.explanation.map((e) => `- [${e.title}](${e.url})`),
      "",
    );

  if (list(d.troubleshooting).length) {
    out.push(
      "## Troubleshooting",
      "",
      "| Step | Problem | Possible reason | Solution |",
      "| --- | --- | --- | --- |",
    );
    for (const r of list(d.troubleshooting)) {
      const cell = (/** @type {unknown} */ v) =>
        String(v).replace(/\|/g, "\\|").replace(/\n/g, " ");
      out.push(
        `| ${cell(r.step)} | ${cell(r.problem)} | ${cell(r.reason)} | ${cell(r.solution)} |`,
      );
    }
    out.push("");
  }
  if (known(d.expected_results))
    out.push("## Expected results", "", String(d.expected_results), "");
  if (known(d.limitations)) out.push("## Limitations", "", String(d.limitations), "");
  if (list(d.substitutions).length) {
    out.push("## Substitutions", "");
    for (const s of list(d.substitutions))
      out.push(`- For ${s.for}, use ${s.use}${s.note ? `: ${s.note}` : ""}`);
    out.push("");
  }
  if (record.history.length) {
    out.push("## Version history", "");
    for (const h of list(d.history))
      out.push(`- Version ${h.version}, ${h.date}: ${h.summary}${h.doi ? ` (doi:${h.doi})` : ""}`);
    out.push("");
  }
  const refs = list(known(d.references));
  if (refs.length) out.push("## References", "", ...refs.map((r) => `- ${r}`), "");
  return `${out
    .join("\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim()}\n`;
}

/**
 * The search uid of the page at `path`: the one the page had when it was a content page, so a search
 * link survives the move. Also what removing a procedure's search records is keyed by.
 *
 * @param {string} path
 */
export function procedureSearchUid(path) {
  return `page:${path.slice(1).replaceAll("/", ":")}`;
}

/**
 * What the search index takes for this procedure, in the shape recordsForPages reads, with the uid
 * `procedureSearchUid` names.
 *
 * @param {ProcedureRecord} record
 * @param {import("./parse.mjs").ParsedProcedure} parsed
 */
export function procedureSearchInput(record, parsed) {
  const markdown = procedureMarkdown(record, parsed);
  const sections = parsed.sections.map((section) => {
    const body = section.blocks
      .map((block) =>
        block.type === "prose"
          ? block.markdown
          : block.steps
              .map((s) =>
                [
                  s.segments.map((x) => segmentText(x)).join(""),
                  ...s.flags.why,
                  ...s.flags.critical,
                ].join(" "),
              )
              .join(" "),
      )
      .join(" ");
    return { anchor: section.id, title: section.title, body: plainText(body) };
  });
  return {
    url: record.path,
    uid: procedureSearchUid(record.path),
    title: record.title,
    description: record.description,
    intro: plainText(parsed.intro),
    sections,
    markdown,
  };
}

app/kb/registry/equipment.mjs.source:
// The equipment kind of the lab registry (docs/REGISTRY.md): the instruments and labware the lab's protocols list under
// Equipment. Like the reagents, the equipment is one table (the library's Equipment tab) with a page for each item that lists the
// protocols using it (docs/KNOWLEDGE-BASE.md, A1), and each protocol's own Equipment table is drawn from these records beside the
// protocol's own words for the item.
//
// A record states what the lab's own pages state about one item: its name and who makes it, which is `MISSING: <why>` where no
// record in the repository says and is listed for Dustin. A centrifuge also carries the rotor its speeds are read for, which is
// Dustin's to name (core.md: the ZnCl2 rotor), so it is recorded as a gap and the protocols' rpm cannot yet be given as x g.
//
// What the protocols do with an item is the PROTOCOLS' and is never stored here: a protocol lists it under its own words (55 °C
// water bath for molten top agar, plate incubator at 29 °C for M. foliorum) and names the record with `equipment: <id>`, so the
// setting is the protocol's own and the table lists the protocols that name it.

const LINE = /^[^\r\n]+$/;

/** @param {unknown} value @param {number} max */
const oneLine = (value, max) =>
  typeof value === "string" && LINE.test(value) && value === value.trim() && value.length <= max
    ? null
    : `is one line of at most ${max} characters`;

/** @type {import("./kinds.mjs").KindSpec} */
export const EQUIPMENT = {
  singular: "equipment",
  plural: "equipment",
  fields: {
    manufacturer: { required: true, check: (value) => oneLine(value, 80) },
    // The rotor a centrifuge's speeds are read for: a protocol gives rpm, and x g needs the rotor (core.md: waiting on Dustin).
    rotor: { check: (value) => oneLine(value, 120) },
  },
};

/**
 * An equipment item as a protocol carries it (`StoredEquipment` in app/kb/procedures/render.mjs): the registry's stated facts, none
 * computed, so the protocol's Equipment table, twin and frozen versions say who makes each as it was when the protocol was published.
 * `rotorGap` is whether a rotor is recorded as missing, so a centrifuge's table says so rather than leaving it blank.
 *
 * @param {import("./kinds.mjs").RegistryItem} item
 * @returns {import("../procedures/render.mjs").StoredEquipment}
 */
export function storedEquipment(item) {
  const f = /** @type {Record<string, unknown>} */ (item.fields);
  const text = (/** @type {unknown} */ value) =>
    typeof value === "string" && value !== "" && !value.startsWith("MISSING") ? value : null;
  return {
    id: item.id,
    name: item.name,
    status: item.status,
    manufacturer: text(f.manufacturer),
    rotor: text(f.rotor),
    rotorGap: typeof f.rotor === "string" && f.rotor.startsWith("MISSING"),
  };
}

app/lib/admin/roving.mjs.source:
/**
 * The key map of a roving tabindex (APG toolbar, radio group and menu patterns): which item an arrow,
 * Home or End moves to. Pure, so a node test can hold it; the components own focus and state.
 *
 * `axis` is the arrows that move: "horizontal" for a toolbar, "vertical" for a list, "both" for a
 * radio group, where Down and Right go forward and Up and Left go back.
 * Movement wraps, as the APG toolbar and radio group examples do.
 *
 * @param {string} key a KeyboardEvent `key`
 * @param {number} at the index that has focus now
 * @param {number} count how many items there are
 * @param {"horizontal" | "vertical" | "both"} [axis]
 * @returns {number | null} the index to move to, or null when the key is not a movement key
 */
export function rovingTarget(key, at, count, axis = "horizontal") {
  if (count <= 0) return null;
  const across = axis !== "vertical";
  const down = axis !== "horizontal";
  if ((across && key === "ArrowRight") || (down && key === "ArrowDown")) return (at + 1) % count;
  if ((across && key === "ArrowLeft") || (down && key === "ArrowUp"))
    return (at - 1 + count) % count;
  if (key === "Home") return 0;
  if (key === "End") return count - 1;
  return null;
}

app/lib/blog-listing.mjs.source:
export const POSTS_PER_PAGE = 10;

/** The home page's Writing section is a taste, not a feed: the featured post and two more. */
export const HOME_CARDS = 3;

/**
 * The essays that follow the featured post on the home page, in this order. `featured` marks one post
 * (it leads /writing), so the rest of the home page's best-of is a hand-picked list. A pick that is
 * not published drops out and the newest post fills its place; test/blog-listing.test.mjs holds each
 * pick against a published file in content/posts.
 */
export const HOME_PICKS = ["policy-in-the-api-not-the-mcp", "observable-plot-inside-a-worker"];

/**
 * The home page's picks first, in `picks` order, then everything else in the order given. Stable, so
 * the rest stay newest first. Duplicates by slug are dropped, because the caller merges two queries.
 *
 * @template {{ slug: string }} T
 * @param {T[]} rows none of them featured
 * @param {readonly string[]} [picks]
 * @returns {T[]}
 */
export function picksFirst(rows, picks = HOME_PICKS) {
  const seen = new Set();
  const unique = rows.filter((row) => !seen.has(row.slug) && seen.add(row.slug));
  const rank = (/** @type {string} */ slug) => {
    const i = picks.indexOf(slug);
    return i === -1 ? picks.length : i;
  };
  return unique
    .map((row, i) => ({ row, i }))
    .sort((a, b) => rank(a.row.slug) - rank(b.row.slug) || a.i - b.i)
    .map(({ row }) => row);
}

/**
 * A `?page=` a listing can use: a positive whole number, else 1. `-3`, `1.5` and `abc` all read as 1.
 *
 * @param {string | null} raw
 */
export function readPage(raw) {
  if (raw === null || !/^\d+$/.test(raw)) return 1;
  const page = Number(raw);
  return page > 0 && Number.isSafeInteger(page) ? page : 1;
}

/**
 * @param {number} position 1-based
 * @param {number} [perPage]
 */
export function pageForPosition(position, perPage = POSTS_PER_PAGE) {
  return Math.floor((position - 1) / perPage) + 1;
}

/**
 * An empty corpus still has one page, because /writing renders an empty state rather than a 404.
 *
 * @param {number} total
 * @param {number} [perPage]
 */
export function pageCount(total, perPage = POSTS_PER_PAGE) {
  return Math.max(1, Math.ceil(total / perPage));
}

/**
 * Returns the list with the hero REMOVED, or it renders twice. Matched by slug, not identity,
 * because a serialization boundary upstream would silently break identity.
 *
 * @template {{ slug: string, featured?: boolean }} T
 * @param {T[]} posts the page of posts, in order
 * @param {boolean} eligible whether this request may show a hero at all
 * @returns {{ featured: T | null, posts: T[] }}
 */
export function splitFeatured(posts, eligible) {
  if (!eligible) return { featured: null, posts };
  const featured = posts.find((post) => post.featured) ?? null;
  if (!featured) return { featured: null, posts };
  return { featured, posts: posts.filter((post) => post.slug !== featured.slug) };
}

/**
 * A pure function rather than SQL because the offline machine-readable check renders this section
 * without a database. With no featured post the newest leads. `others` must exclude the featured
 * post or it prints twice.
 *
 * @template {{ slug: string }} T
 * @param {T[]} featuredRows at most one, the featured post
 * @param {T[]} others in the order they follow the lead, none of them featured: `picksFirst` for the home page
 * @param {number} [cards] how many the section shows in total, lead included
 * @returns {{ featured: T | null, recent: T[] }}
 */
export function startHere(featuredRows, others, cards = HOME_CARDS) {
  const lead = featuredRows[0] ?? others[0] ?? null;
  if (lead === null) return { featured: null, recent: [] };
  const recent = featuredRows[0] ? others.slice(0, cards - 1) : others.slice(1, cards);
  return { featured: lead, recent };
}

/**
 * The facts describe the FILTERED list, not the corpus: a tag view stating the whole blog's span
 * would be true of something the page does not show. A null is not a zero; the row omits itself.
 *
 * @param {number} total posts in the whole filtered list, not on this page of it
 * @param {{ firstYear: string | null, lastYear: string | null, minutes: number | null }} span
 * @returns {(string | null)[]} three facts, in the row's order
 */
export function listingFacts(total, span) {
  const years =
    span.firstYear && span.lastYear
      ? span.firstYear === span.lastYear
        ? span.firstYear
        : `${span.firstYear} to ${span.lastYear}`
      : null;
  // Hours only past two: "1 hour" rounded from 38 minutes would be wrong.
  const reading = span.minutes
    ? span.minutes >= 120
      ? `${Math.round(span.minutes / 60)} hours of reading`
      : `${span.minutes} minutes of reading`
    : null;
  return [`${total} post${total === 1 ? "" : "s"}`, years, reading];
}

app/lib/cv/entries.mjs.source:
/**
 * The CV resolved: the files in content/cv/ (assembled by app/lib/cv/compile.mjs) joined to the publication
 * records, one flat list every surface renders. The page (app/routes/cv.tsx), the markdown twin
 * (app/lib/cv/markdown.mjs, served by app/routes/cv[.md].ts) and the PDF (rendered from the twin by
 * app/lib/cv/pdf.server.ts, and offline by scripts/build-cv-pdf.mjs) all resolve it with `buildCv`, so they cannot say different things. Pure and clock-free, so the twin and
 * the PDF fingerprint are reproducible.
 */

import { slugify } from "@drdustinedwards/site-helpers/slug";

import { deriveIdentity } from "../identity.mjs";
import { IDENTITY } from "../identity.generated.mjs";
import { canonicalAuthor } from "../publications/authors.mjs";
import { decodeEntities } from "../publications/entities.mjs";
import { paperPath, paperPdfPath } from "../publications/paths.mjs";
import { areaLabel, foldText, formatDollars, roleLabel, typeLabel } from "./view.mjs";

/** A CV entry's id part: Prelum's slug, capped at 48. @param {string} value */
const entrySlug = (value) => slugify(value, { max: 48 });

export { formatDollars };

/** @typedef {import("./types.ts").CvType} CvType */
/** @typedef {import("./types.ts").CvArea} CvArea */
/** @typedef {import("./types.ts").CvRole} CvRole */
/** @typedef {import("./types.ts").CvLink} CvLink */
/** @typedef {import("./types.ts").CvSourceEntry} CvSourceEntry */
/** @typedef {import("./types.ts").CvSource} CvSource */
/** @typedef {import("../publications/types.ts").Publication} Publication */
/** @typedef {import("../publications/types.ts").TopicId} TopicId */

/**
 * @typedef {object} CvPaper
 * @property {string[]} authors as the record lists them, the owner included
 * @property {string} venue journal, volume(issue):pages
 * @property {string | null} doi
 * @property {string | null} pagePath the site's page for the paper, which carries the abstract
 * @property {string | null} pdfPath
 * @property {string | null} pmid
 * @property {string | null} pmcUrl
 * @property {boolean} hasAbstract
 * @property {string} citation the plain citation a reader copies
 * @property {string | null} bibtexPath the site's .bib export, or null when the text is inline
 * @property {string | null} risPath
 * @property {string | null} bibtex inline BibTeX, for a paper the site has no record for
 * @property {string | null} ris
 * @property {Publication | null} record the site record, for JSON-LD
 */

/**
 * @typedef {object} CvEntry
 * @property {string} id a stable anchor, unique across the CV
 * @property {CvType} type
 * @property {string | null} section the subsection it sits under when grouped by type
 * @property {number | null} year when it started
 * @property {number | "present" | null} endYear null for a single year
 * @property {string} when the dates as printed: "2019", "2014-2020", "2015-present", or ""
 * @property {CvArea[]} areas
 * @property {CvRole | null} role
 * @property {string} title the entry's first line
 * @property {string[]} meta the lines after it
 * @property {string | null} note
 * @property {CvLink[]} links
 * @property {CvPaper | null} paper
 * @property {number | null} amount a grant's US dollars
 * @property {number | null} students how many students a mentoring line counts
 * @property {boolean} cohort a mentoring count that belongs to its start year alone
 * @property {{ heading: string, items: string[] }[]} duties
 * @property {string} search folded text the search box matches
 */

/** The PDF's public path: a Worker route over one R2 object the Worker renders after each CV save (app/routes/cv-pdf.ts). */
export const CV_PDF_PATH = "/dustin-edwards-cv.pdf";

export const CV_PAGE = {
  path: "/cv",
  title: "Curriculum Vitae",
  seoTitle: `${IDENTITY.name} CV: ${IDENTITY.role}, Tarleton`,
  description: `${IDENTITY.name}'s CV: ${IDENTITY.role} at ${IDENTITY.affiliation}. Appointments, education, publications, grants, teaching and service.`,
};

/** @type {Record<TopicId, CvArea>} */
const TOPIC_AREA = {
  "human-simian-retroviruses": "retroviruses",
  "avian-retroviruses": "retroviruses",
  bacteriophages: "bacteriophages",
  "science-education": "science-education",
};

const OWNER = "Dustin Edwards";

/**
 * @param {number | null} year
 * @param {number | "present" | undefined} endYear
 */
function formatWhen(year, endYear) {
  if (year === null) return "";
  if (endYear === undefined || endYear === year) return String(year);
  return `${year}-${endYear}`;
}

/**
 * @param {string | null} journal
 * @param {string | null | undefined} volume
 * @param {string | null | undefined} issue
 * @param {string | null | undefined} pages
 */
function venueOf(journal, volume, issue, pages) {
  let out = decodeEntities(journal ?? "");
  if (volume) out += ` ${volume}${issue ? `(${issue})` : ""}`;
  if (pages) out += `${volume ? ":" : ", "}${pages}`;
  return out.trim();
}

/** @param {Publication} p @returns {CvRole} */
function authorRole(p) {
  const at = p.authors.findIndex((name) => canonicalAuthor(name) === OWNER);
  if (at < 0) {
    throw new Error(
      `cv: ${p.doi} does not list ${OWNER} among its authors, so the CV cannot claim it.`,
    );
  }
  if (at === 0) return "first-author";
  if (at === p.authors.length - 1) return "senior-author";
  return "co-author";
}

/**
 * @param {string[]} authors
 * @param {number | null} year
 * @param {string} title
 * @param {string} venue
 * @param {string | null} doi
 */
function plainCitation(authors, year, title, venue, doi) {
  const names = authors.map((name) => canonicalAuthor(name)).join(", ");
  const end = /[.?!]$/.test(title) ? "" : ".";
  return `${names}. ${year ?? "n.d."}. ${title}${end} ${venue}.${doi ? ` https://doi.org/${doi}` : ""}`;
}

/**
 * @param {CvSourceEntry} source
 * @param {Map<string, Publication>} byDoi the publication records by lower-cased DOI
 * @returns {Omit<CvEntry, "id" | "search">}
 */
function resolveOne(source, byDoi) {
  const base = {
    section: null,
    note: null,
    links: /** @type {CvLink[]} */ ([]),
    paper: null,
    amount: null,
    students: null,
    cohort: false,
    duties: /** @type {{ heading: string, items: string[] }[]} */ ([]),
  };

  if (source.type === "publication" && "doi" in source) {
    const p = byDoi.get(source.doi.toLowerCase());
    if (!p) {
      throw new Error(
        `cv: no publication record for DOI ${source.doi}; add its file to content/publications/ first.`,
      );
    }
    const title = decodeEntities(p.title);
    const venue = venueOf(p.journal, p.volume, p.issue, p.pages);
    const { slug } = p;
    const areas = [...new Set(p.topics.map((t) => TOPIC_AREA[t]))];
    /** @type {CvLink[]} */
    const links = [{ label: "DOI", href: `https://doi.org/${p.doi}` }];
    if (p.pmid) links.push({ label: "PubMed", href: `https://pubmed.ncbi.nlm.nih.gov/${p.pmid}/` });
    if (p.pmcUrl) links.push({ label: "PMC", href: p.pmcUrl });
    return {
      ...base,
      type: "publication",
      year: p.year,
      endYear: null,
      when: String(p.year),
      areas,
      role: authorRole(p),
      title,
      meta: [venue],
      links,
      paper: {
        authors: p.authors.map((name) => decodeEntities(name)),
        venue,
        doi: p.doi,
        pagePath: paperPath(slug),
        pdfPath: p.access === "self-hosted" && p.pdfPath ? paperPdfPath(slug) : null,
        pmid: p.pmid,
        pmcUrl: p.pmcUrl,
        hasAbstract: Boolean(p.abstract),
        citation: plainCitation(p.authors, p.year, title, venue, p.doi),
        bibtexPath: `/research/publications/${slug}.bib`,
        risPath: `/research/publications/${slug}.ris`,
        bibtex: null,
        ris: null,
        record: p,
      },
    };
  }

  const when = formatWhen(source.year, source.endYear);
  const common = {
    ...base,
    year: source.year,
    endYear: source.endYear ?? null,
    when,
    areas: source.areas,
    role: source.role,
    links: source.links ?? [],
  };

  switch (source.type) {
    case "publication": {
      const venue = venueOf(source.journal, source.volume, source.issue, source.pages);
      const key = `${entrySlug(source.authors[0]?.split(" ").pop() ?? "cv")}-${source.year}-${entrySlug(source.title).split("-").slice(0, 3).join("-")}`;
      const bibtex = [
        `@article{${key},`,
        `  title = {${source.title}},`,
        `  author = {${source.authors.join(" and ")}},`,
        `  journal = {${source.journal}},`,
        `  year = {${source.year}},`,
        ...(source.volume ? [`  volume = {${source.volume}},`] : []),
        ...(source.issue ? [`  number = {${source.issue}},`] : []),
        ...(source.pages ? [`  pages = {${source.pages.replace("-", "--")}},`] : []),
        "}",
      ].join("\n");
      const pages = source.pages?.split("-") ?? [];
      const ris = [
        "TY  - JOUR",
        `TI  - ${source.title}`,
        ...source.authors.map((name) => `AU  - ${name}`),
        `JO  - ${source.journal}`,
        `PY  - ${source.year}`,
        ...(source.volume ? [`VL  - ${source.volume}`] : []),
        ...(source.issue ? [`IS  - ${source.issue}`] : []),
        ...(pages[0] ? [`SP  - ${pages[0]}`] : []),
        ...(pages[1] ? [`EP  - ${pages[1]}`] : []),
        "ER  - ",
      ].join("\n");
      return {
        ...common,
        type: "publication",
        title: source.title,
        meta: [venue],
        paper: {
          authors: source.authors,
          venue,
          doi: null,
          pagePath: null,
          pdfPath: null,
          pmid: null,
          pmcUrl: null,
          hasAbstract: false,
          citation: plainCitation(source.authors, source.year, source.title, venue, null),
          bibtexPath: null,
          risPath: null,
          bibtex,
          ris,
          record: null,
        },
      };
    }
    case "appointment":
      return {
        ...common,
        type: "appointment",
        section: source.section,
        title: source.title,
        meta: [source.org, ...(source.detail ? [source.detail] : [])],
        duties: source.duties ?? [],
      };
    case "education":
      return {
        ...common,
        type: "education",
        title: source.title,
        meta: [source.org, ...(source.detail ? [source.detail] : [])],
      };
    case "grant":
      return {
        ...common,
        type: "grant",
        title: source.title,
        meta: [source.funder ?? ""].filter(Boolean),
        note: source.note ?? null,
        amount: source.amount,
      };
    case "award":
      return {
        ...common,
        type: "award",
        title: source.title,
        meta: [[source.org, source.place].filter(Boolean).join(", ")].filter(Boolean),
      };
    case "talk":
      return {
        ...common,
        type: "talk",
        title: source.title,
        meta: [
          source.venue,
          ...(source.presenters.length > 1
            ? [`With ${source.presenters.slice(1).join(", ")}`]
            : []),
        ],
      };
    case "course":
      return {
        ...common,
        type: "course",
        title: `${source.code}: ${source.title}`,
        meta: [`${source.org}, ${source.term}`],
      };
    case "mentoring": {
      const counted = `${source.count} ${source.unit === "awards" ? (source.count === 1 ? "award" : "awards") : source.count === 1 ? "student" : "students"}`;
      return {
        ...common,
        type: "mentoring",
        section: source.section,
        title: `${counted}: ${source.level}`,
        meta: [source.program, source.org, ...(source.detail ? [source.detail] : [])],
        students: source.unit === "students" ? source.count : null,
        cohort: source.cohort,
      };
    }
    case "service":
      return {
        ...common,
        type: "service",
        section: source.section,
        title: source.title,
        meta: [[source.org, source.place].filter(Boolean).join(", ")].filter(Boolean),
      };
    case "development":
      return {
        ...common,
        type: "development",
        title: source.title,
        meta: [[source.org, source.place].filter(Boolean).join(", ")].filter(Boolean),
      };
    default:
      throw new Error(`cv: an entry has no known type: ${JSON.stringify(source)}`);
  }
}

/**
 * @param {CvSourceEntry[]} sources
 * @param {Publication[]} publications
 * @returns {CvEntry[]}
 */
function resolveAll(sources, publications) {
  /** @type {Map<string, Publication>} */
  const byDoi = new Map(publications.flatMap((p) => (p.doi ? [[p.doi.toLowerCase(), p]] : [])));
  const seen = new Map();
  return sources.map((source) => {
    const entry = resolveOne(source, byDoi);
    const stem = `${entry.type}-${entry.year ?? "undated"}-${entrySlug(entry.title)}`;
    const n = (seen.get(stem) ?? 0) + 1;
    seen.set(stem, n);
    const id = n === 1 ? stem : `${stem}-${n}`;
    const search = foldText(
      [
        entry.title,
        ...entry.meta,
        entry.note ?? "",
        entry.when,
        ...(entry.paper ? entry.paper.authors : []),
        ...entry.duties.flatMap((d) => [d.heading, ...d.items]),
      ].join(" "),
    );
    return { ...entry, id, search };
  });
}

/**
 * @param {CvSource} source what the files state (assembleCvSource)
 * @param {Publication[]} publications the published records: D1's (app/db/cv.ts) or the build's
 *   (scripts/lib/publications.mjs)
 */
export function buildCv(source, publications) {
  // The header's title is derived from the current appointments and the discipline, never stated in the profile.
  const derived = deriveIdentity(source.person, source.entries);
  if (!derived.ok) throw new Error(`the CV cannot give a title: ${derived.errors.join("; ")}`);
  return {
    edition: source.edition,
    person: { ...source.person, title: derived.identity.cvTitle },
    presentations: source.presentations,
    entries: resolveAll(source.entries, publications),
  };
}

/** @typedef {ReturnType<typeof buildCv>} Cv */

/**
 * What filtering reads from each entry (app/lib/cv/view.mjs). The search text also carries the type,
 * role and area labels the page prints beside the entry, so a word a reader can see is a word the
 * search finds, on the server and in the browser alike.
 *
 * @param {CvEntry[]} entries
 * @returns {import("./view.mjs").Facts[]}
 */
export function cvFacts(entries) {
  return entries.map((e, order) => ({
    id: e.id,
    type: e.type,
    section: e.section,
    areas: e.areas,
    role: e.role,
    year: e.year,
    endYear: e.endYear,
    students: e.students,
    cohort: e.cohort,
    amount: e.amount,
    order,
    search: foldText(
      [
        e.search,
        typeLabel(e.type),
        e.role ? roleLabel(e.role) : "",
        ...e.areas.map(areaLabel),
      ].join(" "),
    ),
  }));
}

app/lib/dictionary-entries.mjs.source:
/**
 * How a dictionary entry reads on each surface. The entries themselves are files, content/dictionary/<key>.md
 * (docs/DICTIONARY.md), compiled by app/lib/dictionary/compile.mjs and drawn from D1 (the dictionary_entries
 * table) at request time; this module only turns one entry into the page's lead, the markdown twin's lead, the
 * search record's sentences and the DefinedTerm JSON-LD, so people and machines read the same entry.
 *
 * Each name is a real English word most readers rarely meet, so the page first says what the word means, then
 * what the software is. Sense 1 follows the dictionaries; sense 2 is the software, plain and factual, and
 * carries the subject label "software." in italics, as a dictionary marks a specialized sense.
 */

import { thing } from "@drdustinedwards/site-helpers/schema";

/**
 * An etymology is text with foreign words marked, so the page can set them in italics with their
 * language and the twin can emphasize them: a string is plain text, a pair is [lang, word].
 *
 * @typedef {string | [string, string]} EtymologyPart
 * @typedef {{
 *   path: string,
 *   term: string,
 *   syllables: string,
 *   ipa: string,
 *   respelling: string,
 *   partOfSpeech: string,
 *   plural: string[] | null,
 *   etymology: EtymologyPart[],
 *   senses: [string, string],
 *   senseLabels: [string | null, string | null],
 *   audio: string,
 * }} DictionaryEntry
 */

/** The subject label on each software sense (Dustin, 2026-09-28), set in italics before it. */
export const SOFTWARE_LABEL = "software";

/** @param {string | null | undefined} label */
function labelPrefix(label) {
  return label ? `${label}. ` : "";
}

/** @param {string} term */
export function listenLabel(term) {
  return `Listen to the pronunciation of ${term}`;
}

/** @param {DictionaryEntry} entry */
function etymologyText(entry) {
  return entry.etymology.map((part) => (typeof part === "string" ? part : part[1])).join("");
}

/**
 * The entry as plain sentences, for the search record, where markup would be noise.
 *
 * @param {DictionaryEntry} entry
 */
export function dictionaryEntryText(entry) {
  const plural = entry.plural ? `; plural ${entry.plural.join(" or ")}` : "";
  return [
    `${entry.term} (${entry.syllables}), ${entry.ipa}, ${entry.respelling}, ${entry.partOfSpeech}${plural}.`,
    ...entry.senses.map((sense, i) => `${i + 1}. ${labelPrefix(entry.senseLabels[i])}${sense}`),
    `Etymology: ${etymologyText(entry)}`,
  ].join(" ");
}

/**
 * The entry in the markdown twin, directly under the title, the same place the page shows it.
 *
 * @param {DictionaryEntry} entry
 * @param {string} origin absolute origin for the audio link, so the twin read alone still resolves
 */
export function dictionaryEntryMarkdown(entry, origin = "") {
  const plural = entry.plural
    ? `; plural ${entry.plural.map((form) => `*${form}*`).join(" or ")}`
    : "";
  const etymology = entry.etymology
    .map((part) => (typeof part === "string" ? part : `*${part[1]}*`))
    .join("");
  return [
    `**${entry.syllables}** ${entry.ipa} (${entry.respelling}), *${entry.partOfSpeech}*${plural}. [Pronunciation audio](${origin}${entry.audio})`,
    "",
    ...entry.senses.map((sense, i) => {
      const label = entry.senseLabels[i];
      return `${i + 1}. ${label ? `*${label}.* ` : ""}${sense}`;
    }),
    "",
    `Etymology: ${etymology}`,
    "",
  ].join("\n");
}

/**
 * schema.org DefinedTerm: the name, sense 2 as the description (what the word means on this page),
 * and the set every entry belongs to, which is the Software hub.
 *
 * @param {DictionaryEntry} entry
 * @param {string} origin
 */
export function definedTermJsonLd(entry, origin) {
  return thing("DefinedTerm", {
    name: entry.term,
    description: entry.senses[1],
    url: `${origin}${entry.path}`,
    inDefinedTermSet: {
      "@type": "DefinedTermSet",
      name: "Software names on dustinedwards.info",
      url: `${origin}/software`,
    },
  });
}

app/lib/health/ask-converge.mjs.source:
/**
 * One row of /health, as ship reads it (rows.mjs healthChecks). `waitedMs` is set only by settleAskDrift.
 *
 * @typedef {{ name?: string, ok?: boolean, expected?: number, present?: number, waitedMs?: number }} HealthCheckRow
 */

export const ASK_POLL_ATTEMPTS = 12;
export const ASK_POLL_INTERVAL_MS = 10_000;
export const ASK_POLL_WINDOW_MS = 120_000;

/**
 * @param {object} options
 * @param {() => Promise<{ ok: boolean, expected?: number, present?: number } | null>} options.reading
 * @param {(ms: number) => Promise<unknown>} options.sleep
 * @param {() => number} [options.now]
 * @param {number} [options.attempts]
 * @param {number} [options.intervalMs]
 * @param {number} [options.windowMs]
 * @param {(event: { poll: number, reading: any, error: string | null }) => void} [options.onPoll]
 * @returns {Promise<{ converged: boolean, polls: number, latest: any, lastError: string | null }>}
 */
export async function awaitAskConvergence({
  reading,
  sleep,
  now = Date.now,
  attempts = ASK_POLL_ATTEMPTS,
  intervalMs = ASK_POLL_INTERVAL_MS,
  windowMs = ASK_POLL_WINDOW_MS,
  onPoll = () => {},
}) {
  const deadline = now() + windowMs;
  /** @type {any} */
  let latest = null;
  let polls = 0;
  /** A thrown read is an unreadable poll, and its reason is carried out rather than dropped. */
  /** @type {string | null} */
  let lastError = null;

  for (let i = 0; i < attempts && now() < deadline; i += 1) {
    await sleep(intervalMs);
    polls += 1;

    /** @type {any} */
    let observed = null;
    /** @type {string | null} */
    let error = null;
    try {
      observed = await reading();
    } catch (thrown) {
      // A failing HTTP status is not this: it is a readable answer, and the caller parses the body.
      error = thrown instanceof Error ? thrown.message : String(thrown);
      lastError = error;
    }

    const usable = observed && typeof observed.ok === "boolean" ? observed : null;
    if (usable) latest = usable;
    onPoll({ poll: polls, reading: usable, error });

    if (usable && usable.ok) return { converged: true, polls, latest, lastError };
  }

  return { converged: false, polls, latest, lastError };
}

/**
 * Ship's post-repair assertion reads health seconds after the Ask upload, and the index can list
 * short then even when the upload's own write-back read was full (157 then 155, deploy run
 * 36274700184). A failing row gets the same bounded window as the write-back; one that converges
 * is ok, and one that does not keeps its latest counts and the time waited, for the miss.
 *
 * @param {object} options
 * @param {HealthCheckRow | undefined} options.row the ask-index-drift row
 * @param {() => Promise<{ ok: boolean, expected?: number, present?: number } | null>} options.reading
 * @param {(ms: number) => Promise<unknown>} options.sleep
 * @param {() => number} [options.now]
 * @param {(event: { poll: number, reading: any, error: string | null }) => void} [options.onPoll]
 * @returns {Promise<HealthCheckRow | undefined>}
 */
export async function settleAskDrift({ row, reading, sleep, now = Date.now, onPoll }) {
  if (!row || row.ok === true) return row;

  const started = now();
  const { converged, latest } = await awaitAskConvergence({ reading, sleep, now, onPoll });
  // The row's own counts are the stale ones; a converged row carries none, as health's ok rows do.
  if (converged) return { name: row.name, ok: true };
  const counts =
    latest && typeof latest.expected === "number" && typeof latest.present === "number"
      ? { expected: latest.expected, present: latest.present }
      : {};
  return { ...row, ...counts, waitedMs: now() - started };
}

app/lib/health/rows.mjs.source:
/**
 * /health's checks as the readers that act on them want them: ship's readiness, operator-sync's Ask re-read and
 * the colophon's snapshot. /health (site-runtime's healthResponse) gives each check a status, and a drift check
 * that fails carries "present of expected" as its detail; this turns that into `ok` and the two counts, so every
 * reader judges the same rows the same way. Which failing check maps to which repair is Capsid's ops_sites.operator
 * row for this site, read by its watcher (capsid src/site-watch.ts), not a table here.
 *
 * @typedef {{ name: string, status: "pass" | "warn" | "fail", ok: boolean, expected?: number, present?: number, waitedMs?: number }} HealthRow
 */

const COUNTS = /^(\d+) of (\d+)$/;

/**
 * Fails closed: a body that is not a /health answer has no rows, and a row with no status is not a pass.
 *
 * @param {unknown} body the parsed /health body
 * @returns {HealthRow[]}
 */
export function healthChecks(body) {
  const checks = /** @type {any} */ (body)?.checks;
  if (!Array.isArray(checks)) return [];
  return checks
    .filter((c) => c && typeof c === "object" && typeof c.name === "string")
    .map((c) => {
      const status =
        c.status === "pass" || c.status === "warn" || c.status === "fail" ? c.status : "fail";
      const counts =
        status !== "pass" && typeof c.detail === "string" ? COUNTS.exec(c.detail) : null;
      return {
        name: c.name,
        status,
        ok: status === "pass",
        ...(counts ? { present: Number(counts[1]), expected: Number(counts[2]) } : {}),
      };
    });
}

app/lib/health/snapshot.mjs.source:
// /health's verdict, written only by the site Worker's health-snapshot cron job (snapshot-store.server.ts), so the
// tile's AGE is that job's liveness: nothing else may stamp this key, /health included (UptimeRobot, Capsid's watcher
// and Capsomer's network board read it every few minutes and would keep a stopped job looking alive).
// Measured: running the suite in a page loader cost about 1.2 s, so the colophon reads this instead.

import { healthChecks } from "./rows.mjs";
import { HEALTH_SNAPSHOT_EVERY_MINUTES } from "../cron-jobs.mjs";

/** One key, not a prefix: a prefix would invite a second writer. */
export const HEALTH_SNAPSHOT_KEY = "health:snapshot";

/** The health-snapshot job's interval in app/lib/cron-jobs.mjs, in seconds. */
export const HEALTH_POLL_INTERVAL_SECONDS = HEALTH_SNAPSHOT_EVERY_MINUTES * 60;

/** Three intervals: a Cron Trigger is best effort, and a tile that flaps on one missed poll gets muted. */
export const HEALTH_SNAPSHOT_STALE_AFTER_SECONDS = 3 * HEALTH_POLL_INTERVAL_SECONDS;

/**
 * @typedef {{ name: string, status: "pass" | "warn" | "fail" }} SnapshotCheck
 * @typedef {{ ok: boolean, total: number, failed: number, readAt: string, checks: SnapshotCheck[] }} HealthSnapshot
 */

/**
 * @typedef {(
 *   | { state: "fresh", ok: boolean, total: number, failed: number, readAt: string, ageSeconds: number, checks: SnapshotCheck[] }
 *   | { state: "stale", ok: boolean, total: number, failed: number, readAt: string, ageSeconds: number, checks: SnapshotCheck[] }
 *   | { state: "missing" }
 *   | { state: "unreadable" }
 * )} HealthTile
 */

/**
 * Fails to "missing" in every uncertain direction, including a FUTURE timestamp: this is untyped KV JSON,
 * and a cached page presenting a bad value as a verdict would be lying.
 *
 * @param {unknown} snapshot the parsed KV value, or null
 * @param {number} nowMs
 * @returns {HealthTile}
 */
export function healthTile(snapshot, nowMs) {
  if (!snapshot || typeof snapshot !== "object") return { state: "missing" };

  const value = /** @type {Record<string, unknown>} */ (snapshot);
  const { ok, total, failed, readAt, checks } = value;

  if (typeof readAt !== "string") return { state: "missing" };
  if (!Array.isArray(checks) || checks.length !== total) return { state: "missing" };
  const named = checks.filter(
    (c) =>
      c &&
      typeof c.name === "string" &&
      (c.status === "pass" || c.status === "warn" || c.status === "fail"),
  );
  if (named.length !== checks.length) return { state: "missing" };
  if (typeof ok !== "boolean") return { state: "missing" };
  if (!Number.isFinite(total) || !Number.isFinite(failed)) return { state: "missing" };

  const takenMs = Date.parse(readAt);
  if (!Number.isFinite(takenMs)) return { state: "missing" };

  const ageSeconds = Math.floor((nowMs - takenMs) / 1000);
  if (ageSeconds < 0) return { state: "missing" };

  return {
    state: ageSeconds > HEALTH_SNAPSHOT_STALE_AFTER_SECONDS ? "stale" : "fresh",
    ok,
    total: /** @type {number} */ (total),
    failed: /** @type {number} */ (failed),
    readAt,
    ageSeconds,
    checks: named.map((c) => ({ name: c.name, status: c.status })),
  };
}

/**
 * No seconds: on a fifteen minute schedule "47 seconds ago" claims a precision the arrangement lacks.
 *
 * @param {number} ageSeconds
 * @returns {string}
 */
export function formatAge(ageSeconds) {
  if (ageSeconds < 60) return "under a minute ago";
  const minutes = Math.floor(ageSeconds / 60);
  if (minutes < 60) return `${minutes} minute${minutes === 1 ? "" : "s"} ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours} hour${hours === 1 ? "" : "s"} ago`;
  const days = Math.floor(hours / 24);
  return `${days} day${days === 1 ? "" : "s"} ago`;
}

/**
 * Each check's name and status, as public as /health itself, and no detail. Null for a body that is not a
 * /health answer, so a refusal or an error page is never stored as a verdict.
 *
 * @param {unknown} body the parsed /health body
 * @param {string} readAt an ISO 8601 timestamp
 * @returns {HealthSnapshot | null}
 */
export function snapshotFromBody(body, readAt) {
  const checks = healthChecks(body);
  if (checks.length === 0) return null;
  return {
    ok: checks.every((c) => c.ok),
    total: checks.length,
    failed: checks.filter((c) => !c.ok).length,
    readAt,
    checks: checks.map((c) => ({ name: c.name, status: c.status })),
  };
}

app/lib/operator/sync-report.mjs.source:
// `converged` is DERIVED from counts read back after the writes, never asserted by the caller: `ship`
// fails on it, and a loop over a wrongly built corpus still reports a healthy `uploaded`.

/**
 * Any failed key makes `converged` false, even when the counts happen to agree.
 *
 * @param {{
 *   uploaded: number,
 *   removed: number,
 *   cacheDropped: number,
 *   expected: number,
 *   present: number,
 *   failed?: Array<{ key: string, error: string }>,
 * }} counts
 * @returns {{
 *   uploaded: number,
 *   removed: number,
 *   cacheDropped: number,
 *   expected: number,
 *   present: number,
 *   drift: number,
 *   converged: boolean,
 *   failed: Array<{ key: string, error: string }>,
 *   unreadable: boolean,
 * }}
 */
export function askSyncReport(counts) {
  const agreement = convergence(counts.expected, counts.present);
  // An absent list means the caller had nothing to report; anything else that is not an array is an
  // unreadable failure list, and a report that cannot say what failed has not converged.
  const failedReadable = counts.failed === undefined || Array.isArray(counts.failed);
  const failed = Array.isArray(counts.failed) ? counts.failed : [];
  return {
    uploaded: whole(counts.uploaded),
    removed: whole(counts.removed),
    cacheDropped: whole(counts.cacheDropped),
    ...agreement,
    converged: agreement.converged && failedReadable && failed.length === 0,
    failed,
    unreadable: !failedReadable,
  };
}

/**
 * ABSOLUTE drift: an index holding more than its source is stale too, and a negative number would read
 * as healthy to a caller testing `drift > 0`.
 *
 *
 * @param {unknown} expectedRaw @param {unknown} presentRaw
 * @returns {{ expected: number, present: number, drift: number, converged: boolean }}
 */
function convergence(expectedRaw, presentRaw) {
  const expected = whole(expectedRaw);
  const present = whole(presentRaw);
  const drift = Math.abs(expected - present);
  return {
    expected,
    present,
    drift,
    converged: unreadable(expectedRaw, presentRaw) ? false : drift === 0,
  };
}

/**
 * Media drifts by KEY: dropping one file while inventing one row leaves the totals equal, so drift is
 * `missing` plus `extra`, not a count difference.
 *
 *
 * @param {{
 *   indexed: number,
 *   removed: number,
 *   failures: string[],
 *   expected: number,
 *   present: number,
 *   missing: string[],
 *   extra: string[],
 * }} counts
 */
export function mediaSyncReport(counts) {
  const totals = convergence(counts.expected, counts.present);
  const missing = list(counts.missing);
  const extra = list(counts.extra);
  const drift = missing.length + extra.length;
  const failures = list(counts.failures);
  // Fails closed: a list that is not an array of strings cannot say what is missing or what failed, so
  // the report does not converge on it.
  const readable = [counts.missing, counts.extra, counts.failures].every(stringList);

  return {
    indexed: whole(counts.indexed),
    removed: whole(counts.removed),
    expected: totals.expected,
    present: totals.present,
    drift,
    missing,
    extra,
    failures,
    // A failed derivation leaves no row and no source change, so the key sets can agree while wrong.
    converged: totals.converged && readable && drift === 0 && failures.length === 0,
    unreadable: !readable,
  };
}

/** @param {unknown} v @returns {string[]} */
function list(v) {
  return Array.isArray(v) ? v.filter((x) => typeof x === "string") : [];
}

/** @param {unknown} v @returns {boolean} */
function stringList(v) {
  return Array.isArray(v) && v.every((x) => typeof x === "string");
}

/**
 * @param {ReturnType<typeof mediaSyncReport>} report
 * @returns {string}
 */
export function mediaSyncSummary(report) {
  if (report.converged) {
    return (
      `Media index converged: ${report.expected} expected, ${report.present} present, ` +
      `${report.indexed} indexed, ${report.removed} removed.`
    );
  }
  const why = [
    report.missing.length ? `${report.missing.length} missing` : "",
    report.extra.length ? `${report.extra.length} extra` : "",
    report.failures.length ? `${report.failures.length} failed to derive` : "",
    report.unreadable ? "an unreadable missing, extra or failure list" : "",
  ].filter(Boolean);
  return (
    `MEDIA INDEX STILL DRIFTED: ${report.expected} expected, ${report.present} present` +
    (why.length ? ` (${why.join(", ")})` : "") +
    `, after indexing ${report.indexed} and removing ${report.removed}.`
  );
}

/**
 * An unreadable count is not a passing count.
 *
 * @param {unknown} a @param {unknown} b
 */
function unreadable(a, b) {
  return !Number.isInteger(a) || !Number.isInteger(b);
}

/** @param {unknown} n @returns {number} */
function whole(n) {
  return Number.isInteger(n) ? Number(n) : 0;
}

/**
 * @param {ReturnType<typeof askSyncReport>} report
 * @returns {string}
 */
export function askSyncSummary(report) {
  if (report.failed?.length) {
    return (
      `ASK UPLOAD FAILED for ${report.failed.length} key(s) after retries: ` +
      `${report.failed.map((f) => `${f.key} (${f.error})`).join(", ")}. ` +
      `${report.expected} expected, ${report.present} present.`
    );
  }
  if (report.unreadable) {
    return (
      `ASK SYNC REPORT UNREADABLE: the failure list was not a list, so what failed is unknown. ` +
      `${report.expected} expected, ${report.present} present.`
    );
  }
  return report.converged
    ? `Ask index converged: ${report.expected} expected, ${report.present} present, ` +
        `${report.uploaded} uploaded, ${report.removed} removed.`
    : `ASK INDEX STILL SHORT: ${report.expected} expected, ${report.present} present, ` +
        `drift ${report.drift}, after uploading ${report.uploaded} and removing ${report.removed}.`;
}

app/lib/pages/compile.mjs.source:
// One door from a page file to everything derived from it: parse, validate, render, the markdown twin and
// the search input. build:content, sync:content and the adapter's page save all call compilePage, so
// a file CI passes is the file the save tool accepts and the page draws (docs/PAGES.md).

import matter from "gray-matter";

import { gitBlobSha } from "../content/hashes.mjs";
import {
  CONTENT_PAGE_SECTIONS,
  DESCRIPTION_MAX,
  LEGAL_BANNER,
  LEGAL_PAGE_PATHS,
  PAGE_FILE_PATHS,
  SEO_TITLE_MAX,
  contentPageFile,
  contentPageMarkdownBody,
  contentPageSearchInputs,
  markdownTableFacts,
} from "../content-pages.mjs";
import { IDENTITY } from "../identity.generated.mjs";
import { expandPhagePage, expandPhageTokens, withPhageRowIds } from "../phages/compile.mjs";
import { pageInvariantErrors } from "./invariants.mjs";
import { protectedPageReason } from "./protected.mjs";

export const PAGES_DIR = "content/pages";

/** The identity facts a page may state by token ({{identity.role}}): text, from the CV (app/lib/identity.mjs). */
export const IDENTITY_TOKEN_KEYS = /** @type {const} */ ([
  "name",
  "degree",
  "discipline",
  "disciplineLower",
  "rank",
  "role",
  "adminTitle",
  "jobTitle",
  "cvTitle",
  "department",
  "departmentSubject",
  "affiliation",
]);
const IDENTITY_TOKEN = /\{\{\s*identity\.([A-Za-z]+)\s*\}\}/g;

/**
 * Every token a page can carry, filled: the owner's identity from the CV, then the phage facts from the rows. A
 * title, a role or a headship a page states is read, never typed, so a CV change updates the page. A token that
 * names nothing is an error, never an empty string.
 *
 * @param {string} text
 * @param {import("../phages/compile.mjs").Phage[] | undefined} phages
 * @returns {{ ok: true, text: string } | { ok: false, errors: string[] }}
 */
export function expandPageTokens(text, phages) {
  /** @type {string[]} */
  const errors = [];
  const withIdentity = text.replace(IDENTITY_TOKEN, (whole, key) => {
    if (!(/** @type {readonly string[]} */ (IDENTITY_TOKEN_KEYS).includes(key))) {
      errors.push(`${whole} is not an identity fact (${IDENTITY_TOKEN_KEYS.join(", ")})`);
      return whole;
    }
    return String(/** @type {Record<string, unknown>} */ (IDENTITY)[key]);
  });
  if (errors.length > 0) return { ok: false, errors };
  return expandPhageTokens(withIdentity, phages);
}

/** The repository path of a page's file, from its file key (`research-phages`). */
export function pageSourcePath(/** @type {string} */ slug) {
  return `${PAGES_DIR}/${slug}.md`;
}

/** The file key of a registered path: `/research/phages` is `research-phages`. */
export function pageSlug(/** @type {string} */ path) {
  return contentPageFile(path).slice(0, -3);
}

/** The registered path a file key stands for, or undefined when no page file may have that key. */
export function pagePathForSlug(/** @type {string} */ slug) {
  return PAGE_FILE_PATHS.find((path) => pageSlug(path) === slug);
}

/** The schema.org types a page may declare; app/routes/content-page.tsx shapes a node for each. */
const SCHEMA_TYPES = ["SoftwareApplication", "SoftwareSourceCode", "WebSite", "WebPage", "Dataset"];

/**
 * @typedef {{
 *   schemaType?: string,
 *   productUrl?: string,
 *   codeRepository?: string,
 *   applicationCategory?: string,
 *   license?: string,
 *   programmingLanguage?: string,
 *   runtimePlatform?: string,
 *   spatialCoverage?: string,
 *   dataset?: { variableMeasured: string[], temporalCoverage: string | null, rows: number },
 * }} PageSchema
 *
 * What only a legal page states (LEGAL_PAGE_PATHS): `banner` is the one word "Draft", `lastUpdated` an ISO date.
 * @typedef {{ banner?: string, lastUpdated?: string }} PageLegal
 *
 * @typedef {{ depth: number, id: string, text: string }} TocEntry
 *
 * The page as the routes, the search index and the gates read it. `markdown` is the body without front
 * matter; the twin a machine reads is built from it (contentPageMarkdownBody).
 * @typedef {{
 *   path: string, title: string, seoTitle: string, description: string, html: string,
 *   markdown: string, toc: TocEntry[],
 * } & PageSchema & PageLegal} CompiledPage
 *
 * What D1's `record` column holds: the page less its markdown, with its file key and draft flag.
 * @typedef {Omit<CompiledPage, "markdown"> & { slug: string, draft: boolean }} PageRecord
 */

/**
 * The structured-data facts a page's front matter states, each only when it is written there: the JSON-LD
 * says what the page holds and never fills a gap. A Dataset also carries what its first table says.
 *
 * @param {Record<string, unknown>} fm
 * @param {string} markdown
 * @param {string[]} errors
 * @returns {PageSchema}
 */
function pageSchema(fm, markdown, errors) {
  const text = (/** @type {unknown} */ value) =>
    value == null || value === "" ? "" : String(value);
  const schemaType = text(fm.schema_type);
  if (schemaType && !SCHEMA_TYPES.includes(schemaType)) {
    errors.push(`schema_type "${schemaType}" is not one of ${SCHEMA_TYPES.join(", ")}`);
  }
  const codeRepository = text(fm.code_repository);
  if (codeRepository && !["SoftwareApplication", "SoftwareSourceCode"].includes(schemaType)) {
    errors.push(
      "code_repository is only stated for software (schema_type SoftwareApplication or SoftwareSourceCode)",
    );
  }
  const dataset = schemaType === "Dataset" ? markdownTableFacts(markdown) : null;
  if (schemaType === "Dataset" && !dataset) {
    errors.push("schema_type is Dataset but the page has no markdown table for it to describe");
  }
  /** @type {Array<[Exclude<keyof PageSchema, "dataset">, string]>} */
  const fields = [
    ["schemaType", schemaType],
    ["productUrl", text(fm.product_url)],
    ["codeRepository", codeRepository],
    ["applicationCategory", text(fm.application_category)],
    ["license", text(fm.license)],
    ["programmingLanguage", text(fm.programming_language)],
    ["runtimePlatform", text(fm.runtime_platform)],
    ["spatialCoverage", text(fm.spatial_coverage)],
  ];
  /** @type {PageSchema} */
  const schema = dataset ? { dataset } : {};
  for (const [key, value] of fields) if (value !== "") schema[key] = value;
  return schema;
}

/**
 * The banner and the last-updated date a legal page states, each only when it is written there. The banner is
 * the single word "Draft" and nothing else; the date is a real calendar day. Neither belongs on any other page.
 * YAML reads an unquoted `2026-10-06` as a Date and rolls an impossible `2026-02-30` over to March, so the
 * day is read from the front matter's own text, the way it was written, and the parsed value only when the
 * line cannot be found.
 *
 * @param {Record<string, unknown>} fm
 * @param {string} frontMatter the front matter's text, as written
 * @param {string} path
 * @param {string[]} errors
 * @returns {PageLegal}
 */
function pageLegal(fm, frontMatter, path, errors) {
  /** @type {PageLegal} */
  const legal = {};
  const banner = fm.banner == null ? "" : String(fm.banner).trim();
  if (banner !== "") {
    if (banner !== LEGAL_BANNER)
      errors.push(
        `banner is ${JSON.stringify(banner)}; the one word it may say is "${LEGAL_BANNER}"`,
      );
    else legal.banner = banner;
  }
  const written = /^last_updated:[ \t]*["']?([^"'#\r\n]*?)["']?[ \t]*(?:#.*)?$/m.exec(
    frontMatter,
  )?.[1];
  const raw = written ?? fm.last_updated;
  if (raw != null && raw !== "") {
    const day = raw instanceof Date ? raw.toISOString().slice(0, 10) : String(raw).trim();
    const real =
      /^\d{4}-\d{2}-\d{2}$/.test(day) &&
      new Date(`${day}T00:00:00.000Z`).toISOString().slice(0, 10) === day;
    if (real) legal.lastUpdated = day;
    else errors.push(`last_updated is ${JSON.stringify(day)}; it is a real day written YYYY-MM-DD`);
  }
  if (
    (legal.banner || legal.lastUpdated || fm.banner != null || fm.last_updated != null) &&
    !LEGAL_PAGE_PATHS.includes(path)
  ) {
    errors.push(
      `banner and last_updated belong to the legal pages (${LEGAL_PAGE_PATHS.join(", ")}), not to ${path}`,
    );
  }
  return legal;
}

/**
 * The page's dictionary entry (docs/DICTIONARY.md), when it has a published one, leads its twin and its search
 * record, so `entry` is the caller's to give: the build reads it from content/dictionary, the Worker from D1.
 *
 * @param {{
 *   slug: string,
 *   raw: string,
 *   pipeline: { renderBody: (input: { file: string, body: string, resolveImage: (src: string) => Promise<never> }) => Promise<{ html: string, toc: TocEntry[], blockedUrls: Array<{ url: string }> }>,
 *               findWideDashes: (text: string) => Array<{ line: number, column: number, char: string, excerpt: string }> },
 *   sourcePath?: string,
 *   generated?: boolean,
 *   entry?: import("../dictionary-entries.mjs").DictionaryEntry,
 *   phages?: import("../phages/compile.mjs").Phage[],
 * }} input
 * @returns {Promise<
 *   | { ok: false, errors: string[] }
 *   | { ok: true, errors: [], page: CompiledPage, record: PageRecord, draft: boolean, markdown: string,
 *       searchInput: ReturnType<typeof contentPageSearchInputs>[number], sourcePath: string, sourceBlobSha: string }
 * >}
 */
export async function compilePage({
  slug,
  raw,
  pipeline,
  sourcePath,
  generated = false,
  entry,
  phages,
}) {
  const expectedPath = pagePathForSlug(slug);
  if (!expectedPath) {
    return {
      ok: false,
      errors: [
        `"${slug}" is not a registered page. A page's address is structure: add the path to CONTENT_PAGE_PATHS ` +
          "(app/lib/content-pages.mjs) in code, and a save can then write its file; a save cannot create a new path",
      ],
    };
  }
  const file = sourcePath ?? pageSourcePath(slug);
  /** @type {string[]} */
  const errors = (generated ? [] : pipeline.findWideDashes(raw)).map(
    (hit) =>
      `line ${hit.line}, column ${hit.column}: wide dash ${hit.char}; house style uses commas, periods, parentheses or colons ("${hit.excerpt}")`,
  );

  let parsed;
  try {
    parsed = matter(raw);
  } catch (error) {
    return {
      ok: false,
      errors: [
        ...errors,
        `the front matter is not valid YAML: ${error instanceof Error ? error.message : String(error)}`,
      ],
    };
  }
  const fm = /** @type {Record<string, unknown>} */ (parsed.data);
  // A phage fact a page states (the count, the span, a genome's size) is read from the phage rows by a token,
  // never typed, so the title and description fill the same way the body does.
  /** @param {unknown} value @returns {string} */
  const filled = (value) => {
    const result = expandPageTokens(String(value ?? ""), phages);
    if (!result.ok) {
      errors.push(...result.errors);
      return String(value ?? "");
    }
    return result.text;
  };
  const page = {
    path: String(fm.path ?? ""),
    title: filled(fm.title),
    seoTitle: filled(fm.seo_title),
    description: filled(fm.description),
  };
  if (page.path !== expectedPath) {
    errors.push(
      `path is "${page.path}", but ${contentPageFile(expectedPath)} is the file for ${expectedPath}: every page ` +
        "must be listed in CONTENT_PAGE_PATHS (app/lib/content-pages.mjs) and its file must say so",
    );
  }
  for (const [field, value] of [
    ["title", page.title],
    ["seo_title", page.seoTitle],
    ["description", page.description],
  ]) {
    if (!value) errors.push(`${field} is required`);
  }
  if (page.seoTitle.length > SEO_TITLE_MAX) {
    errors.push(
      `seo_title is ${page.seoTitle.length} characters (at most ${SEO_TITLE_MAX}); Google would clip it`,
    );
  }
  if (page.description.length > DESCRIPTION_MAX) {
    errors.push(
      `description is ${page.description.length} characters (at most ${DESCRIPTION_MAX}); Google would clip it`,
    );
  }
  if (fm.draft !== undefined && typeof fm.draft !== "boolean") {
    errors.push(`draft is ${JSON.stringify(fm.draft)}; it is true or false`);
  }
  // The phage page's table is drawn from the phage rows where the file's marker says (docs/PHAGES.md), before
  // anything reads the body, so its HTML, twin, dataset facts and search record all come from one text. Every
  // other page passes through unchanged.
  const drawn = expandPhagePage(page.path, parsed.content, phages);
  if (!drawn.ok) errors.push(...drawn.errors);
  const drawnBody = drawn.ok
    ? expandPageTokens(drawn.markdown, phages)
    : /** @type {const} */ ({ ok: true, text: parsed.content });
  if (!drawnBody.ok) errors.push(...drawnBody.errors);
  const body = drawnBody.ok ? drawnBody.text : parsed.content;
  const schema = pageSchema(fm, body, errors);
  const legal = pageLegal(fm, parsed.matter, page.path, errors);
  const keep = protectedPageReason(page.path);
  if (keep && fm.draft === true) errors.push(`draft is true, but ${keep}`);
  if (errors.length > 0) return { ok: false, errors };

  let rendered;
  try {
    rendered = await pipeline.renderBody({
      file,
      body,
      resolveImage: async (src) => {
        throw new Error(
          `the page references an image ("${src}") and these pages have no image pipeline`,
        );
      },
    });
  } catch (error) {
    return { ok: false, errors: [error instanceof Error ? error.message : String(error)] };
  }
  if (rendered.blockedUrls.length > 0) {
    errors.push(
      `links the URL allowlist refused: ${rendered.blockedUrls.map((b) => b.url).join(", ")}`,
    );
  }
  for (const section of CONTENT_PAGE_SECTIONS) {
    const [sectionPath, id] = section.split("#");
    if (sectionPath === page.path && !rendered.toc.some((heading) => heading.id === id)) {
      errors.push(
        `no heading has the id "${id}", which CONTENT_PAGE_SECTIONS (app/lib/content-pages.mjs) lists for the header menu`,
      );
    }
  }

  /** @type {CompiledPage} */
  const compiled = {
    ...page,
    html: withPhageRowIds(page.path, rendered.html, phages),
    markdown: body,
    toc: rendered.toc,
    ...schema,
    ...legal,
  };
  errors.push(...pageInvariantErrors(compiled, { phages }));
  if (errors.length > 0) return { ok: false, errors };

  const draft = fm.draft === true;
  const { markdown: _body, ...rest } = compiled;
  const [searchInput] = contentPageSearchInputs([compiled], () => entry);
  if (!searchInput) throw new Error(`no search input was made for ${page.path}`);
  return {
    ok: true,
    errors: [],
    page: compiled,
    record: { slug, draft, ...rest },
    draft,
    markdown: contentPageMarkdownBody(compiled, entry),
    searchInput,
    sourcePath: file,
    sourceBlobSha: await gitBlobSha(raw),
  };
}

