// Decoded where a person reads it, never at rest: check:machine-readable asserts no stored abstract
// contains <, which keeps registry text safe in JSON-LD and exports. One alternation in one pass, so
// &amp;lt; decodes to &lt; and stops. Unknown names are left verbatim on purpose.

const NAMED = {
  amp: "&",
  lt: "<",
  gt: ">",
  quot: '"',
  apos: "'",
};

const REFERENCE = /&(?:#(\d+)|#[xX]([0-9a-fA-F]+)|([a-zA-Z][a-zA-Z0-9]*));/g;

/**
 * String.fromCodePoint throws out of range, which would fail a render over one bad deposit.
 *
 * @param {number} code
 * @returns {string | null}
 */
function fromCodePoint(code) {
  // Zero too: &#0; is a NUL, which no reader should receive from a deposit or a feed.
  if (!Number.isInteger(code) || code < 1 || code > 0x10ffff) return null;
  // Lone surrogates are valid integers and produce unpaired halves.
  if (code >= 0xd800 && code <= 0xdfff) return null;
  return String.fromCodePoint(code);
}

/**
 * @param {string | null | undefined} text
 * @returns {string}
 */
export function decodeEntities(text) {
  return String(text ?? "").replace(REFERENCE, (whole, dec, hex, name) => {
    if (dec !== undefined) return fromCodePoint(Number(dec)) ?? whole;
    if (hex !== undefined) return fromCodePoint(Number.parseInt(hex, 16)) ?? whole;
    return Object.prototype.hasOwnProperty.call(NAMED, name)
      ? /** @type {string} */ (NAMED[/** @type {keyof NAMED} */ (name)])
      : whole;
  });
}

app/lib/publications/pdf-redirect.mjs.source:
// A paper's canonical URL is the slash form, because Google Scholar honors `citation_pdf_url` only when the
// PDF sits in the abstract page's own subdirectory. Not a move: the slashless form was never the page.

export const PUBLICATIONS_PREFIX = "/research/publications/";

// The HTTPS redirect's own rule, so the redirect helpers never disagree.
export { httpsRedirectStatus as pdfRedirectStatus } from "../https-redirect.mjs";

/**
 * Skips anything with a dot so the PDF inside the directory still reaches the asset handler.
 *
 * @param {string} pathname
 * @returns {string | null} the canonical path, or null
 */
export function paperSlashTarget(pathname) {
  if (typeof pathname !== "string") return null;
  if (!pathname.startsWith(PUBLICATIONS_PREFIX)) return null;
  const rest = pathname.slice(PUBLICATIONS_PREFIX.length);
  if (rest.length === 0) return null;
  if (rest.includes("/")) return null;
  if (rest.includes(".")) return null;
  return `${pathname}/`;
}

app/lib/publications/validate.mjs.source:
// Judges a parsed publication file (docs/PUBLICATIONS.md). check:machine-readable and the Carrel adapter's
// save both call this, so a file CI refuses is a file the save refuses, for the same reason in the same
// words. Every message starts with the field path, with no leading dot (`authors[2]: ...`).
//
// The checks that need the repository (does the PDF exist, does its hash match) and the other papers
// (is this id or DOI taken) arrive as `host` and `others`, so CI reads a clone and the Worker asks GitHub
// and D1 without this module knowing which.

import { contentIdFits } from "../carrel/content-id.mjs";
import { accessionUrl, accessionsInText } from "./accessions.mjs";
import { HOSTED_WITHOUT_LICENSE, permitsRedistribution } from "./hosting.mjs";
import { doiSlug, paperPdfPath } from "./paths.mjs";
import { updateNoticeProblem } from "./update-notice.mjs";
import { TOPIC_IDS } from "./topics.mjs";

const PUBLICATION_KIND = "publication";
const TYPES = /** @type {const} */ ([
  "article",
  "review",
  "chapter",
  "abstract",
  "teaching-resource",
]);
const ACCESS = /** @type {const} */ (["self-hosted", "external"]);
const STATUSES = /** @type {const} */ (["published", "submitted"]);

/** Every key a file may carry. Anything else is a typo that would be silently ignored. */
const FRONT_MATTER_FIELDS = new Set([
  "doi",
  "slug",
  "id",
  "status",
  "draft",
  "type",
  "title",
  "authors",
  "journal",
  "publishedDate",
  "year",
  "volume",
  "issue",
  "pages",
  "topics",
  "access",
  "pdfPath",
  "pdfSha256",
  "externalUrl",
  "pmid",
  "pmcid",
  "pmcUrl",
  "preprintDoi",
  "isOpenAccess",
  "license",
  "licenseSource",
  "summary",
  "selected",
  "accessions",
  "updateNotice",
  "abstract",
  "csl",
]);

const SLUG_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const DOI_PATTERN = /^10\.\d{4,9}\/\S+$/;
const PMC_URL = /^https:\/\/pmc\.ncbi\.nlm\.nih\.gov\/articles\/PMC\d+\/$/;
const DATE_PATTERN = /^\d{4}(-\d{2}){0,2}$/;
const SHA256 = /^[0-9a-f]{64}$/;
const ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_-]*$/;
/** A character reference: titles are stored decoded, so one left in is a value that would render twice-decoded. */
const CHARACTER_REFERENCE = /&(?:#\d+|#[xX][0-9a-fA-F]+|[a-zA-Z][a-zA-Z0-9]*);/;
/** The PreToolUse hook cannot reach data files; escapes keep this file free of the dashes. */
const WIDE_DASH = new RegExp("[\\u2013\\u2014]");
/** A scanned PDF extracts to nothing and everything else still passes. */
const MIN_FULL_TEXT_CHARS = 500;
const SUMMARY_MAX = 200;
/** What `paperAskUrl` may produce before it is a URL no client will send. */
export const ASK_URL_MAX = 600;

/**
 * @typedef {object} PublicationHost
 * @property {(path: string) => Promise<{ size: number, sha256?: string } | null>} pdf the repository file at a
 *   site-absolute public path (`/research/...`), or null when it is not there. `sha256` is present where the
 *   host can hash the bytes (CI); the Worker's GitHub reads cannot, so the hash is checked in CI only.
 *
 * @typedef {object} OtherPublication
 * @property {string} slug
 * @property {string} id
 * @property {string | null} doi
 */

/** @param {unknown} value @returns {value is string} */
const isString = (value) => typeof value === "string";
/** @param {unknown} value @returns {value is Record<string, unknown>} */
const isObject = (value) => Boolean(value) && typeof value === "object" && !Array.isArray(value);
/** @param {unknown} value @returns {value is string} */
const isFilled = (value) => isString(value) && value.trim() !== "";

/**
 * DOI names are case-insensitive: the one key the corpus joins on.
 *
 * @param {string | null | undefined} doi
 */
export const doiKey = (doi) => (doi ?? "").trim().toLowerCase();

/**
 * @param {object} input
 * @param {import("./parse.mjs").ParsedPublication} input.parsed
 * @param {string} input.slug the file's name without `.md`
 * @param {PublicationHost} input.host
 * @param {OtherPublication[]} [input.others] every OTHER publication, for uniqueness
 * @returns {Promise<string[]>}
 */
export async function validatePublicationFile({ parsed, slug, host, others = [] }) {
  /** @type {string[]} */
  const errors = [...parsed.problems];
  const { data, fullText } = parsed;
  /** @param {string} field @param {string} message */
  const bad = (field, message) => errors.push(`${field}: ${message}`);

  for (const key of Object.keys(data)) {
    if (!FRONT_MATTER_FIELDS.has(key)) bad(key, "is not a publication field");
  }

  // ---- identity: slug, id, DOI, status
  const status = data.status ?? "published";
  if (!STATUSES.includes(/** @type {any} */ (status))) {
    bad("status", `${JSON.stringify(status)} is not one of ${STATUSES.join(", ")}`);
  }
  const submitted = status === "submitted";

  if (!SLUG_PATTERN.test(slug)) {
    bad("slug", `the file name "${slug}" is not a lowercase kebab-case slug`);
  } else if (!contentIdFits(PUBLICATION_KIND, slug)) {
    bad(
      "slug",
      `"${slug}" is too long: ${PUBLICATION_KIND}.<slug> must fit the 200 characters of a Carrel content id`,
    );
  }
  if (data.slug !== undefined && data.slug !== null && data.slug !== slug) {
    bad("slug", `${JSON.stringify(data.slug)} is not the file's name "${slug}"`);
  }

  const doi = data.doi;
  if (doi === undefined || doi === null) {
    if (!submitted)
      bad(
        "doi",
        "is required for a published paper; a manuscript without one is status: submitted",
      );
    if (submitted && data.slug !== slug)
      bad(
        "slug",
        "a record with no DOI names its slug in the file (slug: ...), since there is no DOI to derive it from",
      );
  } else if (!isString(doi) || !DOI_PATTERN.test(doi)) {
    bad("doi", `${JSON.stringify(doi)} is not a DOI name (10.<registrant>/<suffix>)`);
  } else if (SLUG_PATTERN.test(slug) && doiSlug(doi) !== slug) {
    bad(
      "doi",
      `its page slug would be "${doiSlug(doi)}", but the file is named "${slug}". The file name is the DOI's slug and never changes after Google Scholar has indexed it`,
    );
  }

  if (!isFilled(data.id)) {
    bad("id", "is required (the curated id, which is also the BibTeX key)");
  } else if (!isString(data.id) || !ID_PATTERN.test(data.id)) {
    bad("id", `${JSON.stringify(data.id)} must be letters, digits, hyphens and underscores`);
  }

  for (const other of others) {
    if (other.slug === slug) continue;
    if (isString(data.id) && other.id === data.id)
      bad("id", `"${data.id}" is already the id of ${other.slug}`);
    if (isString(doi) && other.doi && doiKey(other.doi) === doiKey(doi)) {
      bad(
        "doi",
        `${doi} is already ${other.slug}'s DOI (DOI names are case-insensitive, so two casings are one work)`,
      );
    }
    if (doiSlug(other.doi ?? "") === slug && other.slug !== slug)
      bad("slug", `the page slug "${slug}" is already ${other.slug}'s`);
  }

  if (data.draft !== undefined && typeof data.draft !== "boolean")
    bad("draft", "must be true or false");

  // ---- the citation
  if (!isFilled(data.type) || !TYPES.includes(/** @type {any} */ (data.type))) {
    bad("type", `${JSON.stringify(data.type)} is not one of ${TYPES.join(", ")}`);
  }

  const title = data.title;
  if (!isFilled(title)) {
    bad("title", "is required");
  } else if (isString(title)) {
    // paperAskUrl quotes the title and the search reads a quoted run as a phrase, so a quote splits it.
    if (/["']/.test(title))
      bad(
        "title",
        "contains a quotation mark; the paper's Ask link quotes the title, so a quote inside splits the phrase",
      );
    if (CHARACTER_REFERENCE.test(title))
      bad(
        "title",
        "carries a character reference (&amp; and the like); write the character itself",
      );
    if (title.includes("<"))
      bad("title", 'contains "<", which would end a JSON-LD script block early');
    if (title !== title.trim() || /\s{2,}/.test(title))
      bad("title", "has leading, trailing or repeated whitespace");
  }

  if (!Array.isArray(data.authors) || data.authors.length === 0) {
    bad("authors", "must list at least one author; a shortened list is a wrong citation");
  } else {
    data.authors.forEach((name, i) => {
      if (!isFilled(name)) bad(`authors[${i}]`, "is empty; every author has a name");
    });
  }

  for (const key of ["journal", "volume", "issue", "pages"]) {
    const value = data[key];
    if (value !== undefined && value !== null && !isString(value)) bad(key, "must be text");
    if (isString(value) && value.trim() === "") bad(key, "is blank; leave it out instead");
  }

  const date = data.publishedDate;
  if (date !== undefined && date !== null && !(isString(date) && DATE_PATTERN.test(date))) {
    bad("publishedDate", `${JSON.stringify(date)} is not YYYY-MM-DD, YYYY-MM or YYYY`);
  }
  if (data.year !== undefined && data.year !== null) {
    if (
      !Number.isInteger(data.year) ||
      /** @type {number} */ (data.year) < 1900 ||
      /** @type {number} */ (data.year) > 2200
    ) {
      bad("year", `${JSON.stringify(data.year)} is not a year`);
    } else if (isString(date) && String(data.year) !== date.slice(0, 4)) {
      bad(
        "year",
        `${data.year} disagrees with publishedDate ${date}; leave year out, it comes from the date`,
      );
    }
  }
  if ((date === undefined || date === null) && !Number.isInteger(data.year)) {
    bad("publishedDate", "is required (or year, for a manuscript with no date yet)");
  }

  if (!Array.isArray(data.topics) || data.topics.length === 0) {
    bad("topics", "must carry at least one topic");
  } else {
    data.topics.forEach((topic, i) => {
      if (!isString(topic) || !TOPIC_IDS.has(topic))
        bad(
          `topics[${i}]`,
          `${JSON.stringify(topic)} is not a declared topic (${[...TOPIC_IDS].join(", ")})`,
        );
    });
  }

  // ---- identifiers
  if (
    data.pmid !== undefined &&
    data.pmid !== null &&
    !(isString(data.pmid) && /^\d+$/.test(data.pmid))
  ) {
    bad("pmid", `${JSON.stringify(data.pmid)} is not digits`);
  }
  if (
    data.pmcUrl !== undefined &&
    data.pmcUrl !== null &&
    !(isString(data.pmcUrl) && PMC_URL.test(data.pmcUrl))
  ) {
    bad(
      "pmcUrl",
      `${JSON.stringify(data.pmcUrl)} is not in landing-page form (https://pmc.ncbi.nlm.nih.gov/articles/PMC<digits>/)`,
    );
  }
  if (Boolean(data.pmcid) !== Boolean(data.pmcUrl))
    bad("pmcid", "and pmcUrl are present together or absent together");
  if (
    data.pmcid !== undefined &&
    data.pmcid !== null &&
    !(isString(data.pmcid) && /^PMC\d+$/.test(data.pmcid))
  ) {
    bad("pmcid", `${JSON.stringify(data.pmcid)} is not PMC<digits>`);
  }
  if (data.preprintDoi !== undefined && data.preprintDoi !== null) {
    if (!isString(data.preprintDoi) || !DOI_PATTERN.test(data.preprintDoi))
      bad("preprintDoi", `${JSON.stringify(data.preprintDoi)} is not a DOI name`);
    else if (doiKey(data.preprintDoi) === doiKey(isString(doi) ? doi : ""))
      bad("preprintDoi", "is the paper's own DOI");
  }
  if (data.isOpenAccess !== undefined && typeof data.isOpenAccess !== "boolean")
    bad("isOpenAccess", "must be true or false");
  if (data.selected !== undefined && typeof data.selected !== "boolean")
    bad("selected", "must be true or false");

  // ---- access: where the reader gets the paper
  const access = data.access;
  if (!ACCESS.includes(/** @type {any} */ (access))) {
    bad("access", `${JSON.stringify(access)} is not one of ${ACCESS.join(", ")}`);
  }
  const hasPdfPath = data.pdfPath !== undefined && data.pdfPath !== null;
  if (access === "self-hosted") {
    if (submitted) bad("access", "a submitted manuscript has no PDF on this site; use external");
    const derived = SLUG_PATTERN.test(slug) ? paperPdfPath(slug) : null;
    if (!hasPdfPath) {
      bad("pdfPath", `is required for a self-hosted paper (${derived ?? "the derived path"})`);
    } else if (derived && data.pdfPath !== derived) {
      bad(
        "pdfPath",
        `${JSON.stringify(data.pdfPath)} should be ${derived}: the PDF lives in its own page's directory, which is what Google Scholar needs`,
      );
    }
    if (data.externalUrl !== undefined && data.externalUrl !== null)
      bad("externalUrl", "is for external papers; a self-hosted one links its own PDF");
    if (derived && hasPdfPath && data.pdfPath === derived) {
      const file = await host.pdf(derived);
      if (!file) {
        bad(
          "pdfPath",
          `${derived} is not in the repository at public${derived}. Add the PDF in a pull request first; adding one is a code change, never an upload through this tool`,
        );
      } else {
        if (file.size === 0) bad("pdfPath", `${derived} is a zero-byte file`);
        if (!isString(data.pdfSha256) || !SHA256.test(data.pdfSha256)) {
          bad(
            "pdfSha256",
            "is required for a self-hosted paper: the sha256 of the PDF the full text was extracted from",
          );
        } else if (file.sha256 !== undefined && file.sha256 !== data.pdfSha256) {
          bad(
            "pdfSha256",
            `${data.pdfSha256.slice(0, 12)} does not match the PDF in the repository (${file.sha256.slice(0, 12)}); re-extract the full text from the current PDF`,
          );
        }
      }
    }
    if (fullText === null) {
      bad(
        "Full text",
        `a self-hosted paper carries its extracted text under a "## Full text" heading`,
      );
    } else if (fullText.length < MIN_FULL_TEXT_CHARS) {
      bad(
        "Full text",
        `is ${fullText.length} characters. Extraction produced almost nothing; a scanned PDF with no text layer looks exactly like this`,
      );
    }
  } else if (access === "external") {
    if (hasPdfPath) bad("pdfPath", "is for self-hosted papers; an external one has none");
    if (data.pdfSha256 !== undefined && data.pdfSha256 !== null)
      bad("pdfSha256", "is for self-hosted papers");
    if (fullText !== null)
      bad("Full text", "a paper this site does not host has no extracted text");
    const external = data.externalUrl;
    if (
      external !== undefined &&
      external !== null &&
      !(isString(external) && /^https:\/\/\S+$/.test(external))
    ) {
      bad("externalUrl", `${JSON.stringify(external)} is not an https URL`);
    }
    if (!submitted && !data.externalUrl && !isString(doi))
      bad("externalUrl", "an external published paper links out through a DOI or an externalUrl");
  }

  // ---- rights: hosting a paper whose license does not permit it is Dustin's call, per DOI
  if (access === "self-hosted") {
    const license = isString(data.license) ? data.license : null;
    if (!permitsRedistribution(license) && !(isString(doi) && HOSTED_WITHOUT_LICENSE.has(doi))) {
      bad(
        "license",
        `${license ?? "none"} does not permit redistribution, and ${isString(doi) ? doi : "this paper"} is not one Dustin has chosen to host without one. ` +
          `Hosting a paper whose license does not permit it is Dustin's call, recorded per DOI in app/lib/publications/hosting.mjs, so a new one is a new decision and not a precedent`,
      );
    }
    if (!permitsRedistribution(license) && !data.licenseSource && license === null) {
      bad(
        "licenseSource",
        "a hosted paper with no license records what the registries said (crossref:tdm-only, none-deposited, ...), so a closed paper is not mistaken for an unchecked one",
      );
    }
  }

  // ---- the plain-language line
  if (data.summary !== undefined && data.summary !== null) {
    const summary = data.summary;
    if (!isString(summary) || summary.trim() === "") {
      bad("summary", "is present but blank; absent is a state, empty is a mistake");
    } else {
      if (summary.length > SUMMARY_MAX)
        bad("summary", `is ${summary.length} characters; the limit is ${SUMMARY_MAX}`);
      if (/[.!?]\s+[A-Z]/.test(summary)) bad("summary", "is more than one sentence");
      if (WIDE_DASH.test(summary))
        bad("summary", "carries an em dash or en dash; use a comma, period, parentheses or colon");
    }
  }

  // ---- the abstract and the raw record
  if (data.abstract !== undefined && data.abstract !== null) {
    if (!isString(data.abstract)) bad("abstract", "must be text");
    else if (data.abstract.includes("<"))
      bad(
        "abstract",
        `contains "<", which would end a JSON-LD script block early; store it as &lt;`,
      );
  }
  if (data.csl !== undefined && data.csl !== null) {
    if (!isObject(data.csl)) {
      bad("csl", "must be the Crossref record as a mapping");
    } else {
      const cslDoi = data.csl.DOI;
      if (isString(doi) && doiKey(isString(cslDoi) ? cslDoi : "") !== doiKey(doi)) {
        bad("csl.DOI", `${JSON.stringify(cslDoi)} is not this paper's DOI ${doi}`);
      }
      if (isString(data.csl.abstract) && data.csl.abstract.includes("<")) {
        bad("csl.abstract", `contains "<"`);
      }
    }
  }

  // ---- update notice and accessions
  const noticeProblem = updateNoticeProblem(data.updateNotice);
  if (noticeProblem) bad("updateNotice", noticeProblem);

  if (
    data.accessions !== undefined &&
    data.accessions !== null &&
    !Array.isArray(data.accessions)
  ) {
    bad("accessions", "must be a list of { kind, id }");
  }
  const declared = Array.isArray(data.accessions) ? data.accessions : [];
  declared.forEach((entry, i) => {
    if (!isObject(entry) || !isFilled(entry.kind) || !isFilled(entry.id)) {
      bad(`accessions[${i}]`, "needs a kind and an id");
      return;
    }
    try {
      const url = accessionUrl({ kind: String(entry.kind), id: String(entry.id) });
      if (!url.startsWith("https://www.ncbi.nlm.nih.gov/") || !url.endsWith(String(entry.id))) {
        bad(`accessions[${i}]`, `builds ${url}, which is not an NCBI URL ending in its own id`);
      }
    } catch (error) {
      bad(`accessions[${i}].kind`, error instanceof Error ? error.message : String(error));
    }
  });
  // Both directions: the statement in the paper, not a bare regex, decides what this paper deposited.
  if (access === "self-hosted" && fullText !== null) {
    const flat = (/** @type {Array<{ kind?: unknown, id?: unknown }>} */ list) =>
      list
        .map((a) => `${a.kind}:${a.id}`)
        .sort()
        .join(",");
    const found = accessionsInText([fullText]);
    if (flat(found) !== flat(declared.filter(isObject))) {
      bad(
        "accessions",
        `the data-availability statement in the PDF names [${flat(found)}] but the file lists [${flat(declared.filter(isObject))}]. ` +
          `The text decides; a bare accession regex returns the comparison organisms' deposits, so only the statement counts`,
      );
    }
  } else if (declared.length > 0) {
    bad(
      "accessions",
      "an accession is read from the paper's own data-availability statement, which only a hosted PDF's text carries",
    );
  }

  return errors;
}

/**
 * The corpus-level checks the per-file rules cannot see: duplicates across files. CI calls this over
 * every file; the Worker's save passes `others` to the per-file rule instead.
 *
 * @param {Array<{ file: string, slug: string, id: unknown, doi: unknown }>} files
 * @returns {string[]}
 */
export function validateCorpus(files) {
  /** @type {string[]} */
  const errors = [];
  /** @param {string} label @param {(f: typeof files[number]) => string | null} key */
  const unique = (label, key) => {
    /** @type {Map<string, string>} */
    const seen = new Map();
    for (const f of files) {
      const k = key(f);
      if (!k) continue;
      const first = seen.get(k);
      if (first) errors.push(`${f.file}: ${label} "${k}" is also ${first}'s`);
      else seen.set(k, f.file);
    }
  };
  unique("id", (f) => (isString(f.id) ? f.id : null));
  unique("DOI (case-folded)", (f) => (isString(f.doi) ? doiKey(f.doi) : null));
  unique("page slug", (f) => f.slug);
  if (files.length === 0)
    errors.push("no publication files: the corpus is empty, which would publish an empty page");
  return errors;
}

app/lib/transition-abort.mjs.source:
// A cross-document view transition (motion-print.css, type `site`) the browser abandons rejects its promises with
// `InvalidStateError: Transition was aborted because of invalid state`: the page was reloaded, went hidden or was
// navigated again while the transition was still running. Nothing in the page caused it and nothing in the page can
// handle it, since the promise belongs to the browser's own navigation. It is the one error the page lets go: every
// other rejection, including any other InvalidStateError, is still reported.

/**
 * Whether a rejection is the browser abandoning a view transition.
 *
 * @param {unknown} reason
 */
export function isAbandonedTransition(reason) {
  return (
    reason instanceof DOMException &&
    reason.name === "InvalidStateError" &&
    reason.message.startsWith("Transition was aborted")
  );
}

app/kb/admin.mjs.source:
// The admin's Knowledge Base page (docs/KNOWLEDGE-BASE.md, step 2), the part that needs no runtime: its tabs and their
// counts, the search over a base's entries, and the Needs info list, every recorded gap of every entry and registry item
// on one screen. Pure, so node:test holds it; the route passes in the rows it read from D1. Read-only: nothing here writes.

import { foldText } from "../lib/cv/view.mjs";
import { BASES } from "./bases.mjs";
import { labelGaps } from "./gap-labels.mjs";
import { hasItemPage, itemPath, kindPath } from "./registry/catalog.mjs";
import { isGap } from "./registry/compile.mjs";
import { KINDS } from "./registry/kinds.mjs";

export const KB_ADMIN_PATH = "/admin/kb";

/** Where an entry's file is edited (step 3). @param {string} slug */
export const entryEditHref = (slug) => `${KB_ADMIN_PATH}/entry/${slug}`;

/** Where a registry item's file is edited (step 3). @param {string} kind @param {string} id */
const itemEditHref = (kind, id) => `${KB_ADMIN_PATH}/item/${kind}/${id}`;

/** The tab that lists every gap, beside one tab per base. */
export const NEEDS_INFO = "needs-info";

/**
 * @typedef {{
 *   slug: string,
 *   path: string,
 *   profile: string,
 *   title: string,
 *   description: string,
 *   draft: boolean,
 *   version: string | null,
 *   updated: string | null,
 *   gaps: Array<{ field: string, reason: string, where?: string[], section?: string }>,
 * }} KbEntry
 *
 * @typedef {{ kind: string, id: string, name: string, status: string, fields: Record<string, unknown> }} KbItem
 *
 * @typedef {{ what: string, kindLabel: string, href: string, editHref: string, field: string, label: string, reason: string }} KbGap
 */

/** The tab a `?tab=` value names, else the first base. @param {string | null} value */
export function resolveTab(value) {
  if (value === NEEDS_INFO || BASES.some((base) => base.id === value))
    return /** @type {string} */ (value);
  return /** @type {string} */ (BASES[0]?.id);
}

/** A tab's address, keeping the search only where it still applies (a base's list). @param {string} tab @param {string} [q] */
export function tabHref(tab, q = "") {
  const params = new URLSearchParams({ tab });
  if (q && tab !== NEEDS_INFO) params.set("q", q);
  return `${KB_ADMIN_PATH}?${params}`;
}

/**
 * Every tab with its count, read from the same rows the lists are drawn from: one per base, then Needs info.
 *
 * @param {KbEntry[]} entries
 * @param {KbGap[]} gaps
 */
export function kbTabs(entries, gaps) {
  return [
    ...BASES.map((base) => ({
      id: base.id,
      label: base.name,
      count: entries.filter((e) => e.profile === base.profile).length,
    })),
    { id: NEEDS_INFO, label: "Needs info", count: gaps.length },
  ];
}

/**
 * A base's entries, narrowed by a search over the title, description and slug (case and accents folded), in title order.
 *
 * @param {KbEntry[]} entries
 * @param {string} tab
 * @param {string} [q]
 */
export function baseEntries(entries, tab, q = "") {
  const base = BASES.find((b) => b.id === tab);
  if (!base) return [];
  const needle = foldText(q);
  return entries
    .filter((e) => e.profile === base.profile)
    .filter(
      (e) => needle === "" || foldText(`${e.title} ${e.description} ${e.slug}`).includes(needle),
    )
    .sort((a, b) => foldText(a.title).localeCompare(foldText(b.title), "en", { numeric: true }));
}

/** Where an item is read: its own page, or its kind's table where the kind has no item pages. @param {KbItem} item */
function itemHref(item) {
  return hasItemPage(item.kind) ? itemPath(item.kind, item.id) : kindPath(item.kind);
}

/**
 * Every recorded gap (`MISSING: <why>`), entries first in title order, then registry items in the registry's order, each
 * with the field and the reason as written.
 *
 * @param {KbEntry[]} entries
 * @param {KbItem[]} items
 * @returns {KbGap[]}
 */
export function needsInfo(entries, items) {
  const profileName = Object.fromEntries(BASES.map((base) => [base.profile, base.singular]));
  const fromEntries = [...entries]
    .sort((a, b) => foldText(a.title).localeCompare(foldText(b.title), "en", { numeric: true }))
    .flatMap((e) =>
      labelGaps(e.gaps, e.profile).map((gap) => ({
        what: e.title,
        kindLabel: profileName[e.profile] ?? e.profile,
        href: e.path,
        editHref: `${entryEditHref(e.slug)}#${gap.anchor}`,
        field: gap.field,
        label: gap.label,
        reason: gap.reason,
      })),
    );
  const fromItems = items.flatMap((item) =>
    labelGaps(
      Object.entries(item.fields)
        .filter(([, value]) => isGap(value))
        .map(([field, value]) => ({ field, reason: String(value).replace(/^MISSING:\s*/, "") })),
      null,
    ).map((gap) => ({
      what: item.name,
      kindLabel: capitalize(KINDS[item.kind]?.singular ?? item.kind),
      href: itemHref(item),
      editHref: `${itemEditHref(item.kind, item.id)}#${gap.anchor}`,
      field: gap.field,
      label: gap.label,
      reason: gap.reason,
    })),
  );
  return [...fromEntries, ...fromItems];
}

/** @param {string} word */
function capitalize(word) {
  return word.charAt(0).toUpperCase() + word.slice(1);
}

app/kb/procedures/parse.mjs.source:
// Reads a procedure file (docs/PROCEDURES.md) into its structure: the front matter as written, then the
// body as an intro and sections, each section a run of prose blocks and step lists. Nothing here renders
// or judges; validate.mjs judges and render.mjs renders, so the check and the save tool read one parse.

import { slug as githubSlug } from "github-slugger";
import matter from "gray-matter";

import { yamlPlain } from "../../lib/yaml-plain.mjs";

import { readConditions, segmentText, tokenize } from "./marks.mjs";

export const PROCEDURES_DIR = "content/procedures";

/** The repository path of a procedure's file. */
export function procedurePath(/** @type {string} */ slug) {
  return `${PROCEDURES_DIR}/${slug}.md`;
}

/**
 * The heading id rehype-slug gives the same words, by the same library, so an anchor the old pages
 * published keeps working. A repeated heading's -1, -2 suffix is render.mjs's, which slugs the page in
 * one pass as rehype-slug does.
 *
 * @param {string} text
 */
export function headingId(text) {
  return githubSlug(text);
}

const FLAG_KEYS = /** @type {const} */ ({
  CRITICAL: "critical",
  "PAUSE POINT": "pause",
  WHY: "why",
  TROUBLESHOOTING: "troubleshooting",
  EXPECT: "expect",
  SPIN: "spin",
  CALC: "calc",
  CHALLENGE: "challenge",
  SOLUTION: "solution",
});

/** The platforms a fenced block may name (docs/PROCEDURES.md, S4): a how-to's commands where they differ by system. */
export const PLATFORMS = /** @type {const} */ ({
  linux: "Linux",
  macos: "macOS",
  windows: "Windows",
});

/**
 * @typedef {{ critical: string[], pause: string[], why: string[], troubleshooting: string[], expect: string[], spin: string[], calc: string[], challenge: string[], solution: string[] }} Flags
 * @typedef {{ lang: string, code: string, output: string | null, platform: string | null }} Command
 * @typedef {{
 *   number: number,
 *   line: number,
 *   source: string,
 *   segments: import("./marks.mjs").Segment[],
 *   flags: Flags,
 *   commands: Command[],
 *   photos: Array<{ alt: string, src: string }>,
 * }} Step
 * @typedef {{ type: "prose", markdown: string } | { type: "steps", steps: Step[] }} Block
 * @typedef {{ title: string, id: string, custom: boolean, line: number, blocks: Block[] }} Section
 */

/**
 * The lines under a step, with its indentation removed, split into the step's own words, its flags,
 * its commands and its photos.
 *
 * @param {string} first the text after "N. "
 * @param {string[]} rest the indented lines under it, dedented
 * @param {number} line
 * @param {number} number
 * @returns {{ step: Step, problems: string[] }}
 */
function readStep(first, rest, line, number) {
  /** @type {string[]} */
  const problems = [];
  /** @type {string[]} */
  const words = [first];
  /** @type {Flags} */
  const flags = {
    critical: [],
    pause: [],
    why: [],
    troubleshooting: [],
    expect: [],
    spin: [],
    calc: [],
    challenge: [],
    solution: [],
  };
  /** @type {Command[]} */
  const commands = [];
  /** @type {Array<{ alt: string, src: string }>} */
  const photos = [];
  /** @type {keyof Flags | null} */
  let openFlag = null;

  for (let i = 0; i < rest.length; i += 1) {
    const text = rest[i] ?? "";
    // "```bash platform=linux": a language, then attributes; platform is the only one the format has.
    const fence = /^```(\S*)((?:\s+[a-z]+=\S+)*)\s*$/.exec(text);
    if (fence) {
      openFlag = null;
      const lang = fence[1] ?? "";
      const attrs = Object.fromEntries(
        [...(fence[2] ?? "").matchAll(/([a-z]+)=(\S+)/g)].map((m) => [m[1], m[2]]),
      );
      for (const key of Object.keys(attrs))
        if (key !== "platform")
          problems.push(
            `line ${line}: step ${number} has a code block with "${key}=", and platform= is the only attribute a block takes`,
          );
      /** @type {string[]} */
      const code = [];
      i += 1;
      while (i < rest.length && !/^```\s*$/.test(rest[i] ?? "")) {
        code.push(rest[i] ?? "");
        i += 1;
      }
      if (i >= rest.length)
        problems.push(`line ${line}: step ${number} has a code block that is never closed`);
      if (lang === "output") {
        const target = commands[commands.length - 1];
        if (!target)
          problems.push(
            `line ${line}: step ${number} has an output block with no command before it`,
          );
        else target.output = code.join("\n");
      } else {
        commands.push({
          lang,
          code: code.join("\n"),
          output: null,
          platform: attrs.platform ?? null,
        });
      }
      continue;
    }
    const flag =
      /^>\s*(CRITICAL|PAUSE POINT|WHY|TROUBLESHOOTING|EXPECT|SPIN|CALC|CHALLENGE|SOLUTION)\s*:\s*(.*)$/.exec(
        text,
      );
    if (flag) {
      openFlag = FLAG_KEYS[/** @type {keyof typeof FLAG_KEYS} */ (flag[1])];
      const body = (flag[2] ?? "").trim();
      // A solution answers the challenge before it (the Carpentries challenge with its nested solution), one each.
      if (openFlag === "solution" && flags.solution.length >= flags.challenge.length) {
        problems.push(
          `line ${line}: step ${number} has a SOLUTION with no CHALLENGE before it to answer`,
        );
      }
      if (openFlag === "troubleshooting" || openFlag === "calc") {
        flags[openFlag].push(...body.split(/[,\s]+/).filter(Boolean));
      } else {
        flags[openFlag].push(body);
      }
      continue;
    }
    const more = /^>\s?(.*)$/.exec(text);
    if (more) {
      if (!openFlag || openFlag === "troubleshooting" || openFlag === "calc") {
        problems.push(
          `line ${line}: step ${number} has a quoted line that follows no flag: "${text.trim()}"`,
        );
      } else {
        const list = flags[openFlag];
        list[list.length - 1] = `${list[list.length - 1] ?? ""}\n${more[1] ?? ""}`.replace(
          /^\n/,
          "",
        );
      }
      continue;
    }
    openFlag = null;
    const photo = /^!\[([^\]]*)\]\(([^)\s]+)\)\s*$/.exec(text.trim());
    if (photo) {
      photos.push({ alt: photo[1] ?? "", src: photo[2] ?? "" });
      continue;
    }
    if (text.trim()) words.push(text.trim());
  }

  const source = words.join(" ");
  return {
    step: {
      number,
      line,
      source,
      segments: tokenize(source),
      flags: {
        ...flags,
        critical: flags.critical.map((s) => s.trim()),
        pause: flags.pause.map((s) => s.trim()),
        why: flags.why.map((s) => s.trim()),
        expect: flags.expect.map((s) => s.trim()),
        spin: flags.spin.map((s) => s.trim()),
        challenge: flags.challenge.map((s) => s.trim()),
        solution: flags.solution.map((s) => s.trim()),
      },
      commands,
      photos,
    },
    problems,
  };
}

/**
 * A section's lines as blocks: numbered items become steps; everything else at the margin is prose.
 *
 * @param {string[]} lines
 * @param {number} firstLine the file line of lines[0]
 * @returns {{ blocks: Block[], problems: string[] }}
 */
function readBlocks(lines, firstLine) {
  /** @type {Block[]} */
  const blocks = [];
  /** @type {string[]} */
  const problems = [];
  /** @type {string[]} */
  let prose = [];
  /** @type {Step[] | null} */
  let steps = null;
  let inFence = false;

  const flushProse = () => {
    const markdown = prose.join("\n").trim();
    if (markdown) blocks.push({ type: "prose", markdown });
    prose = [];
  };

  for (let i = 0; i < lines.length; i += 1) {
    const text = lines[i] ?? "";
    if (text.startsWith("```")) inFence = !inFence;
    const item = inFence ? null : /^(\d+)\.\s+(.*)$/.exec(text);
    if (!item) {
      if (steps && (text.trim() === "" || /^\s{2,}/.test(text))) {
        // A blank line inside a list is still the list, unless the margin comes next.
        const next = lines.slice(i + 1).find((l) => l.trim() !== "");
        if (text.trim() === "" && (next === undefined || !/^(\s{2,}|\d+\.\s)/.test(next)))
          steps = null;
        continue;
      }
      steps = null;
      prose.push(text);
      continue;
    }
    flushProse();
    const start = i;
    /** @type {string[]} */
    const rest = [];
    while (i + 1 < lines.length) {
      const next = lines[i + 1] ?? "";
      if (/^\s{2,}\S/.test(next)) rest.push(next.replace(/^\s{2,4}/, ""));
      else if (next.trim() === "" && /^\s{2,}\S/.test(lines[i + 2] ?? "")) rest.push("");
      else break;
      i += 1;
    }
    const read = readStep(item[2] ?? "", rest, firstLine + start, Number(item[1]));
    problems.push(...read.problems);
    if (!steps) {
      steps = [];
      blocks.push({ type: "steps", steps });
    }
    steps.push(read.step);
  }
  flushProse();
  return { blocks, problems };
}

/**
 * @param {{ file: string, raw: string }} input
 */
export function parseProcedure({ file, raw }) {
  /** @type {string[]} */
  const problems = [];
  let parsed;
  try {
    parsed = matter(raw);
  } catch (error) {
    return {
      file,
      data: /** @type {Record<string, any>} */ ({}),
      intro: "",
      sections: /** @type {Section[]} */ ([]),
      problems: [
        `the front matter is not valid YAML: ${error instanceof Error ? error.message : String(error)}`,
      ],
    };
  }
  const data = /** @type {Record<string, any>} */ (yamlPlain(parsed.data));
  const headerLines = raw.slice(0, raw.length - parsed.content.length).split("\n").length - 1;
  const lines = parsed.content.split(/\r?\n/);

  /** @type {Section[]} */
  const sections = [];
  /** @type {string[]} */
  const intro = [];
  let current =
    /** @type {{ title: string, id: string, custom: boolean, line: number, lines: string[] } | null} */ (
      null
    );
  const close = () => {
    if (!current) return;
    const { blocks, problems: found } = readBlocks(current.lines, current.line + 1);
    problems.push(...found);
    sections.push({
      title: current.title,
      id: current.id,
      custom: current.custom,
      line: current.line,
      blocks,
    });
  };

  let inFence = false;
  lines.forEach((text, index) => {
    if (text.startsWith("```")) inFence = !inFence;
    const heading = inFence ? null : /^## (.+?)(?:\s+\{#([a-z0-9-]+)\})?\s*$/.exec(text);
    if (heading) {
      close();
      const title = (heading[1] ?? "").trim();
      current = {
        title,
        id: heading[2] ?? headingId(title),
        custom: Boolean(heading[2]),
        line: headerLines + index + 1,
        lines: [],
      };
      return;
    }
    if (current) current.lines.push(text);
    else intro.push(text);
  });
  close();

  // A step list before the first heading would have no section to belong to.
  if (intro.some((line) => /^\d+\.\s/.test(line))) {
    problems.push("the method starts before the first ## heading; put every step under a section");
  }

  return { file, data, intro: intro.join("\n").trim(), sections, problems };
}

/** @typedef {ReturnType<typeof parseProcedure>} ParsedProcedure */

/**
 * Every step in the procedure, in order.
 *
 * @param {ParsedProcedure} parsed
 */
export function allSteps(parsed) {
  return parsed.sections.flatMap((section) =>
    section.blocks.flatMap((block) => (block.type === "steps" ? block.steps : [])),
  );
}

/**
 * The calculators a step's CALC flag names, each with the values the step itself states for its fields:
 * `> CALC: webbed-plate volume=10, titer` is webbed-plate with volume 10, then titer. A `name=value` belongs
 * to the calculator before it; one with none before it is read as a calculator with no id, which validate.mjs refuses.
 *
 * @param {string[]} tokens the flag's words, as readStep split them
 * @returns {Array<{ id: string, values: Record<string, string> }>}
 */
export function readCalcs(tokens) {
  /** @type {Array<{ id: string, values: Record<string, string> }>} */
  const calcs = [];
  for (const token of tokens) {
    const eq = token.indexOf("=");
    if (eq === -1) {
      calcs.push({ id: token, values: {} });
      continue;
    }
    if (calcs.length === 0) calcs.push({ id: "", values: {} });
    /** @type {{ id: string, values: Record<string, string> }} */ (calcs[calcs.length - 1]).values[
      token.slice(0, eq)
    ] = token.slice(eq + 1);
  }
  return calcs;
}

/**
 * A step's words with its marks read out, and the temperatures and spins those words state.
 *
 * @param {Step} step
 */
export function stepConditions(step) {
  return readConditions(step.segments.map((s) => segmentText(s)).join(""));
}

app/kb/procedures/validate.mjs.source:
// Judges a parsed procedure against its profile (docs/PROCEDURES.md). check:protocols and the operator
// API's save_procedure both call validateProcedure, so a file CI refuses is a file the save tool refuses,
// for the same reason in the same words.
//
// A value nobody has yet is written "MISSING: <why>" in place. It passes and is returned as a gap, so
// the check can print it and the read tool can show it. A bare MISSING, or a required field left out,
// is an error: a forgotten field cannot pass as a recorded gap.

import { DOI_PATTERN, VERSION_PATTERN } from "./cite.mjs";
import { allSteps, PLATFORMS, readCalcs, stepConditions } from "./parse.mjs";
import { proofErrors } from "./proof.mjs";
import { COURSES, METHODS, NON_STRAIN_ORGANISMS, PROTOCOL_STATUSES } from "./taxonomy.mjs";
import { TOOLS } from "../../lib/phage-tools.mjs";
import { BASES } from "../bases.mjs";

const PROFILES = /** @type {const} */ (["protocol", "recipe", "computational"]);

/** Where each profile's pages live (its knowledge base's root, app/kb/bases.mjs); the file's name is the last segment. */
const PROFILE_ROOTS = /** @type {Record<(typeof PROFILES)[number], string>} */ (
  Object.fromEntries(BASES.map((base) => [base.profile, base.entryRoot]))
);

const NOT_APPLICABLE = "not applicable";

/** A software how-to's form, per Diátaxis (docs/KNOWLEDGE-BASE.md, S1): a lesson that teaches, or a recipe for a task. */
export const HOWTO_TYPES = /** @type {const} */ ({ tutorial: "Tutorial", "how-to": "How-to" });

/** The sentences a how-to's WHY may run to before its reasoning belongs on an explanation page it links (S1). */
const HOWTO_WHY_SENTENCES = 3;

/** The sentences in some markdown: each run of words ended by ., ! or ? before a capital or the end, so "e.g. this" is one. @param {string} text */
export function sentenceCount(text) {
  return (
    text
      .replace(/`[^`]*`/g, "x")
      .match(/[^.!?]*[A-Za-z0-9][^.!?]*[.!?]+(?=[*_]*(?:\s+[*_]*[A-Z0-9]|\s*$))/g) ?? []
  ).length;
}

/** Units are a closed list. A unit outside it fails until it is added here on purpose. */
const PROTOCOL_UNITS = [
  "µl",
  "µL",
  "ml",
  "mL",
  "l",
  "L",
  "M",
  "mM",
  "µM",
  "nM",
  "mg/ml",
  "µg/ml",
  "ng/µl",
  "%",
  "U",
  "g",
  "mg",
  "µg",
  "ng",
  "volume",
  "volumes",
  "tube",
  "tubes",
  "reaction",
  "reactions",
  "plate",
  "plates",
  "x",
];
const TIME_UNITS = [
  "second",
  "seconds",
  "sec",
  "s",
  "minute",
  "minutes",
  "min",
  "hour",
  "hours",
  "h",
  "day",
  "days",
];

/** A recorded gap: the marker and the reason, never the marker alone. */
const GAP = /^MISSING:\s*(\S.*)$/s;

/** The levels a protocol's `biosafety_level` may name; each is Dustin's to set. */
export const BIOSAFETY_LEVELS = ["BSL-1", "BSL-2"];

/** Words kept off a protocol's `biosafety` note: the agent only. The separate `biosafety_level` field holds the level. */
const BIOSAFETY_BANNED = /\b(BSL|biosafety level|IBC|NIH)\b/i;

/** A primer's id in the lab registry (app/kb/registry/compile.mjs ID_PATTERN): a protocol names primers by it and stores no sequence. */
const PRIMER_ID = /^[a-z0-9][a-z0-9-]{0,62}$/;

const SEO_TITLE_MAX = 60;
const DESCRIPTION_MAX = 155;

/**
 * @param {unknown} value
 */
function isGap(value) {
  return typeof value === "string" && GAP.test(value);
}

/**
 * @param {Record<string, unknown>} item
 * @param {number} index
 */
function label(item, index) {
  for (const key of ["id", "name", "set", "citation", "for"]) {
    if (typeof item[key] === "string" && item[key]) return /** @type {string} */ (item[key]);
  }
  return String(index);
}

/** What an item in a list is called in words: its name, stage or set, else its id. @param {Record<string, unknown>} item */
function itemName(item) {
  for (const key of ["name", "stage", "set", "id", "citation", "for"]) {
    if (typeof item[key] === "string" && item[key]) return /** @type {string} */ (item[key]);
  }
  return null;
}

/**
 * Every recorded gap under `value`, by path, with `where`: the same place in words, below the top-level field, so the
 * admin can say "TES buffer: storage" for solutions[tes-buffer].storage (app/kb/gap-labels.mjs). An unnamed item is its
 * place in its list ("step 2"), left out when it is the list's only item.
 *
 * @param {unknown} value
 * @param {string} path
 * @param {Array<{ field: string, reason: string, where?: string[] }>} gaps
 * @param {string[]} errors
 * @param {string[]} [where]
 * @param {string} [key] the key the value sits under
 */
function collectGaps(value, path, gaps, errors, where = [], key = "") {
  if (typeof value === "string") {
    const m = GAP.exec(value);
    if (m)
      gaps.push({
        field: path,
        reason: (m[1] ?? "").trim(),
        ...(where.length > 0 ? { where } : {}),
      });
    else if (/^MISSING\b/.test(value))
      errors.push(`${path} is "${value}": write MISSING: and the reason it is missing`);
  } else if (Array.isArray(value)) {
    value.forEach((item, i) => {
      const object =
        item && typeof item === "object" ? /** @type {Record<string, unknown>} */ (item) : null;
      const name = object ? itemName(object) : null;
      const words = name
        ? [...where, name]
        : value.length > 1
          ? [...where, `${key.replace(/s$/, "")} ${i + 1}`]
          : where;
      collectGaps(item, `${path}[${object ? label(object, i) : i}]`, gaps, errors, words, key);
    });
  } else if (value && typeof value === "object") {
    for (const [k, v] of Object.entries(value)) {
      // A list or a group under a key is named by its items; a value is named by its key.
      const leaf = path && !(v && typeof v === "object");
      collectGaps(
        v,
        path ? `${path}.${k}` : k,
        gaps,
        errors,
        leaf ? [...where, k.replace(/_c$/, " (°C)").replaceAll("_", " ")] : where,
        k,
      );
    }
  }
}

/**
 * "250 µl", "0.5 ml", "100% or 80%", "1.25 to 5 µl", "2.5 volumes".
 *
 * @param {string[]} units
 */
function quantityPattern(units) {
  const number = String.raw`\d[\d,]*(?:\.\d+)?`;
  const unit = units.map((u) => u.replace(/[.*+?^${}()|[\]\\/]/g, "\\$&")).join("|");
  return new RegExp(`^${number}(?: ?(?:${unit}))?(?: (?:to|or) ${number})? ?(?:${unit})$`);
}

const PROTOCOL_QUANTITY = quantityPattern(PROTOCOL_UNITS);

/**
 * @param {unknown} value
 */
function nonEmptyString(value) {
  return typeof value === "string" && value.trim().length > 0;
}

/**
 * The version history, newest first: each version with its date, what changed and, once Zenodo has minted
 * one, its DOI. The first entry is the version the page is at, so the version is stored once in `version`
 * and the history cannot disagree with it.
 *
 * @param {Record<string, any>} d
 * @param {string[]} errors
 */
function validateHistory(d, errors) {
  if (d.history === undefined || isGap(d.history)) return;
  if (!Array.isArray(d.history) || d.history.length === 0) {
    errors.push("history must be a list of versions, newest first");
    return;
  }
  const seen = new Set();
  let newer = "9999-12-31";
  d.history.forEach((/** @type {any} */ h, /** @type {number} */ i) => {
    const at = `history[${h?.version ?? i}]`;
    if (!h || typeof h !== "object") return errors.push(`${at} must be a version`);
    for (const k of Object.keys(h))
      if (!["version", "date", "summary", "doi"].includes(k))
        errors.push(`${at}.${k} is not a history field (version, date, summary, doi)`);
    if (!VERSION_PATTERN.test(String(h.version ?? "")))
      errors.push(`${at} needs a version of letters, digits, dots, hyphens and underscores`);
    if (seen.has(String(h.version))) errors.push(`${at}: the version is listed twice`);
    seen.add(String(h.version));
    if (!/^\d{4}-\d{2}-\d{2}$/.test(String(h.date ?? "")))
      errors.push(`${at}.date is ${JSON.stringify(h.date)}; write the date as YYYY-MM-DD`);
    else if (String(h.date) > newer)
      errors.push(
        `${at}.date ${h.date} is later than the entry above it; the history is newest first`,
      );
    else newer = String(h.date);
    if (!nonEmptyString(h.summary)) errors.push(`${at} needs a summary of what changed`);
    if (h.doi !== undefined && !DOI_PATTERN.test(String(h.doi)))
      errors.push(
        `${at}.doi is ${JSON.stringify(h.doi)}; write the DOI as 10.xxxx/suffix, without the https://doi.org/ address`,
      );
  });
  if (d.version === undefined || d.version === null || isGap(d.version)) {
    errors.push(
      "history needs a version: the first entry is the version the page is at, so set version to it",
    );
  } else if (String(d.history[0]?.version) !== String(d.version)) {
    errors.push(
      `version is ${JSON.stringify(d.version)} but the first history entry is ${JSON.stringify(String(d.history[0]?.version))}; the newest entry is the current version`,
    );
  }
}

/**
 * Checks one parsed procedure.
 *
 * @param {import("./parse.mjs").ParsedProcedure} parsed
 * @param {{ slug: string, primers?: ReadonlySet<string> | null, strains?: ReadonlySet<string> | null, reagents?: ReadonlySet<string> | null, equipment?: ReadonlySet<string> | null }} expect the slug its file name gives, and the ids of the primers and
 *   host strains the lab registry holds (null or absent when the registry is not at hand, which `compileProcedure` refuses for a protocol that lists primers)
 * @returns {{ errors: string[], gaps: Array<{ field: string, reason: string, where?: string[], section?: string }> }}
 */
export function validateProcedure(parsed, expect) {
  /** @type {string[]} */
  const errors = [...parsed.problems];
  /** @type {Array<{ field: string, reason: string, where?: string[], section?: string }>} */
  const gaps = [];
  const d = parsed.data;
  const profile = /** @type {typeof PROFILES[number]} */ (d.profile);

  if (!PROFILES.includes(profile)) {
    errors.push(
      `profile is ${JSON.stringify(d.profile)}; it must be one of ${PROFILES.join(", ")}`,
    );
    return { errors, gaps };
  }

  /** @param {string} field */
  const required = (field) => {
    const value = d[field];
    if (
      value === undefined ||
      value === null ||
      value === "" ||
      (Array.isArray(value) && value.length === 0)
    ) {
      errors.push(
        `${field} is required for a ${profile}; write the value, or "MISSING: <why>" if nobody has it yet`,
      );
      return false;
    }
    return true;
  };

  collectGaps(d, "", gaps, errors);

  // Identity.
  const root = PROFILE_ROOTS[profile];
  if (required("path")) {
    if (typeof d.path !== "string" || d.path !== `${root}${expect.slug}`) {
      errors.push(
        `path is ${JSON.stringify(d.path)}; a ${profile} named ${expect.slug}.md lives at ${root}${expect.slug}`,
      );
    }
  }
  for (const field of ["title", "seo_title", "description"]) {
    if (required(field) && !nonEmptyString(d[field])) errors.push(`${field} must be text`);
  }
  if (typeof d.seo_title === "string" && d.seo_title.length > SEO_TITLE_MAX) {
    errors.push(
      `seo_title is ${d.seo_title.length} characters; Google clips near ${SEO_TITLE_MAX}`,
    );
  }
  if (typeof d.description === "string" && d.description.length > DESCRIPTION_MAX) {
    errors.push(
      `description is ${d.description.length} characters; Google clips near ${DESCRIPTION_MAX}`,
    );
  }
  if (d.draft !== undefined && typeof d.draft !== "boolean")
    errors.push("draft must be true or false");
  // A variant made with the editor's Duplicate names the procedure it was copied from, and the version it was copied at.
  if (d.forked_from !== undefined) {
    const f = d.forked_from;
    if (
      !f ||
      typeof f !== "object" ||
      Array.isArray(f) ||
      !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(String(f.slug ?? ""))
    ) {
      errors.push(
        "forked_from is { slug, version }: the file name of the procedure this one was copied from, and its version if it had one",
      );
    } else {
      for (const key of Object.keys(f))
        if (!["slug", "version"].includes(key))
          errors.push(`forked_from.${key} is not a forked_from field (slug, version)`);
      if (f.slug === expect.slug) errors.push("forked_from names this procedure itself");
    }
  }

  // What the library filters by. method, organism and course are ids from the closed lists in taxonomy.mjs; target
  // is the gene, region or sample, in words. Every procedure is some method, so method is required.
  // An organism is a non-strain organism or a strain of the lab registry (docs/REGISTRY.md), read from it as the host strains are.
  const organisms = expect.strains
    ? [...Object.keys(NON_STRAIN_ORGANISMS), ...expect.strains]
    : null;
  for (const [field, vocabulary] of /** @type {const} */ ([
    ["method", METHODS],
    ["organism", null],
    ["course", COURSES],
  ])) {
    if (field === "method") required(field);
    const value = d[field];
    if (value === undefined || isGap(value)) continue;
    const allowed = vocabulary ? Object.keys(vocabulary) : organisms;
    // With no registry at hand an organism cannot be judged, and compileProcedure refuses a file that names one.
    if (!allowed) continue;
    if (!Array.isArray(value))
      errors.push(`${field} must be a list of ids from: ${allowed.join(", ")}`);
    else {
      for (const id of value) {
        if (allowed.includes(id)) continue;
        errors.push(
          vocabulary
            ? `${field} "${id}" is not one of: ${allowed.join(", ")} (taxonomy.mjs)`
            : `organism "${id}" is neither one of: ${Object.keys(NON_STRAIN_ORGANISMS).join(", ")} (taxonomy.mjs) nor a strain in the lab registry (there is no content/registry/strain/${id}.md)`,
        );
      }
      if (new Set(value).size !== value.length) errors.push(`${field} names one id twice`);
    }
  }
  if (d.target !== undefined && !isGap(d.target)) {
    if (!Array.isArray(d.target) || d.target.some((t) => !nonEmptyString(t)))
      errors.push(
        "target must be a list of the genes, regions or samples it works on, each in words",
      );
  }

  // Where it stands in the library's "Start here" list: a position (1, 2, ...), stored, never inferred. A position
  // two procedures share would make the order a guess, so the corpus check refuses it (checkStartHere).
  if (d.start_here !== undefined && !isGap(d.start_here)) {
    if (!Number.isInteger(d.start_here) || d.start_here < 1)
      errors.push("start_here must be a position in the Start here list: 1, 2, 3 ...");
  }

  // Proof of use: the papers that used the method and the phages it produced, as slugs. Stated, never inferred.
  if (!isGap(d.proof_of_use)) errors.push(...proofErrors(d.proof_of_use));

  // The shared core.
  if (required("version") && !isGap(d.version) && !VERSION_PATTERN.test(String(d.version))) {
    errors.push(
      `version is ${JSON.stringify(d.version)}; it sits in a URL, so use letters, digits, dots, hyphens and underscores, such as "2" or "1.1"`,
    );
  }
  validateHistory(d, errors);
  if (required("updated") && !isGap(d.updated) && !/^\d{4}-\d{2}-\d{2}$/.test(String(d.updated))) {
    errors.push(`updated is ${JSON.stringify(d.updated)}; write the date as YYYY-MM-DD`);
  }
  if (required("based_on") && !isGap(d.based_on)) {
    if (!Array.isArray(d.based_on)) errors.push("based_on must be a list of sources");
    else {
      d.based_on.forEach((/** @type {any} */ s, /** @type {number} */ i) => {
        if (!s || typeof s !== "object" || !nonEmptyString(s.citation))
          errors.push(`based_on[${i}] needs a citation`);
        else if (!nonEmptyString(s.for))
          errors.push(`based_on[${s.citation}] needs a "for": what it is the source of`);
      });
    }
  }
  if (required("references") && !isGap(d.references)) {
    if (!Array.isArray(d.references) || d.references.some((r) => !nonEmptyString(r))) {
      errors.push("references must be a list of markdown lines");
    }
  }
  for (const field of ["expected_results", "limitations"]) {
    if (required(field) && !nonEmptyString(d[field])) errors.push(`${field} must be markdown text`);
  }
  if (d.time !== undefined) {
    if (!d.time || typeof d.time !== "object") errors.push("time must hold total and hands_on");
    else
      for (const k of Object.keys(d.time))
        if (!["total", "hands_on"].includes(k)) errors.push(`time.${k} is not a time field`);
  }

  // Materials and equipment.
  /** @type {Map<string, any>} */
  const materials = new Map();
  if (profile !== "recipe" || d.materials !== undefined) {
    if (required("materials")) {
      if (!Array.isArray(d.materials)) errors.push("materials must be a list");
      else {
        d.materials.forEach((/** @type {any} */ m, /** @type {number} */ i) => {
          if (!m || typeof m !== "object" || !nonEmptyString(m.name)) {
            errors.push(`materials[${i}] needs a name`);
            return;
          }
          const key = m.name.toLowerCase();
          if (materials.has(key)) errors.push(`materials lists "${m.name}" twice`);
          materials.set(key, m);
        });
      }
    }
  }
  if (d.equipment !== undefined && !Array.isArray(d.equipment))
    errors.push("equipment must be a list");
  // An item that is lab-registry equipment names it with `equipment: <id>` (docs/REGISTRY.md): the protocol keeps its own phrase for
  // it (the setting is the protocol's), and who makes it is stored there once.
  if (Array.isArray(d.equipment)) {
    for (const e of d.equipment) {
      if (typeof e !== "object" || e === null || e.equipment === undefined) continue;
      const at = `equipment[${String(e.name)}]`;
      if (typeof e.equipment !== "string" || !PRIMER_ID.test(e.equipment)) {
        errors.push(
          `${at}.equipment is the id of an equipment item in the lab registry (content/registry/equipment/), such as water-bath`,
        );
      } else if (expect.equipment && !expect.equipment.has(e.equipment)) {
        errors.push(
          `${at}.equipment names no equipment in the lab registry (there is no content/registry/equipment/${e.equipment}.md)`,
        );
      }
    }
  }
  const equipmentNames = new Set(
    (Array.isArray(d.equipment) ? d.equipment : []).map((/** @type {any} */ e) =>
      String(typeof e === "string" ? e : (e?.name ?? "")).toLowerCase(),
    ),
  );

  // Troubleshooting.
  const troubleIds = new Set();
  if (d.troubleshooting !== undefined) {
    if (!Array.isArray(d.troubleshooting)) errors.push("troubleshooting must be a list of rows");
    else {
      d.troubleshooting.forEach((/** @type {any} */ row, /** @type {number} */ i) => {
        const at = `troubleshooting[${row?.id ?? i}]`;
        if (!row || typeof row !== "object") return errors.push(`${at} must be a row`);
        if (!/^[a-z0-9-]+$/.test(String(row.id ?? "")))
          errors.push(`${at} needs an id in lowercase-with-hyphens`);
        if (troubleIds.has(row.id)) errors.push(`${at}: the id is used twice`);
        troubleIds.add(row.id);
        for (const col of ["step", "problem", "reason", "solution"]) {
          if (!nonEmptyString(row[col]))
            errors.push(
              `${at} needs ${col}: the table's columns are step, problem, possible reason, solution`,
            );
        }
        for (const k of Object.keys(row)) {
          if (!["id", "step", "problem", "reason", "solution"].includes(k))
            errors.push(`${at}.${k} is not a column`);
        }
      });
    }
  }

  // The method.
  const steps = allSteps(parsed);
  if (steps.length === 0)
    errors.push("the procedure has no steps: a method section holds a numbered list");
  let previous = 0;
  for (const section of parsed.sections) {
    for (const block of section.blocks) {
      if (block.type !== "steps") continue;
      const first = block.steps[0];
      if (first && first.number !== 1 && first.number !== previous + 1) {
        errors.push(
          `line ${first.line}: step ${first.number} neither restarts at 1 nor follows step ${previous}`,
        );
      }
      block.steps.forEach((step, i) => {
        if (i > 0 && step.number !== (block.steps[i - 1]?.number ?? 0) + 1) {
          errors.push(
            `line ${step.line}: step ${step.number} follows step ${block.steps[i - 1]?.number}`,
          );
        }
      });
      previous = block.steps[block.steps.length - 1]?.number ?? previous;
    }
  }

  // A step's section, so a gap in it can say where it is (app/kb/gap-labels.mjs).
  const sectionOf = new Map(
    parsed.sections.flatMap((section) =>
      section.blocks.flatMap((block) =>
        block.type === "steps" ? block.steps.map((s) => [s, section.title]) : [],
      ),
    ),
  );
  for (const step of steps) {
    const at = `line ${step.line}, step ${step.number}`;
    if (!step.source.trim()) errors.push(`${at} has no words`);
    for (const reason of step.flags.critical)
      if (!reason) errors.push(`${at}: CRITICAL needs its reason`);
    for (const kind of /** @type {const} */ (["pause", "why", "expect", "challenge", "solution"])) {
      for (const text of step.flags[kind])
        if (!text) errors.push(`${at}: an empty ${kind.toUpperCase()} flag`);
    }
    for (const id of step.flags.troubleshooting) {
      if (!troubleIds.has(id))
        errors.push(
          `${at}: TROUBLESHOOTING names "${id}", which is not a row id in troubleshooting`,
        );
    }
    if (step.flags.calc.length > 0 && profile !== "protocol")
      errors.push(`${at}: CALC belongs to the protocol profile`);
    const calcs = readCalcs(step.flags.calc);
    if (new Set(calcs.map((c) => c.id)).size !== calcs.length)
      errors.push(`${at}: CALC names a calculator twice`);
    for (const { id, values } of calcs) {
      const tool = Object.hasOwn(TOOLS, id) ? TOOLS[id] : undefined;
      if (!tool) {
        errors.push(
          id
            ? `${at}: CALC names "${id}", which is not a calculator (${Object.keys(TOOLS).join(", ")})`
            : `${at}: CALC gives a value before it names a calculator`,
        );
        continue;
      }
      for (const [name, value] of Object.entries(values)) {
        if (!tool.fields.some((f) => f.name === name))
          errors.push(
            `${at}: CALC ${id} has no field "${name}" (${tool.fields.map((f) => f.name).join(", ")})`,
          );
        // Every value is the step's own: a number that is not in the step's words is not from the record.
        else if (!step.source.includes(value))
          errors.push(
            `${at}: CALC ${id} ${name}=${value}, but the step does not state ${value}; a value is filled in only from the step's own words`,
          );
      }
    }
    for (const seg of step.segments) {
      if (seg.type === "material") {
        const declared = materials.get(seg.name.toLowerCase());
        if (!declared && profile !== "recipe") {
          errors.push(
            `${at}: @${seg.name} is not in materials; declare it there with its stock and amount`,
          );
        }
        if (
          seg.quantity &&
          profile === "protocol" &&
          !PROTOCOL_QUANTITY.test(`${seg.quantity.amount} ${seg.quantity.unit}`.trim())
        ) {
          errors.push(
            `${at}: @${seg.name}'s amount "${seg.quantity.raw}" is not a number and a unit from the closed list (${PROTOCOL_UNITS.join(", ")})`,
          );
        }
      }
      if (
        seg.type === "equipment" &&
        profile !== "recipe" &&
        !equipmentNames.has(seg.name.toLowerCase())
      ) {
        errors.push(`${at}: #${seg.name} is not in equipment`);
      }
      if (seg.type === "timer") {
        if (!seg.quantity || seg.quantity.min === null || !TIME_UNITS.includes(seg.quantity.unit)) {
          errors.push(
            `${at}: the timer ~{${seg.quantity?.raw ?? ""}} needs a number and a unit of time (${TIME_UNITS.join(", ")})`,
          );
        }
      }
    }
    if (profile === "protocol") {
      const { spins } = stepConditions(step);
      const words = step.segments.map((s) => (s.type === "text" ? s.value : "")).join("");
      const spinsHere = /\bspin\b|\bspun\b|\bcentrifuge\b/i.test(
        words.replace(/pulse[- ]spin/gi, ""),
      );
      const hasG = spins.some((s) => s.unit === "x g");
      if (spinsHere && !hasG && step.flags.spin.length === 0) {
        errors.push(
          `${at} spins with no g-force: add "> SPIN: <n> x g", or "> SPIN: MISSING: <why>" (a speed in rpm needs the rotor)`,
        );
      }
      for (const spin of step.flags.spin) {
        if (isGap(spin))
          gaps.push({
            field: `step ${step.number} (line ${step.line}).spin`,
            reason: spin.replace(/^MISSING:\s*/, ""),
            section: sectionOf.get(step) ?? "",
          });
        else if (!/x g\b/.test(spin)) errors.push(`${at}: SPIN "${spin}" is not in x g`);
      }
    } else if (step.flags.spin.length > 0) {
      errors.push(`${at}: SPIN belongs to the protocol profile`);
    }
    // A tutorial teaches with challenges; a how-to links its reasoning out (S1, S5).
    if (
      step.flags.challenge.length > 0 &&
      !(profile === "computational" && d.type === "tutorial")
    ) {
      errors.push(
        `${at}: CHALLENGE belongs to a tutorial (a computational procedure with type: tutorial)`,
      );
    }
    if (step.flags.solution.length < step.flags.challenge.length)
      errors.push(`${at}: each CHALLENGE needs its SOLUTION after it`);
    if (profile === "computational" && d.type === "how-to") {
      for (const why of step.flags.why) {
        const n = sentenceCount(why);
        if (n > HOWTO_WHY_SENTENCES) {
          errors.push(
            `${at}: WHY runs to ${n} sentences; a how-to keeps a reason to ${HOWTO_WHY_SENTENCES} at most, so put the rest on a page and link it under explanation`,
          );
        }
      }
    }
    /** @type {Set<string>} */
    const platforms = new Set();
    for (const cmd of step.commands) {
      if (cmd.platform === null) continue;
      if (profile !== "computational")
        errors.push(`${at}: platform= belongs to the computational profile`);
      else if (!Object.hasOwn(PLATFORMS, cmd.platform))
        errors.push(
          `${at}: platform=${cmd.platform} is not a platform (${Object.keys(PLATFORMS).join(", ")})`,
        );
      else if (platforms.has(cmd.platform))
        errors.push(
          `${at}: two blocks for platform=${cmd.platform}; a step gives each platform one block`,
        );
      platforms.add(cmd.platform);
    }
    if (platforms.size === 1)
      errors.push(
        `${at}: a block names one platform alone; give each platform its block, or name none`,
      );
    if (profile === "computational") {
      for (const cmd of step.commands) {
        if (cmd.output === null && step.flags.expect.length === 0) {
          errors.push(
            `${at}: a command needs its expected output: a \`\`\`output block after it, or an EXPECT flag`,
          );
        }
      }
    } else if (step.commands.length > 0 && profile === "recipe") {
      errors.push(`${at}: a recipe step carries no commands`);
    }
    if (step.photos.length > 0 && profile !== "recipe")
      errors.push(`${at}: step photos belong to the recipe profile`);
    for (const photo of step.photos)
      if (!photo.alt.trim()) errors.push(`${at}: a step photo needs its alt text`);
  }

  // The profiles.
  // A recipe's density, so its volume can be shown as weight: a number the recipe states, never a table's (DECIDE 7).
  for (const m of Array.isArray(d.materials) ? d.materials : []) {
    if (m?.grams_per_cup === undefined) continue;
    const at = `materials[${String(m.name)}].grams_per_cup`;
    if (profile !== "recipe") errors.push(`${at} belongs to the recipe profile`);
    else if (typeof m.grams_per_cup !== "number" || !(m.grams_per_cup > 0))
      errors.push(`${at} is the grams in one US cup of it, a number above 0`);
  }
  if (profile === "protocol")
    protocolRules(
      d,
      errors,
      required,
      materials,
      expect.primers ?? null,
      expect.strains ?? null,
      expect.reagents ?? null,
    );
  if (profile === "recipe") recipeRules(d, errors, required);
  if (profile === "computational") computationalRules(d, errors, required, materials);
  else {
    for (const field of ["type", "questions", "objectives", "key_points", "explanation"]) {
      if (d[field] !== undefined) errors.push(`${field} belongs to the computational profile`);
    }
  }

  return { errors, gaps };
}

/**
 * @param {Record<string, any>} d
 * @param {string[]} errors
 * @param {(field: string) => boolean} required
 * @param {Map<string, any>} materials
 * @param {ReadonlySet<string> | null} primerIds the primers the lab registry holds
 * @param {ReadonlySet<string> | null} strainIds the strains the lab registry holds
 * @param {ReadonlySet<string> | null} reagentIds the reagents the lab registry holds
 */
function protocolRules(d, errors, required, materials, primerIds, strainIds, reagentIds) {
  for (const field of [
    "host_strain",
    "status",
    "last_run",
    "biosafety",
    "biosafety_level",
    "scale",
  ])
    required(field);
  // A host strain is the lab registry's, named by id and never typed (docs/REGISTRY.md): its organism, designation and
  // collection number are stored once, on its record.
  if (d.host_strain !== undefined && d.host_strain !== NOT_APPLICABLE && !isGap(d.host_strain)) {
    if (!Array.isArray(d.host_strain))
      errors.push(
        `host_strain must be a list of { strain: <id> }, "${NOT_APPLICABLE}" or "MISSING: <why>"`,
      );
    else {
      /** @type {Set<string>} */
      const seenStrains = new Set();
      for (const s of d.host_strain) {
        const id = s?.strain;
        const at = `host_strain[${typeof id === "string" ? id : "?"}]`;
        if (typeof id !== "string" || !PRIMER_ID.test(id)) {
          errors.push(
            `${at} is { strain: <id> }: the id of a strain in the lab registry (content/registry/strain/), such as foliorum. A protocol names its host strains and types none`,
          );
        } else if (seenStrains.has(id)) {
          errors.push(`${at} is listed twice`);
        } else {
          seenStrains.add(id);
          if (strainIds && !strainIds.has(id))
            errors.push(
              `${at} names no strain in the lab registry (there is no content/registry/strain/${id}.md)`,
            );
        }
        for (const key of Object.keys(s ?? {})) {
          if (key !== "strain")
            errors.push(
              `${at}.${key} is not a protocol field: a strain's organism and collection number are stored once, in the lab registry`,
            );
        }
      }
    }
  }
  if (
    d.status !== undefined &&
    !isGap(d.status) &&
    !Object.keys(PROTOCOL_STATUSES).includes(d.status)
  ) {
    errors.push(
      `status is ${JSON.stringify(d.status)}; it is one of ${Object.keys(PROTOCOL_STATUSES).join(", ")} (taxonomy.mjs), or "MISSING: <why>"`,
    );
  }
  if (
    d.biosafety_level !== undefined &&
    !isGap(d.biosafety_level) &&
    !BIOSAFETY_LEVELS.includes(d.biosafety_level)
  ) {
    errors.push(
      `biosafety_level is ${JSON.stringify(d.biosafety_level)}; it is one of ${BIOSAFETY_LEVELS.join(", ")}, or "MISSING: <why>" until Dustin sets it`,
    );
  }
  if (d.biosafety && !isGap(d.biosafety) && d.biosafety !== NOT_APPLICABLE) {
    if (typeof d.biosafety !== "object" || !nonEmptyString(d.biosafety.organism)) {
      errors.push(
        'biosafety lists the agent only: { organism, strain, atcc }, or "not applicable"',
      );
    } else {
      for (const k of Object.keys(d.biosafety)) {
        if (!["organism", "strain", "atcc"].includes(k))
          errors.push(`biosafety.${k}: the agent only (organism, strain, ATCC number)`);
      }
    }
  }
  if (BIOSAFETY_BANNED.test(JSON.stringify(d.biosafety ?? ""))) {
    errors.push(
      "biosafety names a biosafety level, an IBC or the NIH Guidelines; it lists the agent only",
    );
  }
  if (d.scale && !isGap(d.scale)) {
    if (
      typeof d.scale !== "object" ||
      !(Number(d.scale.count) > 0) ||
      !nonEmptyString(d.scale.unit)
    ) {
      errors.push("scale needs a count and a unit, such as { count: 5, unit: tube }");
    }
  }
  const solutionIds = new Set();
  if (d.solutions !== undefined) {
    if (!Array.isArray(d.solutions)) errors.push("solutions must be a list");
    else {
      for (const s of d.solutions) {
        const at = `solutions[${s?.id ?? "?"}]`;
        if (!s || !/^[a-z0-9-]+$/.test(String(s.id ?? "")))
          errors.push(`${at} needs an id in lowercase-with-hyphens`);
        solutionIds.add(s?.id);
        if (!nonEmptyString(s?.name)) errors.push(`${at} needs a name`);
        if (!Array.isArray(s?.components) || s.components.length === 0)
          errors.push(`${at} needs its components`);
        for (const field of ["storage", "shelf_life"]) {
          if (!nonEmptyString(s?.[field])) errors.push(`${at} needs ${field}, or "MISSING: <why>"`);
        }
        for (const c of Array.isArray(s?.components) ? s.components : []) {
          if (!nonEmptyString(c?.name)) errors.push(`${at} has a component with no name`);
          for (const q of ["final", "amount"]) {
            if (c?.[q] !== undefined && !isGap(c[q]) && !PROTOCOL_QUANTITY.test(String(c[q]))) {
              errors.push(
                `${at}.${c.name}.${q} is "${c[q]}", not a number and a unit from the closed list`,
              );
            }
          }
        }
      }
    }
  }
  for (const m of materials.values()) {
    const at = `materials[${m.name}]`;
    // A material that is a reagent of the lab registry names it by id (docs/REGISTRY.md): who supplies it and its catalog number
    // are stored there once, and the protocol keeps its own amount, stock and final.
    if (m.reagent !== undefined) {
      if (typeof m.reagent !== "string" || !PRIMER_ID.test(m.reagent)) {
        errors.push(
          `${at}.reagent is the id of a reagent in the lab registry (content/registry/reagent/), such as zinc-chloride`,
        );
      } else if (reagentIds && !reagentIds.has(m.reagent)) {
        errors.push(
          `${at}.reagent names no reagent in the lab registry (there is no content/registry/reagent/${m.reagent}.md)`,
        );
      }
    }
    for (const key of ["amount", "final", "per"]) {
      const q = m[key];
      if (q === undefined || isGap(q)) continue;
      if (key === "per" && typeof q === "string" && !/^\d/.test(q)) continue;
      if (typeof q !== "string" || !PROTOCOL_QUANTITY.test(q)) {
        errors.push(
          `${at}.${key} is "${String(q)}", not a number and a unit from the closed list (${PROTOCOL_UNITS.join(", ")})`,
        );
      }
    }
    if (m.stock !== undefined) {
      const stocks = Array.isArray(m.stock) ? m.stock : [m.stock];
      for (const s of stocks) {
        if (!isGap(s) && !PROTOCOL_QUANTITY.test(String(s)))
          errors.push(`${at}.stock "${s}" is not a number and a unit from the closed list`);
      }
    }
    if (m.solution !== undefined && !solutionIds.has(m.solution))
      errors.push(`${at}.solution names "${m.solution}", which is not in solutions`);
  }
  if (d.primers !== undefined && d.primers !== NOT_APPLICABLE && !isGap(d.primers)) {
    if (!Array.isArray(d.primers)) errors.push(`primers must be a list, or "${NOT_APPLICABLE}"`);
    else {
      /** @type {Set<string>} */
      const seen = new Set();
      for (const p of d.primers) {
        const id = p?.primer;
        const at = `primers[${typeof id === "string" ? id : "?"}]`;
        if (typeof id !== "string" || !PRIMER_ID.test(id)) {
          errors.push(
            `${at} is { primer: <id> }: the id of a primer in the lab registry (content/registry/primer/), such as lco1490. A protocol names its primers and stores no sequence`,
          );
        } else if (seen.has(id)) {
          errors.push(`${at} is listed twice`);
        } else {
          seen.add(id);
          if (primerIds && !primerIds.has(id))
            errors.push(
              `${at} names no primer in the lab registry (there is no content/registry/primer/${id}.md)`,
            );
        }
        for (const key of Object.keys(p ?? {})) {
          if (key !== "primer")
            errors.push(
              `${at}.${key} is not a protocol field: a primer's sequence, direction and set are stored once, in the lab registry`,
            );
        }
      }
    }
  }
  if (d.cycling !== undefined) {
    if (!Array.isArray(d.cycling)) errors.push("cycling must be a list of programs");
    else {
      const walk = (/** @type {any} */ stage, /** @type {string} */ at) => {
        if (Array.isArray(stage?.steps))
          stage.steps.forEach((/** @type {any} */ s, /** @type {number} */ i) =>
            walk(s, `${at}.steps[${i}]`),
          );
        if (
          typeof stage?.temperature_c === "string" &&
          /^\d+ to \d+$/.test(stage.temperature_c) &&
          stage.touchdown_step_c === undefined
        ) {
          errors.push(
            `${at} is a touchdown (${stage.temperature_c} °C) with no touchdown_step_c; write it, or "MISSING: <why>"`,
          );
        }
      };
      d.cycling.forEach((/** @type {any} */ program, /** @type {number} */ i) => {
        const at = `cycling[${program?.set ?? i}]`;
        if (!Array.isArray(program?.program))
          errors.push(`${at} needs its program: a list of stages`);
        else
          program.program.forEach((/** @type {any} */ stage, /** @type {number} */ j) =>
            walk(stage, `${at}.program[${stage?.stage ?? j}]`),
          );
      });
    }
  }
}

/**
 * @param {Record<string, any>} d
 * @param {string[]} errors
 * @param {(field: string) => boolean} required
 */
function recipeRules(d, errors, required) {
  for (const field of ["servings", "cuisine", "category", "prep_time", "cook_time", "image"])
    required(field);
  if (d.servings !== undefined && !isGap(d.servings) && !(Number(d.servings) > 0))
    errors.push("servings must be a number");
  for (const field of ["prep_time", "cook_time"]) {
    if (
      d[field] !== undefined &&
      !isGap(d[field]) &&
      !/^\d+(?:\.\d+)? (minutes?|hours?)$/.test(String(d[field]))
    ) {
      errors.push(`${field} is "${d[field]}"; write it as "20 minutes" or "1.5 hours"`);
    }
  }
  if (
    d.image !== undefined &&
    !isGap(d.image) &&
    (!nonEmptyString(d.image?.src) || !nonEmptyString(d.image?.alt))
  ) {
    errors.push("image needs src and alt");
  }
  if (d.substitutions !== undefined) {
    if (!Array.isArray(d.substitutions)) errors.push("substitutions must be a list");
    else
      for (const s of d.substitutions)
        if (!nonEmptyString(s?.for) || !nonEmptyString(s?.use))
          errors.push("each substitution needs for and use");
  }
  if (d.scale !== undefined) errors.push("a recipe scales by servings, not scale");
}

/**
 * @param {Record<string, any>} d
 * @param {string[]} errors
 * @param {(field: string) => boolean} required
 * @param {Map<string, any>} materials
 */
function computationalRules(d, errors, required, materials) {
  required("environment");
  if (required("type") && !Object.hasOwn(HOWTO_TYPES, d.type)) {
    errors.push(
      `type is ${JSON.stringify(d.type)}; it is one of ${Object.keys(HOWTO_TYPES).join(", ")}`,
    );
  }
  // A tutorial opens as a Carpentries episode does: what it answers, what the reader will be able to do, and how long (S2).
  for (const field of ["questions", "objectives", "key_points"]) {
    if (d[field] === undefined || isGap(d[field])) continue;
    if (!Array.isArray(d[field]) || d[field].some((/** @type {unknown} */ x) => !nonEmptyString(x)))
      errors.push(`${field} must be a list of lines`);
  }
  if (d.type === "tutorial") {
    required("objectives");
    if (!d.time || !nonEmptyString(d.time.total))
      errors.push("a tutorial states its time: time.total, such as 30 minutes");
  }
  if (d.explanation !== undefined && !isGap(d.explanation)) {
    if (!Array.isArray(d.explanation))
      errors.push("explanation must be a list of pages, each with a title and a url");
    else {
      d.explanation.forEach((/** @type {any} */ e, /** @type {number} */ i) => {
        if (!e || typeof e !== "object" || !nonEmptyString(e.title))
          errors.push(`explanation[${i}] needs a title`);
        else if (typeof e.url !== "string" || !/^(\/[^/\s]|https:\/\/\S)/.test(e.url))
          errors.push(
            `explanation[${e.title}].url is a page on this site (/...) or an https address`,
          );
      });
    }
  }
  if (required("prerequisites") && !isGap(d.prerequisites) && !Array.isArray(d.prerequisites)) {
    errors.push("prerequisites must be a list");
  }
  if (d.scale !== undefined || d.servings !== undefined)
    errors.push("a computational procedure does not scale");
  for (const m of materials.values()) {
    if (!["software", "data", "file"].includes(m.kind))
      errors.push(`materials[${m.name}].kind must be software, data or file`);
    if (m.kind === "software" && !nonEmptyString(m.version))
      errors.push(`materials[${m.name}] is software and needs its version`);
  }
}

app/kb/registry/align.mjs.source:
// Placing a primer on a reference, and the product a pair makes there (docs/REGISTRY.md): COMPUTED by the primer code in
// app/lib/primers.mjs (findSites, amplicons), whose tests hold it to hand-worked cases, and never copied from a paper or a
// database. A primer is looked for exactly first, then with one mismatch more at a time up to MAX_MISMATCHES, and the first
// level that finds it is the answer, with its mismatches reported. A primer that binds only with a mismatch is therefore
// shown with the mismatch, never silently absorbed, and a primer that binds nowhere within the limit has no placement.
//
// Coordinates are the accession's own: a slice of a chromosome (`NC_052532.1:76902320-76906237`) is reported on the
// chromosome, so a reader can check a position against the record at NCBI.

import { amplicons, findSites } from "../../lib/primers.mjs";
import { accessionPosition } from "./reference.mjs";
import { REFERENCES } from "./references.generated.mjs";

/** The most mismatches a primer may have against a reference and still be placed. A primer is 16 to 30 bases. */
export const MAX_MISMATCHES = 4;
/** A product longer than this is not a PCR product here; the registry's references are short or the primers sit close. */
const MAX_PRODUCT = 5000;

/**
 * @typedef {import("./reference.mjs").Reference} Reference
 * @typedef {{
 *   strand: "+" | "-",
 *   start: number,
 *   end: number,
 *   mismatches: number,
 *   mismatchPositions: number[],
 * }} Placed
 * A site in the accession's own coordinates; `mismatchPositions` are 1-based from the primer's 5' end.
 *
 * @typedef {{ reference: { id: string, accession: string, description: string }, sites: Placed[], mismatches: number }} Placement
 * @typedef {{
 *   length: number,
 *   start: number,
 *   end: number,
 *   forward: Placed,
 *   reverse: Placed,
 * }} Product
 */

/** The reference an id names, or null. @param {string} id @param {Record<string, Reference>} [references] */
function referenceFor(id, references = /** @type {any} */ (REFERENCES)) {
  const found = references[id];
  return found ? parseReferenceShape(found) : null;
}

/** The generated module's entries are already parsed; this keeps the type and refuses a malformed one. @param {any} entry @returns {Reference} */
function parseReferenceShape(entry) {
  if (typeof entry?.sequence !== "string" || typeof entry?.id !== "string")
    throw new Error("a reference in references.generated.mjs is malformed");
  return entry;
}

/** @param {Reference} reference @param {import("../../lib/primers.mjs").Site} site @returns {Placed} */
function placed(reference, site) {
  return {
    strand: site.strand,
    start: accessionPosition(reference, site.start),
    end: accessionPosition(reference, site.end),
    mismatches: site.mismatches,
    mismatchPositions: site.mismatchPositions,
  };
}

/**
 * Where a primer binds a reference: every site at the fewest mismatches that finds one.
 *
 * @param {string} sequence the primer, 5' to 3', A, C, G and T only
 * @param {string} referenceId
 * @param {Record<string, Reference>} [references]
 * @returns {Placement | null} null when the reference is unknown or the primer binds nowhere within MAX_MISMATCHES
 */
export function placePrimer(sequence, referenceId, references = /** @type {any} */ (REFERENCES)) {
  const reference = referenceFor(referenceId, references);
  if (!reference || !/^[ACGT]+$/.test(sequence)) return null;
  for (let mismatches = 0; mismatches <= MAX_MISMATCHES; mismatches += 1) {
    const sites = findSites(reference.sequence, sequence, { maxMismatches: mismatches }).filter(
      (s) => s.mismatches === mismatches,
    );
    if (sites.length > 0) {
      return {
        reference: {
          id: reference.id,
          accession: reference.accession,
          description: reference.description,
        },
        sites: sites.map((site) => placed(reference, site)),
        mismatches,
      };
    }
  }
  return null;
}

/**
 * The products a forward and a reverse primer make on a reference, each at the fewest mismatches either needs, shortest
 * first. A pair that makes none, or whose primers do not both place, has no product.
 *
 * @param {string} forward
 * @param {string} reverse
 * @param {string} referenceId
 * @param {Record<string, Reference>} [references]
 * @returns {{ reference: Placement["reference"], products: Product[] } | null}
 */
export function pairProducts(
  forward,
  reverse,
  referenceId,
  references = /** @type {any} */ (REFERENCES),
) {
  const reference = referenceFor(referenceId, references);
  const f = placePrimer(forward, referenceId, references);
  const r = placePrimer(reverse, referenceId, references);
  if (!reference || !f || !r) return null;
  const level = Math.max(f.mismatches, r.mismatches);
  const found = amplicons(reference.sequence, forward, reverse, {
    maxMismatches: level,
    maxLength: MAX_PRODUCT,
  })
    // Only the sites each primer was placed at: a product that used a worse site than the best is not the pair's.
    .filter((p) => p.forward.mismatches === f.mismatches && p.reverse.mismatches === r.mismatches)
    .map((p) => ({
      length: p.length,
      start: accessionPosition(reference, p.start),
      end: accessionPosition(reference, p.end),
      forward: placed(reference, p.forward),
      reverse: placed(reference, p.reverse),
    }))
    .sort((a, b) => a.length - b.length || a.start - b.start);
  return found.length === 0 ? null : { reference: f.reference, products: found };
}

/**
 * The products a protocol's primers make, computed, for the primer table of a page, sheet or twin: each set that holds one
 * forward and one reverse primer on one reference gives its pair's products, keyed by the id of both primers. A row with no
 * mate, no reference or no placement has no entry.
 *
 * @param {Array<{ id: string, set: string | null, direction: string | null, sequence: string | null, reference: string | null }>} rows
 * @returns {Map<string, { reference: Placement["reference"], products: Product[] }>}
 */
export function productsForRows(rows) {
  /** @type {Map<string, { reference: Placement["reference"], products: Product[] }>} */
  const out = new Map();
  const sets = new Set(rows.flatMap((row) => (row.set ? [row.set] : [])));
  for (const set of sets) {
    const inSet = rows.filter((row) => row.set === set);
    const forward = inSet.find((row) => row.direction === "forward");
    const reverse = inSet.find((row) => row.direction === "reverse");
    if (
      !forward?.sequence ||
      !reverse?.sequence ||
      !forward.reference ||
      forward.reference !== reverse.reference
    )
      continue;
    const pair = pairProducts(forward.sequence, reverse.sequence, forward.reference);
    if (pair) {
      out.set(forward.id, pair);
      out.set(reverse.id, pair);
    }
  }
  return out;
}

app/kb/registry/reagent.mjs.source:
// The reagent kind of the lab registry (docs/REGISTRY.md): the substances the lab's protocols use up, as distinct from the
// samples they work on (a lysate, soil, an eluate), the primers (their own kind) and the cultures (strains). The reagents are one
// table (the library's Reagents tab) and each has a page of its own, listing the protocols that use it (docs/KNOWLEDGE-BASE.md,
// A1); each protocol's own Reagents table is drawn from these records with that protocol's amount, stock and final.
//
// A record states what the lab's own pages state about one substance: its name, an abbreviation or what it is made of where a
// protocol says so, and where it comes from. A BOUGHT reagent has a supplier and a catalog number (each stated, or
// `MISSING: <why>` where no record in the repository says, listed for Dustin) and a product link where a protocol linked it. A
// reagent PREPARED IN THE LAB says so (`prepared_in_lab: true`) and carries a link to its recipe in place of a supplier and a
// catalog number; the recipe is a procedure with the recipe profile, and where none exists yet the link is MISSING and listed for
// Dustin, because recipes are written by the lab and never invented here.
//
// What the protocols use of it is COMPUTED: a protocol names a reagent on one of its materials by id (`reagent: <id>`), keeps its
// own amount, stock and final, and the table lists the protocols that name it.

const LINE = /^[^\r\n]+$/;

/** @param {unknown} value @param {number} max */
const oneLine = (value, max) =>
  typeof value === "string" && LINE.test(value) && value === value.trim() && value.length <= max
    ? null
    : `is one line of at most ${max} characters`;

/** A field the file does not carry reads as null (compile.mjs). @param {unknown} value */
const absent = (value) => value === undefined || value === null;

/** @param {unknown} value */
const isGap = (value) => typeof value === "string" && value.startsWith("MISSING");

/** @type {import("./kinds.mjs").KindSpec} */
export const REAGENT = {
  singular: "reagent",
  plural: "reagents",
  fields: {
    // What a protocol calls it in one phrase, as the protocols' own words give it: ZnCl2 for zinc chloride.
    abbreviation: { check: (value) => oneLine(value, 40) },
    // What it is made of, where a protocol says: DNase I plus RNase A.
    contents: { check: (value) => oneLine(value, 120) },
    // Bought (a supplier and a catalog number) or prepared in the lab (a recipe): setErrors holds each item to one of the two.
    supplier: { check: (value) => oneLine(value, 80) },
    catalog_number: { check: (value) => oneLine(value, 40) },
    product_url: {
      check: (value) =>
        typeof value === "string" && /^https:\/\/[^\s]+$/.test(value)
          ? null
          : "is an https address",
    },
    prepared_in_lab: {
      check: (value) => (value === true ? null : "is true, or absent for a reagent that is bought"),
    },
    // The recipe of a reagent prepared in the lab: the file key of a procedure with the recipe profile, or MISSING.
    recipe: {
      check: async (value, { host }) =>
        typeof value === "string" &&
        /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(value) &&
        (await host.recipe(value))
          ? null
          : "is the file key of a procedure with the recipe profile (content/procedures/<key>.md, profile: recipe), or MISSING: <why>",
    },
  },
  /**
   * A bought reagent states a supplier and a catalog number (or a gap for each) and no recipe; a reagent prepared in the lab states
   * a recipe (or a gap) and no supplier, catalog number or product link, because it has none.
   */
  setErrors(items) {
    /** @type {string[]} */
    const errors = [];
    for (const { id, fields } of items) {
      if (fields.prepared_in_lab === true) {
        if (absent(fields.recipe))
          errors.push(
            `reagent/${id} is prepared in the lab, so it states its recipe, or MISSING: <why>`,
          );
        for (const field of ["supplier", "catalog_number", "product_url"]) {
          if (!absent(fields[field]))
            errors.push(`reagent/${id} is prepared in the lab, so it has no ${field}`);
        }
      } else {
        for (const field of ["supplier", "catalog_number"]) {
          if (absent(fields[field]))
            errors.push(`reagent/${id} is bought, so it states its ${field}, or MISSING: <why>`);
        }
        if (!absent(fields.recipe) && !isGap(fields.recipe))
          errors.push(`reagent/${id} is not prepared in the lab, so it has no recipe`);
      }
    }
    return errors;
  },
};

/**
 * A reagent as a protocol carries it (`StoredReagent` in app/kb/procedures/render.mjs): the registry's stated facts, none computed,
 * so the protocol's Reagents table, twin and frozen versions say where each came from as it was when the protocol was published.
 *
 * @param {import("./kinds.mjs").RegistryItem} item
 * @returns {import("../procedures/render.mjs").StoredReagent}
 */
export function storedReagent(item) {
  const f = /** @type {Record<string, unknown>} */ (item.fields);
  const text = (/** @type {unknown} */ value) =>
    typeof value === "string" && value !== "" && !value.startsWith("MISSING") ? value : null;
  return {
    id: item.id,
    name: item.name,
    status: item.status,
    preparedInLab: f.prepared_in_lab === true,
    supplier: text(f.supplier),
    catalogNumber: text(f.catalog_number),
    productUrl: text(f.product_url),
    recipe: text(f.recipe),
  };
}

app/lib/content-pages.mjs.source:
/**
 * The Research, Teaching and Software pages: markdown in content/pages/, rendered at build time into
 * content/generated/pages.json like the About page, and served by one route module. This list is the
 * one place their paths are named: app/routes.ts registers a route per entry, the sitemap lists each,
 * and the build refuses a markdown file whose path is not here or an entry with no file.
 *
 * The 2026-09-27 cutover wrote them from the old WordPress site, its knowledge base and the lab's
 * notebooks (cutover.md, "Pages to build before the switch").
 */

import { ogImageKey } from "./content/og-card-text.mjs";
import { dictionaryEntryMarkdown, dictionaryEntryText } from "./dictionary-entries.mjs";
import { longDateUTC } from "./long-date.mjs";
import { splitSections } from "./search/records.mjs";

export const CONTENT_PAGE_PATHS = /** @type {const} */ ([
  "/research",
  "/research/retroviruses",
  "/research/retroviruses/human",
  "/research/retroviruses/avian",
  "/research/bacteriophages",
  "/research/science-education",
  "/research/phages",
  // Not in cutover.md's page list, but its redirect rows land old knowledge-base addresses here.
  "/research/protocols",
  // The protocols themselves are procedures (content/procedures/, docs/PROCEDURES.md), drawn from D1.
  // The phage lab calculators (job_c2b88d76b3c1). Their addresses are fixed: the citable version
  // (Zenodo DOI, JMBE) replaces them in place, so none of these may move.
  "/research/tools",
  "/research/tools/titer",
  "/research/tools/dilution",
  "/research/tools/webbed-plate",
  "/research/tools/moi",
  "/research/tools/eop",
  "/research/tools/lysate-volume",
  "/teaching",
  "/teaching/phage-discovery",
  "/teaching/virus-isolation",
  "/teaching/virus-isolation/faq",
  "/teaching/phage-bioinformatics",
  "/teaching/central-dogma",
  "/teaching/study-skills",
  "/software",
  "/software/foxhound",
  "/software/foxing",
  "/software/foxing-edu",
  "/software/germomics",
  "/software/capsid",
  "/software/enarratio",
  "/software/carrel",
  "/software/capsomer",
  "/software/prelum",
  "/software/site-runtime",
  "/software/site-api",
  "/software/d1-dump",
  "/software/devkit",
  // The CV. Its entries are the files in content/cv/ (docs/CV.md), not a markdown page kept in content/pages/.
  "/cv",
  // The legal pages, in Carrel with the rest (job_044f96426efa). /terms is also the terms the site's data is
  // published under: the `license` of every Dataset (app/lib/license.mjs).
  "/privacy",
  "/terms",
  // The accessibility statement (job_fea2f94832b3): what the gates check, in Carrel with the legal pages but
  // not one of them. It ships as a draft until Dustin approves its text, and the footer links it once published.
  "/accessibility",
]);

/**
 * The legal pages: the only ones whose front matter may state a `banner` (the one word "Draft") and a
 * `last_updated` date, which the layout draws for every reader and the markdown twin repeats. Carrel writes
 * both (carrel design-legal-pages.md).
 *
 * @type {readonly string[]}
 */
export const LEGAL_PAGE_PATHS = ["/privacy", "/terms"];

/** The one word a legal page's `banner` may say. */
export const LEGAL_BANNER = "Draft";

/**
 * The listed pages whose markdown is GENERATED from structured data rather than read from
 * content/pages/: build:content renders it from app/lib/cv/markdown.mjs, so the twin, sitemap, search
 * records and llms.txt treat /cv like every other page. Their HTML comes from their own route
 * (app/routes/cv.tsx) and their twin from another (app/routes/cv[.md].ts), both drawn from the cv table, so
 * pages.json and the pages table leave them out.
 *
 * @type {readonly string[]}
 */
export const CONTENT_PAGES_FROM_DATA = ["/cv"];

/**
 * The listed pages a reader can open: every one whose page is published, and the ones generated from data.
 * llms.txt must list each of these. `published` is the published paths from whichever source the caller
 * judges against: the page files (readPublishedPages()) in CI and the gates, the D1 rows in the llms.txt save.
 *
 * @param {readonly string[]} published
 * @returns {string[]}
 */
export function publishedContentPagePaths(published) {
  return CONTENT_PAGE_PATHS.filter(
    (path) => CONTENT_PAGES_FROM_DATA.includes(path) || published.includes(path),
  );
}

/**
 * The listed pages that are drafts: llms.txt may name them (so a page's line can land before or after it is
 * published, in either order) but need not.
 *
 * @param {readonly string[]} published as for publishedContentPagePaths
 * @returns {string[]}
 */
export function draftContentPagePaths(published) {
  const open = publishedContentPagePaths(published);
  return CONTENT_PAGE_PATHS.filter((path) => !open.includes(path));
}

/**
 * The pages that have a file in content/pages/, a row in the pages table and the page save, but whose
 * route, layout and structured data are their own (app/routes/about.tsx, a ProfilePage with its photo). They
 * are not in CONTENT_PAGE_PATHS, so the research splat, a markdown twin, a search record and the llms.txt
 * rules never see them: moving About onto D1 changed where its prose is kept and nothing a visitor reads.
 *
 * @type {readonly string[]}
 */
export const CONTENT_PAGES_OWN_ROUTE = ["/about"];

/** Every path a file in content/pages/ may name: the listed pages and the ones with a route of their own. */
export const PAGE_FILE_PATHS = /** @type {readonly string[]} */ ([
  ...CONTENT_PAGE_PATHS,
  ...CONTENT_PAGES_OWN_ROUTE,
]);

/**
 * Pages read one after another, each a way on to the next with signs at its foot (content-page.tsx, Capsomer's
 * `.cap-signs`). Each `label` is what a screen reader hears before the title; the sign shows the title alone.
 */
const PAGE_SEQUENCES = /** @type {const} */ ([
  {
    // The Phage Discovery Program's two semesters, in teaching order (content/pages/teaching.md).
    paths: ["/teaching/virus-isolation", "/teaching/phage-bioinformatics"],
    prev: "Previous semester",
    next: "Next semester",
  },
]);

/**
 * The pages either side of `path` in its sequence, or nulls for a page in none.
 *
 * @param {string} path
 * @returns {{ prev: { path: string, label: string } | null, next: { path: string, label: string } | null }}
 */
export function pageSequenceNeighbors(path) {
  for (const sequence of PAGE_SEQUENCES) {
    const at = /** @type {readonly string[]} */ (sequence.paths).indexOf(path);
    if (at === -1) continue;
    const before = sequence.paths[at - 1];
    const after = sequence.paths[at + 1];
    return {
      prev: before ? { path: before, label: sequence.prev } : null,
      next: after ? { path: after, label: sequence.next } : null,
    };
  }
  return { prev: null, next: null };
}

/**
 * The headings on these pages that the header menus link to by anchor, as `path#id`. A menu shows a
 * section link only once it is listed here, and the build refuses an entry whose page has no heading
 * with that id, so no menu link lands on the top of a page for want of its heading.
 *
 * @type {readonly string[]}
 */
export const CONTENT_PAGE_SECTIONS = ["/teaching#join-the-lab", "/teaching#teaching-philosophy"];

/**
 * The markdown file a path is written in: slashes to hyphens, `/research/phages` in research-phages.md.
 *
 * @param {string} path
 */
export function contentPageFile(path) {
  return `${path.slice(1).replaceAll("/", "-")}.md`;
}

/**
 * The markdown twin's URL: the page path plus `.md`. Not `contentPageFile`, which is the repo filename.
 *
 * @param {string} path
 */
export function contentPageMarkdownPath(path) {
  return `${path}.md`;
}

/**
 * The twin a machine reads. The HTML page's h1 is not in the source body, so the title is the first line,
 * followed by the page's dictionary entry where it has one, where the page shows it. The entry is the
 * caller's to give: the build reads it from content/dictionary, the Worker from D1 (docs/DICTIONARY.md).
 *
 * @param {{ path?: string, title: string, markdown: string, banner?: string, lastUpdated?: string }} page
 * @param {import("./dictionary-entries.mjs").DictionaryEntry} [entry] the page's published entry, if any
 */
export function contentPageMarkdownBody(page, entry) {
  const body = String(page.markdown ?? "").replace(/^\n+/, "");
  const lead = entry ? `${dictionaryEntryMarkdown(entry)}\n` : "";
  // A legal page's banner and date are facts a reader sees under the title, so the twin states them too.
  const stated = [
    page.banner,
    page.lastUpdated ? `Last updated: ${longDateUTC(page.lastUpdated)}` : "",
  ].filter(Boolean);
  const legal = stated.length > 0 ? `${stated.join("\n\n")}\n\n` : "";
  return `# ${page.title}\n\n${legal}${lead}${body}`;
}

/**
 * The pages build:og draws a social card of their own, by the root they sit under: the root and every
 * page below it, so a calculator added under /research/tools is carded with no edit here. Every other
 * page keeps the site card. Adding a root cards its pages on the next build:og.
 *
 * @type {readonly string[]}
 */
export const CARDED_PAGE_ROOTS = ["/software", "/research/tools", "/cv"];

/** @param {string} path */
export function hasPageCard(path) {
  return CARDED_PAGE_ROOTS.some((root) => path === root || path.startsWith(`${root}/`));
}

/**
 * What build:og draws for a page, in the shape ogImageKey hashes: the page's og:title (its SERP title)
 * and its description, with no date line, since these pages are not dated. The `page-` prefix keeps a
 * page's key apart from a post's, and build:og refuses two cards with one key.
 *
 * @param {{ path: string, seoTitle: string, description: string }} page
 */
export function contentPageCardInput(page) {
  return {
    slug: `page-${page.path.slice(1).replaceAll("/", "-")}`,
    title: page.seoTitle,
    description: page.description,
    publishAt: null,
  };
}

/**
 * The /media path of a page's card, which its og:image names, or null for a page on the site card. The
 * key hashes what the card draws, so a retitled page names a new card, which build:og then draws.
 *
 * @param {{ path: string, seoTitle: string, description: string }} page
 * @returns {string | null}
 */
export function contentPageCardPath(page) {
  return hasPageCard(page.path) ? `/media/${ogImageKey(contentPageCardInput(page))}` : null;
}

/**
 * What a Dataset node says about a page's first markdown table, read from the markdown the page renders:
 * its column headings, as the variables, and the span of its Year column, as an ISO 8601 interval. Null
 * when the page has no table.
 *
 * @param {string} markdown
 * @returns {{ variableMeasured: string[], temporalCoverage: string | null, rows: number } | null}
 */
export function markdownTableFacts(markdown) {
  const lines = String(markdown ?? "").split("\n");
  const rule = /^\|(\s*:?-+:?\s*\|)+\s*$/;
  const at = lines.findIndex(
    (line, i) => /^\|.*\|\s*$/.test(line) && rule.test(lines[i + 1] ?? ""),
  );
  if (at < 0) return null;
  const cells = (/** @type {string} */ line) =>
    line
      .trim()
      .replace(/^\||\|$/g, "")
      .split("|")
      .map((cell) => cell.trim());
  const headings = cells(lines[at] ?? "");
  /** @type {string[][]} */
  const rows = [];
  for (let i = at + 2; i < lines.length && (lines[i] ?? "").startsWith("|"); i += 1)
    rows.push(cells(lines[i] ?? ""));
  const yearColumn = headings.findIndex((heading) => /^year$/i.test(heading));
  const years =
    yearColumn < 0
      ? []
      : rows
          .map((row) => Number(row[yearColumn]))
          .filter((year) => Number.isInteger(year) && year > 0);
  const first = Math.min(...years);
  const last = Math.max(...years);
  const temporalCoverage =
    years.length === 0 ? null : first === last ? String(first) : `${first}/${last}`;
  return { variableMeasured: headings, temporalCoverage, rows: rows.length };
}

/** Google clips near these; the build refuses longer ones rather than ship a clipped result. */
export const SEO_TITLE_MAX = 60;
export const DESCRIPTION_MAX = 155;

/** The hubs, and the trail label each gives the pages under it. */
const HUBS = /** @type {const} */ ([
  ["/research", "Research"],
  ["/teaching", "Teaching"],
  ["/software", "Software"],
]);

/**
 * The trail above a page: its hub, the page it sits under when it is three deep (the course above its
 * FAQ), then the page itself. A hub stands alone.
 *
 * @param {{ path: string, title: string }} page
 * @param {(path: string) => string | undefined} [titleOf] the title of another listed page
 * @returns {Array<[string, string]>}
 */
export function contentPageTrail(page, titleOf = () => undefined) {
  const hub = HUBS.find(([path]) => page.path.startsWith(`${path}/`));
  if (!hub) return [[page.title, page.path]];
  const trail = /** @type {Array<[string, string]>} */ ([[hub[1], hub[0]]]);
  const parent = page.path.slice(0, page.path.lastIndexOf("/"));
  const parentTitle = parent !== hub[0] ? titleOf(parent) : undefined;
  if (parentTitle) trail.push([parentTitle, parent]);
  trail.push([page.title, page.path]);
  return trail;
}

/** The search uid of a page path: a removal needs it to find the page's records. */
export function contentPageSearchUid(/** @type {string} */ path) {
  return `page:${path.slice(1).replaceAll("/", ":")}`;
}

/**
 * Search inputs in the shape `recordsForPages` takes: one record for the page, one per heading, each
 * deep-linking to the heading's own anchor.
 *
 * @param {Array<{ path: string, title: string, description: string, markdown: string, toc: Array<{ depth: number, id: string, text: string }> }>} pages
 * @param {(path: string) => import("./dictionary-entries.mjs").DictionaryEntry | undefined} [entryFor] the
 *   published dictionary entry of a page path, which leads that page's record
 */
export function contentPageSearchInputs(pages, entryFor = () => undefined) {
  return pages.map((page) => {
    const { intro, sections } = splitSections(page.markdown, page.toc);
    const entry = entryFor(page.path);
    return {
      url: page.path,
      uid: contentPageSearchUid(page.path),
      title: page.title,
      description: page.description,
      intro: entry ? `${dictionaryEntryText(entry)} ${intro}` : intro,
      sections: sections.map(({ anchor, title, body }) => ({ anchor, title, body })),
    };
  });
}

