// Every writer and comparer of posts.source_blob_sha and posts.render_hash uses this module;
// a second implementation is drift. The git header counts UTF-8 BYTES, not string.length.

import { toHex } from "@dustinedwards/site-runtime/encoding";

const encoder = new TextEncoder();

/**
 * @param {"SHA-1" | "SHA-256"} algorithm
 * @param {Uint8Array<ArrayBuffer>} bytes
 * @returns {Promise<string>} lowercase hex
 */
async function digestHex(algorithm, bytes) {
  const digest = await crypto.subtle.digest(algorithm, bytes);
  return toHex(digest);
}

/**
 * @param {string} source the whole file, frontmatter included
 * @returns {Promise<string>}
 */
export async function gitBlobSha(source) {
  const body = encoder.encode(source);
  const header = encoder.encode(`blob ${body.byteLength}\0`);
  const framed = new Uint8Array(header.byteLength + body.byteLength);
  framed.set(header, 0);
  framed.set(body, header.byteLength);
  return digestHex("SHA-1", framed);
}

/**
 * @param {string} html
 * @returns {Promise<string>}
 */
export async function renderHash(html) {
  return digestHex("SHA-256", encoder.encode(html));
}

app/lib/cv/pdf-html.mjs.source:
// The CV's print document and the numbers the PDF is stamped with, shared by the two renderers: the Worker
// (app/lib/cv/pdf.server.ts, Browser Run's quickAction after each CV save) and the offline script
// (scripts/build-cv-pdf.mjs, headless Chrome through puppeteer). One copy of the HTML, so the two cannot draw
// different documents. Nothing here needs a browser, a filesystem or a Worker binding: the markdown pipeline and
// the fonts come in as arguments, because the Worker reads them one way and the script another.

import { escapeHtml } from "@dustinedwards/site-runtime/html";

import { sha256Hex, toBase64 } from "@dustinedwards/site-runtime/encoding";
import { OWNER_ORCID, SITE_ORIGIN } from "../seo.ts";
import { cvMarkdownBody, cvMarkdownDocument } from "./markdown.mjs";

/** The words the PDF's last line carries before the fingerprint. */
export const FINGERPRINT_LABEL = "CV data";

/**
 * Eight hex characters of the twin's source (SHA-256, through Web Crypto so the Worker and Node compute the same).
 * The PDF prints it, and the stored object carries it as custom metadata, so a PDF rendered from other data than
 * the CV now holds is a difference two sides can compare.
 *
 * @param {import("./entries.mjs").Cv} CV
 * @returns {Promise<string>}
 */
export async function cvFingerprint(CV) {
  return (await sha256Hex(cvMarkdownDocument(CV))).slice(0, 8);
}

/**
 * What the stored PDF is stamped with: the data's fingerprint and eight hex characters of the print document (its
 * stylesheet, its footer, the page options and the font files), so a deploy that changes only how the PDF
 * is drawn leaves the stored one stale, and the drift check and sync_cv_pdf render it again. A font recut under the
 * same file name is the one change this cannot see; a recut gets a new name.
 *
 * @param {import("./entries.mjs").Cv} CV
 * @returns {Promise<string>}
 */
export async function cvPdfStamp(CV) {
  const print = JSON.stringify([PRINT_CSS, cvFooterCss(CV), cvPdfOptions(), PDF_FONTS]);
  return `${await cvFingerprint(CV)}-${(await sha256Hex(print)).slice(0, 8)}`;
}

/**
 * The running footer, in the page's margin boxes (CSS Paged Media). Not Chrome's footerTemplate: a template is
 * drawn without the document's web fonts, so it fell back to the system's Arial (Liberation Sans in Browser Run)
 * whatever face it named. A margin box is drawn with the document's own fonts.
 *
 * @param {import("./entries.mjs").Cv} CV
 */
function cvFooterCss(CV) {
  const footer = `${CV.person.name}, Curriculum Vitae, ${CV.edition}`;
  const text = `"${footer.replace(/[\\"]/g, "\\$&").replace(/</g, "\\3c ")}"`;
  const box = 'font-family: "Inter", Arial, sans-serif; font-size: 7.5pt; color: #6a6159;';
  return `@page { @bottom-left { content: ${text}; ${box} } @bottom-right { content: counter(page) " of " counter(pages); ${box} } }`;
}

/** @param {string} family @param {Uint8Array} bytes @param {string} style */
export function fontFaceRule(family, bytes, style) {
  return `@font-face{font-family:"${family}";src:url(data:font/woff2;base64,${toBase64(bytes)}) format("woff2");font-style:${style};font-weight:100 900;}`;
}

/** The three faces the print document uses: file name, family and style, for whoever reads them. */
export const PDF_FONTS = /** @type {const} */ ([
  { file: "source-serif-4-latin-normal.woff2", family: "Source Serif 4", style: "normal" },
  { file: "source-serif-4-latin-italic.woff2", family: "Source Serif 4", style: "italic" },
  { file: "inter-latin-wght-normal.woff2", family: "Inter", style: "normal" },
]);

const PRINT_CSS = `
@page { size: Letter; margin: 0.8in 0.85in 0.85in; }
html { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
body { margin: 0; color: #1f1a17; font-family: "Source Serif 4", Georgia, serif; font-size: 10.5pt; line-height: 1.42; }
a { color: inherit; text-decoration: none; }
.letterhead { border-bottom: 1.5pt solid #4f2d7f; padding-bottom: 10pt; margin-bottom: 4pt; }
.letterhead h1 { margin: 0; color: #4f2d7f; font-size: 24pt; font-weight: 650; letter-spacing: -0.01em; line-height: 1.1; }
.letterhead p { margin: 4pt 0 0; font-family: "Inter", Arial, sans-serif; font-size: 9pt; color: #4a423b; line-height: 1.45; }
.letterhead .edition { text-transform: uppercase; letter-spacing: 0.08em; font-size: 7.5pt; font-weight: 600; color: #6a6159; margin: 0 0 6pt; }
h2 { margin: 16pt 0 6pt; padding-bottom: 3pt; border-bottom: 0.6pt solid #b9ada0; color: #4f2d7f; font-size: 13pt; font-weight: 650; break-after: avoid; }
h3 { margin: 10pt 0 4pt; font-family: "Inter", Arial, sans-serif; font-size: 8pt; font-weight: 650; letter-spacing: 0.06em; text-transform: uppercase; color: #4a423b; break-after: avoid; }
h4 { margin: 10pt 0 2pt; font-size: 10.5pt; font-weight: 650; break-after: avoid; }
.heading-anchor { display: none; }
p { margin: 3pt 0; }
ul, ol { margin: 3pt 0; padding-left: 16pt; }
li { margin: 0 0 3.5pt; break-inside: avoid; }
ul li::marker { color: #8a7d6e; }
ul:has(> li > strong:first-child) { padding-left: 0; }
ul > li:has(> strong:first-child) { list-style: none; padding-left: 6.4em; text-indent: -6.4em; }
ul > li > strong:first-child { display: inline-block; width: 6.4em; text-indent: 0; font-family: "Inter", Arial, sans-serif; font-size: 8.5pt; font-weight: 600; color: #4a423b; }
ol li::marker { color: #6a6159; font-family: "Inter", Arial, sans-serif; font-size: 8.5pt; }
strong { font-weight: 650; }
em { font-style: italic; }
.fingerprint { margin-top: 18pt; font-family: "Inter", Arial, sans-serif; font-size: 7.5pt; color: #6a6159; }
`;

/**
 * The print document for a resolved CV: the letterhead, the twin's markdown through the site's pipeline, the
 * fonts inlined, and the fingerprint. A function of the CV alone, so whatever holds a CV (the script from the
 * files, the Worker from D1) renders the same page.
 *
 * @param {import("./entries.mjs").Cv} CV
 * @param {{ renderBody: (input: { file: string, body: string, resolveImage: (src: string) => Promise<never> }) => Promise<{ html: string, blockedUrls: Array<{ url: string }> }>, fontCss: string }} deps
 *   the site's markdown pipeline, and the `@font-face` rules for PDF_FONTS
 */
export async function renderCvHtml(CV, { renderBody, fontCss }) {
  const rendered = await renderBody({
    file: "content/cv",
    body: cvMarkdownBody(CV, { pdf: true }),
    resolveImage: async (src) => {
      throw new Error(`the CV references an image (${src}) and its PDF has no image pipeline.`);
    },
  });
  if (rendered.blockedUrls.length > 0) {
    throw new Error(
      `the CV carries link(s) the URL allowlist refused: ${rendered.blockedUrls.map((b) => b.url).join(", ")}`,
    );
  }
  const { person } = CV;
  const host = new URL(SITE_ORIGIN).host;
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><title>${escapeHtml(`${person.name}, Curriculum Vitae`)}</title>
<style>${fontCss}${PRINT_CSS}${cvFooterCss(CV)}</style></head><body>
<header class="letterhead">
<p class="edition">Curriculum Vitae · ${escapeHtml(CV.edition)}</p>
<h1>${escapeHtml(`${person.name}, ${person.degree}`)}</h1>
<p>${escapeHtml(`${person.title}, ${person.department}, ${person.org}`)}</p>
<p><a href="${SITE_ORIGIN}/cv">${escapeHtml(`${host}/cv`)}</a> · <a href="${OWNER_ORCID}">ORCID ${OWNER_ORCID.split("/").pop()}</a></p>
</header>
${rendered.html}
<p class="fingerprint">Generated from the same data as ${escapeHtml(`${host}/cv`)}, where every entry can be searched and filtered. ${FINGERPRINT_LABEL} ${await cvFingerprint(CV)}.</p>
</body></html>`;
}

/**
 * The page.pdf() options, in the form puppeteer and Browser Run's quickAction("pdf") both read (every field is in
 * quickAction's documented pdfOptions). `format` is lower case, which both accept.
 */
export function cvPdfOptions() {
  return {
    format: /** @type {"letter"} */ ("letter"),
    printBackground: true,
    preferCSSPageSize: true,
    tagged: true,
    outline: true,
  };
}

app/lib/media/images.mjs.source:
import { defineImages, pictureProps } from "@dustinedwards/site-runtime/image";

import { digestFromKey, dimensionsFromKey } from "./classify.mjs";

// CSS pixels, never physical: the browser multiplies by the device pixel ratio itself. The 44rem prose column
// is about 704 CSS px.
const CONTENT_SIZES = "(min-width: 46rem) 704px, calc(100vw - 2rem)";

/**
 * Every way the site shows an image from /media, and so the route's closed width set (site-runtime ./image):
 * the set is CLOSED because the Images binding bills each unique transform, and the pipeline and the route
 * share it, so a width the page advertises is never a 400 mid-article. `breakpoints` keeps the widths the
 * site served before the move (640, 1024, 1408), so cached pages and feeds that link `?w=1024` still work;
 * the content use then serves 640, 704, 1024 and 1408. `tile` is the admin grid and `portrait` the about photo
 * (both 320 and 640), scaled, never cropped. `shareImages` adds the 1200-wide crops a post's Article JSON-LD names
 * (articleCrops).
 */
export const images = defineImages({
  shareImages: true,
  breakpoints: [640, 1024, 1408],
  uses: {
    content: { layout: "constrained", width: 704, sizes: CONTENT_SIZES },
    tile: { layout: "fixed", width: 320 },
    portrait: { layout: "fixed", width: 320, sizes: "(min-width: 46rem) 14rem, 11rem" },
  },
});

/**
 * A /media file's version, which its size URLs carry (`v=`, site-runtime ./image), so a file whose bytes change is a new
 * URL and none is cached stale for the year a size is kept: the bytes' sha256 where the caller read the row (a replace
 * or a turn in place writes it), else the digest its content key carries (dustin-edwards-<name>-<digest>-<w>x<h>.<ext>).
 * Rendered bodies, covers and procedure photos use the key's digest, which the Node build can read too, so a post
 * renders the same in the Worker and in the build; a file replaced in place keeps that address in them until the post
 * is rendered again from a row that holds its new hash. Not site-api's `mediaVersion` (`r` and the index row's rev, the
 * version its media writes are checked against): this one is the bytes' digest, which a size URL needs and the build can read.
 *
 * @param {string} keyOrPath a /media key or path
 * @param {string | null} [sha256]
 */
export function mediaContentVersion(keyOrPath, sha256 = null) {
  return sha256 ?? digestFromKey(keyOrPath);
}

/**
 * Responsive attributes for one /media image in the prose column. A key that does not carry its size gets the
 * ladder anyway, as before the move: the route scales down and never up, so a smaller original is served at its
 * own size.
 *
 * @param {string} src a `/media/` path
 * @param {{ width: number, height: number } | null} dimensions
 */
export function contentImage(src, dimensions) {
  const { width, height } = dimensions ?? { width: 2816, height: 2816 };
  return images.attributes({ src, width, height, version: mediaContentVersion(src) }, "content");
}

/**
 * A post cover's Article image set, absolute: the 16:9, 4:3 and 1:1 crops at 1200 wide Google asks for, versioned. Empty
 * for a cover that is not a /media raster whose key spells its size, so the JSON-LD keeps its one share image.
 *
 * @param {string | null} src the cover's path
 * @param {string} origin
 */
export function articleCrops(src, origin) {
  const dimensions = src?.startsWith("/media/") ? dimensionsFromKey(src) : null;
  if (!src || !dimensions) return [];
  return images
    .articleImages({ src, ...dimensions, version: mediaContentVersion(src) })
    .map(({ url, width, height }) => ({ url: new URL(url, origin).href, width, height }));
}

/**
 * A picture in the prose column as a `<picture>`: a /media image at its stored size, else the size its key spells, gets
 * the content use with AVIF and WebP; anything else (a static file, an SVG) has no size to read and gets a plain `src`,
 * since an invented size would distort the image.
 *
 * @param {string} src
 * @param {{ alt: string, width?: number | null, height?: number | null, priority?: boolean, className?: string }} options
 */
export function contentPicture(src, { alt, width, height, priority = false, className }) {
  const dimensions = width && height ? { width, height } : dimensionsFromKey(src);
  const attrs =
    dimensions && src.startsWith("/media/")
      ? contentImage(src, dimensions)
      : {
          src,
          srcset: undefined,
          sizes: undefined,
          sources: [],
          width: dimensions?.width,
          height: dimensions?.height,
          background: undefined,
        };
  return pictureProps(attrs, { alt, priority, className });
}

app/lib/media/upload-contract.mjs.source:
// The form branch is selected ONLY by `intent=upload-form`, never by sniffing a header: a changed
// default header would silently hand the editors' `response.json()` an HTML page.
// Must stay loadable by node:test: never import anything reaching a binding, a `.server` module or React.

import { byteSize } from "./byte-size.mjs";

export const ALLOWED = new Map([
  ["image/webp", "webp"],
  ["image/png", "png"],
  ["image/jpeg", "jpg"],
  ["image/avif", "avif"],
  ["image/gif", "gif"],
  // Stored as JPEG (site-api's prepareUpload converts them), so the extension is never used.
  ["image/heic", "jpg"],
  ["image/heif", "jpg"],
  // A chart's data (checklist E3): a post cites it as `:::chart{src="/media/<key>"}`, and the render reads it through
  // Prelum's chartData (app/lib/content/chart-data.mjs). Text, so it has no size and no Images step.
  ["text/csv", "csv"],
]);

/** The data files in ALLOWED: stored as uploaded, with no size in the key. */
export const DATA_TYPES = new Set(["text/csv"]);

// NOT IN THE ALLOWLIST, and refused by name rather than as an unknown type: an SVG can carry script,
// and /media is this site's own origin. The /media CSP (workers/csp.mjs) is the second wall, for
// anything that reaches the bucket some other way.
const SVG_TYPE = "image/svg+xml";

const SVG_REFUSED =
  "SVG is not accepted: it can carry script, and /media is this site's own origin. " +
  "Export it as PNG or WebP.";

// A hint, not a control: drag-drop or a scripted post ignores `accept`. The control is the server check.
export const ACCEPT_ATTRIBUTE = [...ALLOWED.keys()].join(",");

export const MAX_BYTES = 10 * 1024 * 1024;

export const UPLOAD_FORM_INTENT = "upload-form";

export const UPLOAD_RETURN_PATH = "/admin/media";

/**
 * @param {unknown} intent the submitted `intent` field, whatever arrived
 * @returns {boolean}
 */
export function isFormUpload(intent) {
  return intent === UPLOAD_FORM_INTENT;
}

/**
 * @param {string} message
 */
export function uploadErrorBody(message) {
  return { error: message };
}

// A code in the URL, not the message, so the address bar never carries prose someone can edit.
const UPLOAD_ERRORS = {
  "no-file": "No file was chosen.",
  "unsupported-type":
    `That file type is not one this endpoint accepts. Uploads here are images and chart data: ` +
    `${[...ALLOWED.keys()].map((mime) => mime.split("/")[1]).join(", ")}.`,
  "too-large": `That image is over the ${MAX_BYTES / (1024 * 1024)} MB limit.`,
  "svg-refused": SVG_REFUSED,
  "content-mismatch":
    "That file's bytes are not the image type it was uploaded as. " +
    "Export the image again as PNG, JPEG or WebP.",
  "images-unavailable":
    "The image could not be measured, because Cloudflare Images did not answer. " +
    "Nothing was stored; try again.",
};

/**
 * `no-file` is left to each caller, because its repair differs. The byte signature is site-api's prepareUpload's,
 * after this: SVG bytes declared `image/png` fail it as `content-mismatch`.
 *
 * @param {{ type: string, bytes: { byteLength: number } }} file what arrived, before any store
 * @returns {{ code: "unsupported-type" | "svg-refused" | "too-large", message: string, status: number } | null}
 */
export function validateUpload({ type, bytes }) {
  const size = bytes.byteLength;

  // Before the generic check, so the refusal says why instead of reading as an oversight.
  if (type.toLowerCase().split(";")[0]?.trim() === SVG_TYPE) {
    return { code: "svg-refused", message: SVG_REFUSED, status: 415 };
  }

  if (!ALLOWED.has(type)) {
    return {
      code: "unsupported-type",
      message: `Unsupported file type "${type || "unknown"}".`,
      status: 415,
    };
  }

  if (size > MAX_BYTES) {
    return {
      code: "too-large",
      message: `The file is ${byteSize(size)}, over the ${MAX_BYTES / (1024 * 1024)} MB limit.`,
      status: 413,
    };
  }

  return null;
}

/**
 * @param {string | null} code
 * @returns {string | null} the sentence, or null for a code nothing emits
 */
export function uploadErrorSentence(code) {
  if (!code) return null;
  return Object.prototype.hasOwnProperty.call(UPLOAD_ERRORS, code)
    ? UPLOAD_ERRORS[/** @type {keyof typeof UPLOAD_ERRORS} */ (code)]
    : null;
}

/**
 * Success carries the key, so a reload repeats a harmless read rather than a second upload.
 *
 * @param {{ ok: true, key: string } | { ok: false, code: string }} result
 */
export function uploadRedirectTo(result) {
  const params = result.ok
    ? `uploaded=${encodeURIComponent(result.key)}`
    : `upload-error=${encodeURIComponent(result.code)}`;
  return `${UPLOAD_RETURN_PATH}?${params}`;
}

app/lib/media/usage.mjs.source:
// Three states, not two: post evidence cannot see an asset placed by route code, so without "in template"
// the roster photos read as orphans beside a delete button. "Unattached" is an ABSENCE of evidence, not
// "unused". A file both cited and referenced reports USED, the claim that can name a post.

export const USAGE_STATES = {
  used: {
    id: "used",
    label: "used",
    title: "Referenced by a post",
    note: "The usage tracker found this address in published content.",
  },
  template: {
    id: "template",
    label: "in template",
    title: "Placed by page code",
    note:
      "Found by scanning the repository, not the post index. A post-level " +
      "tracker will always report this file as unreferenced.",
  },
  unattached: {
    id: "unattached",
    label: "unattached",
    title: "No reference found",
    note:
      "Not found in posts or in repository code. Unattached is not the same as " +
      "unused: a file can still be linked from outside the site, and a path the " +
      "code builds at runtime is invisible to the scan. Verify before deleting.",
  },
};

export const USAGE_ORDER = ["used", "template", "unattached"];

/**
 * @param {{ postRefs: number, citations: number, templateRefs: number }} evidence
 * @returns {"used"|"template"|"unattached"}
 */
export function usageStateOf(evidence) {
  if (evidence.postRefs > 0 || evidence.citations > 0) return "used";
  if (evidence.templateRefs > 0) return "template";
  return "unattached";
}

/**
 * @param {string} state
 * @returns {{ id: string, label: string, title: string, note: string }}
 */
export function usageDescriptor(state) {
  return (
    /** @type {Record<string, typeof USAGE_STATES.used>} */ (USAGE_STATES)[state] ??
    USAGE_STATES.unattached
  );
}

/**
 * @param {string} state
 * @returns {number}
 */
export function usageRank(state) {
  const at = USAGE_ORDER.indexOf(state);
  return at < 0 ? USAGE_ORDER.length : at;
}

export const LARGE_FILE_BYTES = 1024 * 1024;

/**
 * `noAlt` applies to images only: a document takes no alt text.
 *
 *
 * @param {{ viewable: boolean, alt: string | null, size: number, twinCount: number }} row
 * @returns {Array<{ id: string, label: string }>}
 */
export function flagsFor(row) {
  /** @type {Array<{ id: string, label: string }>} */
  const out = [];
  if (row.twinCount > 0) out.push({ id: "duplicate", label: "duplicate" });
  if (row.viewable && !(row.alt ?? "").trim()) out.push({ id: "no-alt", label: "no alt" });
  if (row.size > LARGE_FILE_BYTES) out.push({ id: "large", label: "over 1 MB" });
  return out;
}

/**
 * One dot: on a 150px tile three is a rash. Ordered by what the reader can lose by not knowing.
 *
 *
 * @param {{ flags: Array<{ id: string, label: string }>, usage: string, twin: string | null }} row
 * @returns {{ id: string, title: string } | null}
 */
export function tileFlagFor(row) {
  /** @param {string} id */
  const has = (id) => row.flags.some((f) => f.id === id);
  if (has("duplicate")) {
    return { id: "duplicate", title: row.twin ? `Duplicate of ${row.twin}` : "Duplicate" };
  }
  if (row.usage === "unattached") return { id: "unattached", title: "No reference found" };
  if (has("no-alt")) return { id: "no-alt", title: "No alt text" };
  return null;
}

export const LENS_NOTES = {
  unattached:
    "No reference was found in posts or in repository code. That is not proof a " +
    "file is unused: check before deleting.",
  duplicates:
    "These files share a content hash with another file. Both addresses serve " + "the same bytes.",
  "no-alt":
    "Images published without alt text. Documents are not listed; they do not " + "take alt text.",
  large: "Large files slow the pages that embed them. Consider a smaller derivative.",
};

/**
 * Offered, never applied: alt text nobody read is worse than a visibly empty field.
 *
 * @param {string} base a filename, no directory
 * @returns {string}
 */
export function suggestedAlt(base) {
  return base
    .replace(/\.[a-z0-9]+$/i, "")
    .replace(/[-_]+/g, " ")
    .trim();
}

/**
 * @param {string} key
 * @returns {string[]}
 */
export function suggestedTags(key) {
  const parts = key.split("/").filter(Boolean);
  /** @type {string[]} */
  const out = [];
  // A content-addressed key has no directory, and its first segment is a hash, not a label.
  const leading = parts[0];
  if (key.startsWith("/") && parts.length > 1 && leading) {
    out.push(leading.replace(/[-_]+/g, " "));
  }
  const year = key.match(/\b(20\d{2})\b/)?.[1];
  if (year) out.push(year);
  const term = key.match(/\b(spring|fall|summer|winter)\b/i)?.[1];
  if (term) out.push(term.toLowerCase());
  return [...new Set(out.map((t) => t.trim().toLowerCase()).filter(Boolean))];
}

/**
 * An image goes in as `![alt](src)` and a document as `[title](href)`; an `<img>` for a PDF breaks the page.
 *
 * @param {{ url: string, viewable: boolean, alt: string | null, base: string }} row
 * @returns {Array<{ id: string, label: string, name: string, value: string }>}
 */
export function copySnippetsFor(row) {
  const alt = (row.alt ?? "").trim();
  const title = suggestedAlt(row.base);
  // `label` is what the button shows, `name` what a screen reader hears: the visible "Copy" group
  // heading supplies the verb only for sighted readers.
  if (row.viewable) {
    return [
      { id: "address", label: "Copy address", name: "Copy the address", value: row.url },
      {
        id: "markdown",
        label: "Markdown",
        name: "Copy the markdown image",
        value: `![${alt}](${row.url})`,
      },
      {
        id: "html",
        label: "HTML tag",
        name: "Copy the HTML image tag",
        value: `<img src="${row.url}" alt="${alt}">`,
      },
    ];
  }
  return [
    { id: "address", label: "Copy address", name: "Copy the address", value: row.url },
    {
      id: "markdown",
      label: "Markdown",
      name: "Copy the markdown link",
      value: `[${title}](${row.url})`,
    },
    {
      id: "html",
      label: "HTML link",
      name: "Copy the HTML link",
      value: `<a href="${row.url}">${title}</a>`,
    },
  ];
}

