/**
 * @typedef {{ tag: "div" | "h3" | "ol" | "li" | "p" | "strong" | "sup", className?: string, children: Array<ViewNode | string> }} ViewNode
 */

/** @param {string} line @returns {Array<ViewNode | string>} */
function lineNodes(line) {
  return textParts(line).map((part) =>
    part.sup ? { tag: "sup", children: [part.text] } : part.text,
  );
}

/**
 * What a result looks like, as plain nodes, so the server component and the browser module build the
 * same markup from one description and neither parses HTML. `summary` is the one line per section the
 * status region announces; `detail` is the worked steps under it.
 *
 * @param {ToolResult} result
 * @returns {{ summary: Array<ViewNode | string>, detail: ViewNode[] }}
 */
export function resultView(result) {
  if (!result.ok) {
    return {
      summary: [{ tag: "p", className: "phage-tool-error", children: [result.error] }],
      detail: [],
    };
  }
  const summary = result.sections
    .filter((section) => section.result)
    .map((section) => ({
      tag: /** @type {const} */ ("p"),
      className: "phage-tool-answer",
      children: [
        `${section.heading}: `,
        { tag: /** @type {const} */ ("strong"), children: lineNodes(section.result ?? "") },
      ],
    }));
  const detail = result.sections.map((section) => ({
    tag: /** @type {const} */ ("div"),
    className: "phage-tool-section",
    children: [
      { tag: /** @type {const} */ ("h3"), children: [section.heading] },
      {
        tag: /** @type {const} */ ("ol"),
        className: "phage-tool-steps",
        children: section.steps.map((step) => ({
          tag: /** @type {const} */ ("li"),
          children: lineNodes(step),
        })),
      },
      ...(section.notes ?? []).map((note) => ({
        tag: /** @type {const} */ ("p"),
        className: "phage-tool-note",
        children: lineNodes(note),
      })),
    ],
  }));
  return { summary, detail };
}

app/lib/podcast/feed.mjs.source:
// Pure, so node:test and the CSP builder can import it. Every feed URL is checked against a host
// allowlist; the audio list is what workers/csp.mjs writes into `media-src`, so the two cannot disagree.

import { decodeEntities } from "../publications/entities.mjs";

export const PODCAST_FEED_URL = "https://germomics.com/feed/podcast/";

export const PODCAST_SITE_URL = "https://germomics.com/";

// `op3.dev` is the feed's analytics prefix and 302s to `media.germomics.com`; CSP checks the redirect
// target too, so both are listed.
export const PODCAST_AUDIO_HOSTS = ["op3.dev", "media.germomics.com"];

const EPISODE_PAGE_HOSTS = ["germomics.com", "www.germomics.com"];

/**
 * @typedef {{
 *   guid: string,
 *   title: string,
 *   link: string,
 *   publishedAt: string,
 *   durationSeconds: number | null,
 *   description: string,
 *   audioUrl: string,
 *   audioType: string,
 *   season: number | null,
 *   episode: number | null,
 *   transcriptUrl: string | null,
 * }} PodcastEpisode
 */

/**
 * The shared decoder, plus `&nbsp;`: podcast hosts write it in show notes, and every whitespace run
 * here collapses to one space anyway. Replaced before decoding, so `&amp;nbsp;` still reads literally.
 *
 * @param {string} text
 */
function decodeFeedEntities(text) {
  return decodeEntities(text.replace(/&nbsp;/g, " "));
}

/**
 * @param {string} xml @param {string} tag
 */
function textOf(xml, tag) {
  const escaped = tag.replace(":", "\\:");
  const match = xml.match(new RegExp(`<${escaped}(?:\\s[^>]*)?>([\\s\\S]*?)</${escaped}>`));
  if (!match) return "";
  const raw = (match[1] ?? "").replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, "$1");
  return decodeFeedEntities(raw.replace(/<[^>]*>/g, " "))
    .replace(/\s+/g, " ")
    .trim();
}

/** @param {string} xml @param {string} tag @param {string} attr */
function attrOf(xml, tag, attr) {
  const element = xml.match(new RegExp(`<${tag.replace(":", "\\:")}\\s[^>]*>`));
  if (!element) return "";
  const value = element[0].match(new RegExp(`\\s${attr}="([^"]*)"`));
  return value ? decodeFeedEntities(value[1] ?? "") : "";
}

/**
 * @param {string} value @param {readonly string[]} hosts
 */
function allowedHttpsUrl(value, hosts) {
  try {
    const url = new URL(value);
    if (url.protocol !== "https:" || url.username || url.password || url.port) return null;
    return hosts.includes(url.hostname) ? url.href : null;
  } catch {
    return null;
  }
}

/**
 * @param {string} value
 */
export function parseDuration(value) {
  if (!/^\d+(:\d{1,2}){0,2}$/.test(value)) return null;
  return value.split(":").reduce((total, part) => total * 60 + Number(part), 0);
}

/** @param {string} value */
function positiveInt(value) {
  return /^\d+$/.test(value) && Number(value) > 0 ? Number(value) : null;
}

/**
 * @param {string} xml
 * @returns {PodcastEpisode[]}
 */
export function parsePodcastFeed(xml) {
  /** @type {PodcastEpisode[]} */
  const episodes = [];
  for (const [, item = ""] of xml.matchAll(/<item>([\s\S]*?)<\/item>/g)) {
    const title = textOf(item, "title");
    const guid = textOf(item, "guid");
    const link = allowedHttpsUrl(textOf(item, "link"), EPISODE_PAGE_HOSTS);
    const audioUrl = allowedHttpsUrl(attrOf(item, "enclosure", "url"), PODCAST_AUDIO_HOSTS);
    const audioType = attrOf(item, "enclosure", "type");
    const published = new Date(textOf(item, "pubDate"));
    if (!title || !guid || !link || !audioUrl || !audioType.startsWith("audio/")) continue;
    if (Number.isNaN(published.getTime())) continue;
    episodes.push({
      guid,
      title,
      link,
      publishedAt: published.toISOString(),
      durationSeconds: parseDuration(textOf(item, "itunes:duration")),
      description: textOf(item, "description"),
      audioUrl,
      audioType,
      season: positiveInt(textOf(item, "itunes:season")),
      episode: positiveInt(textOf(item, "itunes:episode")),
      // Podcasting 2.0's <podcast:transcript> (podcastindex.org namespace): Germomics publishes a WebVTT for each episode.
      transcriptUrl: allowedHttpsUrl(attrOf(item, "podcast:transcript", "url"), EPISODE_PAGE_HOSTS),
    });
  }
  return episodes.sort((a, b) => b.publishedAt.localeCompare(a.publishedAt));
}

app/lib/post-order.mjs.source:
// The order posts are listed in, newest first, as one rule for the two places that apply it: the D1 listing
// queries (app/db/posts.ts, newestFirstOrder) and the header's build-time list (scripts/lib/nav-data.mjs).
//
// 1. Publish instant, latest first.
// 2. Posts that share an instant: a series stays together and reads latest part first (the newest part of a
//    series is its newest post). A series sits among unrelated posts where its latest row would.
// 3. Otherwise the later row first. The database breaks that tie by row id; the build cannot see ids, so it
//    passes the slug, because rows are inserted in slug order (scripts/build-content.mjs).
//
// Concretely: sort by instant, then by the group key (the largest tie-break value among the posts sharing the
// instant and series, or the post's own value when it has no series), then by part, then by the tie-break
// value. That is a total order, which "part descending within a series, the tie-break otherwise" alone is not.

/**
 * @template {{ publishAt: string, series: string | null, part: number | null }} P
 * @param {P[]} posts
 * @param {(post: P) => string | number} tie the row id in a database, the slug in the build
 * @returns {P[]} a new array, newest first
 */
export function newestFirst(posts, tie) {
  /** @type {Map<string, string | number>} */
  const latest = new Map();
  const groupOf = (/** @type {P} */ p) => `${p.publishAt}\u0000${p.series}`;
  for (const p of posts) {
    if (p.series === null) continue;
    const seen = latest.get(groupOf(p));
    if (seen === undefined || tie(p) > seen) latest.set(groupOf(p), tie(p));
  }
  const key = (/** @type {P} */ p) =>
    p.series === null ? tie(p) : /** @type {string | number} */ (latest.get(groupOf(p)));
  const desc = (/** @type {string | number} */ a, /** @type {string | number} */ b) =>
    a === b ? 0 : a < b ? 1 : -1;
  return [...posts].sort(
    (a, b) =>
      desc(a.publishAt, b.publishAt) ||
      desc(key(a), key(b)) ||
      desc(a.part ?? 0, b.part ?? 0) ||
      desc(tie(a), tie(b)),
  );
}

app/lib/publications/compile.mjs.source:
// One door from a publication file to everything derived from it: parse, validate, the record every
// surface reads, the markdown twin and the search input. check:machine-readable, sync:content, the
// build and the Carrel adapter's save all call compilePublication, so a file CI passes is the file the
// save accepts and the page draws, and the twin a machine reads is the one a person's page agrees with.

import { gitBlobSha } from "../content/hashes.mjs";
import { keyForUrl, urlForKey } from "../search/ask-keys.mjs";
import { buildCitationTags, REQUIRED_CITATION_TAGS } from "./citation-tags.mjs";
import { citedByFetchedAt, citedByFor } from "./cited-by.mjs";
import { decodeEntities } from "./entities.mjs";
import { organismsIn, toBibtex, toRis } from "./exports.mjs";
import { parsePublication, publicationPath } from "./parse.mjs";
import { paperAskUrl, paperMarkdownPath, paperPath, paperPdfPath } from "./paths.mjs";
import { recordFromData } from "./record.mjs";
import { paperSearchInputs } from "./search-inputs.mjs";
import { paperTwin } from "./twin.mjs";
import { ASK_URL_MAX, validatePublicationFile } from "./validate.mjs";

const ORIGIN = "https://example.invalid";
const REFERENCE = /&(?:amp|lt|gt|quot|apos|#\d+);/;

/**
 * What a record promises other surfaces, checked once it is built: the Scholar tag set, the exports,
 * the twin, the search record and the Ask key. Each is a function of the record alone, so a file that
 * passes here cannot fail the page at render time.
 *
 * @param {import("./types.ts").Publication} record
 * @param {{ twin: string, searchBody: string, fullText: string | null }} built
 * @returns {string[]}
 */
function derivedProblems(record, built) {
  /** @type {string[]} */
  const errors = [];
  const { slug } = record;
  const hosted = record.access === "self-hosted" && record.pdfPath !== null;

  if (record.doi !== null) {
    try {
      const tags = buildCitationTags(record, {
        abstractUrl: `${ORIGIN}${paperPath(slug)}`,
        pdfUrl: hosted ? `${ORIGIN}${paperPdfPath(slug)}` : null,
      });
      const names = tags.map((t) => t.name);
      for (const required of REQUIRED_CITATION_TAGS) {
        if (!names.includes(required)) errors.push(`citation tags: no ${required}`);
      }
      const authorTags = tags.filter((t) => t.name === "citation_author").length;
      if (authorTags !== record.authors.length) {
        errors.push(
          `citation tags: ${authorTags} citation_author tags for ${record.authors.length} authors; one per author, or Scholar reads a single author whose name is the whole list`,
        );
      }
      const pdf = tags.find((t) => t.name === "citation_pdf_url");
      if (hosted && !pdf) errors.push("citation tags: hosted but no citation_pdf_url");
      if (!hosted && pdf) errors.push("citation tags: not hosted but has citation_pdf_url");
      if (pdf && !pdf.content.startsWith(`${ORIGIN}${paperPath(slug)}`)) {
        errors.push(`citation tags: citation_pdf_url is not under ${paperPath(slug)}`);
      }
    } catch (error) {
      errors.push(error instanceof Error ? error.message : String(error));
    }

    const bib = toBibtex(record);
    const ris = toRis(record);
    if (!bib.includes(record.doi) || !ris.includes(record.doi))
      errors.push("exports: the DOI is missing from the BibTeX or RIS entry");
    if (record.doi !== record.doi.toLowerCase() && !bib.includes(`doi = {${record.doi}}`)) {
      errors.push("exports: a mixed-case DOI must be exported as deposited");
    }
    if (REFERENCE.test(bib) || REFERENCE.test(ris))
      errors.push("exports: a character reference survives into BibTeX or RIS");
    const unprotected = organismsIn(record.title).filter((o) => !bib.includes(`{${o}}`));
    if (unprotected.length > 0)
      errors.push(
        `exports: organism name(s) not brace-protected in BibTeX: ${unprotected.join(", ")}`,
      );
  }

  if (REFERENCE.test(built.twin)) errors.push("twin: carries an undecoded character reference");
  if (hosted && built.fullText !== null && !built.twin.includes("## Full text"))
    errors.push("twin: a hosted paper's twin lacks its Full text section");
  // Classic search shows the line it matched, so two-column text would snippet a mangled one.
  if (hosted && built.fullText && built.searchBody.length > built.fullText.length / 2) {
    errors.push(
      "search record: the body carries the PDF text; only the abstract, summary and citation belong in it",
    );
  }

  const key = keyForUrl(paperPath(slug));
  if (key !== `research/publications/${slug}.md` || urlForKey(key) !== paperPath(slug)) {
    errors.push(`Ask key: ${key} does not map back to ${paperPath(slug)}`);
  }
  if (`/${key}` !== paperMarkdownPath(slug))
    errors.push(`Ask key: ${key} is not the twin's path ${paperMarkdownPath(slug)}`);
  const askUrl = paperAskUrl(decodeEntities(record.title));
  if (!askUrl.startsWith("/search?q=") || askUrl.length > ASK_URL_MAX)
    errors.push("Ask link: the quoted title does not build a /search URL");
  return errors;
}

/**
 * @param {object} input
 * @param {string} input.slug
 * @param {string} input.raw the whole file
 * @param {import("./validate.mjs").PublicationHost} input.host
 * @param {import("./validate.mjs").OtherPublication[]} [input.others]
 * @param {unknown} input.citedByArtifact the parsed data/publications.cited-by.json, which the twin's
 *   citedBy line is a pure function of, so a build and a save write the same twin
 * @returns {Promise<
 *   | { ok: false, errors: string[] }
 *   | { ok: true, errors: [], record: import("./types.ts").Publication, draft: boolean, csl: Record<string, unknown> | null,
 *       fullText: string | null, pdfSha256: string | null, twin: string, searchInput: { uid: string, url: string, title: string, body: string },
 *       sourcePath: string, sourceBlobSha: string }
 * >}
 */
export async function compilePublication({ slug, raw, host, others, citedByArtifact }) {
  const file = publicationPath(slug);
  const parsed = parsePublication({ file, raw });
  const errors = await validatePublicationFile({ parsed, slug, host, others });
  if (errors.length > 0) return { ok: false, errors };

  const record = recordFromData(/** @type {any} */ (parsed.data), slug);
  const hosted = record.access === "self-hosted" && record.pdfPath !== null;
  const twin = paperTwin(record, {
    pages: hosted ? [parsed.fullText ?? ""] : null,
    citedBy: record.doi ? citedByFor(citedByArtifact, record.doi) : null,
    citedByFetchedAt: citedByFetchedAt(citedByArtifact),
    pagePath: paperPath(slug),
    pdfPath: hosted ? paperPdfPath(slug) : null,
  });
  const searchInput = /** @type {NonNullable<ReturnType<typeof paperSearchInputs>[number]>} */ (
    paperSearchInputs([record])[0]
  );
  const derived = derivedProblems(record, {
    twin,
    searchBody: searchInput.body,
    fullText: parsed.fullText,
  });
  if (derived.length > 0) return { ok: false, errors: derived };

  const csl =
    parsed.data.csl && typeof parsed.data.csl === "object"
      ? /** @type {Record<string, unknown>} */ (parsed.data.csl)
      : null;
  return {
    ok: true,
    errors: [],
    record,
    draft: parsed.data.draft === true,
    csl,
    fullText: parsed.fullText,
    pdfSha256: typeof parsed.data.pdfSha256 === "string" ? parsed.data.pdfSha256 : null,
    twin,
    searchInput,
    sourcePath: file,
    sourceBlobSha: await gitBlobSha(raw),
  };
}

app/lib/search/ask-pacing.mjs.source:
// Paced rather than a flat cap: a flat cap is a cliff a distributed caller spends in minutes, denying
// Ask until UTC midnight. Paced, the denial ends when the abuse does. The bill is bounded either way.

/**
 * Never above dailyLimit, so this only ever refuses earlier than the flat cap would.
 *
 * @param {number} dailyLimit total answers permitted in a UTC day
 * @param {number} burst units available on top of the paced share
 * @param {Date} now
 * @returns {number} the ceiling to enforce at this instant
 */
export function pacedAllowance(dailyLimit, burst, now) {
  const SECONDS_PER_DAY = 86400;

  const elapsed = now.getUTCHours() * 3600 + now.getUTCMinutes() * 60 + now.getUTCSeconds();

  // floor, not ceil: at 00:00:00 the allowance must be exactly burst.
  const paced = Math.floor((dailyLimit * elapsed) / SECONDS_PER_DAY);

  return Math.min(dailyLimit, paced + burst);
}

/**
 * The honest Retry-After under pacing; seconds-until-midnight would send readers away for a day.
 *
 * @param {number} dailyLimit
 * @returns {number} seconds, at least 1
 */
export function secondsPerPacedUnit(dailyLimit) {
  if (dailyLimit <= 0) return 86400;
  return Math.max(1, Math.round(86400 / dailyLimit));
}

app/lib/search/zero-result.mjs.source:
// The privacy boundary: everything the table stores passes through here, and anything that looks
// personal is refused. A dropped legitimate query costs one row; a kept personal one is a record.

/** Matches the CHECK constraint in drizzle/0015_zero_result_queries.sql. */
export const ZERO_RESULT_MAX_LENGTH = 200;

/** Here, not beside the sweep: the admin label derives from it, and a .server import in JSX reaches the client bundle. */
export const ZERO_RESULT_RETENTION_SECONDS = 90 * 24 * 60 * 60;

/** Below this a query is a fragment, not a question, and every site gets thousands of them. */
const MIN_LENGTH = 3;

/** Wider than a real email pattern on purpose: over-matching costs a row, under-matching stores an address. */
const ADDRESS_SHAPE = /\S+@\S+/;

const PHONE_SHAPE = /(?:\+?\d[\d\s().-]{6,}\d)/;

/** A person's name shape. Over-matches ("Cloudflare Workers") on purpose; a name list would hold names. */
const NAME_SHAPE = /\b[A-Z][a-z]+\s+[A-Z][a-z]+/;

/**
 * The shape tests run on the RAW input, since lowercasing destroys the only signal NAME_SHAPE has.
 *
 * @param {string} raw
 * @returns {string | null} the value to store, or null when it must not be stored
 */
export function normalizeZeroResultQuery(raw) {
  if (typeof raw !== "string") return null;

  const trimmed = raw.trim();
  if (trimmed.length < MIN_LENGTH) return null;
  // Refused, not truncated: a truncated paste is the same problem in a shorter field.
  if (trimmed.length > ZERO_RESULT_MAX_LENGTH) return null;

  if (ADDRESS_SHAPE.test(trimmed)) return null;
  if (PHONE_SHAPE.test(trimmed)) return null;
  if (NAME_SHAPE.test(trimmed)) return null;

  const normalized = trimmed.toLowerCase().replace(/\s+/g, " ");
  if (!/[\p{L}\p{N}]/u.test(normalized)) return null;

  return normalized;
}

app/lib/systems.mjs.source:
// The network of systems at /systems and each system at /systems/<id>: Capsid's public model
// (data/system-model.json, the document Capsid serves at /public/model/v1.json) checked, then shown
// by Capsomer's system map, the network as hexagons (the plain map of cards a tab away) and one system at level 2 (Dustin, 2026-11-03).
// Ruling: capsid/rulings/system-explorer-2026-10-10.md, answer 9 (the same component as the explorer).
//
// Every system is drawn whole, a private repo's included (Dustin, 2026-10-23: "do not exclude
// private repos", "fully wired just like the public ones"); a private system carries no repo
// link. The file is refused unless every key is one the published shape allows and a private
// system names no repo, so a mistake upstream stops the build rather than reaching the page.
import { modelMapData } from "capsomer/behavior/system-map";
import { z } from "zod";

export const SYSTEMS_PATH = "/systems";

const Id = z.string().regex(/^[a-z0-9][a-z0-9-]{0,63}$/);
/** @param {number} max */
const Text = (max) => z.string().min(1).max(max);
// The enums are capsid's (src/system-model.ts), so a value it publishes is never refused here.
const FAMILIES = /** @type {const} */ (["system", "writing", "product", "plumbing", "site"]);
const RINGS = /** @type {const} */ (["core", "shared", "used"]);
const RELATIONSHIP_KINDS = /** @type {const} */ ([
  "installs",
  "publishes-to",
  "coordinates",
  "watches",
  "reads",
  "writes",
  "deploys",
  "serves",
]);
const CONTAINER_KINDS = /** @type {const} */ ([
  "worker",
  "database",
  "bucket",
  "kv",
  "queue",
  "cron",
  "package",
  "site",
  "external",
]);

const OpenSystem = z.strictObject({
  id: Id,
  name: Text(40),
  short: Text(12),
  family: z.enum(FAMILIES),
  ring: z.enum(RINGS),
  private: z.literal(false),
  description: Text(280).optional(),
  domain: Text(253).optional(),
  repos: z.array(z.url().max(512)).optional(),
});

// A private system is everything a public one is but its repo link (capsid src/system-model.ts).
const PrivateSystem = OpenSystem.omit({ repos: true }).extend({ private: z.literal(true) });

const PublicModel = z.strictObject({
  version: z.literal(1),
  as_of: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
  systems: z.array(z.union([PrivateSystem, OpenSystem])),
  containers: z.array(
    z.strictObject({
      id: Id,
      system: Id,
      name: Text(40),
      kind: z.enum(CONTAINER_KINDS),
      technology: Text(60),
      description: Text(280).optional(),
    }),
  ),
  relationships: z.array(
    z.strictObject({
      id: Text(200),
      from: Id,
      to: Id,
      kind: z.enum(RELATIONSHIP_KINDS),
      title: Text(280).optional(),
    }),
  ),
  // Capsid's flows (design section 4): walks the explorer animates. Optional, as Capsid's own
  // schema has it, so a model written before flows existed still parses. Not drawn here.
  flows: z
    .array(
      z.strictObject({
        id: Id,
        name: Text(60),
        description: Text(280).optional(),
        steps: z
          .array(
            z.strictObject({
              relationship: Text(200),
              toward: Id,
              text: Text(280),
              lights: z.array(Id).max(8).optional(),
            }),
          )
          .min(2)
          .max(20),
      }),
    )
    .optional(),
  counts: z.strictObject({
    systems: z.number().int(),
    public: z.number().int(),
    private: z.number().int(),
    containers: z.number().int(),
    relationships: z.number().int(),
  }),
});

/** @typedef {z.infer<typeof PublicModel>} SystemModel */
/** @typedef {SystemModel["systems"][number]} ModelSystem */

/**
 * The model, or the reasons it is refused. Beyond the shape: ids are unique, every
 * relationship and container names something that exists, and every flow rides lines the
 * model has.
 * @param {unknown} raw
 * @returns {{ ok: true, model: SystemModel } | { ok: false, problems: string[] }}
 */
export function parseSystemModel(raw) {
  const parsed = PublicModel.safeParse(raw);
  if (!parsed.success)
    return {
      ok: false,
      problems: parsed.error.issues.map((i) => `${i.path.join(".") || "(model)"}: ${i.message}`),
    };
  const model = parsed.data;
  const problems = [];
  const systems = new Map(model.systems.map((s) => [s.id, s]));
  const containers = new Map(model.containers.map((c) => [c.id, c]));
  if (systems.size !== model.systems.length) problems.push("systems: an id is used twice");
  if (containers.size !== model.containers.length) problems.push("containers: an id is used twice");
  for (const c of model.containers) {
    if (!systems.has(c.system)) problems.push(`containers.${c.id}: no system ${c.system}`);
  }
  for (const r of model.relationships) {
    for (const end of [r.from, r.to]) {
      if (!systems.has(end) && !containers.has(end))
        problems.push(`relationships.${r.id}: no element ${end}`);
    }
  }
  const edges = new Map(model.relationships.map((r) => [r.id, r]));
  const flowIds = new Set();
  for (const f of model.flows ?? []) {
    if (flowIds.has(f.id)) problems.push(`flows.${f.id}: the id is used twice`);
    flowIds.add(f.id);
    f.steps.forEach((step, i) => {
      const where = `flows.${f.id}.steps.${i + 1}`;
      const edge = edges.get(step.relationship);
      if (!edge) {
        problems.push(
          `${where}: rides ${step.relationship}, which is not a relationship in the model`,
        );
        return;
      }
      if (step.toward !== edge.from && step.toward !== edge.to)
        problems.push(`${where}: goes toward ${step.toward}, which is not an end of ${edge.id}`);
      // A light is a part the step touches, in a system one of its ends belongs to (Capsid's rule).
      const within = new Set([edge.from, edge.to].map((end) => containers.get(end)?.system ?? end));
      for (const l of step.lights ?? []) {
        const part = containers.get(l);
        if (!part) problems.push(`${where}: lights ${l}, which is not a container`);
        else if (!within.has(part.system))
          problems.push(
            `${where}: lights ${l}, a part of ${part.system}, which the step does not run in`,
          );
      }
    });
  }
  const counts = model.counts;
  const privates = model.systems.filter((s) => s.private).length;
  if (
    counts.systems !== model.systems.length ||
    counts.private !== privates ||
    counts.public !== model.systems.length - privates ||
    counts.containers !== model.containers.length ||
    counts.relationships !== model.relationships.length
  ) {
    problems.push("counts: do not match the systems");
  }
  return problems.length ? { ok: false, problems } : { ok: true, model };
}

/**
 * The checked model, or a thrown error naming every problem: a bad file stops the build.
 * @param {unknown} raw
 */
export function loadSystemModel(raw) {
  const result = parseSystemModel(raw);
  if (!result.ok)
    throw new Error(`data/system-model.json is refused:\n  ${result.problems.join("\n  ")}`);
  return result.model;
}

/** The page of one system: Capsomer's system map at level 2. @param {string} id */
export const systemPath = (id) => `${SYSTEMS_PATH}/${encodeURIComponent(id)}`;

/**
 * The Capsid explorer, built from the same public model, so every system here has a page
 * there under the same id, private ones included (design section 4, "Deep links both ways").
 */
export const EXPLORER_ORIGIN = "https://capsid.dustinedwards.info";
/** @param {string} id */
export const explorerUrl = (id) => `${EXPLORER_ORIGIN}/s/${id}/`;
/** How a page shows that address, as it shows the others: host and path. @param {string} id */
export const explorerLabel = (id) => `${new URL(EXPLORER_ORIGIN).host}/s/${id}`;

/**
 * What Capsomer's map shows, the same as the explorer's (Capsomer's modelMapData): every system, linking to its own
 * page here, every line and the parts.
 * @param {SystemModel} model
 */
export const mapData = (model) => modelMapData(model, systemPath);

// How a line reads from each end.
/** @type {Record<SystemModel["relationships"][number]["kind"], [string, string]>} */
const VERB = {
  installs: ["installs", "is installed by"],
  "publishes-to": ["publishes to", "is published to by"],
  coordinates: ["coordinates", "is coordinated by"],
  watches: ["watches", "is watched by"],
  reads: ["reads", "is read by"],
  writes: ["writes to", "is written to by"],
  deploys: ["deploys", "is deployed by"],
  serves: ["serves", "is served by"],
};

/**
 * One system's connections to other systems, in the model's order: the verb as read from this
 * end, and the system at the other.
 * @param {SystemModel} model
 * @param {string} id
 * @returns {Array<{ verb: string, other: string, name: string }>}
 */
export function connectionsOf(model, id) {
  const byId = new Map(model.systems.map((s) => [s.id, s]));
  return model.relationships
    .filter(
      (r) =>
        (r.from === id || r.to === id) && byId.has(r.from) && byId.has(r.to) && r.from !== r.to,
    )
    .map((r) => {
      const out = r.from === id;
      const other = /** @type {ModelSystem} */ (byId.get(out ? r.to : r.from));
      const verb = VERB[r.kind][out ? 0 : 1];
      return {
        verb: `${verb.charAt(0).toUpperCase()}${verb.slice(1)}`,
        other: other.id,
        name: other.name,
      };
    });
}

/** @type {Record<ModelSystem["ring"], string>} */
const RING_HEADINGS = { core: "Runs everything", shared: "Shared parts", used: "What people use" };

/**
 * A system's parts, in the model's order.
 * @param {SystemModel} model
 * @param {string} id
 */
export const partsOf = (model, id) =>
  model.containers.filter((c) => c.system === id && c.kind !== "external");
/**
 * What a system works with outside its boundary: its `external` containers, such as Capsid's
 * Agents and GitHub (Dustin, 2026-10-11), never counted among its own parts.
 * @param {SystemModel} model
 * @param {string} id
 */
export const outsideOf = (model, id) =>
  model.containers.filter((c) => c.system === id && c.kind === "external");

/**
 * The lines touching a system's parts, to each other or to what is outside it, as sentences
 * ("MCP Worker writes to capsid"), in the model's order.
 * @param {SystemModel} model
 * @param {string} id
 */
export function wiresOf(model, id) {
  // A line to what is outside the system counts too (the Worker serves the Agents); a line
  // between two outside things does not, since it touches none of the system's parts.
  const own = new Set(partsOf(model, id).map((c) => c.id));
  const parts = new Map(model.containers.filter((c) => c.system === id).map((c) => [c.id, c]));
  return model.relationships
    .filter((r) => parts.has(r.from) && parts.has(r.to) && (own.has(r.from) || own.has(r.to)))
    .map((r) => `${parts.get(r.from)?.name} ${VERB[r.kind][0]} ${parts.get(r.to)?.name}`);
}

/**
 * One container as the twin and the page write it: name, what it runs on, what it does.
 * @param {SystemModel["containers"][number]} c
 */
const containerLine = (c) =>
  `${c.name} (${c.technology})${c.description ? `: ${c.description}` : ""}`;

/**
 * What a system's page says about it: its sentence, and that its repo is private when it is.
 * @param {{ description?: string, private?: boolean }} s a system in the model or on the map
 */
const summaryOf = (s) =>
  [s.description, s.private ? "Its repo is private." : undefined].filter(Boolean).join(" ");

/**
 * The repo link a public system shows: its first repo, unless it has none.
 * @param {ModelSystem} s
 */
export const repoOf = (s) => (s.private ? undefined : s.repos?.[0]);

/**
 * The markdown twin of /systems: every system, grouped by ring, each with the facts the page shows
 * on its page, so an agent reads what a person does.
 * @param {SystemModel} model
 * @param {string} origin
 */
export function systemsMarkdown(model, origin) {
  const lines = [
    "# Systems",
    "",
    `The systems Dustin Edwards runs. Public model of ${model.as_of}.`,
    "",
  ];
  for (const ring of RINGS) {
    const inRing = model.systems.filter((s) => s.ring === ring);
    if (inRing.length === 0) continue;
    lines.push(`## ${RING_HEADINGS[ring]}`, "");
    for (const s of inRing) lines.push(systemSectionMarkdown(model, s.id, origin) ?? "");
  }
  lines.push(`Capsid explorer: ${EXPLORER_ORIGIN}/`, "");
  return lines.join("\n");
}

/**
 * One system's section of /systems.md: what its page shows.
 * @param {SystemModel} model
 * @param {string} id
 * @param {string} origin
 */
export function systemSectionMarkdown(model, id, origin) {
  const s = model.systems.find((x) => x.id === id);
  if (!s) return null;
  const lines = [`### ${s.name}${s.private ? " (private)" : ""}`, ""];
  lines.push(summaryOf(s), "");
  lines.push(`- Its page: ${origin}${systemPath(s.id)}`);
  if (s.domain) lines.push(`- Address: https://${s.domain}`);
  const repo = repoOf(s);
  if (repo) lines.push(`- Source: ${repo}`);
  lines.push(`- In the Capsid explorer: ${explorerUrl(s.id)}`);
  const parts = partsOf(model, id);
  const outside = outsideOf(model, id);
  if (parts.length) lines.push("", "#### Inside", "", ...parts.map((c) => `- ${containerLine(c)}`));
  if (outside.length)
    lines.push("", "#### Outside it", "", ...outside.map((c) => `- ${containerLine(c)}`));
  const wires = wiresOf(model, id);
  if (wires.length) lines.push("", "How they connect:", "", ...wires.map((w) => `- ${w}`));
  const links = connectionsOf(model, id);
  lines.push("", "#### Connections", "");
  if (links.length === 0) lines.push("No connections.");
  for (const c of links) lines.push(`- ${c.verb} [${c.name}](${origin}${systemPath(c.other)})`);
  lines.push("");
  return lines.join("\n");
}

/**
 * Whether two models say the same thing. The date is left out: Capsid stamps its build every
 * day, and a pull request a day that changes only the date would teach a reviewer to skip them.
 * @param {SystemModel} a
 * @param {SystemModel} b
 */
export function sameModel(a, b) {
  const { as_of: _a, ...restA } = a;
  const { as_of: _b, ...restB } = b;
  return JSON.stringify(restA) === JSON.stringify(restB);
}

app/kb/form.mjs.source:
// The Knowledge Base's form editor, the part that needs no runtime (docs/KNOWLEDGE-BASE.md): a file read into a form's
// model, and a form's model written back into the file. The file stays the source, so what the form
// writes goes through the same save and the same checks as the raw editor. What the form did not touch is written back
// byte for byte: a front-matter field whose value is unchanged keeps the text it was written in, and a step keeps its
// lines, so a save from the form changes only what was changed. formToFile(fileToForm(raw)) === raw for every file.

import matter from "gray-matter";

import { yamlPlain } from "../lib/yaml-plain.mjs";

/** YAML through gray-matter, the reader every content file is parsed with, so the form reads a field as the compile does. */
const yaml = {
  /** @param {string} text */
  load: (text) => /** @type {Record<string, unknown>} */ (matter(`---\n${text}\n---\n`).data),
  /** @param {Record<string, unknown>} value */
  dump: (value) =>
    matter
      .stringify("", value)
      .replace(/^---\n/, "")
      .replace(/\n---\n*$/, "\n"),
};

/**
 * @typedef {{ kind: string, text: string, indent: string } | { raw: string }} StepLine
 * @typedef {{ number: number, text: string, lines: StepLine[], blanksBefore: number }} FormStep
 * @typedef {{ type: "prose", text: string } | { type: "steps", start: number, steps: FormStep[] }} FormBlock
 * @typedef {{ heading: string, blocks: FormBlock[] }} FormSection
 * @typedef {{ intro: string, sections: FormSection[] }} FormBody
 * @typedef {{ data: Record<string, unknown>, order: string[], body: FormBody | null }} FormModel
 */

/** The step flags the procedure format has (docs/PROCEDURES.md), in the order the form offers them. */
export const STEP_FLAGS = /** @type {const} */ ([
  "CRITICAL",
  "PAUSE POINT",
  "WHY",
  "EXPECT",
  "SPIN",
  "TROUBLESHOOTING",
  "CALC",
  "CHALLENGE",
  "SOLUTION",
]);

const FRONT = /^---\r?\n([\s\S]*?)\r?\n---(\r?\n|$)/;
const KEY = /^([A-Za-z_][\w-]*):(?:\s|$)/;
const DAY = /^\d{4}-\d{2}-\d{2}$/;

/** Equal as data, whatever order an object's keys came in. @param {unknown} a @param {unknown} b @returns {boolean} */
function sameValue(a, b) {
  if (Array.isArray(a) || Array.isArray(b)) {
    return (
      Array.isArray(a) &&
      Array.isArray(b) &&
      a.length === b.length &&
      a.every((x, i) => sameValue(x, b[i]))
    );
  }
  if (a && b && typeof a === "object" && typeof b === "object") {
    const ka = Object.keys(a);
    const kb = Object.keys(b);
    return (
      ka.length === kb.length &&
      ka.every((k) => sameValue(/** @type {any} */ (a)[k], /** @type {any} */ (b)[k]))
    );
  }
  return a === b;
}

/**
 * The file's front matter, split into each top-level field's own text. Lines before the first field (a comment) are
 * kept as the prelude.
 *
 * @param {string} raw
 */
export function splitFile(raw) {
  const match = FRONT.exec(raw);
  if (!match) throw new Error("the file does not start with front matter between --- lines");
  const lines = (match[1] ?? "").split(/\r?\n/);
  /** @type {string[]} */
  const prelude = [];
  /** @type {Array<{ key: string, text: string }>} */
  const fields = [];
  for (const line of lines) {
    const key = KEY.exec(line);
    if (key) fields.push({ key: /** @type {string} */ (key[1]), text: line });
    else if (fields.length > 0)
      /** @type {{ text: string }} */ (fields[fields.length - 1]).text += `\n${line}`;
    else prelude.push(line);
  }
  return { prelude, fields, after: match[2] ?? "\n", body: raw.slice(match[0].length) };
}

/** One field's value, read from its own text. @param {string} text */
function readField(text) {
  const parsed = yaml.load(text);
  return parsed && typeof parsed === "object" ? yamlPlain(Object.values(parsed)[0]) : undefined;
}

/** A plain one-line string YAML reads back as itself, unquoted. @param {string} value */
function bare(value) {
  if (value === "" || value !== value.trim() || /[\n:#]|^[-?[\]{},&*!|>'"%@`]/.test(value))
    return false;
  try {
    return yaml.load(`v: ${value}`)["v"] === value;
  } catch {
    return false;
  }
}

/** A field written fresh, for a value the form changed. @param {string} key @param {unknown} value */
function writeField(key, value) {
  if (typeof value === "string") {
    if (DAY.test(value) || bare(value)) return `${key}: ${value}`;
    return `${key}: ${JSON.stringify(value)}`;
  }
  if (typeof value === "number" || typeof value === "boolean") return `${key}: ${value}`;
  return yaml.dump({ [key]: value }).replace(/\n$/, "");
}

/**
 * A step list's own lines: a numbered item, then its indented lines (flags, commands, wrapped words), with the blank
 * lines inside the list kept where they were.
 *
 * @param {string[]} lines
 * @param {number} i the index of the item line
 */
function readStep(lines, i) {
  const item = /^(\d+)\.\s+(.*)$/.exec(lines[i] ?? "");
  /** @type {StepLine[]} */
  const stepLines = [];
  let j = i + 1;
  while (j < lines.length) {
    const next = lines[j] ?? "";
    if (/^\s{2,}\S/.test(next)) {
      const flag =
        /^(\s+)>\s*(CRITICAL|PAUSE POINT|WHY|TROUBLESHOOTING|EXPECT|SPIN|CALC|CHALLENGE|SOLUTION)\s*:\s?(.*)$/.exec(
          next,
        );
      // A flag is the form's to edit when its line is exactly what the form would write back.
      if (flag && next === `${flag[1]}> ${flag[2]}: ${flag[3]}`)
        stepLines.push({
          kind: /** @type {string} */ (flag[2]),
          text: flag[3] ?? "",
          indent: flag[1] ?? "   ",
        });
      else stepLines.push({ raw: next });
      j += 1;
    } else if (next.trim() === "" && /^\s{2,}\S/.test(lines[j + 1] ?? "")) {
      stepLines.push({ raw: next });
      j += 1;
    } else break;
  }
  return {
    step: { number: Number(item?.[1]), text: item?.[2] ?? "", lines: stepLines, blanksBefore: 0 },
    next: j,
  };
}

/** A section's lines as blocks: step lists, and everything else as prose kept line for line. @param {string[]} lines */
function readBlocks(lines) {
  /** @type {FormBlock[]} */
  const blocks = [];
  /** @type {string[]} */
  let prose = [];
  let inFence = false;
  let i = 0;
  const flush = () => {
    if (prose.length > 0) blocks.push({ type: "prose", text: prose.join("\n") });
    prose = [];
  };
  while (i < lines.length) {
    const text = lines[i] ?? "";
    if (text.startsWith("```")) inFence = !inFence;
    if (!inFence && /^\d+\.\s/.test(text)) {
      flush();
      /** @type {FormStep[]} */
      const steps = [];
      let blanks = 0;
      while (i < lines.length && /^\d+\.\s/.test(lines[i] ?? "")) {
        const { step, next } = readStep(lines, i);
        steps.push({ ...step, blanksBefore: blanks });
        i = next;
        // Blank lines between two items keep the list going; any other line ends it.
        blanks = 0;
        let k = i;
        while (k < lines.length && (lines[k] ?? "").trim() === "") k += 1;
        if (k > i && /^\d+\.\s/.test(lines[k] ?? "")) {
          blanks = k - i;
          i = k;
        }
      }
      blocks.push({ type: "steps", start: steps[0]?.number ?? 1, steps });
      continue;
    }
    prose.push(text);
    i += 1;
  }
  flush();
  return blocks;
}

/**
 * A procedure's body as the form shows it: the intro, then each `## ` section with its prose and its steps.
 *
 * @param {string} body
 * @returns {FormBody}
 */
function readBody(body) {
  const lines = body.split("\n");
  /** @type {string[]} */
  const intro = [];
  /** @type {Array<{ heading: string, lines: string[] }>} */
  const raw = [];
  let inFence = false;
  for (const line of lines) {
    if (line.startsWith("```")) inFence = !inFence;
    if (!inFence && line.startsWith("## ")) raw.push({ heading: line.slice(3), lines: [] });
    else if (raw.length > 0)
      /** @type {{ lines: string[] }} */ (raw[raw.length - 1]).lines.push(line);
    else intro.push(line);
  }
  return {
    intro: intro.join("\n"),
    sections: raw.map((s) => ({ heading: s.heading, blocks: readBlocks(s.lines) })),
  };
}

/** A step's lines, numbered. @param {FormStep} step @param {number} number */
function writeStep(step, number) {
  const lines = [`${number}. ${step.text}`];
  for (const line of step.lines) {
    if ("raw" in line) lines.push(line.raw);
    else lines.push(`${line.indent || "   "}> ${line.kind}: ${line.text}`);
  }
  return [...Array(step.blanksBefore).fill(""), ...lines].join("\n");
}

/** The body the form describes. A step list is numbered from where it started, in the order the form put it. @param {FormBody} body */
function writeBody(body) {
  const parts = [body.intro];
  for (const section of body.sections) {
    const lines = [`## ${section.heading}`];
    for (const block of section.blocks) {
      if (block.type === "prose") lines.push(block.text);
      else lines.push(block.steps.map((step, i) => writeStep(step, block.start + i)).join("\n"));
    }
    parts.push(lines.join("\n"));
  }
  return parts.join("\n");
}

/**
 * A file as a form's model: every front-matter field's value, in the file's order, and for a procedure its body.
 *
 * @param {string} raw
 * @param {{ body?: boolean }} [options] body: false for a registry item, whose file is its front matter alone
 * @returns {FormModel}
 */
export function fileToForm(raw, options = {}) {
  const { fields, body } = splitFile(raw);
  /** @type {Record<string, unknown>} */
  const data = {};
  for (const field of fields) data[field.key] = readField(field.text);
  return {
    data,
    order: fields.map((f) => f.key),
    body: options.body === false ? null : readBody(body),
  };
}

/**
 * The file a form's model describes, written over the file it was read from: an unchanged field keeps its text, a
 * changed one is written fresh, a new one goes after the rest, and a field the form removed (undefined) is left out.
 *
 * @param {string} original
 * @param {FormModel} model
 */
export function formToFile(original, model) {
  const { prelude, fields, after, body } = splitFile(original);
  const known = new Map(fields.map((f) => [f.key, f.text]));
  const keys = [
    ...model.order.filter((k) => known.has(k) || k in model.data),
    ...Object.keys(model.data).filter((k) => !model.order.includes(k)),
  ];
  /** @type {string[]} */
  const out = [...prelude];
  for (const key of new Set(keys)) {
    const value = model.data[key];
    if (value === undefined) continue;
    const text = known.get(key);
    out.push(
      text !== undefined && sameValue(readField(text), value) ? text : writeField(key, value),
    );
  }
  return `---\n${out.join("\n")}\n---${after}${model.body ? writeBody(model.body) : body}`;
}

app/kb/registry/search-inputs.mjs.source:
// What the site's search finds for a registry item (docs/REGISTRY.md): one record per published item, so a search for a primer's
// sequence, its target, its reference or the paper that prints it finds the primer's own page as well as the protocols that use
// it. The record is derived from the item and nothing else, so a save, sync_registry and sync:content write the same text, and a
// draft has none. Like a paper's, it is one record with no deep links: an item has no sections to link to.

import { itemPath, primerRow, siteText } from "./catalog.mjs";
import { stated } from "./primer.mjs";
import { designationOf } from "./strain.mjs";

/** The item's search uid: a removal needs it to find the item's record. @param {string} kind @param {string} id */
export function registrySearchUid(kind, id) {
  // The registry: namespace keeps these uids separable from hand-authored pages and papers when search_docs is pruned.
  return `registry:${kind}/${id}`;
}

/**
 * The words a primer is searched by: what it is, its sequence and reverse complement (a sequence search finds either strand),
 * where it binds, and the paper that prints it. Only facts the record states or computes; a fact that could not be found is
 * not a word to find.
 *
 * @param {import("./kinds.mjs").RegistryItem} item
 */
function primerBody(item) {
  const row = primerRow(item);
  return [
    row.name,
    row.direction ? `${row.direction} primer` : "primer",
    row.sequence,
    row.reverseComplement,
    row.target,
    row.set,
    row.length ? `${row.length} nt` : null,
    row.placement ? `${row.placement.reference.id} ${row.placement.reference.description}` : null,
    ...(row.placement ? row.placement.sites.map(siteText) : []),
    row.publishedIn,
    row.publishedDoi,
    row.publishedName,
    row.publishedSequence,
  ]
    .filter(Boolean)
    .join(" ");
}

/**
 * The words a strain is searched by: its organism, designation, collection and number. The phages isolated on it are the
 * phages table's own records and are not copied into this one.
 *
 * @param {import("./kinds.mjs").RegistryItem} item
 */
function strainBody(item) {
  const f = /** @type {Record<string, unknown>} */ (item.fields);
  return [
    item.name,
    "strain",
    "host",
    stated(f.organism),
    designationOf(f),
    stated(f.collection),
    stated(f.collection_number),
  ]
    .filter(Boolean)
    .join(" ");
}

/**
 * The words a reagent is searched by: its name, what a protocol calls it or makes it of, and where it comes from. A gap is not a
 * word to find.
 *
 * @param {import("./kinds.mjs").RegistryItem} item
 */
function reagentBody(item) {
  const f = /** @type {Record<string, unknown>} */ (item.fields);
  return [
    item.name,
    "reagent",
    stated(f.abbreviation),
    stated(f.contents),
    f.prepared_in_lab === true ? "prepared in the lab" : null,
    stated(f.supplier),
    stated(f.catalog_number),
  ]
    .filter(Boolean)
    .join(" ");
}

/** The words an item of equipment is searched by: its name, who makes it and a centrifuge's rotor. @param {import("./kinds.mjs").RegistryItem} item */
function equipmentBody(item) {
  const f = /** @type {Record<string, unknown>} */ (item.fields);
  return [item.name, "equipment", stated(f.manufacturer), stated(f.rotor)]
    .filter(Boolean)
    .join(" ");
}

/** Each kind's search words. A kind with none is not indexed, so a kind added later is not indexed by accident. */
const BODIES =
  /** @type {Record<string, (item: import("./kinds.mjs").RegistryItem) => string>} */ ({
    primer: primerBody,
    strain: strainBody,
    reagent: reagentBody,
    equipment: equipmentBody,
  });

/**
 * The record input of one item, or null for a kind with no search body yet (so a kind added later is not indexed by accident).
 *
 * @param {import("./kinds.mjs").RegistryItem} item
 * @returns {{ uid: string, url: string, title: string, body: string } | null}
 */
export function registrySearchInput(item) {
  const body = BODIES[item.kind]?.(item) ?? null;
  if (body === null) return null;
  return {
    uid: registrySearchUid(item.kind, item.id),
    url: itemPath(item.kind, item.id),
    title: item.name,
    body,
  };
}

/** The inputs of every published item that has one, for the build's search artifact. @param {import("./kinds.mjs").RegistryItem[]} items */
export function registrySearchInputs(items) {
  return items.flatMap((item) => {
    if (item.status === "draft") return [];
    const input = registrySearchInput(item);
    return input ? [input] : [];
  });
}

