// The one validation module for the CV (docs/CV.md). CI (build:content, test/cv.test.mjs), sync:content and the
// CV save all call it, so a file CI passes is the file a save accepts. It holds a file to its shape, to the
// privacy rules, to the house style (no wide dash) and, once the files are joined to the publications, to the
// rules that need the whole CV: a cited paper exists and lists Dustin, and each section reads newest first.
// Pure: no Env, no filesystem, no clock beyond the year bound below.

import matter from "gray-matter";

import { findWideDashes } from "../content/wide-dash.mjs";
import { canonicalAuthor } from "../publications/authors.mjs";
import { AREAS, ROLES } from "./view.mjs";

const AREA_IDS = new Set(AREAS.map(([id]) => /** @type {string} */ (id)));
const ROLE_IDS = new Set(ROLES.map(([id]) => /** @type {string} */ (id)));

/** The owner, whom every paper the CV claims must list (as the CV's role for it is read from the author list). */
const OWNER = "Dustin Edwards";

/** The edition stamp the CV prints: a season and a year, as "Fall 2026". */
const EDITION_PATTERN = /^(Spring|Summer|Fall|Winter) (\d{4})$/;

/** Entries are dated between these years, so a typo such as 2205 is refused rather than charted. */
const YEAR_MIN = 1950;
const YEAR_MAX = 2100;

const DOI_PATTERN = /^10\.\d{4,9}\/\S+$/;
const HTTPS = /^https:\/\/\S+$/;

/** The sections an appointment or a service line sits under, in the order the CV prints them. */
const APPOINTMENT_SECTIONS = ["Positions", "Administrative and leadership"];
const SERVICE_SECTIONS = [
  "Department",
  "College",
  "University",
  "Professional",
  "Community",
  "Compensated professional consulting",
  "Professional memberships",
];

/**
 * What no CV line may carry (the privacy rules): an email, a phone number, a room, a private community group.
 * Read from the values, so a comment explaining the rule cannot trip it.
 */
const PRIVACY = /** @type {const} */ ([
  [/@[a-z0-9-]+\.[a-z]{2,}/i, "an email address"],
  [/\(\d{3}\)\s*\d{3}-\d{4}|\b\d{3}-\d{3}-\d{4}\b/, "a phone number"],
  [/\bRoom\b|\bSuite\b|\bOffice \d/i, "a room"],
  [/Mountains Lake/i, "a private community group"],
]);

/**
 * A field's kind, for one entry type: `s` a non-empty string, `n` a non-negative integer, `money` US dollars to the cent, `b` a boolean, and
 * a trailing `?` makes it optional. The shared fields (year, endYear, areas, role, links) are checked apart.
 */
const SHAPES = /** @type {const} */ ({
  appointment: {
    section: "s",
    title: "s",
    org: "s",
    detail: "s?",
    duties: "duties?",
    headline: "b?",
  },
  education: { title: "s", org: "s", detail: "s?" },
  grant: { amount: "money", title: "s", funder: "s?", note: "s?" },
  award: { title: "s", org: "s?", place: "s?" },
  talk: { title: "s", presenters: "strings", venue: "s" },
  course: { code: "s", title: "s", org: "s", term: "s" },
  mentoring: {
    section: "s",
    count: "n",
    unit: "unit",
    level: "s",
    program: "s",
    org: "s",
    detail: "s?",
    cohort: "b",
  },
  service: { section: "s", title: "s", org: "s?", place: "s?" },
  development: { title: "s", org: "s?", place: "s?" },
});

/** The inline paper (one the site has no record for) states its own citation. */
const INLINE_PAPER = /** @type {const} */ ({
  title: "s",
  authors: "strings",
  journal: "s",
  volume: "s?",
  issue: "s?",
  pages: "s?",
});

const SHARED_KEYS = ["year", "endYear", "areas", "role", "links"];

/** @param {unknown} value @returns {value is Record<string, unknown>} */
const isRecord = (value) => typeof value === "object" && value !== null && !Array.isArray(value);

/** @param {unknown} value */
const isText = (value) => typeof value === "string" && value.length > 0 && value === value.trim();

/** @param {unknown} value @returns {value is number} */
const isCount = (value) => typeof value === "number" && Number.isInteger(value) && value >= 0;

/**
 * @param {unknown} value
 * @param {string} kind
 * @returns {string | null} a reason, or null when the value fits
 */
function misfit(value, kind) {
  const optional = kind.endsWith("?");
  const base = optional ? kind.slice(0, -1) : kind;
  if (value === undefined) return optional ? null : "is missing";
  switch (base) {
    case "s":
      return isText(value) ? null : "must be non-empty text with no space at either end";
    case "n":
      return isCount(value) ? null : "must be a whole number, zero or more";
    case "money":
      return typeof value === "number" &&
        Number.isFinite(value) &&
        value >= 0 &&
        Math.round(value * 100) === value * 100
        ? null
        : "must be dollars, zero or more, to the cent";
    case "b":
      return typeof value === "boolean" ? null : "must be true or false";
    case "strings":
      return Array.isArray(value) && value.length > 0 && value.every(isText)
        ? null
        : "must be a non-empty list of text";
    case "unit":
      return value === "students" || value === "awards" ? null : 'must be "students" or "awards"';
    case "duties":
      return Array.isArray(value) &&
        value.length > 0 &&
        value.every(
          (duty) =>
            isRecord(duty) &&
            Object.keys(duty).every((key) => key === "heading" || key === "items") &&
            isText(duty.heading) &&
            Array.isArray(duty.items) &&
            duty.items.length > 0 &&
            duty.items.every(isText),
        )
        ? null
        : "must be a non-empty list of { heading, items } with items a non-empty list of text";
    default:
      throw new Error(`cv validate: unknown field kind ${kind}`);
  }
}

/**
 * @param {Record<string, unknown>} entry
 * @param {Record<string, string>} shape
 * @param {string} where
 * @param {string[]} errors
 */
function checkShape(entry, shape, where, errors) {
  for (const [key, kind] of Object.entries(shape)) {
    const reason = misfit(entry[key], kind);
    if (reason) errors.push(`${where}: ${key} ${reason}`);
  }
}

/**
 * The fields every dated entry carries, and the keys it may not.
 *
 * @param {Record<string, unknown>} entry
 * @param {string} where
 * @param {string[]} errors
 */
function checkShared(entry, where, errors) {
  const { year, endYear, areas, role, links } = entry;
  const yearOk =
    year === null ||
    (typeof year === "number" && Number.isInteger(year) && year >= YEAR_MIN && year <= YEAR_MAX);
  if (!yearOk)
    errors.push(
      `${where}: year must be a whole year from ${YEAR_MIN} to ${YEAR_MAX}, or null for an undated line`,
    );
  if (endYear !== undefined) {
    if (year === null) errors.push(`${where}: an undated line (year: null) has no endYear`);
    else if (
      endYear !== "present" &&
      !(typeof endYear === "number" && Number.isInteger(endYear) && endYear <= YEAR_MAX)
    ) {
      errors.push(`${where}: endYear must be a whole year or "present"`);
    } else if (typeof endYear === "number" && typeof year === "number" && endYear < year) {
      errors.push(`${where}: endYear ${endYear} is before year ${year}`);
    }
  }
  if (!Array.isArray(areas) || !areas.every((a) => typeof a === "string" && AREA_IDS.has(a))) {
    errors.push(`${where}: areas must be a list (empty is allowed) of ${[...AREA_IDS].join(", ")}`);
  } else if (new Set(areas).size !== areas.length) {
    errors.push(`${where}: areas names one area twice`);
  }
  if (role !== null && !(typeof role === "string" && ROLE_IDS.has(role))) {
    errors.push(`${where}: role must be null or one of ${[...ROLE_IDS].join(", ")}`);
  }
  if (links !== undefined) {
    const linksOk =
      Array.isArray(links) &&
      links.length > 0 &&
      links.every(
        (l) =>
          isRecord(l) &&
          Object.keys(l).length === 2 &&
          isText(l.label) &&
          typeof l.href === "string" &&
          HTTPS.test(l.href),
      );
    if (!linksOk)
      errors.push(`${where}: links must be a non-empty list of { label, href } with an https href`);
  }
}

/**
 * One entry of a section file, held to its type's shape.
 *
 * @param {import("./types.ts").CvType} type
 * @param {unknown} entry
 * @param {string} where
 * @param {string[]} errors
 */
function checkEntry(type, entry, where, errors) {
  if (!isRecord(entry)) {
    errors.push(`${where}: an entry is a mapping of fields`);
    return;
  }
  if ("type" in entry)
    errors.push(`${where}: an entry does not state its type; the file's front matter does`);

  if (type === "publication" && "doi" in entry) {
    for (const key of Object.keys(entry)) {
      if (key !== "doi") {
        errors.push(
          `${where}: a paper named by DOI states nothing else (${key}); its facts come from content/publications/`,
        );
      }
    }
    if (typeof entry.doi !== "string" || !DOI_PATTERN.test(entry.doi))
      errors.push(`${where}: doi is not a DOI`);
    return;
  }

  /** @type {Record<string, string>} */
  const shape =
    type === "publication"
      ? INLINE_PAPER
      : SHAPES[/** @type {Exclude<typeof type, "publication">} */ (type)];
  checkShape(entry, shape, where, errors);
  checkShared(entry, where, errors);
  const known = new Set([...Object.keys(shape), ...SHARED_KEYS]);
  for (const key of Object.keys(entry)) {
    if (!known.has(key)) errors.push(`${where}: "${key}" is not a field of a ${type} entry`);
  }
  if (
    type === "appointment" &&
    !APPOINTMENT_SECTIONS.includes(/** @type {string} */ (entry.section))
  ) {
    errors.push(`${where}: section must be one of ${APPOINTMENT_SECTIONS.join(", ")}`);
  }
  if (type === "service" && !SERVICE_SECTIONS.includes(/** @type {string} */ (entry.section))) {
    errors.push(`${where}: section must be one of ${SERVICE_SECTIONS.join(", ")}`);
  }
}

/**
 * The profile: the edition stamp, the person and the presentation totals.
 *
 * @param {Record<string, unknown>} data
 * @param {string[]} errors
 */
function checkProfile(data, errors) {
  const { edition, person, presentations } = data;
  for (const key of Object.keys(data)) {
    if (!["edition", "person", "presentations"].includes(key))
      errors.push(`profile: "${key}" is not a field of the profile`);
  }
  if (typeof edition !== "string" || !EDITION_PATTERN.test(edition)) {
    errors.push('edition must be a season and a year, such as "Fall 2026"');
  }
  if (!isRecord(person)) {
    errors.push("person must be a mapping of name, degree, discipline, department and org");
  } else {
    for (const key of ["name", "degree", "discipline", "department", "org"]) {
      if (!isText(person[key]))
        errors.push(`person.${key} must be non-empty text with no space at either end`);
    }
    for (const key of Object.keys(person)) {
      if (!["name", "degree", "discipline", "department", "org"].includes(key)) {
        errors.push(
          key === "title"
            ? "person.title is not a field of the person: the title is derived from the current appointment and the discipline (app/lib/identity.mjs)"
            : `person.${key} is not a field of the person`,
        );
      }
    }
    if (person.name !== OWNER)
      errors.push(
        `person.name is "${String(person.name)}", the site's one name for him is "${OWNER}"`,
      );
  }
  if (!isRecord(presentations)) {
    errors.push("presentations must be a mapping of international, national, from and to");
  } else {
    for (const key of ["international", "national"]) {
      if (!isCount(presentations[key]))
        errors.push(`presentations.${key} must be a whole number, zero or more`);
    }
    for (const key of ["from", "to"]) {
      const value = presentations[key];
      if (
        !(
          typeof value === "number" &&
          Number.isInteger(value) &&
          value >= YEAR_MIN &&
          value <= YEAR_MAX
        )
      ) {
        errors.push(`presentations.${key} must be a whole year from ${YEAR_MIN} to ${YEAR_MAX}`);
      }
    }
    for (const key of Object.keys(presentations)) {
      if (!["international", "national", "from", "to"].includes(key))
        errors.push(`presentations.${key} is not a field of the presentations`);
    }
    if (
      typeof presentations.from === "number" &&
      typeof presentations.to === "number" &&
      presentations.from > presentations.to
    ) {
      errors.push("presentations.from is after presentations.to");
    }
  }
}

/**
 * Parses and judges one CV file.
 *
 * @param {{ slug: string, type: import("./types.ts").CvType | "profile" }} file the registry's entry for it
 * @param {string} raw the whole file, front matter included
 * @returns {{ ok: false, errors: string[] } | { ok: true, errors: [], record: import("./types.ts").CvFileRecord }}
 */
export function parseCvFile(file, raw) {
  /** @type {string[]} */
  const errors = [];
  for (const hit of findWideDashes(raw)) {
    errors.push(
      `line ${hit.line}, column ${hit.column}: wide dash ${hit.char}; house style uses commas, periods, parentheses or colons ("${hit.excerpt}")`,
    );
  }
  let parsed;
  try {
    parsed = matter(raw);
  } catch (error) {
    return {
      ok: false,
      errors: [
        ...errors,
        `the front matter is not valid YAML: ${error instanceof Error ? error.message : String(error)}`,
      ],
    };
  }
  const data = /** @type {Record<string, unknown>} */ (parsed.data);
  if (parsed.content.trim() !== "")
    errors.push(
      "the file has text after its front matter, which no page shows; the CV is the front matter alone",
    );

  const { slug, type } = file;
  if (type === "profile") {
    checkProfile(data, errors);
  } else {
    for (const key of Object.keys(data)) {
      if (key !== "type" && key !== "entries")
        errors.push(`"${key}" is not a field of a section file (type, entries)`);
    }
    if (data.type !== type)
      errors.push(`type is ${JSON.stringify(data.type)}, but ${slug} holds ${type} entries`);
    if (!Array.isArray(data.entries) || data.entries.length === 0) {
      errors.push("entries must be a non-empty list");
    } else {
      data.entries.forEach((entry, i) => checkEntry(type, entry, `entries[${i}]`, errors));
    }
  }

  // The privacy rules read the values, not the comments: JSON of what the file states.
  const values = JSON.stringify(data);
  for (const [pattern, what] of PRIVACY) {
    if (pattern.test(values)) errors.push(`the file carries ${what}; the CV never does`);
  }
  if (errors.length > 0) return { ok: false, errors };

  /** @type {import("./types.ts").CvFileRecord} */
  const record =
    type === "profile"
      ? {
          slug: "profile",
          type: "profile",
          edition: /** @type {string} */ (data.edition),
          person: /** @type {import("./types.ts").CvPerson} */ (data.person),
          presentations: /** @type {import("./types.ts").CvPresentations} */ (data.presentations),
        }
      : {
          slug,
          type,
          // The file states the type once; each entry carries it from here on.
          entries: /** @type {Array<Record<string, unknown>>} */ (data.entries).map(
            (e) => /** @type {import("./types.ts").CvSourceEntry} */ ({ type, ...e }),
          ),
        };
  return { ok: true, errors: [], record };
}

/**
 * The paper references against the publication records: each DOI exists as a published paper, appears once,
 * and the paper lists the owner among its authors (the CV cannot claim a paper he did not write).
 *
 * @param {import("./types.ts").CvSourceEntry[]} entries
 * @param {Map<string, import("../publications/types.ts").Publication>} byDoi the published records by lower-cased DOI
 * @returns {string[]}
 */
export function paperRefErrors(entries, byDoi) {
  /** @type {string[]} */
  const errors = [];
  const seen = new Set();
  for (const entry of entries) {
    if (entry.type !== "publication" || !("doi" in entry)) continue;
    const key = entry.doi.toLowerCase();
    if (seen.has(key)) errors.push(`DOI ${entry.doi} is listed twice`);
    seen.add(key);
    const paper = byDoi.get(key);
    if (!paper) {
      errors.push(
        `no published publication has DOI ${entry.doi}; add its file to content/publications/ first, and publish it`,
      );
    } else if (!paper.authors.some((name) => canonicalAuthor(name) === OWNER)) {
      errors.push(
        `DOI ${entry.doi} does not list ${OWNER} among its authors, so the CV cannot claim it`,
      );
    }
  }
  return errors;
}

/**
 * The types whose sections read newest first, undated lines last, so the page, the twin and the PDF agree on
 * an order the twin states for grants. Service and mentoring lines keep the CV's own order within a section (a
 * committee is listed with its chair first, a cohort by program), so the rule does not reach them.
 */
const NEWEST_FIRST_TYPES = [
  "appointment",
  "education",
  "publication",
  "grant",
  "award",
  "talk",
  "course",
  "development",
];

/**
 * Judged on the resolved entries, so a paper's year is the record's.
 *
 * @param {Array<{ id: string, type: string, section: string | null, year: number | null }>} entries
 * @returns {string[]}
 */
export function orderErrors(entries) {
  /** @type {string[]} */
  const errors = [];
  /** @type {Map<string, { year: number | null, id: string }>} */
  const last = new Map();
  for (const e of entries) {
    if (!NEWEST_FIRST_TYPES.includes(e.type)) continue;
    const key = `${e.type}/${e.section ?? ""}`;
    const before = last.get(key);
    if (before) {
      if (before.year === null && e.year !== null) {
        errors.push(
          `${e.id} is dated ${e.year} but follows the undated ${before.id}; undated lines come last in their section`,
        );
      } else if (before.year !== null && e.year !== null && e.year > before.year) {
        errors.push(
          `${e.id} (${e.year}) follows ${before.id} (${before.year}); each section reads newest first`,
        );
      }
    }
    last.set(key, { year: e.year, id: e.id });
  }
  return errors;
}

app/lib/cv/view.mjs.source:
/**
 * What the CV page shows for a filter state: the state's URL form, which entries match, how they are
 * grouped, the headline counts and the chart inputs. One module for both sides: the route computes the
 * first render from the query string (so a shared URL and a scripts-off reader get the same page), and
 * app/enhance/cv.ts recomputes it on every input. It never imports the data, so the enhancement bundle
 * carries none of it; each side hands in `Facts`.
 */

/** @typedef {import("./types.ts").CvType} CvType */
/** @typedef {import("./types.ts").CvArea} CvArea */
/** @typedef {import("./types.ts").CvRole} CvRole */

/**
 * @typedef {object} Facts what filtering, grouping and counting read from an entry
 * @property {string} id
 * @property {CvType} type
 * @property {string | null} section
 * @property {CvArea[]} areas
 * @property {CvRole | null} role
 * @property {number | null} year
 * @property {number | "present" | null} endYear
 * @property {number | null} students
 * @property {boolean} cohort
 * @property {number | null} amount
 * @property {number} order position in the source, the tiebreak everywhere
 * @property {string} search folded text
 */

/**
 * @typedef {object} CvState
 * @property {CvType[]} types empty means every type
 * @property {CvArea[]} areas empty means every area
 * @property {number | null} from
 * @property {number | null} to
 * @property {CvRole | null} role
 * @property {string} q
 * @property {"type" | "newest" | "oldest"} sort
 */

/** Traditional CV order, which is also the "by type" sort. */
export const TYPES = /** @type {const} */ ([
  ["appointment", "Appointment", "Appointments"],
  ["education", "Education", "Education"],
  ["publication", "Publication", "Publications"],
  ["grant", "Grant", "Grants"],
  ["award", "Award", "Fellowships and awards"],
  ["talk", "Invited talk", "Invited talks"],
  ["course", "Course", "Courses taught"],
  ["mentoring", "Mentoring", "Students mentored"],
  ["service", "Service", "Service"],
  ["development", "Professional development", "Professional development"],
]);

export const AREAS = /** @type {const} */ ([
  ["retroviruses", "Retroviruses"],
  ["bacteriophages", "Bacteriophages"],
  ["science-education", "Science education"],
  ["ai", "AI"],
]);

export const ROLES = /** @type {const} */ ([
  ["first-author", "First author"],
  ["senior-author", "Senior author"],
  ["co-author", "Co-author"],
  ["recipient", "Recipient"],
  ["speaker", "Speaker"],
  ["instructor", "Instructor"],
  ["mentor", "Mentor"],
  ["chair", "Chair"],
  ["organizer", "Organizer"],
  ["member", "Member"],
  ["editor", "Editor"],
  ["reviewer", "Reviewer"],
  ["judge", "Judge"],
  ["advisor", "Advisor"],
  ["volunteer", "Volunteer"],
  ["consultant", "Consultant"],
  ["participant", "Participant"],
]);

export const SORTS = /** @type {const} */ ([
  ["type", "Section"],
  ["newest", "Newest first"],
  ["oldest", "Oldest first"],
]);

/** The timeline figure's id, which Enarratio's `enarratio:select` events carry as `chartId`. */
export const TIMELINE_ID = "cv-timeline";

/** The types the timeline stacks, in stacking order; app/styles/cv.css colors the series in this order. */
export const CHART_SERIES = /** @type {const} */ ([
  ["publication", "Publications"],
  ["grant", "Grants"],
  ["talk", "Invited talks"],
  ["award", "Awards"],
]);

const TYPE_IDS = new Set(TYPES.map(([id]) => /** @type {string} */ (id)));
const AREA_IDS = new Set(AREAS.map(([id]) => /** @type {string} */ (id)));
const ROLE_IDS = new Set(ROLES.map(([id]) => /** @type {string} */ (id)));
const SORT_IDS = new Set(SORTS.map(([id]) => /** @type {string} */ (id)));

/** @param {CvType} type */
export function typeLabel(type, plural = false) {
  const row = TYPES.find(([id]) => id === type);
  if (!row) throw new Error(`cv: unknown type ${type}`);
  return plural ? row[2] : row[1];
}

/** @param {string} area */
export function areaLabel(area) {
  return AREAS.find(([id]) => id === area)?.[1] ?? area;
}

/** @param {string} role */
export function roleLabel(role) {
  return ROLES.find(([id]) => id === role)?.[1] ?? role;
}

/**
 * Lowercased with diacritics removed, so "Galvão" matches "galvao".
 *
 * @param {string} text
 */
export function foldText(text) {
  return String(text ?? "")
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}

/**
 * Whole dollars print without cents; the CV's cents are kept where it has them.
 *
 * @param {number} amount
 */
export function formatDollars(amount) {
  const cents = Math.round(amount * 100) % 100 !== 0;
  return `$${amount.toLocaleString("en-US", { minimumFractionDigits: cents ? 2 : 0, maximumFractionDigits: 2 })}`;
}

/** @returns {CvState} */
function defaultState() {
  return { types: [], areas: [], from: null, to: null, role: null, q: "", sort: "type" };
}

/**
 * Both spellings a list arrives in: repeated keys from the scripts-off form, commas from a hand-typed
 * URL. Unknown values are dropped rather than refused: a stale shared link still opens the CV.
 *
 * @param {URLSearchParams} params
 * @param {string} key
 * @param {Set<string>} known
 */
function listParam(params, key, known) {
  /** @type {string[]} */
  const out = [];
  for (const raw of params.getAll(key)) {
    for (const value of raw.split(",")) {
      const v = value.trim();
      if (known.has(v) && !out.includes(v)) out.push(v);
    }
  }
  return out;
}

/** @param {string | null} raw */
function yearParam(raw) {
  if (!raw || !/^\d{4}$/.test(raw.trim())) return null;
  return Number(raw.trim());
}

/**
 * @param {URLSearchParams} params
 * @returns {CvState}
 */
export function parseState(params) {
  const state = defaultState();
  state.types = /** @type {CvType[]} */ (listParam(params, "type", TYPE_IDS));
  state.areas = /** @type {CvArea[]} */ (listParam(params, "area", AREA_IDS));
  state.from = yearParam(params.get("from"));
  state.to = yearParam(params.get("to"));
  if (state.from !== null && state.to !== null && state.from > state.to) {
    [state.from, state.to] = [state.to, state.from];
  }
  const role = params.get("role") ?? "";
  state.role = ROLE_IDS.has(role) ? /** @type {CvRole} */ (role) : null;
  state.q = (params.get("q") ?? "").trim().slice(0, 100);
  const sort = params.get("sort") ?? "";
  state.sort = SORT_IDS.has(sort) ? /** @type {CvState["sort"]} */ (sort) : "type";
  return state;
}

/**
 * The canonical query string for a state: only what differs from the default, lists in their
 * vocabulary's order, so one filter has one URL. Repeated keys, as the scripts-off form submits them.
 *
 * @param {CvState} state
 */
export function stateToSearch(state) {
  const params = new URLSearchParams();
  for (const [id] of TYPES) if (state.types.includes(id)) params.append("type", id);
  for (const [id] of AREAS) if (state.areas.includes(id)) params.append("area", id);
  if (state.from !== null) params.set("from", String(state.from));
  if (state.to !== null) params.set("to", String(state.to));
  if (state.role) params.set("role", state.role);
  if (state.q) params.set("q", state.q);
  if (state.sort !== "type") params.set("sort", state.sort);
  const out = params.toString();
  return out ? `?${out}` : "";
}

/** @param {CvState} state */
export function isFiltered(state) {
  return (
    state.types.length > 0 ||
    state.areas.length > 0 ||
    state.from !== null ||
    state.to !== null ||
    state.role !== null ||
    state.q !== ""
  );
}

/**
 * An entry's span: an ongoing one runs forever, and an undated one has no span and matches no range.
 *
 * @param {Facts} f
 * @returns {[number, number] | null}
 */
function spanOf(f) {
  if (f.year === null) return null;
  const end = f.endYear === "present" ? Number.POSITIVE_INFINITY : (f.endYear ?? f.year);
  return [f.year, end];
}

/**
 * @param {Facts} f
 * @param {CvState} state
 * @param {{ ignoreYears?: boolean }} [options] the charts show every year and mark the range instead
 */
export function matches(f, state, options = {}) {
  if (state.types.length > 0 && !state.types.includes(f.type)) return false;
  if (state.areas.length > 0 && !f.areas.some((a) => state.areas.includes(a))) return false;
  if (state.role && f.role !== state.role) return false;
  if (!options.ignoreYears && (state.from !== null || state.to !== null)) {
    const span = spanOf(f);
    if (!span) return false;
    if (state.from !== null && span[1] < state.from) return false;
    if (state.to !== null && span[0] > state.to) return false;
  }
  if (state.q) {
    for (const word of foldText(state.q).split(" ")) {
      if (word && !f.search.includes(word)) return false;
    }
  }
  return true;
}

/**
 * @typedef {object} Group
 * @property {string} key
 * @property {string} heading
 * @property {{ key: string, heading: string | null, ids: string[] }[]} parts
 */

/**
 * How the entries sit on the page. By section: the CV's order, each type's subsections in the order
 * they first appear, newest first inside each. By date: one group per year, undated last.
 *
 * @param {Facts[]} facts every entry, matching or not: a hidden entry keeps its place
 * @param {CvState["sort"]} sort
 * @returns {Group[]}
 */
export function groupEntries(facts, sort) {
  const byYearDesc = (/** @type {Facts} */ a, /** @type {Facts} */ b) =>
    (b.year ?? -Infinity) - (a.year ?? -Infinity) || a.order - b.order;

  if (sort === "type") {
    /** @type {Group[]} */
    const groups = [];
    for (const [type, , plural] of TYPES) {
      const members = facts.filter((f) => f.type === type);
      if (members.length === 0) continue;
      /** @type {Map<string, Facts[]>} */
      const parts = new Map();
      for (const f of [...members].sort((a, b) => a.order - b.order)) {
        const key = f.section ?? "";
        if (!parts.has(key)) parts.set(key, []);
        parts.get(key)?.push(f);
      }
      groups.push({
        key: `type-${type}`,
        heading: plural,
        parts: [...parts].map(([section, list]) => ({
          key: `type-${type}-${section ? section.toLowerCase().replace(/[^a-z0-9]+/g, "-") : "all"}`,
          heading: section || null,
          ids: [...list].sort(byYearDesc).map((f) => f.id),
        })),
      });
    }
    return groups;
  }

  const typeRank = new Map(TYPES.map(([id], i) => [/** @type {string} */ (id), i]));
  const years = [...new Set(facts.map((f) => f.year))].sort((a, b) => {
    if (a === null) return 1;
    if (b === null) return -1;
    return sort === "newest" ? b - a : a - b;
  });
  return years.map((year) => ({
    key: `year-${year ?? "undated"}`,
    heading: year === null ? "Undated" : String(year),
    parts: [
      {
        key: `year-${year ?? "undated"}-all`,
        heading: null,
        ids: facts
          .filter((f) => f.year === year)
          .sort(
            (a, b) =>
              (typeRank.get(a.type) ?? 0) - (typeRank.get(b.type) ?? 0) || a.order - b.order,
          )
          .map((f) => f.id),
      },
    ],
  }));
}

/**
 * The headline counts for the matching entries.
 *
 * @param {Facts[]} shown
 */
export function headline(shown) {
  let papers = 0;
  let grants = 0;
  let dollars = 0;
  let students = 0;
  for (const f of shown) {
    if (f.type === "publication") papers += 1;
    if (f.type === "grant") {
      grants += 1;
      dollars += f.amount ?? 0;
    }
    if (f.type === "mentoring") students += f.students ?? 0;
  }
  return {
    papers,
    grants,
    dollars: Math.round(dollars * 100) / 100,
    students,
    entries: shown.length,
  };
}

/**
 * Inclusive, ascending.
 *
 * @param {number} from
 * @param {number} to
 */
function range(from, to) {
  const out = [];
  for (let y = from; y <= to; y += 1) out.push(y);
  return out;
}

/**
 * The year axis every chart shares: the first charted year in the whole CV to the last. Fixed across
 * filters, so bars do not slide sideways when a filter changes.
 *
 * @param {Facts[]} all
 */
export function chartYears(all) {
  const charted = new Set(CHART_SERIES.map(([id]) => /** @type {string} */ (id)));
  const years = all
    .filter((f) => f.year !== null && (charted.has(f.type) || (f.type === "mentoring" && f.cohort)))
    .map((f) => /** @type {number} */ (f.year));
  return range(Math.min(...years), Math.max(...years));
}

/**
 * The stacked timeline's input: output per start year by type, for entries matching every filter but
 * the year range, which the chart marks instead.
 *
 * @param {Facts[]} all
 * @param {CvState} state
 */
export function timelineData(all, state) {
  const years = chartYears(all);
  const shown = all.filter((f) => matches(f, state, { ignoreYears: true }));
  const series = CHART_SERIES.map(([key, label]) => ({
    key,
    label,
    values: years.map((y) => shown.filter((f) => f.type === key && f.year === y).length),
  }));
  return { years, series, selected: selectedRange(state, years), entries: shown.length };
}

/**
 * What the timeline says in place of a chart when the filters leave it nothing to draw: no entry matches at
 * all, or some do but none is a charted type (publications, grants, talks, awards), as with courses or
 * service. Null when there is something to draw. Enarratio refuses to chart no data, so the caller draws this
 * sentence instead and never calls it.
 *
 * @param {ReturnType<typeof timelineData>} data
 * @returns {string | null}
 */
export function timelineEmptyText(data) {
  if (data.series.some((s) => s.values.some((n) => n > 0))) return null;
  if (data.entries === 0) return "No entries match these filters, so there is nothing to chart.";
  const names = data.series.map((s) => s.label.toLowerCase());
  return `The timeline charts ${names.slice(0, -1).join(", ")} and ${names[names.length - 1]}, and none of the entries these filters select is one of those.`;
}

/**
 * @param {CvState} state
 * @param {number[]} years
 * @returns {[number, number] | null}
 */
function selectedRange(state, years) {
  if (state.from === null && state.to === null) return null;
  const first = years[0] ?? 0;
  const last = years[years.length - 1] ?? 0;
  return [state.from ?? first, state.to ?? last];
}

/**
 * Per-year series for the three headline sparklines. Students count only the one-cohort lines: a
 * count spread over a decade (19 lab students, 2015 to 2026) has no honest per-year split.
 *
 * @param {Facts[]} all
 * @param {CvState} state
 */
export function sparkData(all, state) {
  const years = chartYears(all);
  const shown = all.filter((f) => matches(f, state, { ignoreYears: true }));
  const per = (/** @type {(f: Facts) => number} */ value) =>
    years.map((y) => shown.filter((f) => f.year === y).reduce((sum, f) => sum + value(f), 0));
  return {
    years,
    selected: selectedRange(state, years),
    papers: per((f) => (f.type === "publication" ? 1 : 0)),
    grants: per((f) => (f.type === "grant" ? 1 : 0)),
    students: per((f) => (f.type === "mentoring" && f.cohort ? (f.students ?? 0) : 0)),
  };
}

/**
 * The query a year's bar links to with script off: that year alone, or every year when it already is.
 *
 * @param {CvState} state
 * @param {number} year
 */
export function yearHref(state, year) {
  const only = state.from === year && state.to === year;
  return stateToSearch({ ...state, from: only ? null : year, to: only ? null : year });
}

/**
 * One sentence for a screen reader and the status line: what is shown out of what.
 *
 * @param {number} shown
 * @param {number} total
 */
export function summaryText(shown, total) {
  if (shown === total) return `Showing all ${total} entries`;
  if (shown === 0) return `No entries match. ${total} entries in all`;
  return `Showing ${shown} of ${total} entries`;
}

/**
 * How many entries each filter option would show, given every other filter: the number beside a
 * checkbox is what ticking it adds, the way a faceted search counts.
 *
 * @param {Facts[]} all
 * @param {CvState} state
 */
export function facetCounts(all, state) {
  /** @type {Record<string, number>} */
  const types = {};
  /** @type {Record<string, number>} */
  const areas = {};
  /** @type {Record<string, number>} */
  const roles = {};
  const noTypes = { ...state, types: [] };
  const noAreas = { ...state, areas: [] };
  const noRole = { ...state, role: null };
  for (const f of all) {
    if (matches(f, noTypes)) types[f.type] = (types[f.type] ?? 0) + 1;
    if (matches(f, noAreas)) for (const a of f.areas) areas[a] = (areas[a] ?? 0) + 1;
    if (f.role && matches(f, noRole)) roles[f.role] = (roles[f.role] ?? 0) + 1;
  }
  return { types, areas, roles };
}

/**
 * Every year an entry starts in, ascending: the year pickers' options.
 *
 * @param {Facts[]} all
 */
export function yearOptions(all) {
  const years = all.map((f) => f.year).filter((y) => y !== null);
  return range(Math.min(...years), Math.max(...years));
}

/**
 * The timeline's accessible name: what it plots and its peak, since the bars are not read out.
 *
 * @param {ReturnType<typeof timelineData>} data
 */
export function timelineLabel(data) {
  const totals = data.years.map((_, i) =>
    data.series.reduce((sum, s) => sum + (s.values[i] ?? 0), 0),
  );
  const peak = Math.max(0, ...totals);
  const first = data.years[0];
  const last = data.years[data.years.length - 1];
  const names = data.series.map((s) => s.label.toLowerCase());
  const what = `${names.slice(0, -1).join(", ")} and ${names[names.length - 1]} per year, ${first} to ${last}`;
  if (peak === 0) return `${what[0]?.toUpperCase()}${what.slice(1)}: none match the filters.`;
  const peakYears = data.years.filter((_, i) => totals[i] === peak);
  return `${what[0]?.toUpperCase()}${what.slice(1)}. Most in ${peakYears.join(" and ")}, with ${peak}. Each year's bar shows that year only.`;
}

/**
 * @param {string} what "papers", "grants" or "students in one-year cohorts"
 * @param {number[]} years
 * @param {number[]} values
 */
export function sparkLabel(what, years, values) {
  const peak = Math.max(0, ...values);
  if (peak === 0) return `No ${what} per year match the filters.`;
  const at = years.filter((_, i) => values[i] === peak);
  return `${what[0]?.toUpperCase()}${what.slice(1)} per year, ${years[0]} to ${years[years.length - 1]}: most in ${at.join(" and ")}, with ${peak}.`;
}

/**
 * How many filters are on, for the collapsed filter panel's label: each ticked type and area, the year
 * range, the role and the search.
 *
 * @param {CvState} state
 */
export function activeCount(state) {
  return (
    state.types.length +
    state.areas.length +
    (state.from !== null || state.to !== null ? 1 : 0) +
    (state.role ? 1 : 0) +
    (state.q ? 1 : 0)
  );
}

